<?php
$decodeConfigurationValue = static function ($value) {
  if (is_array($value)) {
    return $value;
  }
  if (is_object($value)) {
    return get_object_vars($value);
  }
  if (!is_string($value) || trim($value) === '') {
    return array();
  }
  $candidate = html_entity_decode(trim($value), ENT_QUOTES | ENT_HTML5, 'UTF-8');
  for ($attempt = 0; $attempt < 4; $attempt++) {
    $decoded = json_decode($candidate, true);
    if (is_array($decoded)) {
      return $decoded;
    }
    if (!is_string($decoded) || trim($decoded) === '') {
      break;
    }
    $candidate = html_entity_decode(trim($decoded), ENT_QUOTES | ENT_HTML5, 'UTF-8');
  }
  return array();
};

$itemId = (int) ($itemid ?? 0);
$configurationId = null;
foreach (array(
  $edit_config_id ?? null,
  $config_id ?? null,
  $configuration_id ?? null,
  $api_config_id ?? null,
  $api_id ?? null,
  $configid ?? null
) as $configurationIdCandidate) {
  if ((int) $configurationIdCandidate > 0) {
    $configurationId = (int) $configurationIdCandidate;
    break;
  }
}

$editConfigurationData = array();
foreach (array(
  $edit_config_data ?? null,
  $api_config_data ?? null,
  $configuration_data ?? null,
  $config_data ?? null,
  $api_configuration ?? null,
  $saved_configuration ?? null
) as $configurationDataCandidate) {
  $decodedConfigurationData = $decodeConfigurationValue($configurationDataCandidate);
  if ($decodedConfigurationData) {
    $editConfigurationData = $decodedConfigurationData;
    break;
  }
}
$editPayload = array();
foreach (array('payload', 'configuration', 'full_config_json', 'configuration_json', 'config_json') as $payloadKey) {
  if (!array_key_exists($payloadKey, $editConfigurationData)) {
    continue;
  }
  $candidatePayload = $decodeConfigurationValue($editConfigurationData[$payloadKey]);
  if ($candidatePayload) {
    $editPayload = $candidatePayload;
    break;
  }
}
if (!$editPayload) {
  foreach (array(
    $full_config_json ?? null,
    $configuration_json ?? null,
    $saved_configuration ?? null
  ) as $standalonePayload) {
    $candidatePayload = $decodeConfigurationValue($standalonePayload);
    if ($candidatePayload) {
      $editPayload = $candidatePayload;
      break;
    }
  }
}
if (!$editPayload && (
  isset($editConfigurationData['product'])
  || isset($editConfigurationData['commands'])
  || isset($editConfigurationData['responses'])
  || isset($editConfigurationData['errors'])
)) {
  $editPayload = $editConfigurationData;
}
foreach (array('product', 'commands', 'responses', 'errors') as $payloadSection) {
  if (isset($editPayload[$payloadSection]) && is_string($editPayload[$payloadSection])) {
    $editPayload[$payloadSection] = $decodeConfigurationValue($editPayload[$payloadSection]);
  }
}
// The edit action can return the original JSON and reconstructed database rows
// as separate values. Merge both representations so frame values, partitions,
// and bitwise rows are all available to the browser-side restore logic.
foreach (array('commands', 'responses', 'errors') as $payloadSection) {
  if (!array_key_exists($payloadSection, $editConfigurationData)) {
    continue;
  }
  $outerSection = $decodeConfigurationValue($editConfigurationData[$payloadSection]);
  if (!$outerSection) {
    continue;
  }
  $innerSection = isset($editPayload[$payloadSection])
    ? $decodeConfigurationValue($editPayload[$payloadSection])
    : array();
  $editPayload[$payloadSection] = $innerSection
    ? array_replace_recursive($outerSection, $innerSection)
    : $outerSection;
}
$separateFrameSections = array(
  'commands' => array(
    $commands ?? null,
    $command_data ?? null,
    $command_frames ?? null,
    $cmd_data ?? null,
    $edit_commands ?? null
  ),
  'responses' => array(
    $responses ?? null,
    $response_data ?? null,
    $response_frames ?? null,
    $resp_data ?? null,
    $edit_responses ?? null
  ),
  'errors' => array(
    $errors ?? null,
    $error_data ?? null,
    $error_frames ?? null,
    $edit_errors ?? null
  )
);
foreach ($separateFrameSections as $payloadSection => $sectionCandidates) {
  foreach ($sectionCandidates as $sectionCandidate) {
    $decodedSection = $decodeConfigurationValue($sectionCandidate);
    if (!$decodedSection) {
      continue;
    }
    $currentSection = isset($editPayload[$payloadSection])
      ? $decodeConfigurationValue($editPayload[$payloadSection])
      : array();
    $editPayload[$payloadSection] = $currentSection
      ? array_replace_recursive($decodedSection, $currentSection)
      : $decodedSection;
    break;
  }
}
$editProduct = isset($editConfigurationData['product'])
  ? $decodeConfigurationValue($editConfigurationData['product'])
  : array();
$payloadProduct = isset($editPayload['product'])
  && is_array($editPayload['product'])
  ? $editPayload['product']
  : array();

$resolvedEditProduct = array_merge($payloadProduct, $editProduct);
if (!empty($resolvedEditProduct)) {
  // The edit model returns product defaults beside the nested payload.
  // Keep them together for the browser-side restoration code so the
  // parameter name and saved frame counts are available immediately.
  $editPayload['product'] = array_merge(
    isset($editPayload['product']) && is_array($editPayload['product'])
      ? $editPayload['product']
      : array(),
    $resolvedEditProduct
  );
}
$flatCommandValue = (string) (
  $resolvedEditProduct['command_value']
  ?? $resolvedEditProduct['commandValue']
  ?? $resolvedEditProduct['command_code']
  ?? $resolvedEditProduct['commandCode']
  ?? ($command_value ?? ($command_code ?? ($full_api_value ?? '')))
);
if ($flatCommandValue !== '') {
  if (!isset($editPayload['commands']) || !is_array($editPayload['commands'])) {
    $editPayload['commands'] = array();
  }
  if (!isset($editPayload['commands'][0]) || !is_array($editPayload['commands'][0])) {
    $editPayload['commands'][0] = array();
  }
  if (
    empty($editPayload['commands'][0]['commandCode'])
    && empty($editPayload['commands'][0]['frameCode'])
    && empty($editPayload['commands'][0]['commandValue'])
  ) {
    $editPayload['commands'][0]['commandValue'] = $flatCommandValue;
  }
}
$isEditMode = $configurationId !== null || !empty($editPayload);
$initialConfiguration = !empty($editPayload) ? $editPayload : null;

$brandValue = (string) (
  $resolvedEditProduct['brandname']
  ?? ($brand ?? '')
);
$productValue = (string) (
  $resolvedEditProduct['productname']
  ?? ($category ?? '')
);
$modelValue = (string) (
  $resolvedEditProduct['modelname']
  ?? ($modelno ?? ($model_name ?? ''))
);
$versionValue = (string) ($version ?? 'N/A');
$batchValue = (string) ($batch ?? 'N/A');

/*
 * BRAND / PRODUCT IMAGE SUPPORT (UI ONLY)
 * ---------------------------------------
 * Use image values if the existing backend already included them. If these
 * values are not present, browser-side code below falls back to the same
 * existing items/list_data1vendor endpoint used by the Vendor cards.
 * No controller/model/database change is required.
 */
$brandImageValue = (string) (
  $resolvedEditProduct['brand_image']
  ?? $resolvedEditProduct['brand_logo']
  ?? $resolvedEditProduct['brandlogo']
  ?? ($brand_image ?? ($brand_logo ?? ($brandlogo ?? '')))
);
$productImageValue = (string) (
  $resolvedEditProduct['product_image']
  ?? $resolvedEditProduct['Product_image']
  ?? $resolvedEditProduct['prodimg']
  ?? ($product_image ?? ($Product_image ?? ($prodimg ?? '')))
);

/*
 * Convert the database value into a public image URL.
 *
 * Brand and Product uploads are stored in:
 *     /files/brand_logo/
 *
 * The database can contain only a filename, an existing relative path,
 * or an already-complete URL. Support all three without hardcoding hostnames.
 */
$resolveMetaImageUrl = static function ($value) {
  $value = trim((string) $value);

  if ($value === '') {
    return '';
  }

  if (preg_match('#^(?:https?:)?//#i', $value)) {
    return $value;
  }

  if ($value[0] === '/') {
    return $value;
  }

  // If a relative path was stored, use only its filename because the current
  // Brand/Product upload flow stores public files in files/brand_logo/.
  $filename = basename(str_replace('\\', '/', $value));

  return $filename !== ''
    ? base_url('files/brand_logo/' . rawurlencode($filename))
    : '';
};

$brandImageUrl = $resolveMetaImageUrl($brandImageValue);
$productImageUrl = $resolveMetaImageUrl($productImageValue);

$editParameterName = (string) (
  $resolvedEditProduct['parameter_name']
  ?? $resolvedEditProduct['parameterName']
  ?? $resolvedEditProduct['parametername']
  ?? $resolvedEditProduct['cmd_parametername']
  ?? ''
);

/*
 * EDIT-ONLY COMMAND GET STATUS LOCK
 * ---------------------------------
 * Prefer the explicit backend flag.  The parameter-name fallback is based on
 * the server-restored edit record, not on the live browser input.
 */
$normalizedEditParameterName = strtolower(trim(preg_replace('/\s+/', ' ', $editParameterName)));
$commandGetStatusEditLocked = $isEditMode && (
  !empty($command_get_status_edit_locked)
  || !empty($editConfigurationData['command_get_status_edit_locked'])
  || !empty($resolvedEditProduct['command_get_status_edit_locked'])
  || $normalizedEditParameterName === 'command get status'
);

if ($commandGetStatusEditLocked) {
  // Canonical browser restore value. Backend also enforces this during save.
  if (!isset($editPayload['commands']) || !is_array($editPayload['commands'])) {
    $editPayload['commands'] = array();
  }
  $lockedCommand = isset($editPayload['commands'][0]) && is_array($editPayload['commands'][0])
    ? $editPayload['commands'][0]
    : array();
  $lockedCommand['frameCode'] = 'A1E70A';
  $lockedCommand['commandCode'] = 'A1E70A';
  $lockedCommand['commandValue'] = 'A1E70A';
  if (!isset($lockedCommand['partition']) || !is_array($lockedCommand['partition'])) {
    $lockedCommand['partition'] = array();
  }
  $lockedCommand['partition']['fullApiValue'] = 'A1E70A';
  $lockedCommand['partition']['inferredByteCount'] = 3;
  $editPayload['commands'] = array($lockedCommand);
  $initialConfiguration = $editPayload;
}

/*
 * PARAMETER NAME SOURCE
 * ---------------------
 * Keep both requested sections:
 *   1. Parameter Name Source
 *   2. Parameter Name
 * Existing values come ONLY from Command Get Status -> Response fields.
 */
$existingParameterNames = array();
$existingParameterNameMap = array();
foreach (($existing_parameter_names ?? array()) as $existingParameterName) {
  $existingParameterName = trim((string) $existingParameterName);
  if ($existingParameterName === '') continue;
  $existingKey = strtolower(trim(preg_replace('/\s+/', ' ', $existingParameterName)));
  if ($existingKey === '' || isset($existingParameterNameMap[$existingKey])) continue;
  $existingParameterNameMap[$existingKey] = $existingParameterName;
  $existingParameterNames[] = $existingParameterName;
}

$normalizedCurrentParameterName = strtolower(trim(preg_replace('/\s+/', ' ', $editParameterName)));
$initialParameterSource = '';
$initialExistingParameterName = '';
$initialCustomParameterName = '';

if ($commandGetStatusEditLocked) {
  $initialParameterSource = 'custom';
  $initialCustomParameterName = 'Command Get Status';
} elseif ($editParameterName !== '') {
  if (isset($existingParameterNameMap[$normalizedCurrentParameterName])) {
    $initialParameterSource = 'existing';
    $initialExistingParameterName = $existingParameterNameMap[$normalizedCurrentParameterName];
  } else {
    $initialParameterSource = 'custom';
    $initialCustomParameterName = $editParameterName;
  }
}

$editCommands = isset($editPayload['commands']) && is_array($editPayload['commands'])
  ? $editPayload['commands']
  : array();
$editFrameCount = (int) (
  $resolvedEditProduct['command_frame_count']
  ?? $resolvedEditProduct['commandFrameCount']
  ?? count($editCommands)
);
if ($configurationId && $editFrameCount < 1 && count($editCommands) > 0) {
  $editFrameCount = count($editCommands);
}
$editFrameCount = $commandGetStatusEditLocked
  ? 1
  : max(0, min(20, $editFrameCount));
?>
