      background: #2f9b57;
      color: #fff;
    }

    .flow-stage.completed:not(.active) .flow-stage-status {
      color: #237441;
    }

    .flow-stage.active.in-progress {
      box-shadow: inset 0 -4px 0 #f2b84b;
    }

    .flow-stage.active.completed {
      background: #176b3a;
      border-color: #176b3a;
    }

    .flow-stage.active.completed .flow-stage-number {
      background: #fff;
      color: #176b3a;
    }

    
    .flow-arrow {
      color: #c47b45;
      font-size: 1.15rem;
      flex: 0 0 auto;
    }

    .frame-settings {
      position: relative;
      z-index: 2;
      display: grid;
      grid-template-columns: 1fr;
      gap: 0.65rem;
      margin-top: 0.75rem;
      padding: 0.75rem;
      border: 1px solid #dbe5f0;
      border-radius: 14px;
      background: rgba(255, 255, 255, 0.94);
      cursor: default;
    }

    .frame-setting {
      display: grid;
      gap: 0.3rem;
    }

    .frame-setting label {
      color: #25415d;
      font-size: 0.72rem;
      font-weight: 700;
    }

    .frame-setting select {
      width: 100%;
      min-width: 0;
      border: 1px solid #cfdbea;
      border-radius: 9px;
      background: #fff;
      color: #172b45;
      padding: 0.48rem 0.55rem;
      font-size: 0.76rem;
      outline: none;
      cursor: pointer;
    }

    .frame-setting select:focus {
      border-color: #2a6df4;
      box-shadow: 0 0 0 3px rgba(42, 109, 244, 0.13);
    }

    .frame-setting select.frame-field-error {
      border-color: #dc2626;
      background: #fff7f7;
    }

    .remove-btn {
      background: transparent;
      border: none;
      color: #b91c1c;
      cursor: pointer;
      font-size: 0.8rem;
    }

    .command-frame-help {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      gap: 10px;
      flex-wrap: wrap;
    }

    .command-frame-hint {
      color: #4a6180;
      font-size: 0.78rem;
    }

    .command-example {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      padding: 0.38rem 0.55rem;
      border: 1px solid #c9d8eb;
      border-radius: 11px;
      background: #fff;
      color: #536b88;
      font-size: 0.68rem;
    }

    .command-example strong {
      color: #214467;
    }

    .example-byte {
      display: inline-grid;
      place-items: center;
      min-width: 31px;
      height: 27px;
      padding: 0 5px;
      border: 1px solid #d18d00;
      border-radius: 6px;
      background: #ffb000;
      color: #111827;
      font:
        750 0.74rem Consolas,
        monospace;
    }

    .example-result {
      color: #1f63cf;
      font:
        700 0.7rem Consolas,
        monospace;
    }

    .byte-detail-popup {
      display: none;
      background: #f9fcff;
      border: 1px solid #d0def0;
      border-radius: 20px;
      padding: 1rem 1.5rem;
      margin-top: 1.5rem;
    }

    .byte-detail-popup .popup-head {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 0.5rem;
      font-weight: 600;
      color: #0b1a33;
    }

    .byte-detail-popup .close {
      background: transparent;
      border: none;
      font-size: 1.2rem;
      cursor: pointer;
    }

    .byte-detail-popup .popup-grid {
      display: flex;
      flex-flow: row nowrap;
      align-items: center;
      width: 100%;
      overflow-x: auto;
      overflow-y: hidden;
      white-space: nowrap;
      padding-bottom: 0.35rem;
    }

    .byte-detail-popup .popup-item {
      display: flex;
      justify-content: space-between;
      padding: 0.15rem 0.6rem;
      background: #f6faff;
      border-radius: 20px;
      font-size: 0.8rem;
    }

    .byte-detail-popup .popup-item .idx {
      font-weight: 600;
      color: #1a3d66;
    }

    .byte-detail-popup .popup-item .val {
      font-weight: 500;
      color: #2a5f8a;
    }

    .frame-code {
      margin-top: 0.45rem;
      color: #314b6b;
      font-size: 0.78rem;
      font-family: Consolas, Monaco, monospace;
    }

    .frame-code strong {
      color: #0b1a33;
      letter-spacing: 0.08em;
    }

    .command-entry {
      display: flex;
      flex-wrap: wrap;
      align-items: flex-end;
      gap: 0.65rem;
      margin: 0.8rem 0 1rem;
      padding: 0.8rem;
      background: #eef4ff;
      border-radius: 14px;
    }

    .command-entry label {
      width: 100%;
      font-size: 0.78rem;
      font-weight: 600;
      color: #25415d;
    }

    .command-entry input {
      flex: 1;
      min-width: 200px;
      border: 1px solid #b9cbe5;
      border-radius: 10px;
      padding: 0.55rem 0.7rem;
      font-family: Consolas, Monaco, monospace;
      font-size: 0.95rem;
      text-transform: uppercase;
      outline: none;
    }

    .command-entry input:focus {
      border-color: #2a6df4;
      box-shadow: 0 0 0 3px rgba(42, 109, 244, 0.15);
    }

    .command-entry button {
      border: 0;
      border-radius: 10px;
      padding: 0.58rem 1rem;
      background: #2a6df4;
      color: white;
      font-weight: 600;
      cursor: pointer;
    }

    .command-byte-editor {
      display: flex;
      flex-flow: row wrap;
      align-items: flex-end;
      gap: 10px 8px;
      width: 100%;
      overflow: visible;
      padding: 4px 2px 8px;
    }

    .command-byte-unit {
      position: relative;
      flex: 0 0 auto;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 4px;
      padding-top: 2px;
    }

    .command-entry .command-byte-unit label {
      width: auto;
      color: #637a98;
      font-size: 0.62rem;
      font-weight: 700;
      text-transform: uppercase;
    }

    .command-entry input.command-byte-input {
      flex: 0 0 auto;
      min-width: 80px;
      width: 80px;
      max-width: 360px;
      height: 44px;
      padding: 0.5rem 0.65rem;
      border: 1px solid #9fb7d8;
      border-radius: 9px;
      background: #fff;
      color: #0b1a33;
      font:
        750 1rem Consolas,
        Monaco,
        monospace;
      text-align: left;
      text-transform: uppercase;
    }

    .command-entry input.command-byte-input.invalid {
      border-color: #d92d20;
      background: #fff4f2;
      box-shadow: 0 0 0 3px rgba(217, 45, 32, 0.1);
    }

    .command-entry button.remove-command-byte {
      position: absolute;
      top: -5px;
      right: -6px;
      display: grid;
      place-items: center;
      width: 18px;
      height: 18px;
      padding: 0;
      border-radius: 50%;
      background: #fff;
      color: #b42318;
      border: 1px solid #f2b8b5;
      font-size: 0.72rem;
      line-height: 1;
    }

    .command-entry button.remove-command-byte:hover {
      background: #fee4e2;
    }

    .command-entry button.add-command-byte {
      flex: 0 0 44px;
      width: 44px;
      height: 44px;
      margin-bottom: 0;
      padding: 0;
      border: 2px dashed #79a4e8;
      border-radius: 10px;
      background: #fff;
      color: #1f63cf;
      font-size: 1.45rem;
      line-height: 1;
    }

    .command-entry button.add-command-byte:hover {
      background: #eaf2ff;
      border-style: solid;
    }

    .command-entry .byte-editor-hint {
      width: 100%;
      color: #667e9e;
      font-size: 0.7rem;
    }

    .command-entry .command-byte-count {
      width: 100%;
      color: #214467;
      font-size: 0.72rem;
      font-weight: 700;
    }

    .command-entry input.command-byte-input.new-byte {
      animation: newBytePulse 0.65s ease;
    }

    @keyframes newBytePulse {
      0% {
        transform: scale(0.85);
        box-shadow: 0 0 0 5px rgba(42, 109, 244, 0.2);
      }

      100% {
        transform: scale(1);
        box-shadow: none;
      }
    }

    .command-entry .apply-command-row {
      display: flex;
      justify-content: flex-end;
      width: 100%;
    }

    .command-entry .apply-command-row button {
      display: inline-flex;
      align-items: center;
      gap: 7px;
    }

    .command-error {
      width: 100%;
      color: #b42318;
      font-size: 0.78rem;
      min-height: 1em;
    }

    .command-code-line {
      display: flex !important;
      flex-flow: row nowrap !important;
      align-items: center;
      gap: 10px;
      width: max-content;
      min-width: max-content;
      white-space: nowrap;
    }

    .command-code-label {
      display: inline-block;
      flex: 0 0 auto;
      white-space: nowrap;
      color: #0b1a33;
      font-size: 0.9rem;
      font-weight: 700;
    }

    .command-character-row {
      display: inline-flex !important;
      flex-flow: row nowrap !important;
      align-items: center;
      gap: 8px;
      width: max-content;
      min-width: max-content;
      white-space: nowrap;
    }

    .command-character {
      display: inline-flex;
      flex: 0 0 auto;
      justify-content: center;
      align-items: center;
      width: auto;
      min-width: 46px;
      height: 46px;
      padding: 0 10px;
      background: #ffb000;
      border: 1px solid #202020;
      border-radius: 5px;
      color: #050505;
      font-family: Consolas, Monaco, monospace;
      font-size: 1.25rem;
      font-weight: 700;
      line-height: 1;
      text-transform: uppercase;
      white-space: nowrap;
      cursor: pointer;
      transition: all 0.15s;
    }

    .command-character:hover {
      background: #ffcc66;
      transform: scale(1.05);
    }

    .command-character.partition-colored {
      background: var(--partition-soft);
      border: 2px solid var(--partition-color);
      color: var(--partition-text);
      box-shadow: inset 0 3px 0 var(--partition-color);
    }

    .command-character.partition-colored:hover {
      background: var(--partition-soft);
      filter: saturate(1.15);
    }

    .empty-command {
      color: #667e9e;
      font-size: 0.85rem;
      padding: 0.4rem 0;
    }

    /* Field Description Section */
    .field-desc-section {
      margin-top: 2rem;
      overflow: hidden;
      background: #fff;
      border-radius: 24px;
      border: 1px solid #dbe6f5;
      box-shadow: 0 10px 30px -24px rgba(20, 39, 62, 0.65);
    }

    .field-desc-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      flex-wrap: wrap;
      padding: 1.25rem 1.5rem;
      background: linear-gradient(135deg, #f5f9ff, #eef5ff);
      border-bottom: 1px solid #dbe6f5;
    }

    .field-desc-title {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 750;
      color: #0b1a33;
      font-size: 1.12rem;
    }

    .field-desc-title-icon {
      display: grid;
      place-items: center;
      width: 36px;
      height: 36px;
      border-radius: 11px;
      color: #fff;
      background: #2a6df4;
      box-shadow: 0 6px 14px rgba(42, 109, 244, 0.24);
    }

    .field-desc-dropdown {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-wrap: wrap;
    }

    .field-desc-dropdown label {
      font-weight: 650;
      color: #25415d;
      font-size: 0.86rem;
    }

    .field-desc-dropdown select {
      border: 1px solid #cbd9eb;
      background: white;
      padding: 0.58rem 2rem 0.58rem 0.85rem;
      border-radius: 11px;
      font-size: 0.88rem;
      font-weight: 600;
      color: #0b1a33;
      outline: none;
      min-width: 220px;
      cursor: pointer;
    }

    .field-desc-dropdown select:focus {
      border-color: #2a6df4;
      box-shadow: 0 0 0 3px rgba(42, 109, 244, 0.15);
    }

    .field-desc-help {
      display: flex;
      align-items: flex-start;
      gap: 9px;
      margin: 1rem 1.5rem 0;
      padding: 0.75rem 0.9rem;
      border-radius: 12px;
      background: #f8fbff;
      color: #4b6381;
      font-size: 0.8rem;
      line-height: 1.45;
    }

    .field-desc-help i {
      color: #2a6df4;
      margin-top: 2px;
    }

    #fieldDescContainer {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
      gap: 14px;
      min-height: 92px;
      padding: 1.1rem 1.5rem 1.5rem;
      align-items: start;
    }

    .field-empty {
      grid-column: 1/-1;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 7px;
      min-height: 100px;
      color: #667e9e;
      text-align: center;
      border: 1px dashed #cbd9eb;
      border-radius: 15px;
      background: #fbfdff;
      font-size: 0.88rem;
    }

    .field-empty i {
      font-size: 1.35rem;
      color: #9ab0ca;
    }

    /* Byte Popup Modal */
    .byte-modal-overlay {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: rgba(0, 0, 0, 0.4);
      z-index: 1000;
      justify-content: center;
      align-items: center;
    }

    .byte-modal {
      background: white;
      border-radius: 24px;
      padding: 2rem;
      
      width: min(150%, 990px);
      max-height: 90vh;
      overflow-y: auto;
      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.3);
    }

    .byte-modal h3 {
      font-size: 1.3rem;
      color: #0b1a33;
      margin-bottom: 0.3rem;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .byte-modal .byte-code-badge {
      background: #ffb000;
      padding: 0.2rem 1rem;
      border-radius: 30px;
      font-weight: 700;
      font-family: Consolas, monospace;
      font-size: 1rem;
      display: inline-block;
      margin-bottom: 1rem;
    }

    .byte-modal .close-modal {
      background: transparent;
      border: none;
      font-size: 1.5rem;
      cursor: pointer;
      color: #666;
      float: right;
    }

    .byte-modal .form-group {
      margin-bottom: 0.8rem;
    }

    .byte-modal .form-group label {
      display: block;
      font-weight: 600;
      font-size: 0.8rem;
      color: #25415d;
      margin-bottom: 3px;
    }

    .byte-modal .form-group input,
    .byte-modal .form-group select {
      width: 100%;
      padding: 0.45rem 0.7rem;
      border: 1px solid #d6e0ed;
      border-radius: 10px;
      font-size: 0.9rem;
      outline: none;
    }

    .byte-modal .form-group input:focus,
    .byte-modal .form-group select:focus {
      border-color: #2a6df4;
      box-shadow: 0 0 0 3px rgba(42, 109, 244, 0.15);
    }

    .byte-modal .modal-actions {
      display: flex;
      gap: 12px;
      margin-top: 1.2rem;
      justify-content: flex-end;
    }

    .byte-modal .modal-actions button {
      padding: 0.45rem 1.8rem;
      border-radius: 40px;
      font-weight: 600;
      cursor: pointer;
      border: none;
      font-size: 0.9rem;
    }

    .byte-modal .modal-actions .btn-save-modal {
      background: #0b1a33;
      color: white;
    }

    .byte-modal .modal-actions .btn-cancel-modal {
      background: #eef3fe;
      color: #1a4cba;
      border: 1px solid #d6e3fc;
    }

    /* command character clickable */
    .command-character.clickable {
      cursor: pointer;
      position: relative;
    }

    .command-character.clickable::after {
      content: "";
      position: absolute;
      top: -10px;
      right: -10px;
      font-size: 12px;
      background: white;
      border-radius: 50%;
      padding: 0 2px;
    }

    .field-desc-card {
      background: #fff;
      border: 1px solid #dce6f2;
      border-radius: 17px;
      padding: 0.9rem;
      min-width: 0;
      transition:
        box-shadow 0.15s,
        border-color 0.15s,
        transform 0.15s;
    }

    .field-desc-card:hover {
      border-color: #aac4ee;
      box-shadow: 0 8px 20px -16px rgba(18, 58, 116, 0.8);
      transform: translateY(-1px);
    }

    .field-desc-card.partition-colored {
      border-color: var(--partition-color);
      box-shadow: inset 0 4px 0 var(--partition-color);
    }

    .field-desc-card.partition-colored:hover {
      border-color: var(--partition-color);
    }

    .field-desc-card.partition-colored .field-byte-badge {
      background: var(--partition-soft);
      border-color: var(--partition-color);
      color: var(--partition-text);
    }

    .field-card-top {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .field-byte-badge {
      flex: 0 0 auto;
      display: grid;
      place-items: center;
      min-width: 48px;
      height: 44px;
      padding: 0 8px;
      border-radius: 11px;
      color: #0b1a33;
      background: #ffb000;
      border: 1px solid #e29b00;
      font:
        750 1rem Consolas,
        monospace;
    }

    .field-byte-meta {
      min-width: 0;
      flex: 1;
    }

    .field-byte-index {
      display: block;
      margin-bottom: 4px;
      color: #667e9e;
      font-size: 0.68rem;
      font-weight: 750;
      text-transform: uppercase;
      letter-spacing: 0.06em;
    }

    .field-card-body {
      margin-top: 0.75rem;
      padding-top: 0.75rem;
      border-top: 1px solid #edf1f6;
    }

    /* Bitwise specific styles */
    .binary-labels,
    .bitwise-bits {
      display: grid;
      grid-template-columns: repeat(8, minmax(22px, 1fr));
      gap: 4px;
      width: 100%;
      overflow-x: auto;
      padding-bottom: 2px;
    }

    .binary-labels {
      margin-bottom: 4px;
      color: #7b8da5;
      font:
        650 0.58rem Consolas,
        monospace;
      text-align: center;
    }

    .bit {
      min-width: 0;
      height: 34px;
      display: flex;
      align-items: center;
      justify-content: center;
      border: 1px solid #d4dfed;
      border-radius: 7px;
      font:
        750 0.78rem Consolas,
        monospace;
      cursor: pointer;
      transition: all 0.15s;
      background: white;
      color: #0b1a33;
    }

    .bit:hover {
      border-color: #2a6df4;
      box-shadow: 0 0 0 2px rgba(42, 109, 244, 0.12);
      transform: translateY(-1px);
    }

    .bit.bit-1 {
      background: #e8f0fe;
      border-color: #78a3e8;
      color: #174fa7;
    }

    .bit.bit-0 {
      background: #f7f9fc;
      color: #68798f;
    }

    .binary-value {
      margin-top: 7px;
      padding: 6px 8px;
      border-radius: 8px;
      background: #0b1a33;
      color: #eaf1fe;
      font:
        650 0.72rem Consolas,
        monospace;
      text-align: center;
      letter-spacing: 0.12em;
    }

    .bit-partition-help {
      display: flex;
      align-items: center;
      gap: 7px;
      margin: 2px 0 9px;
      color: #526b88;
      font-size: 0.72rem;
      font-weight: 650;
    }

    .bit-partition-toolbar {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: wrap;
      margin: 9px 0;
    }

    .bit-partition-action {
      min-height: 34px;
      padding: 0.42rem 0.7rem;
      border: 1px solid #2a6df4;
      border-radius: 8px;
      background: #2a6df4;
      color: #fff;
      font-size: 0.72rem;
      font-weight: 750;
      cursor: pointer;
    }

    .bit-partition-action.secondary {
      background: #fff;
      color: #174e99;
      border-color: #b9cce7;
    }

    .bit-partition-action:disabled {
      opacity: 0.45;
      cursor: not-allowed;
    }

    .bit.selected {
      border-color: #dc2626 !important;
      background: #fff0f0 !important;
      color: #b91c1c !important;
      box-shadow: 0 0 0 2px rgba(220, 38, 38, 0.14);
    }

    .bit.grouped {
      border-color: var(--bit-group-color);
      border-bottom-width: 4px;
    }

    .bit-group-list {
      display: flex;
      flex-wrap: wrap;
      gap: 7px;
      margin-top: 9px;
    }

    .bit-group-chip {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      min-height: 34px;
      padding: 0.4rem 0.62rem;
      border: 1px solid var(--bit-group-color);
      border-radius: 9px;
      background: var(--bit-group-soft);
      color: var(--bit-group-text);
      font-size: 0.7rem;
      font-weight: 750;
      cursor: pointer;
    }

    .bit-group-chip.missing {
      outline: 2px solid rgba(220, 38, 38, 0.22);
    }

    .bit-group-chip i {
      font-size: 0.68rem;
    }

    .bit-group-chip small {
      opacity: 0.78;
      font-weight: 650;
    }

    .bit-cut-scroll {
      overflow-x: auto;
      padding: 23px 8px 10px;
      margin-top: 0.6rem;
    }

    .bit-cut-timeline {
      position: relative;
      display: grid;
      grid-template-rows: auto auto;
      min-width: max-content;
      border: 1px solid #b9cae0;
      border-radius: 12px;
      background: #f8fbff;
      overflow: visible;
    }

    .bit-cut-cell {
      position: relative;
      grid-row: 1;
      min-width: 68px;
      padding: 0.55rem 0.32rem;
      text-align: center;
      border-right: 1px solid #dce6f2;
      background: var(--bit-group-soft);
      box-shadow: inset 0 4px 0 var(--bit-group-color);
    }

    .bit-cut-cell:last-of-type {
      border-right: 0;
    }

    .bit-cut-index {
      display: block;
      margin-bottom: 3px;
      color: #667e9e;
      font:
        750 0.58rem Consolas,
        monospace;
    }

    .bit-cut-value {
      display: block;
      color: var(--bit-group-text);
      font:
        850 0.92rem Consolas,
        monospace;
    }

    .bit-range-block {
      grid-row: 2;
      min-width: 0;
      padding: 0.5rem 0.35rem;
      border-top: 2px solid var(--bit-group-color);
      border-right: 1px solid rgba(255, 255, 255, 0.9);
      background: var(--bit-group-soft);
      color: var(--bit-group-text);
      font-size: 0.68rem;
      font-weight: 800;
      cursor: pointer;
      text-align: center;
    }

    .bit-range-block:hover,
    .bit-range-block:focus-visible {
      filter: brightness(0.97);
      box-shadow: inset 0 0 0 2px var(--bit-group-color);
      outline: none;
    }

    .bit-range-block small {
      display: block;
      margin-top: 3px;
      font-size: 0.58rem;
      font-weight: 700;
      opacity: 0.78;
    }

    .bit-configure-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 4px;
      width: calc(100% - 4px);
      min-height: 32px;
      margin-top: 6px;
      padding: 0.28rem 0.38rem;
      border: 1px solid var(--bit-group-color);
      border-radius: 7px;
      background: #fff;
      color: var(--bit-group-text);
      font-size: 0.58rem;
      font-weight: 800;
      line-height: 1.15;
      cursor: pointer;
    }

    /* .bit-range-block.missing .bit-configure-btn {
        border-color: #d92d20;
        color: #b42318;
      } */
    .bit-configure-btn:hover,
    .bit-configure-btn:focus-visible {
      background: var(--bit-group-color);
      color: #fff;
      outline: none;
    }

    .bit-range-block.single-bit-range {
      padding: 0.45rem 0.25rem;
    }

    .bit-range-block.single-bit-range>span {
      display: block;
      overflow: hidden;
      font-size: 0.62rem;
      line-height: 1.15;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .bit-range-block.single-bit-range>small {
      min-height: 24px;
      font-size: 0.52rem;
      line-height: 1.15;
    }

    .bit-range-block.single-bit-range .bit-configure-btn {
      width: calc(100% - 2px);
      min-height: 30px;
      margin-top: 5px;
      padding: 0.25rem 0.18rem;
      gap: 3px;
      font-size: 0.54rem;
      white-space: nowrap;
    }

    .bit-cut-target {
      position: absolute;
      z-index: 5;
      top: -8px;
      width: 5px;
      height: 26px;
      padding: 0;
      /* transform: translateX(-50%); */
      border: 0;
      background: transparent;
      cursor: pointer;
    }

    .bit-cut-target::before {
      content: "";
      display: none;
      position: absolute;
      top: 18px;
      bottom: 1px;
      left: 50%;
      width: 2px;
      height: 88px;
      transform: translateX(-50%);
      border-left: 3px solid var(--bit-cut-color, #2a6df4);
      pointer-events: none;
    }

    .bit-cut-target::after {
      content: "+";
      position: absolute;
      top: 0;
      left: 50%;
      display: grid;
      place-items: center;
      width: 20px;
      height: 20px;
      transform: translateX(-50%);
      border: 1px solid #b8c9df;
      border-radius: 50%;
      background: #fff;
      color: #47729f;
      font-size: 0.75rem;
      font-weight: 850;
    }

    .bit-cut-target:hover::after {
      border-color: #2a6df4;
      color: #2a6df4;
      background: #eef5ff;
    }

    .bit-cut-target.active::before {
      display: block;
    }

    .bit-cut-target.active::after {
      content: "";
      top: -2px;
      width: 24px;
      height: 24px;
      border: 2px solid var(--bit-cut-color, #2a6df4);
      background: var(--bit-cut-color, #2a6df4);
      color: #fff;
      font-size: 0.68rem;
      box-shadow: 0 3px 9px rgba(42, 109, 244, 0.28);
    }

    .bit-cut-target,
    .bit-cut-target::after {
      transition: none !important;
    }

    .bit-cut-actions {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: wrap;
      margin-top: 0.65rem;
    }

    /* Byte level field description dropdown */
    .byte-field-select {
      width: 100%;
      border: 1px solid #d6e0ed;
      background: white;
      padding: 0.48rem 0.65rem;
      border-radius: 9px;
      font-size: 0.78rem;
      font-weight: 600;
      color: #0b1a33;
      outline: none;
      cursor: pointer;
    }

    .byte-field-select:focus {
      border-color: #2a6df4;
      box-shadow: 0 0 0 3px rgba(42, 109, 244, 0.15);
    }

    .byte-field-wrapper {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-wrap: wrap;
    }

    .view-toggle-buttons {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 5px;
      margin-bottom: 8px;
      padding: 4px;
      border-radius: 10px;
      background: #eef3f9;
    }

    .view-toggle-buttons.single-view {
      grid-template-columns: 1fr;
    }

    .view-toggle-btn {
      padding: 0.42rem 0.55rem;
      border-radius: 9px;
      border-color: rgb(39, 88, 80);
      background: transparent;
      font-size: 0.72rem;
      font-weight: 700;
      color: #526983;
      cursor: pointer;
      transition: all 0.15s;
    }

    .view-toggle-btn.active {
      background: #2a6df4;
      color: white;
      border-color: #2a6df4;
    }

    .view-toggle-btn:hover:not(.active) {
      background: #fff;
    }

    .byte-wise-action {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      padding: 0.65rem 0.75rem;
      border: 1px solid #d6e3f2;
      border-radius: 10px;
      background: #f8fbff;
      color: #214467;
      cursor: pointer;
      text-align: left;
    }

    .byte-wise-action:hover {
      border-color: #2a6df4;
      background: #eef5ff;
    }

    .byte-wise-action strong {
      display: block;
      font-size: 0.78rem;
    }

    .byte-wise-action small {
      display: block;
      margin-top: 2px;
      color: #71839a;
      font-size: 0.66rem;
    }

    /* Step 1: Full API partition editor */
    .step-heading {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-wrap: wrap;
    }

    .step-number {
      display: inline-grid;
      place-items: center;
      min-width: 30px;
      height: 30px;
      padding: 0 8px;
      border-radius: 9px;
      background: #2a6df4;
      color: #fff;
      font-size: 0.78rem;
      font-weight: 800;
    }

    .api-partition-section {
      margin-top: 2rem;
      padding: 1.35rem;
      border: 1px solid #cddcf0;
      border-radius: 24px;
      background: linear-gradient(145deg, #fbfdff, #f3f8ff);
      box-shadow: 0 12px 28px -24px rgba(22, 65, 130, 0.75);
    }

    .api-entry-row {
      display: grid;
      grid-template-columns: minmax(240px, 1fr) auto;
      gap: 12px;
      align-items: end;
      margin-top: 1rem;
    }

    .api-input-wrap label {
      display: block;
      margin-bottom: 6px;
      color: #25415d;
      font-size: 0.83rem;
      font-weight: 700;
    }

    .api-input-wrap input {
      width: 100%;
      min-height: 48px;
      padding: 0.7rem 0.9rem;
      border: 1px solid #aebfd8;
      border-radius: 12px;
      background: #fff;
      color: #0b1a33;
      font:
        750 1rem Consolas,
        Monaco,
        monospace;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      outline: none;
    }

    .api-input-wrap input:focus {
      border-color: #2a6df4;
      box-shadow: 0 0 0 3px rgba(42, 109, 244, 0.14);
    }

    /* Visual byte editor for Command Value.
       The real #fullApiInput remains in the DOM and is synchronized for the
       existing save/backend logic. Command/Response/Error start empty. */
    .hex-command-editor-wrap {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-wrap: wrap;
      min-height: 54px;
    }

    .hex-command-editor-wrap > #fullApiInput {
      position: absolute;
      width: 1px;
      height: 1px;
      opacity: 0;
      pointer-events: none;
      padding: 0;
      border: 0;
    }

    .hex-byte-editor {
      display: flex;
      align-items: center;
      flex-wrap: wrap;
      gap: 5px;
      width: 100%;
      padding: 7px 8px;
      min-height: 44px;
      background: #fff;
      border: 1px solid #d6e0ed;
      border-radius: 14px;
    }

    .hex-byte-unit {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      flex: 0 0 auto;
      padding: 3px;
      border-radius: 10px;
      background: #f8fbff;
    }

    .hex-byte {
      width: 92px;
      min-width: 70px;
      max-width: 120px;
      flex: 1 1 82px;
      height: 40px;
      padding: 0 10px;
      border: 1px solid #cbd7e6;
      border-radius: 7px;
      background: #f7faff;
      color: #0b1a33;
      text-align: center;
      font: 700 0.9rem/40px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
      text-transform: uppercase;
      outline: none;
    }

    .hex-byte:focus {
      border-color: #2a6df4;
      box-shadow: 0 0 0 3px rgba(42, 109, 244, 0.14);
      background: #fff;
    }

    .hex-byte.hex-byte-fixed {
      background: #eef4f1;
      border-color: #bfd4ca;
      color: #164c43;
      cursor: default;
      box-shadow: inset 0 0 0 1px rgba(36, 157, 143, 0.06);
    }

    .hex-byte.hex-byte-fixed:focus {
      border-color: #bfd4ca;
      box-shadow: inset 0 0 0 1px rgba(36, 157, 143, 0.06);
      background: #eef4f1;
    }

    .hex-byte-action-stack {
      width: 34px;
      flex: 0 0 34px;
      display: inline-flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 4px;
    }

    .hex-byte-plus {
      width: 34px;
      height: 34px;
      flex: 0 0 34px;
      border: 1px solid #b7ccf0;
      border-radius: 7px;
      background: #eef4ff;
      color: #1a4cba;
      display: inline-grid;
      place-items: center;
      cursor: pointer;
      font-size: 0.78rem;
      transition: all 0.15s ease;
    }

    .hex-byte-plus:hover:not(:disabled) {
      background: #dce9ff;
      transform: scale(1.08);
    }

    .hex-byte-plus:disabled {
      opacity: 0.48;
      cursor: not-allowed;
      transform: none;
    }

    .hex-byte-minus {
      width: 34px;
      height: 34px;
      flex: 0 0 34px;
      border: 1px solid #efb9b9;
      border-radius: 7px;
      background: #fff3f3;
      color: #b42318;
      display: inline-grid;
      place-items: center;
      cursor: pointer;
      font-size: 0.72rem;
      transition: all 0.15s ease;
    }

    .hex-byte-minus:hover:not(:disabled) {
      background: #fee4e2;
      border-color: #e69a95;
      transform: scale(1.08);
    }

    .hex-byte-minus:disabled {
      opacity: 0.32;
      cursor: not-allowed;
      transform: none;
    }

    .hex-byte-empty {
      color: #71839a;
      font-size: 0.82rem;
      padding: 0 5px;
    }

    .api-count {
      min-height: 48px;
      display: flex;
      align-items: center;
      gap: 7px;
      padding: 0 1rem;
      border: 1px solid #d5e0ee;
      border-radius: 12px;
      background: #fff;
      color: #45617f;
      font-size: 0.8rem;
      font-weight: 700;
      white-space: nowrap;
    }

    .api-error {
      min-height: 20px;
      margin-top: 6px;
      color: #b42318;
      font-size: 0.76rem;
    }

    .partition-workspace {
      margin-top: 0.9rem;
      padding: 1rem;
      border: 1px solid #d9e4f2;
      border-radius: 17px;
      background: #fff;
    }

    .partition-instruction {
      display: flex;
      align-items: flex-start;
      gap: 8px;
      color: #526b89;
      font-size: 0.79rem;
      line-height: 1.45;
    }

    .partition-instruction i {
      margin-top: 2px;
      color: #2a6df4;
    }

    .api-timeline-scroll {
      overflow-x: auto;
      padding: 23px 10px 12px;
      margin-top: 0.7rem;
      scroll-behavior: smooth;
      scrollbar-gutter: stable;
    }

    .partition-timeline-shell {
      display: grid;
      grid-template-columns: 42px minmax(0, 1fr) 42px;
      align-items: stretch;
      gap: 8px;
      margin-top: 0.7rem;
    }

    .partition-timeline-shell .api-timeline-scroll {
      min-width: 0;
      margin-top: 0;
    }

    .partition-side-nav {
      align-self: stretch;
      display: grid;
      place-items: center;
      min-height: 112px;
      margin-top: 23px;
      margin-bottom: 12px;
      padding: 0;
      border: 1px solid #ffffff;
      border-radius: 13px;
      background: linear-gradient(180deg, #ffffff, #ffffff);
      color: #161616;
      box-shadow: 0 8px 18px -14px rgba(252, 252, 253, 0.8);
      cursor: pointer;
      transition:
        transform 160ms ease,
        border-color 160ms ease,
        background 160ms ease,
        color 160ms ease,
        box-shadow 160ms ease;
    }

    .partition-side-nav i {
      font-size: 1rem;
      transition: transform 160ms ease;
    }

    .partition-side-nav:not(:disabled):hover {
      transform: translateY(-1px);
      border-color: #f9fafd;
      background: #f9fafc;
      color: #0c0c0c;
      box-shadow: 0 10px 20px -12px rgba(248, 248, 248, 0.85);
    }

    .partition-side-nav.left:not(:disabled):hover i {
      transform: translateX(-3px);
    }

    .partition-side-nav.right:not(:disabled):hover i {
      transform: translateX(3px);
    }

    .partition-side-nav:focus-visible {
      outline: 3px solid rgba(42, 109, 244, 0.22);
      outline-offset: 2px;
    }

    .partition-side-nav:disabled {
      border-color: #dce5f0;
      background: #f4f7fb;
      color: #a7b4c5;
      box-shadow: none;
      cursor: not-allowed;
      opacity: 0.72;
    }

    .api-timeline {
      position: relative;
      display: grid;
      grid-template-rows: auto auto;
      grid-auto-columns: minmax(54px, 1fr);
      min-width: min-content;
      border: 1px solid #b9cae0;
      border-radius: 12px;
      background: #f8fbff;
      overflow: visible;
    }

    .api-byte-cell {
      position: relative;
      min-width: 54px;
      padding: 0.7rem 0.45rem 0.58rem;
      text-align: center;
      border-right: 1px solid #dce6f2;
      grid-row: 1;
    }

    .api-byte-cell:last-child {
      border-right: 0;
    }

    .api-byte-cell.partition-colored {
      background: var(--partition-soft);
      box-shadow: inset 0 4px 0 var(--partition-color);
    }

    .api-byte-cell.partition-colored .api-byte-value {
      color: var(--partition-text);
    }

    .api-byte-index {
      display: block;
      margin-bottom: 3px;
      color: #7a8da7;
      font-size: 0.58rem;
      font-weight: 750;
      text-transform: uppercase;
    }

    .api-byte-value {
      color: #0b1a33;
      font:
        800 1rem Consolas,
        monospace;
    }

    .partition-name-band {
      min-width: 0;
      padding: 0.55rem 0.45rem 0.65rem;
      border-top: 1px solid var(--partition-color);
      border-right: 1px solid rgba(255, 255, 255, 0.85);
      background: var(--partition-soft);
      grid-row: 2;
    }

    .partition-name-band:first-of-type {
      border-bottom-left-radius: 11px;
    }

    .partition-name-band:last-of-type {
      border-right: 0;
      border-bottom-right-radius: 11px;
    }

    .partition-name-band label {
      display: flex;
      align-items: center;
      gap: 5px;
      margin-bottom: 4px;
      color: var(--partition-text);
      font-size: 0.6rem;
      font-weight: 800;
      text-transform: uppercase;
      white-space: nowrap;
    }

    .partition-name-dot {
      flex: 0 0 auto;
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--partition-color);
    }

    .partition-name-band select {
      width: 100%;
      min-width: 116px;
      padding: 0.42rem 1.55rem 0.42rem 0.5rem;
      border: 1px solid var(--partition-color);
      border-radius: 8px;
      background: #fff;
      color: var(--partition-text);
      font-size: 0.7rem;
      font-weight: 750;
      outline: none;
      cursor: pointer;
    }

    .partition-name-band select:focus {
      box-shadow: 0 0 0 3px var(--partition-soft);
    }

    .partition-config-controls {
      margin-top: 0.5rem;
      padding-top: 0.5rem;
      border-top: 1px solid color-mix(in srgb, var(--partition-color) 35%, transparent);
    }

    .partition-config-controls .view-toggle-buttons {
      margin-bottom: 6px;
      background: rgba(255, 255, 255, 0.58);
    }

    .partition-name-band .partition-mode-quick {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      margin: 0.5rem 0;
      padding: 3px;
      border: 1px solid color-mix(in srgb, var(--partition-color) 35%, transparent);
      background: rgba(255, 255, 255, 0.72);
    }

    .partition-name-band .partition-mode-quick .view-toggle-btn {
      min-width: 0;
      padding: 0.4rem 0.32rem;
      font-size: 0.66rem;
      white-space: nowrap;
    }

    .partition-name-band .partition-mode-quick .view-toggle-btn.active {
      color: #fff !important;
      background: var(--partition-color) !important;
    }

    .partition-config-controls .view-toggle-btn.active {
      background: var(--partition-color);
    }

    .partition-config-controls .byte-wise-action {
      min-width: 170px;
      padding: 0.5rem 0.58rem;
      border-color: var(--partition-color);
      background: #fff;
      color: var(--partition-text);
    }

    .partition-config-controls .byte-wise-action small {
      color: var(--partition-text);
      opacity: 0.72;
    }

    .partition-config-controls .binary-value {
      background: var(--partition-text);
    }

    .partition-config-controls .bit.bit-1 {
      background: var(--partition-soft);
      border-color: var(--partition-color);
      color: var(--partition-text);
    }

    .partition-config-summary {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 7px;
      width: 100%;
      margin-top: 0.48rem;
      padding: 0.42rem 0.5rem;
      border: 1px solid var(--partition-color);
      border-radius: 8px;
      background: #fff;
      color: var(--partition-text);
      font-size: 0.66rem;
      font-weight: 800;
      cursor: pointer;
    }

    .partition-config-summary:hover {
      background: var(--partition-soft);
    }

    .partition-config-summary.config-missing {
      color: #b42318 !important;
      background: #fff1f0 !important;
      border: 2px solid #d92d20 !important;
      box-shadow: 0 0 0 3px rgba(217, 45, 32, 0.1);
    }

    .partition-config-summary.config-missing:hover,
    .partition-config-summary.config-missing:focus-visible {
      color: #8f1d16 !important;
      background: #ffe8e5 !important;
      border-color: #b42318 !important;
      box-shadow: 0 0 0 4px rgba(217, 45, 32, 0.16);
    }

    .partition-mode-overlay {
      display: none;
      position: fixed;
      inset: 0;
      z-index: 900;
      align-items: center;
      justify-content: center;
      padding: 1rem;
      background: rgba(7, 18, 38, 0.48);
      backdrop-filter: blur(2px);
    }

    .partition-mode-modal {
      width: min(900px, calc(100vw - 32px));
      max-height: 88vh;
      overflow-y: auto;
      border: 2px solid var(--partition-color, #2a6df4);
      border-radius: 20px;
      background: var(--partition-soft, #eef5ff);
      box-shadow: 0 24px 70px rgba(5, 20, 48, 0.32);
    }

    @media (max-width: 650px) {
      .partition-mode-modal {
        width: calc(100vw - 20px);
      }
    }

    .partition-mode-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 1rem 1.1rem 0.8rem;
      border-bottom: 1px solid var(--partition-color, #2a6df4);
    }

    .partition-mode-heading {
      min-width: 0;
    }

    .partition-mode-heading strong {
      display: block;
      color: var(--partition-text, #1746a2);
      font-size: 1rem;
    }

    .partition-mode-heading code {
      display: block;
      margin-top: 3px;
      overflow: hidden;
      text-overflow: ellipsis;
      color: #425d7b;
      font-size: 0.75rem;
      white-space: nowrap;
    }

    .partition-mode-close {
      display: grid;
      place-items: center;
      flex: 0 0 auto;
      width: 32px;
      height: 32px;
      padding: 0;
      border: 1px solid var(--partition-color, #2a6df4);
      border-radius: 50%;
      background: #fff;
      color: var(--partition-text, #1746a2);
      font-size: 1.1rem;
      cursor: pointer;
    }

    .partition-mode-body {
      padding: 1rem;
      background: #fff;
    }

    .partition-mode-body .partition-config-controls {
      margin: 0;
      padding: 0;
      border: 0;
    }

    .partition-mode-actions {
      display: flex;
      justify-content: flex-end;
      padding: 0.8rem 1rem 1rem;
    }

    .partition-mode-done {
      padding: 0.55rem 1.2rem;
      border: 0;
      border-radius: 9px;
      background: var(--partition-color, #2a6df4);
      color: #fff;
      font-weight: 800;
      cursor: pointer;
    }

    .partition-config-warning {
      display: none;
      align-items: flex-start;
      gap: 9px;
      margin: 0 0 0.85rem;
      padding: 0.72rem 0.8rem;
      border: 1px solid #d92d20;
      border-radius: 10px;
      background: #fff1f0;
      color: #b42318;
      font-size: 0.78rem;
      font-weight: 750;
      line-height: 1.4;
    }

    .partition-config-warning.show {
      display: flex;
      animation: warningShake 0.3s ease;
    }

    .partition-config-warning i {
      margin-top: 2px;
    }

    .partition-mode-modal.config-invalid {
      border-color: #d92d20 !important;
      box-shadow:
        0 0 0 4px rgba(217, 45, 32, 0.14),
        0 24px 70px rgba(5, 20, 48, 0.32);
    }

    .partition-mode-modal.config-invalid .partition-mode-done {
      background: #d92d20;
    }

    /* .byte-wise-action.config-missing {
        border: 2px solid #d92d20 !important;
        background: #fff1f0 !important;
        color: #b42318 !important;
        box-shadow: 0 0 0 3px rgba(217, 45, 32, 0.1);
      } */
    .byte-wise-action.config-missing small {
      color: #203b35!important;
      opacity: 1;
    }

    .bit.config-missing {
      border: 2px solid #d92d20 !important;
      background: #fff1f0 !important;
      color: #b42318 !important;
      box-shadow: 0 0 0 2px rgba(217, 45, 32, 0.1);
    }

    .inline-config-warning {
      display: flex;
      align-items: center;
      gap: 6px;
      margin-top: 0.5rem;
      color: #b42318;
      font-size: 0.7rem;
      font-weight: 800;
    }

    .byte-modal .field-form-warning {
      display: none;
      align-items: flex-start;
      gap: 8px;
      margin: 0.2rem 0 0.85rem;
      padding: 0.68rem 0.75rem;
      border: 1px solid #d92d20;
      border-radius: 10px;
      background: #fff1f0;
      color: #b42318;
      font-size: 0.76rem;
      font-weight: 750;
    }

    .byte-modal .field-form-warning.show {
      display: flex;
      animation: warningShake 0.3s ease;
    }

    .byte-modal .form-group.field-invalid input,
    .byte-modal .form-group.field-invalid select {
      border: 2px solid #d92d20 !important;
      background: #fff8f7;
      box-shadow: 0 0 0 3px rgba(217, 45, 32, 0.1);
    }

    .byte-modal .form-group.field-invalid label {
      color: #b42318 !important;
    }

    @keyframes warningShake {

      0%,      100% {
        transform: translateX(0);
      }

      30% {
        transform: translateX(-4px);
      }

      60% {
        transform: translateX(4px);
      }
    }

    .cut-target {
      position: absolute;
      z-index: 5;
      top: -8px;
      width: 5px;
      height: 26px;
      padding: 0;
      /* transform: translateX(-40%); */
      border: 0;
      background: transparent;
      cursor: pointer;
    }

    .cut-target::before {
      content: "";
      position: absolute;
      top: 20px;
      bottom: 7px;
      left: 50%;
      width: 2px;
      height: 112px;
      transform: translateX(-50%);
      border-left: 2px dashed #c6d4e5;
      pointer-events: none;
    }

    .cut-target:not(.active)::before {
      display: none;
    }

    .cut-target::after {
      content: "+";
      position: absolute;
      top: 0;
      left: 50%;
      display: grid;
      place-items: center;
      width: 20px;
      height: 20px;
      transform: translateX(-50%);
      border: 1px solid #b8c9df;
      border-radius: 50%;
      background: #fff;
      color: #47729f;
      font-size: 0.75rem;
      font-weight: 800;
    }

    .cut-target:hover::before {
      border-color: #2a6df4;
    }

    .cut-target:hover::after {
      border-color: #2a6df4;
      color: #2a6df4;
      background: #eef5ff;
    }

    .cut-target.active {
      cursor: pointer;
    }

    .cut-target.active::before {
      top: 17px;
      bottom: 1px;
      border-left: 3px solid #2a6df4;
    }

    .cut-target.active::after {
      content: "";
      width: 24px;
      height: 24px;
      top: -3px;
      border: 2px solid #2a6df4;
      background: #2a6df4;
      color: #fff;
      box-shadow: 0 3px 9px rgba(42, 109, 244, 0.28);
      font-size: 0.7rem;
    }

    .cut-target.active.partition-colored::before {
      border-left-color: var(--partition-color);
    }

    .cut-target.active.partition-colored::after {
      border-color: var(--partition-color);
      background: var(--partition-color);
    }

    .cut-target.active.dragging::after {
      transform: translateX(-50%) scale(1.12);
    }

    .timeline-empty {
      display: grid;
      place-items: center;
      min-height: 84px;
      border: 1px dashed #c4d3e5;
      border-radius: 12px;
      color: #71839a;
      font-size: 0.82rem;
      text-align: center;
      padding: 1rem;
      background: #fbfdff;
    }

    .partition-toolbar {
      display: flex;
      align-items: center;
      gap: 9px;
      flex-wrap: wrap;
      margin-top: 0.85rem;
    }

    .partition-btn {
      display: inline-flex;
