    }

    @keyframes sectionHighlight {

      0%,
      100% {
        box-shadow: none;
      }

      45% {
        box-shadow: 0 0 0 5px rgba(42, 109, 244, 0.18);
      }
    }

    /* Accessible visual refresh */
    :root {
      --primary: #175cd3;
      --primary-dark: #123c7a;
      --primary-soft: #eaf2ff;
      --ink: #102a43;
      --muted: #52677e;
      --line: #cbd8e6;
      --surface: #ffffff;
      --surface-soft: #f5f8fc;
      --success: #067647;
      --success-soft: #ecfdf3;
      --warning: #9a6700;
      --focus: rgba(23, 92, 211, 0.22);
    }

    html {
      font-size: 17px;
      scroll-behavior: smooth;
    }

    body {
      min-height: 100vh;
      color: var(--ink);
      background:
        radial-gradient(circle at top left,
          rgba(23, 92, 211, 0.11),
          transparent 30rem),
        linear-gradient(180deg, #f7fafe 0%, #edf3fa 100%);
      line-height: 1.55;
      padding: 2.2rem 1rem 4rem;
    }

    .card {
      max-width: 1240px;
      border: 1px solid rgba(164, 184, 207, 0.65);
      border-radius: 24px;
      box-shadow: 0 18px 50px -30px rgba(16, 42, 67, 0.65);
      padding: clamp(1.15rem, 3vw, 2.4rem);
    }

    .header-title {
      padding-bottom: 1.15rem;
      margin-bottom: 1.25rem;
    }

    .header-title h1 {
      color: var(--ink);
      font-size: clamp(1.55rem, 3vw, 2.05rem);
      font-weight: 800;
      letter-spacing: -0.025em;
    }

    .header-title h1 i,
    .section-title i {
      color: #dbe9e6;
    }

    .brand-badge {
      color: var(--primary-dark);
      background: var(--primary-soft);
      border-color: #b9d1f7;
      font-size: 0.88rem;
      font-weight: 750;
    }

    .product-meta {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
      gap: 0.75rem;
      background: #f8fafd;
      border-color: var(--line);
      border-radius: 16px;
      padding: 1rem;
    }

    .meta-item {
      align-items: flex-start;
      flex-direction: column;
      gap: 1px;
      padding: 0.25rem 0.5rem;
    }

    .meta-item .label {
      color: #53697f;
      font-size: 0.72rem;
      font-weight: 750;
      letter-spacing: 0.055em;
    }

    .meta-item .value,
    .meta-item .value.light {
      color: var(--ink);
      font-size: 0.98rem;
      font-weight: 700;
    }

    .section-title {
      color: var(--ink);
      font-size: 1.18rem;
      font-weight: 800;
    }

    .section-desc,
    .section-guidance {
      color: var(--muted);
      font-size: 0.92rem;
      line-height: 1.6;
    }

    .api-partition-section,
    #commandFramesSection,
    .param-grid {
      background: var(--surface) !important;
      border: 1px solid var(--line) !important;
      border-radius: 18px !important;
      box-shadow: 0 8px 24px -22px rgba(16, 42, 67, 0.8);
    }

    .api-partition-section {
      padding: clamp(1rem, 2.5vw, 1.5rem);
    }

    .param-grid {
      padding: clamp(1rem, 2.5vw, 1.4rem);
      gap: 1rem;
    }

    .step-number {
      color: #fff;
      background: var(--primary);
      border-color: var(--primary);
      font-size: 0.72rem;
      letter-spacing: 0.05em;
    }

    .selected-frame-banner,
    .linked-api-panel,
    .partition-instruction {
      border-color: #b8d0f2;
      background: #f1f6fd;
      color: var(--primary-dark);
    }

    .param-row {
      align-items: flex-end;
      gap: 1rem 1.4rem;
    }

    .param-item {
      align-items: flex-start;
      flex-direction: column;
      gap: 0.35rem;
      flex: 1 1 190px;
    }

    .param-item label,
    .api-input-wrap label,
    .byte-modal .form-group label {
      color: #294763;
      font-size: 0.83rem;
      font-weight: 750;
    }

    .param-item input,
    .param-item select,
    .api-input-wrap input,
    .byte-modal .form-group input,
    .byte-modal .form-group select {
      width: 100% !important;
      min-width: 0 !important;
      min-height: 46px;
      padding: 0.65rem 0.8rem;
      border: 1px solid #afc1d4;
      border-radius: 10px;
      color: var(--ink);
      background: #fff;
      font-size: 1rem;
      font-weight: 600;
    }

    input::placeholder {
      color: #71859a;
      opacity: 1;
    }

    button,
    select,
    input {
      font: inherit;
    }

    button {
      min-height: 44px;
      transition:
        background-color 0.15s,
        border-color 0.15s,
        box-shadow 0.15s,
        transform 0.15s;
    }

    button:hover:not(:disabled) {
      transform: translateY(-px);
    }

    button:focus-visible,
    input:focus-visible,
    select:focus-visible,
    [tabindex]:focus-visible {
      outline: 3px solid var(--focus) !important;
      outline-offset: 2px;
      border-color: var(--primary) !important;
    }

    button:disabled {
      opacity: 0.55;
      cursor: not-allowed;
      transform: none;
    }

    .generate-btn,
    .continue-btn,
    .save-btn,
    .command-entry button,
    .btn-save-modal {
      color: #fff !important;
      background: var(--primary) !important;
      border: 1px solid var(--primary) !important;
      border-radius: 10px !important;
      padding: 0.68rem 1.1rem !important;
      font-size: 0.92rem !important;
      font-weight: 750 !important;
      justify-content: center;
    }

    .generate-btn:hover,
    .continue-btn:hover,
    .save-btn:hover,
    .command-entry button:hover,
    .btn-save-modal:hover {
      background: var(--primary-dark) !important;
    }

    .demo-open-btn,
    .partition-btn,
    .btn-cancel-modal,
    .demo-popup-actions button {
      min-height: 42px;
      border-radius: 9px;
      color: var(--primary-dark);
      border: 1px solid #afc8ed;
      background: #fff;
      font-weight: 750;
    }

    .command-frame-card {
      min-height: 140px;
      border: 1px solid #bfcfe0;
      border-radius: 14px;
      background: #fff;
      padding: 1rem;
    }

    .command-frame-card:hover {
      border-color: var(--primary);
      background: #f7faff;
      box-shadow: 0 8px 20px -18px rgba(23, 92, 211, 0.8);
    }

    .command-frame-card.selected {
      border: 2px solid var(--primary);
      background: var(--primary-soft);
      box-shadow: 0 0 0 3px var(--focus);
    }

    .command-frame-card .frame-title {
      font-size: 1rem;
      font-weight: 800;
    }

    .frame-code,
    .frame-direction,
    .command-frame-hint {
      font-size: 0.8rem;
    }

    .byte-detail-popup {
      border-color: #b8cbe0;
      border-radius: 16px;
      background: #f8fbff;
    }

    .partition-status {
      font-size: 0.88rem;
      line-height: 1.5;
    }

    .partition-status.complete {
      color: var(--success);
    }

    .action-row {
      justify-content: flex-end;
      gap: 0.8rem;
    }

    .save-btn {
      margin-left: 0;
      min-width: 210px;
    }

    .save-status-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      min-height: 42px;
      padding: 0.55rem 0.85rem;
      border: 1px solid #c8d5e3;
      border-radius: 999px;
      color: #53697f;
      background: #f7f9fc;
      font-size: 0.82rem;
      font-weight: 750;
    }

    .save-status-badge.saved {
      color: var(--success);
      border-color: #86d3ad;
      background: var(--success-soft);
    }

    .save-status-badge.unsaved {
      color: var(--warning);
      border-color: #e8c76c;
      background: #fff8e1;
    }

    .save-status-badge.error {
      color: #b42318;
      border-color: #fda29b;
      background: #fff1f0;
    }

    .save-status-badge i {
      font-size: 0.92rem;
    }

    .byte-modal,
    .partition-mode-modal,
    .demo-popup {
      border: 1px solid #b8c8d9;
      border-radius: 18px;
    }

    .byte-modal-overlay,
    .partition-mode-overlay,
    .demo-overlay {
      background: rgba(16, 42, 67, 0.62);
      backdrop-filter: blur(3px);
    }

    .close-modal,
    .partition-mode-close,
    .demo-close-btn,
    .byte-detail-popup .close {
      display: grid;
      place-items: center;
      min-width: 44px;
      min-height: 44px;
      border-radius: 9px;
    }

    /* Rich icon system and purposeful micro-interactions */
    .card {
      position: relative;
      overflow: hidden;
      isolation: isolate;
    }

    .card::before {
      content: "\f121";
      position: absolute;
      z-index: -1;
      top: -64px;
      right: -35px;
      color: rgba(23, 92, 211, 0.045);
      font: 900 15rem/1 "Font Awesome 6 Free";
      transform: rotate(-10deg);
      pointer-events: none;
    }

    .title-icon {
      display: inline-grid;
      place-items: center;
      width: 46px;
      height: 46px;
      border-radius: 14px;
      color: #fff;
      background: linear-gradient(135deg, #175cd3, #6d8ff8);
      box-shadow: 0 10px 22px -10px rgba(23, 92, 211, 0.8);
      animation: titleIconFloat 3.8s ease-in-out infinite;
    }

    .brand-badge i {
      animation: tagWiggle 4s ease-in-out infinite;
      transform-origin: top center;
    }

    .meta-item {
      position: relative;
      min-height: 76px;
      padding: 0.65rem 0.65rem 0.65rem 3.35rem;
      border: 1px solid transparent;
      border-radius: 13px;
      transition:
        border-color 0.22s,
        background-color 0.22s,
        transform 0.22s,
        box-shadow 0.22s;
    }

    .meta-item:hover {
      border-color: #c7d9f2;
      background: #fff;
      box-shadow: 0 9px 20px -18px rgba(16, 42, 67, 0.8);
      transform: translateY(-2px);
    }

    .meta-icon {
      position: absolute;
      left: 0.65rem;
      top: 50%;
      display: grid;
      place-items: center;
      width: 38px;
      height: 38px;
      border-radius: 11px;
      color: var(--primary);
      background: var(--primary-soft);
      border: 1px solid #c4d8f7;
      transform: translateY(-50%);
      transition:
        transform 0.22s,
        background-color 0.22s,
        color 0.22s;
    }

    .meta-item:hover .meta-icon {
      color: #fff;
      background: var(--primary);
      transform: translateY(-50%) scale(1.08) rotate(-4deg);
    }

    .step-number {
      position: relative;
      overflow: hidden;
      box-shadow: 0 7px 15px -10px rgba(23, 92, 211, 0.8);
    }

    .step-number::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(110deg,
          transparent 25%,
          rgba(255, 255, 255, 0.5) 50%,
          transparent 75%);
      transform: translateX(-150%);
      animation: stepShine 4s ease-in-out infinite;
    }

    .section-title>i {
      display: inline-grid;
      place-items: center;
      width: 34px;
      height: 34px;
      border-radius: 10px;
      background: var(--primary-soft);
      transition:
        transform 0.2s,
        background-color 0.2s,
        color 0.2s;
    }

    .section-title:hover>i {
      color: #fff;
      background: var(--primary);
      transform: rotate(-7deg) scale(1.06);
    }

    .section-guidance,
    .section-desc {
      display: flex;
      align-items: flex-start;
      gap: 0.5rem;
    }

    .section-guidance i,
    .section-desc i {
      color: var(--primary);
      margin-top: 0.25rem;
      flex: 0 0 auto;
    }

    .control-label {
      display: flex !important;
      align-items: center;
      gap: 0.45rem;
    }

    .control-label i {
      display: inline-grid;
      place-items: center;
      width: 26px;
      height: 26px;
      border-radius: 8px;
      color: var(--primary);
      background: var(--primary-soft);
      font-size: 0.72rem;
    }

    .param-item:focus-within .control-label i,
    .api-input-wrap:focus-within .control-label i {
      color: #fff;
      background: var(--primary);
      animation: iconPop 0.28s ease;
    }

    .select-with-icon,
    .input-with-icon {
      position: relative;
      width: 100%;
    }

    .select-with-icon>i,
    .input-with-icon>i {
      position: absolute;
      z-index: 2;
      left: 0.8rem;
      top: 50%;
      color: #6280a4;
      transform: translateY(-50%);
      pointer-events: none;
    }

    .select-with-icon select,
    .input-with-icon input {
      padding-left: 2.35rem !important;
    }

    .select-with-icon:focus-within>i,
    .input-with-icon:focus-within>i {
      color: var(--primary);
      animation: iconPop 0.28s ease;
    }

    .param-grid,
    .api-partition-section,
    #commandFramesSection,
    .action-row {
      animation: sectionReveal 0.5s both;
    }

    #commandFramesSection {
      animation-delay: 0.08s;
    }

    .action-row {
      animation-delay: 0.16s;
    }

    .command-frame-card {
      position: relative;
      overflow: hidden;
      animation: cardReveal 0.38s both;
      transition:
        transform 0.22s,
        border-color 0.22s,
        background-color 0.22s,
        box-shadow 0.22s;
    }

    .command-frame-card::before {
      content: "\f120";
      position: absolute;
      right: -8px;
      bottom: -12px;
      color: rgba(23, 92, 211, 0.06);
      font: 900 4.8rem/1 "Font Awesome 6 Free";
      pointer-events: none;
      transition:
        transform 0.25s,
        color 0.25s;
    }

    .command-frame-card:hover::before {
      color: rgba(23, 92, 211, 0.12);
      transform: translate(-4px, -4px) rotate(-5deg);
    }

    .command-frame-card:hover {
      transform: translateY(-4px);
    }

    .frame-title>span {
      display: inline-flex;
      align-items: center;
      gap: 0.48rem;
    }

    .frame-title>span::before {
      content: "\f120";
      color: var(--primary);
      font: 900 0.82rem/1 "Font Awesome 6 Free";
    }

    .remove-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 5px;
      min-width: 34px;
      min-height: 30px;
      padding: 0.28rem 0.55rem;
      border-radius: 9px;
      background: #fff1f0;
      border: 1px solid #ffd1cc;
      color: #b91c1c;
      font-family: inherit;
      font-size: 0.68rem;
      font-weight: 800;
      cursor: pointer;
      transition:
        transform 0.18s,
        background-color 0.18s,
        color 0.18s;
      z-index: 2;
      position: relative;
    }

    .remove-btn:hover {
      color: #fff;
      background: #d92d20;
      border-color: #d92d20;
      transform: translateY(-1px);
    }

    .frame-delete-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      width: 100%;
      margin-top: 0.65rem;
      min-height: 34px;
      padding: 0.4rem 0.65rem;
      border: 1px solid #f0b4ad;
      border-radius: 10px;
      background: #fff7f6;
      color: #b42318;
      font-family: inherit;
      font-size: 0.74rem;
      font-weight: 800;
      cursor: pointer;
      position: relative;
      z-index: 2;
    }

    .frame-delete-btn:hover {
      background: #d92d20;
      border-color: #d92d20;
      color: #fff;
    }

    .partition-btn i,
    .generate-btn i,
    .continue-btn i,
    .save-btn i,
    .demo-open-btn i,
    .partition-mode-done i,
    .modal-actions button i,
    .demo-popup-actions button i {
      transition: transform 0.2s;
    }

    button:hover:not(:disabled) i {
      transform: scale(1.13);
    }

    .generate-btn:hover i,
    .partition-btn.primary:hover i {
      transform: rotate(135deg) scale(1.08);
    }

    .save-btn:hover i,
    .btn-save-modal:hover i {
      animation: saveBounce 0.55s ease;
    }

    button:active:not(:disabled) {
      transform: translateY(1px) scale(0.985) !important;
    }

    .save-status-badge {
      transition:
        color 0.25s,
        border-color 0.25s,
        background-color 0.25s,
        transform 0.25s,
        box-shadow 0.25s;
    }

    .save-status-badge.status-change {
      animation: statusPop 0.48s ease;
    }

    .save-status-badge.saved {
      box-shadow: 0 0 0 4px rgba(6, 118, 71, 0.08);
    }

    .save-status-badge.saved i {
      animation: savedCheck 0.55s ease;
    }

    .api-count i,
    .partition-status i,
    .linked-api-state i,
    .frame-partition-state i {
      animation: softPulse 2.4s ease-in-out infinite;
    }

    .api-byte-cell {
      animation: byteReveal 0.3s both;
    }

    .partition-name-band {
      animation: bandReveal 0.34s both;
    }

    .byte-modal-overlay[style*="flex"] .byte-modal,
    .partition-mode-overlay[style*="flex"] .partition-mode-modal,
    .demo-overlay[style*="flex"] .demo-popup {
      animation: modalEnter 0.28s cubic-bezier(0.2, 0.8, 0.2, 1) both;
    }

    .byte-modal-overlay[style*="flex"],
    .partition-mode-overlay[style*="flex"],
    .demo-overlay[style*="flex"] {
      animation: fadeIn 0.2s ease both;
    }

    .byte-detail-popup[style*="block"] {
      animation: modalEnter 0.28s cubic-bezier(0.2, 0.8, 0.2, 1) both;
    }

    .demo-step-card {
      transition:
        transform 0.2s,
        border-color 0.2s,
        box-shadow 0.2s;
      animation: cardReveal 0.42s both;
    }

    .demo-step-card:hover {
      transform: translateY(-3px);
      border-color: #90b5ec;
      box-shadow: 0 12px 25px -22px rgba(16, 42, 67, 0.9);
    }

    .demo-step-card:nth-child(2) {
      animation-delay: 0.06s;
    }

    .demo-step-card:nth-child(3) {
      animation-delay: 0.12s;
    }

    .demo-step-card:nth-child(4) {
      animation-delay: 0.18s;
    }

    .demo-step-card:nth-child(5) {
      animation-delay: 0.24s;
    }

    .interactive-icon {
      display: inline-grid;
      place-items: center;
      width: 30px;
      height: 30px;
      border-radius: 9px;
      color: var(--primary);
      background: var(--primary-soft);
    }

    .empty-command,
    .timeline-empty,
    .field-empty {
      position: relative;
      overflow: hidden;
    }

    .timeline-empty::before,
    .field-empty::before {
      content: "\f1c9";
      display: block;
      margin-bottom: 0.35rem;
      color: #9cb2ca;
      font: 900 1.4rem/1 "Font Awesome 6 Free";
      animation: softPulse 2.4s ease-in-out infinite;
    }

    @keyframes titleIconFloat {

      0%,
      100% {
        transform: translateY(0) rotate(0);
      }

      50% {
        transform: translateY(-4px) rotate(-3deg);
      }
    }

    @keyframes tagWiggle {

      0%,
      88%,
      100% {
        transform: rotate(0);
      }

      92% {
        transform: rotate(-12deg);
      }

      96% {
        transform: rotate(10deg);
      }
    }

    @keyframes stepShine {

      0%,
      60% {
        transform: translateX(-150%);
      }

      85%,
      100% {
        transform: translateX(150%);
      }
    }

    @keyframes sectionReveal {
      from {
        opacity: 0;
        transform: translateY(12px);
      }

      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @keyframes cardReveal {
      from {
        opacity: 0;
        transform: translateY(12px) scale(0.98);
      }

      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

    @keyframes byteReveal {
      from {
        opacity: 0;
        transform: translateY(-7px);
      }

      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @keyframes bandReveal {
      from {
        opacity: 0;
        transform: scaleY(0.82);
        transform-origin: top;
      }

      to {
        opacity: 1;
        transform: scaleY(1);
      }
    }

    @keyframes modalEnter {
      from {
        opacity: 0;
        transform: translateY(16px) scale(0.96);
      }

      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

    @keyframes fadeIn {
      from {
        opacity: 0;
      }

      to {
        opacity: 1;
      }
    }

    @keyframes iconPop {
      50% {
        transform: scale(1.16) rotate(-7deg);
      }
    }

    @keyframes saveBounce {

      0%,
      100% {
        transform: translateY(0);
      }

      45% {
        transform: translateY(-4px);
      }

      70% {
        transform: translateY(1px);
      }
    }

    @keyframes statusPop {
      0% {
        transform: scale(0.94);
      }

      55% {
        transform: scale(1.035);
      }

      100% {
        transform: scale(1);
      }
    }

    @keyframes savedCheck {
      0% {
        transform: scale(0.4) rotate(-30deg);
      }

      70% {
        transform: scale(1.2) rotate(5deg);
      }

      100% {
        transform: scale(1) rotate(0);
      }
    }

    @keyframes softPulse {

      0%,
      100% {
        opacity: 1;
        transform: scale(1);
      }

      50% {
        opacity: 0.68;
        transform: scale(0.92);
      }
    }

    @media (max-width: 650px) {
      html {
        font-size: 16px;
      }

      body {
        padding: 0.65rem 0.45rem 3rem;
      }

      .card {
        padding: 1rem;
        border-radius: 17px;
      }

      .header-title {
        align-items: flex-start;
        gap: 0.8rem;
      }

      .product-meta {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .param-row {
        flex-direction: column;
        align-items: stretch;
      }

      .param-item {
        flex-basis: auto;
        width: 100%;
      }

      .byte-modal {
        padding: 1.2rem;
      }

      .field-desc-header {
        align-items: stretch;
      }

      .field-desc-dropdown {
        align-items: stretch;
        flex-direction: column;
      }

      .field-desc-dropdown select {
        width: 100%;
        min-width: 0;
      }

      #fieldDescContainer {
        grid-template-columns: 1fr;
        padding: 1rem;
      }

      .field-desc-help {
        margin: 1rem 1rem 0;
      }

      .command-frame-help {
        justify-content: flex-start;
        margin-top: 0.65rem;
      }

      .command-example {
        width: 100%;
        overflow-x: auto;
      }

      .api-entry-row {
        grid-template-columns: 1fr;
      }

      .api-count {
        width: max-content;
        max-width: 100%;
      }

      .api-partition-section {
        padding: 1rem;
      }

      .section-guidance {
        margin-left: 0;
        margin-top: 5px;
      }

      .linked-api-panel {
        flex-direction: column;
      }

      .demo-open-btn {
        margin-left: 0;
      }

      .demo-steps-grid {
        grid-template-columns: 1fr;
      }

      .demo-step-card:last-child {
        grid-column: auto;
      }

      .partition-confirm-row,
      .action-row {
        align-items: stretch;
        flex-direction: column;
      }

      .continue-btn,
      .save-btn,
      .save-status-badge {
        width: 100%;
      }

      .save-status-badge {
        justify-content: center;
      }

      .card::before {
        font-size: 10rem;
      }

      .title-icon {
        width: 40px;
        height: 40px;
        border-radius: 12px;
      }

      .meta-item {
        min-height: 70px;
        padding-left: 3rem;
      }

      .meta-icon {
        width: 34px;
        height: 34px;
      }
    }

    @media (prefers-reduced-motion: reduce) {

      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }

    /* EFACTOR warm earth palette */
    :root {
      --primary: #a98b76;
      --primary-dark: #765c4b;
      --primary-soft: #f3e4c9;
      --secondary: #bfa28c;
      --sage: #babf94;
      --ink: #382e28;
      --muted: #695a50;
      --line: #d8c7b8;
      --surface: #fffdf8;
      --surface-soft: #f7f0e4;
      --success: #5f6844;
      --success-soft: #eef0de;
      --warning: #806441;
      --focus: rgba(169, 139, 118, 0.34);
    }

    body {
      color: var(--ink);
      background:
        radial-gradient(circle at top left,
          rgba(186, 191, 148, 0.34),
          transparent 31rem),
        linear-gradient(180deg, #f3e4c9 0%, #e8d6c5 100%);
    }

    .card {
      background: #fffdf8;
      border-color: #cdb9a8;
      box-shadow: 0 18px 50px -30px rgba(83, 61, 47, 0.5);
    }

    .card::before,
    .command-frame-card::before {
      color: rgba(169, 139, 118, 0.09);
    }

    .command-frame-card:hover::before {
      color: rgba(169, 139, 118, 0.17);
    }

    .header-title {
      border-color: #decdbf;
    }

    .title-icon {
