    @keyframes sectionHighlight {

      0%,
      100% {
        box-shadow: none;
      }

      45% {
        box-shadow: 0 0 0 5px rgba(169, 139, 118, 0.24);
      }
    }

    @keyframes newBytePulse {
      0% {
        transform: scale(0.85);
        box-shadow: 0 0 0 5px rgba(169, 139, 118, 0.24);
      }

      100% {
        transform: scale(1);
        box-shadow: none;
      }
    }

    /* Final simple green UI theme: solid colours and clear states */
    :root {
      --primary: #659287;
      --primary-dark: #3f6d63;
      --primary-soft: #e6f2dd;
      --secondary: #88bda4;
      --secondary-soft: #b1d3b9;
      --ink: #203b35;
      --muted: #526a64;
      --line: #b8cdc4;
      --surface: #ffffff;
      --surface-soft: #f3f8f1;
      --success: #2f765c;
      --success-soft: #e7f5ec;
      --warning: #b42318;
      --focus: rgba(101, 146, 135, 0.28);
    }

    html {
      background: #e6f2dd;
    }

    body {
      color: var(--ink);
      background: #e6f2dd !important;
      background-image: none !important;
    }

    .card {
      background: #ffffff !important;
      background-image: none !important;
      border: 1px solid #b8cdc4;
      box-shadow: 0 14px 34px -24px rgba(32, 59, 53, 0.48);
    }

    .card::before,
    .step-number::after {
      display: none;
    }

    .title-icon {
      color: #ffffff;
      background: #659287 !important;
      background-image: none !important;
      box-shadow: none;
