    .field-desc-header,
    .linked-api-panel,
    .selected-frame-banner,
    .partition-instruction,
    .command-entry,
    .field-desc-help {
      color: #355c53 !important;
      background: #e6f2dd !important;
    }

    .step-number,
    .selected-frame-banner span,
    .view-toggle-btn.active,
    .partition-btn.primary {
      color: #ffffff !important;
      background: #659287 !important;
      background-image: none !important;
      border-color: #659287 !important;
      box-shadow: none;
    }

    .generate-btn,
    .continue-btn,
    .save-btn,
    .command-entry button,
    .btn-save-modal,
    .partition-mode-done {
      color: #ffffff !important;
      background: #3f6d63 !important;
      background-image: none !important;
      border-color: #3f6d63 !important;
    }

    .generate-btn:hover,
    .continue-btn:hover,
    .save-btn:hover,
    .command-entry button:hover,
    .btn-save-modal:hover,
    .partition-mode-done:hover {
      background: #2f554d !important;
      border-color: #2f554d !important;
    }

    .demo-open-btn,
    .partition-btn,
    .btn-cancel-modal,
    .demo-popup-actions button,
    .add-frame-btn,
    .byte-wise-action {
      color: #3f6d63 !important;
      background: #ffffff !important;
      border-color: #88bda4 !important;
    }

    .demo-open-btn:hover,
    .partition-btn:hover,
    .btn-cancel-modal:hover,
    .demo-popup-actions button:hover,
    .byte-wise-action:hover {
      color: #203b35 !important;
      background: #e6f2dd !important;
      border-color: #659287 !important;
    }

    .param-item input,
    .param-item select,
    .api-input-wrap input,
    .byte-modal .form-group input,
    .byte-modal .form-group select,
    .command-entry input,
    .byte-field-select {
      color: #203b35 !important;
      background: #ffffff !important;
      border-color: #9fb9ae !important;
    }

    button:focus-visible,
    input:focus-visible,
    select:focus-visible,
    [tabindex]:focus-visible {
      outline-color: var(--focus) !important;
      border-color: #659287 !important;
    }

    .command-frame-card:hover,
    .command-frame-card.selected {
      border-color: #659287 !important;
      background: #e6f2dd !important;
      box-shadow: 0 0 0 3px rgba(101, 146, 135, 0.18);
    }

    .command-frame-card.needs-partition,
    .command-frame-card.needs-partition:hover {
      background: #fffbf2 !important;
      box-shadow: inset 0 4px 0 #f0b429 !important;
    }

    .command-frame-card.frame-in-progress,
    .command-frame-card.frame-in-progress:hover {
      border: 2px solid #2a6df4 !important;
      background: #f5f9ff !important;
      box-shadow: inset 0 4px 0 #2a6df4 !important;
    }

    .command-frame-card.partition-complete,
    .command-frame-card.partition-complete:hover {
      border: 2px solid #1b8a55 !important;
      background: #f3fbf6 !important;
      box-shadow: inset 0 4px 0 #1b8a55 !important;
    }

    .command-frame-card.selected.needs-partition {
      box-shadow:
        inset 0 4px 0 #f0b429,
        0 0 0 3px rgba(240, 180, 41, 0.28) !important;
    }

    .command-frame-card.selected.frame-in-progress {
      box-shadow:
        inset 0 4px 0 #2a6df4,
        0 0 0 3px rgba(42, 109, 244, 0.25) !important;
    }

    .command-frame-card.selected.partition-complete {
      box-shadow:
        inset 0 4px 0 #1b8a55,
        0 0 0 3px rgba(27, 138, 85, 0.25) !important;
    }

    .command-frame-card.awaiting-click,
    .command-frame-card.awaiting-click:hover {
      border-color: #2a6df4 !important;
      background: #eaf1fe !important;
      box-shadow: 0 0 0 3px rgba(42, 109, 244, 0.18) !important;
    }

    .frame-direction,
    .view-toggle-buttons {
      color: #3f6d63;
      background: #e6f2dd;
      border-color: #b1d3b9;
    }

    /* Keep Step 2 simple while preserving distinct partition colours. */
    #apiPartitionSection {
      color: #203b35;
      background: #f3f8f1 !important;
      background-image: none !important;
      border-color: #b8cdc4 !important;
      box-shadow: none;
    }

    #apiPartitionSection .step-number,
    #apiPartitionSection .partition-btn.primary {
      color: #ffffff !important;
      background: #659287 !important;
      border-color: #659287 !important;
    }

    #apiPartitionSection .selected-frame-banner {
      color: #355c53 !important;
      background: #e6f2dd !important;
      border-color: #b1d3b9 !important;
    }

    #apiPartitionSection .selected-frame-banner span {
      color: #ffffff !important;
      background: #659287 !important;
      border-color: #659287 !important;
    }

    #apiPartitionSection .partition-workspace {
      background: #ffffff !important;
      border-color: #b8cdc4 !important;
    }

    #apiPartitionSection .partition-instruction {
      color: #355c53 !important;
      background: #f3f8f1 !important;
      border-color: #b8cdc4 !important;
    }

    #apiPartitionSection .partition-instruction i,
    #apiPartitionSection .section-title i,
    #apiPartitionSection .timeline-empty::before {
      color: #659287 !important;
    }

    #apiPartitionSection .api-input-wrap input:focus {
      border-color: #659287 !important;
      box-shadow: 0 0 0 3px rgba(101, 146, 135, 0.18);
    }

    #apiPartitionSection .partition-btn {
      color: #3f6d63 !important;
      background: #ffffff !important;
      border-color: #88bda4 !important;
    }

    #apiPartitionSection .partition-btn:hover {
      color: #203b35 !important;
      background: #e6f2dd !important;
      border-color: #659287 !important;
    }

    #apiPartitionSection .continue-btn {
      color: #ffffff !important;
      background: #3f6d63 !important;
      border-color: #3f6d63 !important;
    }

    #apiPartitionSection .demo-open-btn {
      color: #3f6d63 !important;
      background: #ffffff !important;
      border-color: #88bda4 !important;
    }

    #apiPartitionSection .demo-open-btn:hover {
      color: #203b35 !important;
      background: #e6f2dd !important;
      border-color: #659287 !important;
    }

    /* Required dropdown warning state */
    .select-with-icon.dropdown-error select,
    #apiPartitionSection .partition-name-band select.dropdown-error {
      color: #8f1d16 !important;
      background: #fff4f2 !important;
      border: 2px solid #d92d20 !important;
      box-shadow: 0 0 0 3px rgba(217, 45, 32, 0.1);
    }

    .select-with-icon.dropdown-error>i {
      color: #d92d20 !important;
    }

    .input-with-icon.input-error input {
      color: #8f1d16 !important;
      background: #fff4f2 !important;
      border: 2px solid #d92d20 !important;
      box-shadow: 0 0 0 3px rgba(217, 45, 32, 0.1);
    }

    .input-with-icon.input-error>i {
      color: #d92d20 !important;
    }

    .dropdown-warning {
      display: flex;
      align-items: center;
      gap: 6px;
      width: 100%;
      margin-top: 5px;
      color: #b42318;
      font-size: 0.72rem;
      font-weight: 750;
      line-height: 1.35;
    }

    .dropdown-warning[hidden] {
      display: none;
    }

    .partition-frame-label {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      margin-top: 0.55rem;
      padding: 0.35rem 0.75rem;
      border-radius: 999px;
      background: #eaf1fe;
      border: 1px solid #c9daf8;
      color: #1a4cba;
      font-size: 0.8rem;
      font-weight: 800;
    }

    .partition-name-band.missing-selection {
      outline: none;
    }

    .partition-name-band.missing-selection.show-warning {
      outline: 3px solid rgba(217, 45, 32, 0.18);
      outline-offset: -3px;
    }

    .partition-name-band .partition-dropdown-warning {
      display: flex;
      align-items: center;
      gap: 4px;
      margin-top: 5px;
      color: #b42318;
      font-size: 0.62rem;
      font-weight: 850;
    }

    .partition-ready-hint {
      display: none;
      align-items: center;
      gap: 10px;
      margin-top: 0.75rem;
      padding: 0.75rem 0.9rem;
      border: 2px solid #659287;
      border-radius: 12px;
      color: #203b35;
      background: #eaf5ec;
      font-size: 0.8rem;
      font-weight: 800;
      line-height: 1.4;
    }

    .partition-ready-hint.show {
      display: flex;
      animation: framePartitionReveal 0.3s ease;
    }

    .partition-ready-hint i {
      flex: 0 0 auto;
      color: #3f6d63;
      font-size: 1rem;
    }

    /* Clear visual partition blocks with code and text */
    .partition-visual {
      margin-top: 1rem;
      padding: 1rem;
      border: 1px solid #b8cdc4;
      border-radius: 14px;
      background: #f3f8f1;
    }

    .partition-visual-title {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 0.75rem;
      color: #203b35;
      font-size: 0.86rem;
      font-weight: 850;
    }

    .partition-visual-title i {
      color: #659287;
    }

    .partition-blocks {
      display: flex;
      align-items: stretch;
      gap: 8px;
      width: 100%;
      overflow-x: auto;
      padding: 2px 2px 8px;
    }

    .partition-visual-block {
      position: relative;
      flex: 1 0 145px;
      min-height: 104px;
      padding: 0.75rem;
      border: 2px solid var(--partition-color);
      border-radius: 11px;
      background: var(--partition-soft);
      color: var(--partition-text);
    }

    .partition-visual-block::after {
      content: "";
      position: absolute;
      top: 50%;
      right: -10px;
      width: 10px;
      border-top: 2px solid #91a9a0;
    }

    .partition-visual-block:last-child::after {
      display: none;
    }

    .partition-visual-block.missing {
      background: #fff4f2;
      color: #8f1d16;
    }

    .partition-visual-index {
      display: block;
      margin-bottom: 4px;
      font-size: 0.62rem;
      font-weight: 900;
      letter-spacing: 0.055em;
      text-transform: uppercase;
    }

    .partition-visual-code {
      display: block;
      margin-bottom: 6px;
      color: inherit;
      font:
        850 1rem Consolas,
        Monaco,
        monospace;
      letter-spacing: 0.06em;
      overflow-wrap: anywhere;
    }

    .partition-visual-name {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 0.76rem;
      font-weight: 850;
    }

    .partition-visual-field-name {
      display: block;
      margin-top: 4px;
      font-size: 0.72rem;
      font-weight: 900;
      line-height: 1.25;
      overflow-wrap: anywhere;
    }

    .partition-visual-range {
      display: block;
      margin-top: 4px;
      font-size: 0.65rem;
      opacity: 0.78;
    }

    .partition-visual-empty {
      color: #61756f;
      font-size: 0.8rem;
    }

    @media (max-width: 650px) {
      .partition-visual-block {
        flex-basis: 132px;
      }
    }

    .generate-validation-overlay {
      display: none;
      position: fixed;
      inset: 0;
      z-index: 1300;
      padding: 20px;
      align-items: center;
      justify-content: center;
      background: rgba(28, 49, 43, 0.62);
      backdrop-filter: blur(4px);
    }

    .generate-validation-overlay.open {
      display: flex;
      animation: fadeIn 0.2s ease both;
    }

    .generate-validation-dialog {
      width: min(480px, 100%);
      overflow: hidden;
      border: 1px solid #b1d3b9;
      border-radius: 18px;
      background: #fff;
      box-shadow: 0 24px 70px rgba(28, 49, 43, 0.28);
      animation: modalEnter 0.25s cubic-bezier(0.2, 0.8, 0.2, 1) both;
    }

    .generate-validation-head {
      display: flex;
      gap: 12px;
      align-items: flex-start;
      padding: 20px;
      color: #243c35;
      background: #e6f2dd;
      border-bottom: 1px solid #b1d3b9;
    }

    .generate-validation-icon {
      display: grid;
      flex: 0 0 42px;
      width: 42px;
      height: 42px;
      place-items: center;
      border-radius: 50%;
      color: #fff;
      background: #d33c3c;
      font-size: 1.05rem;
    }

    .generate-validation-head h3 {
      margin: 0 0 5px;
      font-size: 1.12rem;
      color: #243c35;
    }

    .generate-validation-head p {
      margin: 0;
      color: #526b63;
      font-size: 0.86rem;
      line-height: 1.5;
    }

    /* Saved JSON confirmation popup */
    .json-save-overlay {
      position: fixed;
      inset: 0;
      z-index: 1600;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 20px;
      background: rgba(28, 49, 43, 0.65);
      backdrop-filter: blur(4px);
    }

    .json-save-overlay.open {
      display: flex;
      animation: fadeIn 0.2s ease both;
    }

    .json-save-dialog {
      width: min(1180px, 100%);
      max-height: min(92vh, 920px);
      display: flex;
      flex-direction: column;
      overflow: hidden;
      border: 1px solid #b1d3b9;
      border-radius: 18px;
      background: #fff;
      box-shadow: 0 24px 70px rgba(28, 49, 43, 0.3);
      animation: modalEnter 0.25s cubic-bezier(0.2, 0.8, 0.2, 1) both;
    }

    .json-save-head {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 18px 20px;
      color: #243c35;
      background: #e6f2dd;
      border-bottom: 1px solid #b1d3b9;
    }

    .json-save-head>i {
      display: grid;
      flex: 0 0 42px;
      width: 42px;
      height: 42px;
      place-items: center;
      border-radius: 50%;
      color: #fff;
      background: #2f7d61;
    }

    .json-save-head h3 {
      margin: 0 0 3px;
      font-size: 1.1rem;
    }

    .json-save-head p {
      margin: 0;
      color: #526b63;
      font-size: 0.85rem;
    }

    .json-save-close {
      width: 38px;
      height: 38px;
      margin-left: auto;
      border: 0;
      border-radius: 10px;
      color: #3f5d53;
      background: rgba(255, 255, 255, 0.8);
      cursor: pointer;
    }

    .json-save-body {
      min-height: 0;
      padding: 18px 20px 24px;
      overflow: auto;
      background: #f7f4f1;
    }

    .json-save-code[hidden] {
      display: none !important;
    }

    .configuration-data-preview {
      display: grid;
      gap: 18px;
      color: #24273d;
    }

    .preview-summary-card {
      overflow: hidden;
      border: 1px solid #d8d5d0;
      border-radius: 12px;
      background: #fff;
      box-shadow: 0 8px 24px rgba(31, 35, 55, 0.07);
    }

    .preview-summary-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 14px;
      padding: 15px 17px;
      color: #fff;
      background: #292d49;
    }

    .preview-summary-head h4,
    .preview-frame-section-title h4 {
      margin: 0;
      font-size: 0.88rem;
      font-weight: 800;
      letter-spacing: 0.045em;
      text-transform: uppercase;
    }

    .preview-summary-head p {
      margin: 3px 0 0;
      color: #d9dced;
      font-size: 0.72rem;
    }

    .preview-count-badges {
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      gap: 7px;
    }

    .preview-count-badge {
      padding: 5px 9px;
      border: 1px solid rgba(255, 255, 255, 0.28);
      border-radius: 999px;
      color: #fff;
      background: rgba(255, 255, 255, 0.09);
      font-size: 0.63rem;
      font-weight: 800;
      letter-spacing: 0.035em;
      text-transform: uppercase;
      white-space: nowrap;
    }

    .preview-product-grid {
      display: grid;
      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 9px;
      padding: 13px;
      background: #fbfaf9;
    }

    .preview-product-field {
      min-width: 0;
      padding: 10px 11px;
      border: 1px solid #ded9d3;
      border-radius: 8px;
      background: #fff;
    }

    .preview-product-field.wide {
      grid-column: span 2;
    }

    .preview-product-label {
      display: block;
      margin-bottom: 5px;
      color: #bf6f30;
      font-size: 0.62rem;
      font-weight: 800;
      letter-spacing: 0.045em;
      text-transform: uppercase;
    }

    .preview-product-value {
      display: block;
      overflow-wrap: anywhere;
      color: #25283e;
      font-size: 0.78rem;
      font-weight: 750;
    }

    .preview-frame-section {
      overflow: hidden;
      border: 1px solid #d9d3cd;
      border-radius: 10px;
      background: #fff;
    }

    .preview-frame-section-title {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      padding: 12px 14px;
      border-bottom: 1px solid #d9d3cd;
      background: #eeeae6;
    }

    .preview-frame-section-title span {
      color: #606375;
      font-size: 0.68rem;
      font-weight: 750;
    }

    .preview-frame-list {
      display: grid;
      gap: 14px;
      padding: 11px;
    }

    .preview-frame-card {
      overflow: hidden;
      border: 1px solid #d9cabb;
      border-radius: 8px;
      background: #fff;
    }

    .preview-frame-card-head,
    .preview-row-caption {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      padding: 9px 11px;
      color: #34374d;
      background: #faf7f4;
      font-size: 0.72rem;
      font-weight: 800;
    }

    .preview-frame-code {
      overflow-wrap: anywhere;
      color: #7f4c26;
      font-family: Consolas, Monaco, "Courier New", monospace;
    }

    .preview-row-caption {
      border-top: 1px solid #e3d8ce;
      border-bottom: 1px solid #e3d8ce;
      color: #5f634f;
      background: #f2f4e9;
      text-transform: uppercase;
      letter-spacing: 0.035em;
    }

    .preview-field-table {
      width: 100%;
      border-collapse: collapse;
      table-layout: fixed;
      font-size: 0.7rem;
    }

    .preview-field-table th,
    .preview-field-table td {
      padding: 7px 10px;
      border-bottom: 1px solid #e8ddd3;
      text-align: left;
      vertical-align: top;
      overflow-wrap: anywhere;
    }

    .preview-field-table tr:last-child th,
    .preview-field-table tr:last-child td {
      border-bottom: 0;
    }

    .preview-field-table tr:nth-child(even) {
      background: #fcfaf8;
    }

    .preview-field-table th {
      width: 34%;
      color: #565b72;
      font-weight: 750;
    }

    .preview-field-table td {
      color: #24273d;
      font-weight: 650;
    }

    .preview-empty {
      padding: 22px;
      color: #747789;
      text-align: center;
      font-size: 0.78rem;
    }

    @media (max-width: 900px) {
      .preview-product-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }
    }

    @media (max-width: 640px) {
      .json-save-overlay {
        padding: 8px;
      }

      .json-save-dialog {
        max-height: 96vh;
        border-radius: 12px;
      }

      .json-save-head,
      .json-save-body,
      .json-save-actions {
        padding-left: 12px;
        padding-right: 12px;
      }

      .preview-summary-head {
        align-items: flex-start;
        flex-direction: column;
      }

      .preview-count-badges {
        justify-content: flex-start;
      }

      .preview-product-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .preview-product-field.wide {
        grid-column: span 2;
      }

      .preview-field-table th {
        width: 42%;
      }
    }

    .json-save-actions {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      gap: 10px;
      padding: 14px 20px;
      border-top: 1px solid #d9e6de;
      background: #fff;
    }

    .json-copy-status {
      margin-right: auto;
      color: #2f7d61;
      font-size: 0.84rem;
      font-weight: 700;
    }

    .json-save-actions button {
      min-height: 40px;
      padding: 0 16px;
      border: 1px solid #88bda4;
      border-radius: 10px;
      color: #29483e;
      background: #e6f2dd;
      font-weight: 700;
      cursor: pointer;
    }

    .json-save-actions .json-done-btn {
      color: #fff;
      background: #4f8072;
      border-color: #4f8072;
    }

    @media (max-width: 640px) {
      .json-save-actions {
        flex-wrap: wrap;
      }

      .json-copy-status {
        width: 100%;
      }

      .json-save-actions button {
        flex: 1 1 130px;
      }
    }

    .generate-validation-body {
      padding: 18px 20px 8px;
    }

    .generate-missing-list {
      display: grid;
      gap: 9px;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .generate-missing-item {
      display: flex;
      gap: 10px;
      align-items: center;
      min-height: 44px;
      padding: 10px 12px;
      border: 1px solid #f0b4b4;
      border-radius: 10px;
      color: #872525;
      background: #fff5f5;
      font-weight: 750;
    }

    .generate-missing-item i {
      color: #d33c3c;
    }

    .generate-validation-actions {
      display: flex;
      justify-content: flex-end;
      gap: 10px;
      padding: 14px 20px 20px;
    }

    .generate-validation-actions button {
      min-height: 42px;
      padding: 9px 17px;
      border: 0;
      border-radius: 10px;
      color: #fff;
      background: #659287;
      font-family: inherit;
      font-size: 0.86rem;
      font-weight: 800;
      cursor: pointer;
    }

    .generate-validation-actions button:hover,
    .generate-validation-actions button:focus-visible {
      background: #4f796f;
      outline: 3px solid rgba(136, 189, 164, 0.35);
      outline-offset: 2px;
    }

    @media (prefers-reduced-motion: reduce) {

      .generate-validation-overlay.open,
      .generate-validation-dialog {
        animation: none;
      }
    }

    /* Progressive guidance (hints before red warnings) */
    .field-setup-hint {
      display: flex;
      align-items: center;
      gap: 5px;
      margin-top: 5px;
      color: #5a7394;
      font-size: 0.7rem;
      font-weight: 650;
      line-height: 1.35;
    }

    .field-setup-hint i {
      color: #2a6df4;
      font-size: 0.72rem;
    }

    .field-setup-hint[hidden],
    .dropdown-warning[hidden] {
      display: none !important;
    }

    .param-item.has-error .field-setup-hint {
      display: none;
    }

    .frames-next-banner {
      display: none;
      align-items: center;
      gap: 12px;
      margin: 0 0 1rem;
      padding: 0.85rem 1rem;
      border: 2px solid #2a6df4;
      border-radius: 14px;
      background: linear-gradient(135deg, #eaf1fe 0%, #f5f9ff 100%);
      color: #153a7a;
      font-size: 0.86rem;
      font-weight: 750;
      line-height: 1.4;
      animation: framePartitionReveal 0.35s ease;
    }

    .frames-next-banner.show {
      display: flex;
    }

    .frames-next-banner i {
      flex: 0 0 auto;
      font-size: 1.15rem;
      color: #2a6df4;
    }

    .frames-next-banner strong {
      color: #0b1a33;
    }

    .command-frame-card.awaiting-click {
      border-color: #2a6df4;
      box-shadow: 0 0 0 3px rgba(42, 109, 244, 0.18);
      animation: cardClickPulse 1.4s ease-in-out infinite;
    }

    .frame-config-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      width: 100%;
      margin-top: 0.55rem;
      min-height: 34px;
      padding: 0.4rem 0.65rem;
      border: 1px solid #2a6df4;
      border-radius: 10px;
      background: #2a6df4;
      color: #fff;
      font-family: inherit;
      font-size: 0.74rem;
      font-weight: 800;
      cursor: pointer;
      position: relative;
      z-index: 2;
    }

    .frame-config-btn:hover {
      background: #1a4cba;
      border-color: #1a4cba;
    }

    .command-frame-card.partition-complete .frame-config-btn {
      background: #1b8a55;
      border-color: #1b8a55;
    }

    .command-frame-card.partition-complete .frame-config-btn:hover {
      background: #147248;
      border-color: #147248;
    }

    @keyframes cardClickPulse {

      0%,
      100% {
        transform: translateY(0);
        box-shadow: 0 0 0 3px rgba(42, 109, 244, 0.16);
      }

      50% {
        transform: translateY(-3px);
        box-shadow: 0 8px 18px rgba(42, 109, 244, 0.22);
      }
    }

    @media (prefers-reduced-motion: reduce) {
      .command-frame-card.awaiting-click {
        animation: none;
      }
    }

    /* Partition howto strip */
    .partition-howto {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 8px;
      margin: 0.75rem 0 0.35rem;
    }

    .partition-howto-step {
      display: flex;
      gap: 8px;
      align-items: flex-start;
      padding: 0.65rem 0.7rem;
      border: 1px solid #d5e3f5;
      border-radius: 12px;
      background: #f7faff;
      color: #355070;
      font-size: 0.72rem;
      font-weight: 700;
      line-height: 1.35;
    }

    .partition-howto-step .howto-num {
      display: grid;
      place-items: center;
      flex: 0 0 22px;
      width: 26px;
      height: 26px;
      border-radius: 50%;
      background: #2a6df4;
      color: #fff;
      font-size: 0.68rem;
      font-weight: 900;
    }

    .partition-howto-step i {
      color: #2a6df4;
      margin-right: 2px;
    }

    .partition-howto-step strong {
      display: block;
      color: #0b1a33;
      margin-bottom: 2px;
      font-size: 0.74rem;
    }

    .partition-howto-step .howto-description {
      display: block;
    }

    .cut-target {
      display: grid;
      place-items: start center;
    }

    .cut-target .cut-chip {
      position: absolute;
      top: 0;
      left: 50%;
      z-index: 2;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 3px;
      min-width: 26px;
      height: 26px;
      padding: 0 5px;
      transform: translateX(-50%);
      border: 1px solid #b8c9df;
      border-radius: 999px;
      background: #fff;
      color: #47729f;
      font-size: 0.62rem;
      font-weight: 850;
      box-shadow: 0 2px 6px rgba(20, 45, 80, 0.08);
      pointer-events: none;
      transition: none !important;
    }

    .cut-target::after {
      content: none !important;
    }

    .cut-target:hover .cut-chip {
      border-color: #e34b4b;
      color: #e34b4b;
      background: #fff1f1;
      transform: translateX(-50%);
    }

    .cut-target.active .cut-chip {
      min-width: 26px;
      height: 26px;
      top: -3px;
      border: 2px solid #e34b4b;
      background: #e34b4b;
      color: #fff;
      box-shadow: 0 3px 9px rgba(227, 75, 75, 0.28);
    }

    .cut-target.active.partition-colored .cut-chip {
      border-color: var(--partition-color);
      background: var(--partition-color);
    }

    /* Stable cut controls: hover changes only color/opacity, never geometry. */
    .cut-target,
    .cut-target .cut-chip {
      will-change: auto;
    }

    .cut-target .cut-hover-tip {
      position: absolute;
      z-index: 12;
      top: -38px;
      left: 50%;
      width: max-content;
      max-width: 230px;
      padding: 0.42rem 0.62rem;
      transform: translate(-50%, 4px);
      border: 1px solid #cad7e7;
      border-radius: 9px;
      background: #172b43;
      color: #fff;
      box-shadow: 0 8px 20px rgba(15, 35, 58, 0.18);
      font-size: 0.66rem;
      font-weight: 750;
      line-height: 1.25;
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      transition: opacity 150ms ease, transform 150ms ease, visibility 150ms ease;
    }

    .cut-target:hover .cut-hover-tip,
    .cut-target:focus-visible .cut-hover-tip {
      opacity: 1;
      visibility: visible;
      transform: translate(-50%, 0);
    }

    .cut-target .cut-nudges {
      position: absolute;
      z-index: 11;
      top: -2px;
      left: 50%;
      display: flex;
      align-items: center;
      gap: 34px;
      transform: translateX(-50%);
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      transition: opacity 150ms ease, visibility 150ms ease;
    }

    .cut-target.active:hover .cut-nudges,
    .cut-target.active:focus-within .cut-nudges {
      opacity: 1;
      visibility: visible;
      pointer-events: auto;
    }

    .cut-nudge {
      display: inline-grid;
      place-items: center;
      width: 25px;
      height: 25px;
      border: 1px solid #b9c9dc;
      border-radius: 8px;
      background: #fff;
      color: #28496d;
      box-shadow: 0 5px 14px rgba(18, 47, 78, 0.16);
      font-size: 0.65rem;
      transition: color 140ms ease, background 140ms ease, border-color 140ms ease, transform 140ms ease;
    }

    .cut-nudge:not(.disabled):hover {
      border-color: #2a6df4;
      background: #eef5ff;
      color: #1746a2;
      transform: translateY(-1px);
    }

    .cut-nudge.disabled {
      opacity: 0.38;
      cursor: not-allowed;
    }

    @media (prefers-reduced-motion: reduce) {
      .cut-target .cut-hover-tip,
      .cut-target .cut-nudges,
      .cut-nudge {
        transition: none;
      }
    }

    .cut-coach {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin-top: 0.55rem;
    }

    .cut-coach-pill {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 0.35rem 0.65rem;
      border-radius: 999px;
      border: 1px dashed #9bb4d4;
      background: #fff;
      color: #3d5778;
      font-size: 0.68rem;
      font-weight: 750;
    }

    .cut-coach-pill i {
      color: #2a6df4;
    }

    .partition-name-band .partition-dropdown-hint {
      display: flex;
      align-items: center;
      gap: 4px;
      margin-top: 5px;
      color: #5a7394;
      font-size: 0.62rem;
      font-weight: 750;
    }

    .partition-name-band .partition-dropdown-hint i {
      color: #2a6df4;
    }

    .partition-name-band.missing-selection.show-warning {
      outline: 3px solid rgba(217, 45, 32, 0.18);
      outline-offset: -3px;
    }

    .partition-name-band:not(.show-warning) .partition-dropdown-warning {
      display: none;
    }

    .partition-name-band.show-warning .partition-dropdown-hint {
      display: none;
    }

    /* Redesigned partition block preview */
    .partition-visual {
      margin-top: 1rem;
      padding: 1rem 1.05rem 1.1rem;
      border: 1px solid #c5d7eb;
      border-radius: 16px;
      background:
        linear-gradient(180deg, #f8fbff 0%, #eef5ff 100%);
    }

    .partition-visual-title {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      margin-bottom: 0.85rem;
      color: #17345f;
      font-size: 0.88rem;
      font-weight: 850;
    }

    .partition-visual-title>span {
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }

    .partition-visual-title i {
      color: #2a6df4;
    }

    .partition-visual-legend {
      color: #5d7596;
      font-size: 0.68rem;
      font-weight: 700;
    }

    .partition-config-open-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 5px;
      width: 100%;
      margin-top: 0.45rem;
      min-height: 30px;
      padding: 0.35rem 0.45rem;
      border: 1px solid var(--partition-color, #2a6df4);
      border-radius: 8px;
      background: #fff;
      color: var(--partition-text, #1746a2);
      font-family: inherit;
      font-size: 0.64rem;
      font-weight: 850;
      cursor: pointer;
      transition:
        background-color 0.18s,
        transform 0.18s,
        box-shadow 0.18s;
    }

    .partition-config-open-btn:hover:not(:disabled) {
      background: var(--partition-soft, #eef5ff);
      transform: translateY(-1px);
    }

    .partition-config-open-btn:disabled {
      opacity: 0.55;
      cursor: not-allowed;
    }

    .partition-config-open-btn.config-ready {
      border-color: #1b8a55;
      color: #167647;
      background: #f3fbf6;
    }

    .partition-config-open-btn.config-missing {
      border-color: #d92d20;
      color: #b42318;
      background: #fff4f2;
    }

    /* Byte-box style partition preview */
    .partition-blocks {
      display: flex;
      align-items: stretch;
      gap: 14px;
      width: 100%;
      overflow-x: auto;
      padding: 4px 2px 10px;
    }

    .partition-visual-block {
      position: relative;
      flex: 0 0 auto;
      min-width: 132px;
      margin-right: 0;
      padding: 0.7rem 0.7rem 0.75rem;
      border: 2px solid var(--partition-color);
      border-radius: 14px;
      background: #fff;
      color: var(--partition-text);
      box-shadow: 0 8px 18px rgba(15, 40, 80, 0.06);
    }

    .partition-visual-block::after {
      content: "";
      position: absolute;
      top: 50%;
      right: -12px;
      width: 10px;
      height: 10px;
      border-top: 2px solid #9bb0c9;
      border-right: 2px solid #9bb0c9;
      transform: translateY(-50%) rotate(45deg);
    }

    .partition-visual-block:last-child::after {
      display: none;
    }

    .partition-visual-block.missing {
      border-color: #d92d20;
      background: #fff8f7;
      color: #8f1d16;
    }

    .partition-visual-index {
      display: inline-flex;
      align-items: center;
      gap: 5px;
      margin-bottom: 8px;
      padding: 0.15rem 0.45rem;
      border-radius: 999px;
      background: var(--partition-soft);
      font-size: 0.62rem;
      font-weight: 900;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .partition-byte-boxes {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
      margin-bottom: 8px;
    }

    .partition-byte-box {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-width: 46px;
      min-height: 52px;
      padding: 0.3rem 0.35rem;
      border: 1.5px solid var(--partition-color);
      border-radius: 10px;
      background: var(--partition-soft);
      box-shadow: inset 0 3px 0 var(--partition-color);
    }

    .partition-byte-box .byte-box-index {
      color: var(--partition-text);
      opacity: 0.7;
      font-size: 0.55rem;
      font-weight: 800;
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    .partition-byte-box .byte-box-value {
      margin-top: 2px;
      color: var(--partition-text);
      font:
        850 0.95rem Consolas,
        Monaco,
        monospace;
      letter-spacing: 0.05em;
    }

    .partition-visual-name {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 0.76rem;
      font-weight: 850;
    }

    .partition-visual-range {
      display: block;
      margin-top: 5px;
      opacity: 0.72;
      font-size: 0.64rem;
      font-weight: 700;
    }

    .partition-visual-empty {
      display: flex;
      align-items: center;
      gap: 8px;
      width: 100%;
      padding: 1rem;
      border: 1px dashed #b7c9df;
      border-radius: 12px;
      background: #fff;
      color: #61756f;
      font-size: 0.8rem;
      font-weight: 650;
    }

    .partition-visual-block .partition-config-open-btn {
      margin-top: 0.55rem;
    }

    #apiPartitionSection .partition-byte-box {
      border-color: var(--partition-color);
      background: var(--partition-soft);
    }

    #apiPartitionSection .partition-config-open-btn {
      border-color: var(--partition-color);
      color: var(--partition-text);
    }

    /* Wider Field Configuration layout */
    #modalFieldForm {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 0.9rem 1rem;
      align-items: start;
    }

    #modalFieldForm .ui-type-group,
    #modalFieldForm .field-dynamic-group,
    #modalFieldForm .default-value-group {
      grid-column: 1 / -1;
    }

    #modalFieldForm .form-group {
      margin-bottom: 0;
    }

    /* Field Configuration top row:
       Name | Data Type | Value Definition */
    #modalFieldForm .field-basic-row {
      grid-column: 1 / -1;
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.9rem 1rem;
      align-items: start;
      min-width: 0;
    }

    #modalFieldForm .field-basic-row > .form-group {
      min-width: 0;
    }

    #modalFieldForm .field-basic-row input,
    #modalFieldForm .field-basic-row select {
      width: 100%;
      min-width: 0;
    }

    .field-dynamic-group[hidden] {
      display: none !important;
    }

    @media (max-width: 700px) {
      #modalFieldForm {
        grid-template-columns: 1fr;
      }

      #modalFieldForm .field-basic-row {
        grid-template-columns: 1fr;
      }

      #modalFieldForm .ui-type-group,
      #modalFieldForm .field-dynamic-group {
        grid-column: auto;
      }
    }

    .byte-modal .form-group input.backend-value-loading {
      background-image: linear-gradient(90deg, transparent, rgba(101, 146, 135, 0.14), transparent) !important;
      background-size: 220% 100% !important;
      animation: backendValueLoading 1.1s linear infinite;
    }

    @keyframes backendValueLoading {
      from { background-position: 220% 0; }
      to { background-position: -220% 0; }
    }

    /* UI Type visual picker */
    .ui-type-picker {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px;
      max-height: 260px;
      overflow: auto;
      padding: 2px;
    }

    .ui-type-option {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 0.55rem 0.6rem;
      border: 1px solid #d7e2f0;
      border-radius: 12px;
      background: #fbfcff;
      color: #243b57;
      text-align: left;
      cursor: pointer;
      transition:
        border-color 0.18s,
        background-color 0.18s,
        box-shadow 0.18s;
    }

    .ui-type-option:hover {
      border-color: #8fb0ea;
      background: #f3f7ff;
    }

    .ui-type-option.active {
      border-color: #2a6df4;
      background: #eaf1fe;
      box-shadow: 0 0 0 2px rgba(42, 109, 244, 0.15);
    }

    .ui-type-option .ui-preview {
      flex: 0 0 42px;
      width: 42px;
      height: 32px;
      display: grid;
      place-items: center;
      border-radius: 8px;
      background: #fff;
      border: 1px solid #dce6f4;
      color: #2a6df4;
      font-size: 0.9rem;
    }

    .ui-type-option .ui-preview-label {
      display: flex;
      flex-direction: column;
      gap: 2px;
      min-width: 0;
    }

    .ui-type-option .ui-preview-label strong {
      font-size: 0.72rem;
      font-weight: 800;
      line-height: 1.2;
    }

    .ui-type-option .ui-preview-label small {
      color: #6a7f9b;
      font-size: 0.62rem;
      font-weight: 650;
    }

    .ui-preview-switch {
      position: relative;
      width: 28px;
      height: 16px;
      border-radius: 999px;
      background: #2a6df4;
    }

    .ui-preview-switch::after {
      content: "";
      position: absolute;
      top: 2px;
      right: 2px;
      width: 12px;
      height: 12px;
      border-radius: 50%;
      background: #fff;
    }

    .ui-preview-slider {
      position: relative;
      width: 28px;
      height: 4px;
      border-radius: 999px;
      background: #c9d7ea;
    }

    .ui-preview-slider::after {
      content: "";
      position: absolute;
      top: -4px;
      left: 14px;
      width: 12px;
      height: 12px;
      border-radius: 50%;
      background: #2a6df4;
    }

    .ui-preview-btn {
      width: 26px;
      height: 14px;
      border-radius: 5px;
      background: #2a6df4;
    }

    .ui-preview-input {
      width: 28px;
      height: 12px;
      border-radius: 4px;
      border: 1px solid #b8c9df;
      background: #fff;
    }

    .ui-preview-toast {
      width: 28px;
      height: 12px;
      border-radius: 6px;
      background: #243b57;
    }

    .ui-preview-circle {
      width: 16px;
      height: 16px;
      border-radius: 50%;
      border: 3px solid transparent;
      border-top-color: #ef4444;
      border-right-color: #f59e0b;
      border-bottom-color: #22c55e;
      border-left-color: #3b82f6;
    }

    .ui-preview-dropdown {
      width: 28px;
      height: 14px;
      border-radius: 4px;
      border: 1px solid #b8c9df;
      background: linear-gradient(#fff 60%, #e8eef8 60%);
    }

    #fUiType {
      position: absolute;
      opacity: 0;
      pointer-events: none;
      width: 1px;
      height: 1px;
    }

    .form-group.ui-type-group {
      position: relative;
    }

    @media (max-width: 650px) {
      .partition-howto {
        grid-template-columns: 1fr;
      }

      .ui-type-picker {
        grid-template-columns: 1fr;
      }

      .partition-visual-block {
        flex-basis: 140px;
      }
    }
    .frame-type-row {
      width: 100%;
      display: flex;
      align-items: center;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .frame-type-switcher {
      display: inline-flex;
      gap: 0.55rem;
      flex-wrap: wrap;
      padding: 0.4rem;
      border: 1px solid #dbe6f5;
      border-radius: 14px;
      background: #f8fbff;
    }

    .frame-type-btn {
      border: 1px solid #cbd8e8;
      border-radius: 10px;
      padding: 0.72rem 1rem;
      background: #fff;
      color: #405168;
      font-weight: 700;
      cursor: pointer;
      transition: 0.2s ease;
    }

    .frame-type-btn:hover {
      border-color: #659287;
      color: #365e54;
    }

    .frame-type-btn.active {
      color: #fff;
      background: #659287;
      border-color: #659287;
      box-shadow: 0 5px 14px rgba(101, 146, 135, 0.24);
    }

    .frame-type-btn .type-count {
      display: inline-flex;
      min-width: 1.35rem;
      height: 1.35rem;
      align-items: center;
      justify-content: center;
      margin-left: 0.3rem;
      padding: 0 0.3rem;
      border-radius: 999px;
      background: rgba(101, 146, 135, 0.12);
      font-size: 0.75rem;
    }

    .frame-type-btn.active .type-count {
      background: rgba(255, 255, 255, 0.22);
    }

    /* =========================================================
       Modern form layout
       Visual-only overrides: existing IDs, events and payloads stay intact.
       ========================================================= */
    :root {
      --ui-primary: #376f64;
      --ui-primary-strong: #28584f;
      --ui-primary-soft: #edf7f3;
      --ui-accent: #5f8f84;
      --ui-ink: #172b26;
      --ui-muted: #667972;
      --ui-line: #dce7e2;
      --ui-surface: #ffffff;
      --ui-canvas: #f4f8f6;
      --ui-danger: #c9362b;
      --ui-danger-soft: #fff2f1;
      --ui-warning: #b7791f;
      --ui-success: #168052;
      --ui-radius-lg: 22px;
      --ui-radius-md: 14px;
      --ui-shadow: 0 18px 50px rgba(29, 65, 56, 0.1);
      --ui-control-shadow: 0 1px 2px rgba(29, 65, 56, 0.04);
    }

    html {
      color-scheme: light;
      scroll-behavior: smooth;
    }

    body {
      min-height: 100vh;
      padding: clamp(12px, 2.5vw, 34px);
      background:
        radial-gradient(circle at 5% 0%, rgba(136, 189, 164, 0.2), transparent 28rem),
        linear-gradient(180deg, #f7faf8 0%, var(--ui-canvas) 100%);
      color: var(--ui-ink);
      line-height: 1.5;
    }

    .card {
      width: min(100%, 1280px);
      max-width: 1280px;
      padding: clamp(18px, 3vw, 38px);
      overflow: hidden;
      border: 1px solid rgba(101, 146, 135, 0.2);
      border-radius: 26px;
      background: rgba(255, 255, 255, 0.96);
      box-shadow: var(--ui-shadow);
    }

    .header-title {
      border-bottom: 1px solid #70b990 !important;
    background: linear-gradient(150deg, #94bdab, #274737) !important;
}
      align-items: flex-start;
      gap: 20px;
      margin-bottom: 2px;
      padding-bottom: 22px;
      border-bottom: 1px solid var(--ui-line);
    }

    .page-heading-copy {
      min-width: 0;
    }

    .page-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 7px;
      margin-bottom: 7px;
      color: var(--ui-primary);
      font-size: 0.72rem;
      font-weight: 850;
      letter-spacing: 0.11em;
      text-transform: uppercase;
    }

    .header-title h1 {
      margin: 0;
      color: var(--ui-ink);
      font-size: clamp(1.45rem, 3vw, 2rem);
      font-weight: 780;
      letter-spacing: -0.035em;
    }

    .header-subtitle {
      max-width: 680px;
      margin-top: 7px;
      color: var(--ui-muted);
      font-size: 0.91rem;
    }

    .title-icon {
      display: grid;
      place-items: center;
      width: 42px;
      height: 42px;
      border-radius: 13px;
      background: var(--ui-primary-soft);
      color: var(--ui-primary);
      box-shadow: inset 0 0 0 1px rgba(55, 111, 100, 0.13);
    }

    .brand-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      max-width: 100%;
      padding: 9px 14px;
      border: 1px solid #cfe1d9;
      border-radius: 999px;
      background: var(--ui-primary-soft);
      color: var(--ui-primary-strong);
      font-size: 0.82rem;
      box-shadow: none;
    }

    .product-meta {
      display: grid;
      grid-template-columns: repeat(5, minmax(130px, 1fr));
      gap: 10px;
      margin-bottom: 24px;
      padding: 10px;
      border: 1px solid var(--ui-line);
      border-radius: var(--ui-radius-lg);
      background: #f9fbfa;
    }

    .product-meta .meta-item {
      display: grid;
      grid-template-columns: 34px minmax(0, 1fr);
      column-gap: 80px;
      min-width: 0;
      padding: 11
      px;
      border-radius: 14px;
      background: var(--ui-surface);
    }

    .meta-item .meta-icon {
      grid-row: 1 / 3;
      display: grid;
      place-items: center;
      width: 34px;
      height: 34px;
      align-self: center;
      border-radius: 10px;
      background: var(--ui-primary-soft);
      color: var(--ui-primary);
    }

    .meta-item .label {
      color: var(--ui-muted);
      font-size: 0.64rem;
      font-weight: 800;
      letter-spacing: 0.08em;
    }

    .meta-item .value,
    .meta-item .value.light {
      min-width: 0;
      overflow: hidden;
      color: var(--ui-ink);
      font-size: 0.86rem;
      font-weight: 750;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .command-response-error-flow {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr) auto minmax(0, 1fr);
      align-items: center;
      gap: 12px;
      margin: 0 0 20px;
      padding: 10px;
      border: 1px solid var(--ui-line);
      border-radius: var(--ui-radius-lg);
      background: #f7faf8;
    }

    .flow-stage {
      min-width: 0;
      min-height: 64px;
      padding: 10px 14px;
      border: 1px solid transparent;
      border-radius: 15px;
      background: transparent;
      color: var(--ui-muted);
      box-shadow: none;
    }

    .flow-stage:hover:not(:disabled) {
      border-color: #c8dbd3;
      background: #fff;
      color: var(--ui-primary-strong);
      transform: none;
    }

    .flow-stage.active {
      border-color: var(--ui-primary);
      background: var(--ui-primary);
      color: #fff;
      box-shadow: 0 9px 22px rgba(55, 111, 100, 0.22);
    }

    .flow-stage.completed:not(.active),
    .flow-stage.filled:not(.active) {
      border-color: #a8d6c0;
      background: #eef9f3;
      color: var(--ui-success);
    }

    .flow-arrow {
      color: #9aacA5;
      font-size: 0.78rem;
    }

    .section,
    #commandFramesSection,
    #apiPartitionSection {
      margin-top: 20px !important;
      padding: clamp(16px, 2.3vw, 26px) !important;
      border: 1px solid var(--ui-line) !important;
      border-radius: var(--ui-radius-lg) !important;
      background: var(--ui-surface) !important;
      box-shadow: 0 7px 24px rgba(29, 65, 56, 0.055) !important;
    }

    .step-heading {
      gap: 12px;
      margin-bottom: 18px;
      padding-bottom: 14px;
      border-bottom: 1px solid var(--ui-line);
    }

    .step-number {
      min-width: auto;
      padding: 6px 10px;
      border-radius: 999px;
      background: var(--ui-primary);
      color: #fff;
      font-size: 0.66rem;
      font-weight: 850;
      letter-spacing: 0.08em;
      box-shadow: none;
    }

    .step-number::after {
      display: none;
    }

    .section-title,
    #apiPartitionSection .section-title {
      color: var(--ui-ink) !important;
      font-size: 1.03rem;
      font-weight: 790;
    }

    .section-title i,
    #apiPartitionSection .section-title i {
      color: var(--ui-primary) !important;
    }

    .section-guidance:not(:empty) {
      display: flex;
      align-items: center;
      gap: 8px;
      margin: -4px 0 16px;
      color: var(--ui-muted);
      font-size: 0.79rem;
    }

    .required-note {
      margin-left: auto;
      color: var(--ui-muted);
      font-size: 0.72rem;
      font-weight: 700;
    }

    .required-dot {
      color: var(--ui-danger);
      font-size: 0.92em;
      font-weight: 900;
    }

    .required-badge {
      display: inline-flex;
      margin-left: 6px;
      padding: 2px 6px;
      border-radius: 999px;
      background: var(--ui-danger-soft);
      color: var(--ui-danger);
      font-size: 0.58rem;
      font-weight: 850;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      vertical-align: middle;
    }

    .param-grid {
      gap: 16px;
    }

    .param-row {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 16px;
      align-items: start;
    }

    .param-item {
      min-width: 0;
      padding: 0;
      border: 0;
      background: transparent;
    }

    .control-label,
    #apiPartitionSection .control-label,
    .byte-modal .form-group label {
      display: flex;
      align-items: center;
      gap: 7px;
      margin-bottom: 7px;
      color: #344b44 !important;
      font-size: 0.78rem !important;
      font-weight: 760 !important;
    }

    .control-label i {
      width: 15px;
      color: var(--ui-primary) !important;
      text-align: center;
    }

    .input-with-icon,
    .select-with-icon {
      position: relative;
    }

    .input-with-icon input,
    .select-with-icon select,
    #apiPartitionSection .api-input-wrap input,
    .frame-setting select,
    .byte-modal .form-group input,
    .byte-modal .form-group select {
      width: 100% !important;
      min-width: 0 !important;
      min-height: 46px;
      padding: 10px 13px 10px 42px !important;
      border: 1px solid #cfdcd6 !important;
      border-radius: 12px !important;
      background: #fff !important;
      color: var(--ui-ink) !important;
      font: inherit;
      font-size: 0.88rem !important;
      box-shadow: var(--ui-control-shadow) !important;
      transition: border-color 150ms ease, box-shadow 150ms ease, background-color 150ms ease;
    }

    .input-with-icon > i,
    .select-with-icon > i {
      left: 14px;
      color: #789188 !important;
    }

    .input-with-icon input::placeholder,
    #apiPartitionSection .api-input-wrap input::placeholder {
      color: #97a8a1;
      opacity: 1;
    }

    .input-with-icon input:hover,
    .select-with-icon select:hover,
    #apiPartitionSection .api-input-wrap input:hover {
      border-color: #a9c0b7 !important;
    }

    .input-with-icon input:focus,
    .select-with-icon select:focus,
    #apiPartitionSection .api-input-wrap input:focus,
    .frame-setting select:focus,
    .byte-modal .form-group input:focus,
    .byte-modal .form-group select:focus {
      border-color: var(--ui-primary) !important;
      outline: 0 !important;
      box-shadow: 0 0 0 4px rgba(55, 111, 100, 0.13) !important;
    }

    .field-setup-hint {
      margin-top: 6px;
      color: var(--ui-muted);
      font-size: 0.69rem;
    }

    .field-setup-hint i {
      color: var(--ui-accent);
    }

    .dropdown-warning,
    .api-error:not(:empty),
    .command-error:not(:empty) {
      display: flex;
      align-items: flex-start;
      gap: 7px;
      margin-top: 7px;
      padding: 8px 10px;
      border: 1px solid #f0c0bc;
      border-radius: 9px;
      background: var(--ui-danger-soft);
      color: #9f261e;
      font-size: 0.72rem;
      font-weight: 700;
      line-height: 1.4;
    }

    .dropdown-warning[hidden] {
      display: none !important;
    }

    .input-with-icon.input-error input,
    .select-with-icon.dropdown-error select,
    .command-entry input.command-byte-input.invalid {
      border-color: var(--ui-danger) !important;
      background: #fffafa !important;
      box-shadow: 0 0 0 3px rgba(201, 54, 43, 0.11) !important;
    }

    .linked-api-panel {
      border: 1px dashed #b9cec5;
      border-radius: 14px;
      background: #f8fbf9;
    }

    .partition-howto {
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 10px;
    }

    .partition-howto-step {
      min-height: 74px;
      border-color: var(--ui-line);
      background: #f9fbfa;
    }

    .partition-howto-step .howto-num {
      background: var(--ui-primary);
    }

    .api-entry-row {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 12px;
      align-items: end;
      margin-top: 16px;
    }

    .api-count {
      min-height: 46px;
      display: inline-flex;
      align-items: center;
      padding: 0 14px;
      border: 1px solid var(--ui-line);
      border-radius: 12px;
      background: #f8fbf9;
      color: var(--ui-muted);
      white-space: nowrap;
    }

    .partition-workspace,
    #apiPartitionSection .partition-workspace {
      margin-top: 16px;
      border: 1px solid var(--ui-line) !important;
      border-radius: 16px !important;
      background: #fbfdfc !important;
      box-shadow: none !important;
    }

    .partition-toolbar,
    .partition-confirm-row,
    .action-row {
      gap: 10px;
    }

    button,
    .generate-btn,
    .continue-btn,
    .save-btn,
    .partition-btn,
    .add-frame-btn,
    .demo-open-btn,
    .back-btn {
      min-height: 42px;
      border-radius: 11px !important;
      font-size: 0.78rem;
      font-weight: 780;
      letter-spacing: 0;
      transition: transform 140ms ease, box-shadow 140ms ease, background-color 140ms ease, border-color 140ms ease;
    }

    .generate-btn,
    .continue-btn,
    .save-btn,
    .partition-btn.primary,
    .add-frame-btn {
      border-color: var(--ui-primary) !important;
      background: var(--ui-primary) !important;
      color: #fff !important;
      box-shadow: 0 7px 16px rgba(55, 111, 100, 0.18);
    }

    .generate-btn:hover:not(:disabled),
    .continue-btn:hover:not(:disabled),
    .save-btn:hover:not(:disabled),
    .partition-btn.primary:hover:not(:disabled),
    .add-frame-btn:hover:not(:disabled) {
          border-color: #3f6d63 !important;
    background: #3f6d63 !important;
      box-shadow: 0 10px 20px rgba(40, 88, 79, 0.22);
      transform: translateY(-1px);
    }

    .partition-btn:not(.primary),
    .demo-open-btn,
    .back-btn {
      border-color: #bfd0c9 !important;
      background: #fff !important;
      color: var(--ui-primary-strong) !important;
      box-shadow: none;
    }

    .partition-btn:not(.primary):hover:not(:disabled),
    .demo-open-btn:hover:not(:disabled),
    .back-btn:hover:not(:disabled) {
      border-color: var(--ui-primary) !important;
      background: var(--ui-primary-soft) !important;
      transform: none;
    }

    .back-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      padding: 0.72rem 1rem;
      cursor: pointer;
    }

    button:focus-visible,
    input:focus-visible,
    select:focus-visible {
      outline: 3px solid rgba(55, 111, 100, 0.24) !important;
      outline-offset: 2px;
    }

    #commandFramesContainer {
      grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)) !important;
      gap: 14px !important;
    }

    .command-frame-card {
      border-color: var(--ui-line);
      border-radius: 15px;
      background: #fff;
      box-shadow: 0 4px 14px rgba(29, 65, 56, 0.055);
    }

    .command-frame-card:hover {
      border-color: #9ebeb1;
      box-shadow: 0 9px 24px rgba(29, 65, 56, 0.1);
      transform: translateY(-2px);
    }

    .frame-status-legend {
      color: var(--ui-muted);
    }

    .action-row {
      position: sticky;
      z-index: 20;
      bottom: 10px;
      margin-top: 24px;
      padding: 13px;
      border: 1px solid rgba(207, 225, 217, 0.9);
      border-radius: 16px;
      background: rgba(255, 255, 255, 0.92);
      box-shadow: 0 12px 32px rgba(29, 65, 56, 0.14);
      backdrop-filter: blur(10px);
    }

    #deleteConfigurationBtn {
      border-color: #b42318 !important;
      background: #fff !important;
      color: #b42318 !important;
      box-shadow: none;
    }

    #deleteConfigurationBtn:hover {
      background: #fff1f0 !important;
      transform: none;
    }

    @media (max-width: 980px) {
      .product-meta {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .command-response-error-flow {
        gap: 7px;
      }

      .flow-stage {
        padding-inline: 9px;
      }
    }

    @media (max-width: 720px) {
      body {
        padding: 0;
        background: #fff;
      }

      .card {
        padding: 16px;
        border: 0;
        border-radius: 0;
        box-shadow: none;
      }

      .header-title {
        align-items: stretch;
      }

      .brand-badge {
        align-self: flex-start;
      }

      .product-meta {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .command-response-error-flow {
        grid-template-columns: 1fr;
      }

      .flow-arrow {
        display: none;
      }

      .flow-stage {
        width: 100%;
      }

      .param-row,
      .api-entry-row,
      .partition-howto {
        grid-template-columns: 1fr;
      }

      .api-count {
        justify-content: center;
        white-space: normal;
      }

      .step-heading {
        align-items: flex-start;
      }

      .demo-open-btn {
        margin-left: auto;
      }

      .partition-toolbar,
      .partition-confirm-row,
      .action-row {
        align-items: stretch;
      }

      .action-row {
        bottom: 0;
      }

      .action-row .save-status-badge {
        width: 100%;
      }

      .action-row button {
        flex: 1 1 160px;
      }
    }

    @media (max-width: 460px) {
      .header-title {
        align-items: stretch;
      }

      .header-actions {
        width: 100%;
        justify-content: space-between;
        margin-top: 0.9rem;
      }

      .header-back-btn {
        margin-left: auto;
      }

      .product-meta {
        grid-template-columns: 1fr;
      }

      .section,
      #commandFramesSection,
      #apiPartitionSection {
        padding: 14px !important;
      }

      .partition-side-nav {
        width: 34px;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }

    /* =========================================================
       Enterprise UI system
       Final visual layer only. Existing IDs, events, payloads,
       PHP variables and backend behaviour remain unchanged.
       ========================================================= */
    :root {
      --ent-bg: #f5f7fb;
      --ent-surface: #ffffff;
      --ent-surface-subtle: #f8fafc;
      --ent-surface-raised: #ffffff;
      --ent-text: #172033;
      --ent-text-secondary: #536179;
      --ent-text-tertiary: #7b879d;
      --ent-border: #e1e6ef;
      --ent-border-strong: #cbd3e1;
      --ent-primary: #3f6d63;
      --ent-primary-hover: #3f6d63;
      --ent-primary-soft: #f1f0ff;
      --ent-success: #16825d;
      --ent-success-soft: #ecf9f3;
      --ent-warning: #a15c00;
      --ent-warning-soft: #fff7e8;
      --ent-danger: #c4323f;
      --ent-danger-soft: #fff1f2;
      --ent-focus: rgba(99, 91, 255, 0.18);
      --ent-shadow-xs: 0 1px 2px rgba(23, 32, 51, 0.05);
      --ent-shadow-sm: 0 4px 14px rgba(23, 32, 51, 0.06);
      --ent-shadow-md: 0 18px 48px rgba(23, 32, 51, 0.09);
      --ent-radius-sm: 9px;
      --ent-radius-md: 13px;
      --ent-radius-lg: 18px;
      --ent-transition: 160ms cubic-bezier(0.2, 0, 0, 1);
    }

    html {
      color-scheme: light;
      background: var(--ent-bg);
      font-size: 16px;
      scroll-padding-top: 20px;
    }

    body {
      min-height: 100vh;
      padding: clamp(14px, 2.5vw, 36px) !important;
      color: var(--ent-text) !important;
      background:
        radial-gradient(circle at 50% -20%, rgba(99, 91, 255, 0.09), transparent 34rem),
        var(--ent-bg) !important;
      font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;
      line-height: 1.5;
    }

    body,
    button,
    input,
    select,
    textarea {
      font-family: inherit !important;
    }

    .card {
      width: min(100%, 1320px) !important;
      max-width: 1320px !important;
      padding: clamp(18px, 3vw, 40px) !important;
      overflow: visible !important;
      border: 1px solid var(--ent-border) !important;
      border-radius: 24px !important;
      background: var(--ent-surface) !important;
      box-shadow: var(--ent-shadow-md) !important;
    }

    .header-title {
      display: grid !important;
      grid-template-columns: minmax(0, 1fr) auto !important;
      align-items: start !important;
      gap: 20px !important;
      margin-bottom: 22px !important;
      padding-bottom: 22px !important;
      border-bottom: 1px solid var(--ent-border) !important;
    }

    .page-heading-copy {
      min-width: 0;
    }

    .page-eyebrow {
      color: var(--ent-primary) !important;
      font-size: 0.7rem !important;
      font-weight: 750 !important;
      letter-spacing: 0.1em !important;
    }

    .header-title h1 {
      color: var(--ent-text) !important;
      font-size: clamp(1.55rem, 3vw, 2.1rem) !important;
      font-weight: 760 !important;
      letter-spacing: -0.035em !important;
    }

    .header-subtitle {
      max-width: 720px !important;
      margin-top: 6px !important;
      color: var(--ent-text-secondary) !important;
      font-size: 0.9rem !important;
    }

    .title-icon {
      width: 42px !important;
      height: 42px !important;
      border: 1px solid #d9d7ff !important;
      border-radius: 12px !important;
      color: var(--ent-primary) !important;
      background: var(--ent-primary-soft) !important;
      box-shadow: none !important;
    }

    .header-actions {
      display: flex !important;
      align-items: center !important;
      justify-content: flex-end !important;
      gap: 10px !important;
      margin-left: 0 !important;
    }

    .brand-badge {
      min-height: 40px !important;
      max-width: 320px !important;
      padding: 8px 13px !important;
      border: 1px solid var(--ent-border) !important;
      border-radius: 11px !important;
      color: var(--ent-text-secondary) !important;
      background: var(--ent-surface-subtle) !important;
      box-shadow: none !important;
    }

    .product-meta {
      display: grid !important;
      grid-template-columns: repeat(5, minmax(0, 1fr)) !important;
      gap: 10px !important;
      margin-bottom: 22px !important;
      padding: 10px !important;
      border: 1px solid var(--ent-border) !important;
      border-radius: var(--ent-radius-lg) !important;
      background: var(--ent-surface-subtle) !important;
      box-shadow: none !important;
    }

    .product-meta .meta-item {
      display: grid !important;
      grid-template-columns: 34px minmax(0, 1fr) !important;
      column-gap: 80px !important;
      row-gap: 1px !important;
      min-width: 0 !important;
      padding: 11px !important;
      border: 1px solid #497d70 !important;
      border-radius: 12px !important;
      background: var(--ent-surface) !important;
      box-shadow: var(--ent-shadow-xs) !important;
      transition: border-color var(--ent-transition), box-shadow var(--ent-transition), transform var(--ent-transition) !important;
    }

    .product-meta .meta-item:hover {
      border-color: var(--ent-border-strong) !important;
      box-shadow: var(--ent-shadow-sm) !important;
      transform: translateY(-1px);
    }

    .meta-item .meta-icon {
