    /* Final interaction and presentation layer */
    html {
      scroll-behavior: smooth;
      scrollbar-color: #739b87 #edf3ef;
      scrollbar-width: thin;
    }

    * {
      scrollbar-color: #739b87 #edf3ef;
      scrollbar-width: thin;
    }

    *::-webkit-scrollbar {
      width: 10px;
      height: 10px;
    }

    *::-webkit-scrollbar-track {
      border-radius: 999px;
      background: #edf3ef;
    }

    *::-webkit-scrollbar-thumb {
      min-height: 42px;
      border: 2px solid #edf3ef;
      border-radius: 999px;
      background: linear-gradient(180deg, #88bda4, #5d8975);
    }

    *::-webkit-scrollbar-thumb:hover {
      background: #477361;
    }

