      min-height: 38px;
      padding: 0 12px;
      border: 1px solid #bcd1c5;
      border-radius: 9px;
      color: #29483e;
      background: #fff;
      font-size: 0.78rem;
      font-weight: 800;
      cursor: pointer;
      transition:
        color 160ms ease,
        background 160ms ease,
        border-color 160ms ease,
        transform 160ms ease;
    }

    .json-save-head-actions button:hover {
      border-color: #477361;
      color: #fff;
      background: #477361;
      transform: translateY(-1px);
    }

    .json-save-head-actions .json-save-close {
      width: 38px !important;
      min-width: 38px;
      padding: 0 !important;
      border-radius: 50% !important;
    }

    #viewSavedApi {
      border-color: #c2d5ca !important;
      color: #29483e !important;
      background: #f5faf7 !important;
    }

    @media (max-width: 700px) {
      .frame-settings {
        grid-template-columns: 1fr;
      }

      .json-save-head {
        flex-wrap: wrap;
      }

      .json-save-head-actions {
        width: 100%;
        justify-content: flex-end;
      }

      .json-save-head-actions button:not(.json-save-close) {
        flex: 1 1 auto;
      }
    }

    /* =========================================================
       Final guided-workflow UI
       UI only: no field names, payloads or backend behaviour.
       ========================================================= */
    :root {
      --workflow-ink: #24322d;
      --workflow-muted: #65756e;
      --workflow-line: #d9e3de;
      --workflow-surface: #ffffff;
      --workflow-soft: #f5f8f6;
      --workflow-hover: #edf5f1;
      --workflow-active: #315f50;
      --workflow-active-hover: #274d41;
      --workflow-progress: #a96512;
      --workflow-progress-soft: #fff6df;
      --workflow-complete: #20764b;
      --workflow-complete-soft: #eaf7ef;
      --workflow-danger: #bd3d35;
    }

    /* Keep the Generate action visually centred on every screen size. */
    #parameterCommandSection .param-row:has(#generateFramesBtn),
    #parameterCommandSection .frame-type-row {
      display: flex !important;
      width: 100% !important;
      justify-content: center !important;
      align-items: center !important;
    }

    #generateFramesBtn {
      
      min-width: min(100%, 280px) !important;
      margin: 4px auto 0 !important;
      justify-content: center !important;
      border-color:var(--workflow-active) !important;
      background: #fff !important;
      background-image: linear-gradient(38deg, #376f64 12%, #6592878f 46%, #376f64 90%) !important;
      box-shadow: 0 8px 20px rgba(49, 95, 80, 0.18) !important;
    }

    #generateFramesBtn:hover:not(:disabled) {
      border-color: var(--workflow-active-hover) !important;
      background: var(--workflow-active-hover) !important;
      box-shadow: 0 11px 26px rgba(39, 77, 65, 0.24) !important;
      transform: translateY(-2px);
    }

    #generateFramesBtn:active:not(:disabled) {
      box-shadow: 0 4px 12px rgba(39, 77, 65, 0.18) !important;
      transform: translateY(0);
    }

    /* The generated-frame area is revealed only by Generate in Add mode.
       Edit mode still receives is-visible from the server-rendered class. */
    .frames-generation-section {
      display: none !important;
      opacity: 0;
      transform: translateY(16px) scale(0.992);
    }

    .frames-generation-section.is-visible {
      display: block !important;
      animation: generatedSectionReveal 420ms cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
    }

    @keyframes generatedSectionReveal {
      0% {
        opacity: 0;
        transform: translateY(16px) scale(0.992);
      }
      100% {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

    /* Style the opened option list entries only. The closed select control
       keeps the existing form design. */
    select option {
      padding: 10px 12px;
      color: var(--workflow-ink);
      background-color: #ffffff;
      font-family: inherit;
      font-size: 0.86rem;
      font-weight: 650;
    }

    select option:nth-child(even) {
      background-color: #f4f8f6;
    }

    select option:checked {
      color: #ffffff;
      background: var(--workflow-active);
      font-weight: 800;
    }

    select option:disabled {
      color: #8a9892;
      background-color: #f2f4f3;
    }

    select optgroup {
      color: var(--workflow-active);
      background: #eaf2ee;
      font-weight: 850;
    }

       remain visibly different, including hover states. */
    .command-response-error-flow {
      border: 1px solid #375b52 !important;
    background: linear-gradient(135deg, #71998f, #7d9f8e) !important!important;
      /* border-color: var(--workflow-line) !important;
      background: var(--workflow-soft) !important; */
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
    }

    .flow-stage {
      border: 1px solid var(--workflow-line) !important;
      color: var(--workflow-muted) !important;
      background: var(--workflow-surface) !important;
      box-shadow: 0 2px 7px rgba(36, 50, 45, 0.04) !important;
    }

    .flow-stage .flow-stage-number {
      color: #52625b !important;
      background: #edf1ef !important;
    }

    .flow-stage .flow-stage-status {
      color: #78867f !important;
    }

    .flow-stage:hover:not(:disabled):not(.active) {
      border-color: #99b6aa !important;
      color: var(--workflow-ink) !important;
      background: var(--workflow-hover) !important;
      box-shadow: 0 8px 18px rgba(49, 95, 80, 0.1) !important;
      transform: translateY(-2px) !important;
    }

    .flow-stage.active {
      border-color: var(--workflow-active) !important;
      color: #ffffff !important;
      background: var(--workflow-active) !important;
      box-shadow: 0 9px 22px rgba(49, 95, 80, 0.22) !important;
    }

    .flow-stage.active:hover:not(:disabled) {
          color: #ffffff !important;

      border-color: var(--workflow-active-hover) !important;
      background: var(--workflow-active-hover) !important;
      transform: translateY(-2px) !important;
    }

    .flow-stage.active .flow-stage-number {
      color: var(--workflow-active) !important;
      background: #ffffff !important;
    }

    .flow-stage.active .flow-stage-status {
      color: rgba(255, 255, 255, 0.82) !important;
    }

    .flow-stage.in-progress:not(.active) {
      border-color: #e2b25f !important;
      color: #764508 !important;
      background: var(--workflow-progress-soft) !important;
    }

    .flow-stage.in-progress:not(.active):hover {
      border-color: var(--workflow-progress) !important;
      background: #ffefc4 !important;
    }

    .flow-stage.in-progress:not(.active) .flow-stage-number {
      color: #ffffff !important;
      background: var(--workflow-progress) !important;
    }

    .flow-stage.in-progress:not(.active) .flow-stage-status {
      color: #8a550e !important;
    }

    .flow-stage.active.in-progress {
      border-color: #8c560f !important;
      background: #8c560f !important;
      box-shadow: 0 9px 22px rgba(140, 86, 15, 0.22) !important;
    }

    .flow-stage.completed:not(.active),
    .flow-stage.filled:not(.active) {
      border-color: #8fc3a5 !important;
      color: #155d39 !important;
      background: var(--workflow-complete-soft) !important;
    }

    .flow-stage.completed:not(.active):hover,
    .flow-stage.filled:not(.active):hover {
      border-color: var(--workflow-complete) !important;
      background: #ddf2e5 !important;
    }

    .flow-stage.completed:not(.active) .flow-stage-number,
    .flow-stage.filled:not(.active) .flow-stage-number {
      color: #ffffff !important;
      background: var(--workflow-complete) !important;
    }

    .flow-stage.completed:not(.active) .flow-stage-status,
    .flow-stage.filled:not(.active) .flow-stage-status {
      color: var(--workflow-complete) !important;
    }

    .flow-stage.active.completed,
    .flow-stage.active.filled {
      border-color: var(--workflow-complete) !important;
      background: var(--workflow-complete) !important;
      box-shadow: 0 9px 22px rgba(32, 118, 75, 0.22) !important;
    }

    .flow-stage.active.completed:hover,
    .flow-stage.active.filled:hover {
      border-color: #185d3b !important;
      background: #185d3b !important;
    }

    .flow-stage.active.completed .flow-stage-number,
    .flow-stage.active.filled .flow-stage-number {
      color: var(--workflow-complete) !important;
      background: #ffffff !important;
    }

    .flow-arrow {
      color: #b27a2e !important;
      animation: workflowArrowMove 1.45s ease-in-out infinite;
      transform-origin: center;
    }

    @keyframes workflowArrowMove {
      0%, 100% {
        opacity: 0.5;
        transform: translateX(-2px);
      }
      50% {
        opacity: 1;
        transform: translateX(3px);
      }
    }

    /* Animated partition guide based on the three reference cards. */
    .partition-howto {
      gap: 12px !important;
      margin-top: 14px !important;
    }

    .partition-howto-step {
      position: relative;
      min-height: 112px;
      align-items: stretch !important;
      gap: 11px !important;
      overflow: hidden;
      border: 1px solid #bfd3c9 !important;
      border-radius: 15px !important;
      color: var(--workflow-ink) !important;
      background: linear-gradient(180deg, #ffffff 0%, #f7faf8 100%) !important;
      box-shadow: 0 5px 16px rgba(49, 95, 80, 0.07);
      transition:
        border-color 180ms ease,
        box-shadow 180ms ease,
        transform 180ms ease;
    }

    .partition-howto-step:hover {
      border-color: #719c89 !important;
      box-shadow: 0 10px 24px rgba(49, 95, 80, 0.13);
      transform: translateY(-2px);
    }

    .partition-howto-step .howto-num {
      flex: 0 0 27px !important;
      width: 27px !important;
      height: 27px !important;
      color: #ffffff !important;
      background: #5e8f7d !important;
      box-shadow: 0 4px 10px rgba(49, 95, 80, 0.16);
    }

    .partition-howto-step .howto-content {
      display: flex;
      min-width: 0;
      flex: 1 1 auto;
      flex-direction: column;
      gap: 9px;
    }

    .partition-howto-step strong {
      margin: 2px 0 0 !important;
      color: var(--workflow-ink) !important;
      font-size: 0.8rem !important;
      letter-spacing: 0.01em;
    }

    .howto-motion {
      position: relative;
      display: flex;
      min-height: 46px;
      align-items: center;
      justify-content: center;
      border: 1px dashed #b8cbc2;
      border-radius: 11px;
      color: var(--workflow-active);
      background: #ffffff;
    }

    .howto-plus-demo .fa-plus {
      display: grid;
      width: 31px;
      height: 31px;
      place-items: center;
      border-radius: 50%;
      color: #ffffff !important;
      background: var(--workflow-active);
      animation: howtoPlusPulse 1.6s ease-in-out infinite;
    }

    .howto-plus-demo .fa-hand-pointer {
      position: absolute;
      right: calc(50% - 31px);
      bottom: 2px;
      color: #b06b14 !important;
      font-size: 1rem;
      animation: howtoPointerTap 1.6s ease-in-out infinite;
    }

    .howto-drag-demo {
      overflow: hidden;
    }

    .howto-drag-demo .howto-track {
      position: absolute;
      left: 14px;
      right: 14px;
      height: 3px;
      border-radius: 999px;
      background: #d6e0db;
    }

    .howto-drag-demo .fa-scissors {
      position: absolute;
      left: 18%;
      z-index: 1;
      color: var(--workflow-danger) !important;
      font-size: 1.05rem;
      filter: drop-shadow(0 2px 2px rgba(189, 61, 53, 0.18));
      animation: howtoScissorsDrag 2.2s ease-in-out infinite;
    }

    .howto-select-demo {
      justify-content: flex-start;
      gap: 8px;
      padding: 0 11px;
      color: var(--workflow-ink);
      font-size: 0.7rem;
      font-weight: 750;
    }

    .howto-select-demo .fa-tag {
      color: var(--workflow-active) !important;
      animation: howtoTagBounce 1.7s ease-in-out infinite;
    }

    .howto-select-demo .fa-chevron-down {
      margin-left: auto;
      color: #728078 !important;
      animation: howtoChevron 1.7s ease-in-out infinite;
    }

    @keyframes howtoPlusPulse {
      0%, 100% {
        box-shadow: 0 0 0 0 rgba(49, 95, 80, 0.22);
        transform: scale(1);
      }
      50% {
        box-shadow: 0 0 0 8px rgba(49, 95, 80, 0);
        transform: scale(1.08);
      }
    }

    @keyframes howtoPointerTap {
      0%, 100% { transform: translate(5px, 5px) scale(1); }
      45%, 60% { transform: translate(0, 0) scale(0.88); }
    }

    @keyframes howtoScissorsDrag {
      0%, 100% { left: 18%; transform: rotate(-5deg); }
      50% { left: 72%; transform: rotate(5deg); }
    }

    @keyframes howtoTagBounce {
      0%, 100% { transform: translateY(0) rotate(0); }
      50% { transform: translateY(-3px) rotate(-7deg); }
    }

    @keyframes howtoChevron {
      0%, 100% { transform: translateY(-1px); }
      50% { transform: translateY(3px); }
    }

    @media (max-width: 760px) {
      .command-response-error-flow {
        grid-template-columns: 1fr !important;
      }

      .flow-arrow {
        transform: rotate(90deg);
        animation: workflowArrowMoveMobile 1.45s ease-in-out infinite;
      }

      .partition-howto {
        grid-template-columns: 1fr !important;
      }

      .partition-howto-step {
        min-height: 96px;
      }
    }

    @keyframes workflowArrowMoveMobile {
      0%, 100% {
        opacity: 0.5;
        transform: rotate(90deg) translateX(-2px);
      }
      50% {
        opacity: 1;
        transform: rotate(90deg) translateX(3px);
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      .frames-generation-section.is-visible {
        animation: none;
        opacity: 1;
        transform: none;
      }

      .flow-arrow,
      .howto-plus-demo .fa-plus,
      .howto-plus-demo .fa-hand-pointer,
      .howto-drag-demo .fa-scissors,
      .howto-select-demo .fa-tag,
      .howto-select-demo .fa-chevron-down {
        animation: none !important;
      }
    }

    /* =========================================================
       Modern frame cards
       Visual-only overrides; frame state and event logic unchanged.
       ========================================================= */
    #commandFramesContainer {
      grid-template-columns: repeat(auto-fill, minmax(290px, 1fr)) !important;
      gap: 18px !important;
      align-items: stretch !important;
    }

    .command-frame-card {
      --frame-accent: #b27620;
      --frame-accent-soft: #fff8e9;
      position: relative;
      display: flex;
      min-width: 0;
      min-height: 100%;
      padding: 20px !important;
      overflow: hidden;
      flex-direction: column;
      gap: 5px;
      border: 1px solid #d8e2dd !important;
      border-radius: 18px !important;
      color: #24322d !important;
      background: #ffffff !important;
      box-shadow:
        0 1px 2px rgba(31, 50, 42, 0.05),
        0 10px 26px rgba(31, 50, 42, 0.07) !important;
      isolation: isolate;
      transition:
        border-color 180ms ease,
        box-shadow 180ms ease,
        transform 180ms ease !important;
    }

    .command-frame-card::before {
      position: absolute !important;
      inset: 0 auto 0 0 !important;
      width: 4px !important;
      height: auto !important;
      border-radius: 0 !important;
      background: var(--frame-accent) !important;
      opacity: 1 !important;
      transform: none !important;
      content: "" !important;
    }

    .command-frame-card.needs-partition {
      --frame-accent: #b27620;
      --frame-accent-soft: #fff8e9;
    }

    .command-frame-card.frame-in-progress {
      --frame-accent: #347866;
      --frame-accent-soft: #edf7f3;
    }

    .command-frame-card.partition-complete {
      --frame-accent: #25734b;
      --frame-accent-soft: #ebf7ef;
    }

    .command-frame-card:hover {
      border-color: #a9bcb3 !important;
      background: #ffffff !important;
      box-shadow:
        0 2px 5px rgba(31, 50, 42, 0.07),
        0 18px 38px rgba(31, 50, 42, 0.12) !important;
      transform: translateY(-4px) !important;
    }

    .command-frame-card.selected {
      border-color: var(--frame-accent) !important;
      background:
        linear-gradient(180deg, var(--frame-accent-soft) 0, #ffffff 42%) !important;
      box-shadow:
        0 0 0 3px color-mix(in srgb, var(--frame-accent) 18%, transparent),
        0 18px 38px rgba(31, 50, 42, 0.12) !important;
    }

    .frame-card-head {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      align-items: center;
      gap: 10px;
    }

    .command-frame-card .frame-title {
      display: flex !important;
      min-width: 0;
      align-items: center !important;
      justify-content: flex-start !important;
      gap: 10px;
      margin: 0 !important;
      color: #1f3029 !important;
      font-size: 0.94rem !important;
      font-weight: 850 !important;
      letter-spacing: -0.01em;
    }

    .frame-title-main {
      display: inline-flex;
      min-width: 0;
      align-items: center;
      gap: 10px;
    }

    .command-frame-card .frame-title > .frame-title-main::before {
      display: none !important;
      content: none !important;
    }

    .frame-title-main > span:last-child {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .frame-card-icon {
      display: inline-grid;
      width: 36px;
      height: 36px;
      flex: 0 0 36px;
      place-items: center;
      border: 1px solid color-mix(in srgb, var(--frame-accent) 30%, #ffffff);
      border-radius: 11px;
      color: var(--frame-accent);
      background: var(--frame-accent-soft);
      font-size: 0.82rem;
    }

    .command-frame-card .remove-btn {
      position: absolute;
      top: 14px;
      right: 14px;
      display: grid !important;
      width: 32px !important;
      height: 32px !important;
      min-width: 32px !important;
      padding: 0 !important;
      place-items: center;
      border: 1px solid transparent !important;
      border-radius: 9px !important;
      color: #7c8983 !important;
      background: transparent !important;
      box-shadow: none !important;
      opacity: 0;
      transform: translateY(-2px);
      transition:
        opacity 160ms ease,
        color 160ms ease,
        background 160ms ease,
        border-color 160ms ease,
        transform 160ms ease !important;
    }

    .command-frame-card:hover .remove-btn,
    .command-frame-card:focus-within .remove-btn {
      opacity: 1;
      transform: translateY(0);
    }

    .command-frame-card .remove-btn:hover {
      border-color: #efc7c4 !important;
      color: #aa342e !important;
      background: #fff2f1 !important;
      transform: none !important;
    }

    .frame-status-badge {
      min-height: 32px;
      margin: 0 38px 0 0 !important;
      padding: 5px 9px !important;
      justify-self: end;
      border-radius: 999px !important;
      font-size: 0.64rem !important;
      font-weight: 850 !important;
      letter-spacing: 0.045em !important;
      line-height: 1 !important;
      white-space: nowrap;
    }

    .frame-status-badge.pending {
      border-color: #e7c887 !important;
      color: #80500d !important;
      background: #fff7e5 !important;
    }

    .frame-status-badge.in-progress {
      border-color: #a8cfc2 !important;
      color: #285e50 !important;
      background: #edf7f3 !important;
    }

    .frame-status-badge.filled {
      border-color: #9dceb0 !important;
      color: #1d653f !important;
      background: #eaf7ef !important;
    }

    .command-frame-card .frame-direction {
      display: flex !important;
      width: fit-content;
      max-width: 100%;
      min-height: 30px;
      margin: 0 !important;
      padding: 5px 10px !important;
      border: 1px solid #dce5e0 !important;
      border-radius: 9px !important;
      color: #53665e !important;
      background: #f7faf8 !important;
      font-size: 0.7rem !important;
      font-weight: 750 !important;
    }

    .command-frame-card .frame-direction i {
      color: var(--frame-accent) !important;
    }

    .command-frame-card .frame-settings {
      display: grid !important;
      gap: 10px !important;
      margin: 0 !important;
      padding: 8px !important;
      border: 1px solid #e0e7e3 !important;
      border-radius: 13px !important;
      background: #f8faf9 !important;
      box-shadow: none !important;
    }

    .command-frame-card .frame-setting label {
      min-height: 18px;
      margin: 0 0 6px !important;
      color: #5b6c65 !important;
      font-size: 0.67rem !important;
      font-weight: 800 !important;
      line-height: 1.3;
    }

    .command-frame-card .frame-setting label i {
      color: #71837b !important;
    }

    .command-frame-card .frame-setting select {
      width: 100%;
      min-width: 0;
      min-height: 40px !important;
      padding: 7px 30px 7px 10px !important;
      border: 1px solid #cfdad4 !important;
      border-radius: 9px !important;
      color: #2b3b35 !important;
      background-color: #ffffff !important;
      font-size: 0.74rem !important;
      font-weight: 700 !important;
      box-shadow: 0 1px 2px rgba(31, 50, 42, 0.03) !important;
    }

    .command-frame-card .frame-setting select:hover {
      border-color: #9eb2a9 !important;
    }

    .command-frame-card .frame-setting select:focus {
      border-color: var(--frame-accent) !important;
      box-shadow: 0 0 0 3px color-mix(in srgb, var(--frame-accent) 15%, transparent) !important;
    }

    .command-frame-card .frame-code {
      display: flex;
      min-height: 38px;
      align-items: center;
      gap: 7px;
      margin: 0 !important;
      padding: 9px 11px !important;
      overflow: hidden;
      border: 1px dashed #ced9d3 !important;
      border-radius: 10px !important;
      color: #718078 !important;
      background: #fbfcfb !important;
      font-size: 0.69rem !important;
      font-weight: 750 !important;
    }

    .command-frame-card .frame-code strong {
      min-width: 0;
      overflow: hidden;
      color: #25362f !important;
      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
      font-size: 0.76rem !important;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .command-frame-card .frame-partition-state {
      display: flex !important;
      width: 100%;
      min-height: 35px;
      margin: 0 !important;
      padding: 8px 10px !important;
      justify-content: center;
      border: 1px solid color-mix(in srgb, var(--frame-accent) 28%, #ffffff) !important;
      border-radius: 10px !important;
      color: var(--frame-accent) !important;
      background: var(--frame-accent-soft) !important;
      font-size: 0.7rem !important;
      font-weight: 800 !important;
    }

    .command-frame-card .frame-partition-state[hidden] {
      display: none !important;
    }

    .command-frame-card .frame-config-btn {
      width: 100% !important;
      min-height: 42px !important;
      margin: auto 0 0 !important;
      padding: 9px 13px !important;
      justify-content: center !important;
      border: 1px solid var(--frame-accent) !important;
      border-radius: 11px !important;
      color: #ffffff !important;
      background: var(--frame-accent) !important;
      box-shadow: 0 6px 14px color-mix(in srgb, var(--frame-accent) 20%, transparent) !important;
      font-size: 0.75rem !important;
      font-weight: 850 !important;
      letter-spacing: 0.01em;
      transition:
        filter 160ms ease,
        box-shadow 160ms ease,
        transform 160ms ease !important;
    }

    .command-frame-card .frame-config-btn:hover {
      filter: brightness(0.92);
      box-shadow: 0 9px 18px color-mix(in srgb, var(--frame-accent) 28%, transparent) !important;
      transform: translateY(-1px) !important;
    }

    .command-frame-card.awaiting-click {
      animation: modernFrameAttention 1.8s ease-in-out infinite !important;
    }

    @keyframes modernFrameAttention {
      0%, 100% {
        box-shadow:
          0 1px 2px rgba(31, 50, 42, 0.05),
          0 10px 26px rgba(31, 50, 42, 0.07);
      }
      50% {
        box-shadow:
          0 0 0 4px color-mix(in srgb, var(--frame-accent) 12%, transparent),
          0 14px 30px rgba(31, 50, 42, 0.11);
      }
    }

    @media (max-width: 680px) {
      #commandFramesContainer {
        grid-template-columns: 1fr !important;
        gap: 14px !important;
      }

      .command-frame-card {
        padding: 15px !important;
        border-radius: 15px !important;
      }

      .frame-card-head {
        grid-template-columns: 1fr;
        align-items: start;
      }

      .frame-status-badge {
        margin: 0 !important;
        justify-self: start;
      }

      .command-frame-card .frame-settings {
        grid-template-columns: 1fr;
      }

      .command-frame-card .remove-btn {
        top: 12px;
        right: 12px;
        opacity: 1;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      .command-frame-card.awaiting-click {
        animation: none !important;
      }
    }

    /* =========================================================
       Unified light design system
       Forest, sage, amber and warm-neutral palette ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â no blue/violet.
       Visual overrides only; markup and application logic are unchanged.
       ========================================================= */
    :root {
      color-scheme: light;

      --ds-primary-700: #214e43;
      --ds-primary-600: #2f6f5e;
      --ds-primary-500: #438675;
      --ds-primary-100: #dcece5;
      --ds-primary-050: #eff7f3;

      --ds-accent-700: #7a4618;
      --ds-accent-600: #a06024;
      --ds-accent-500: #c3823b;
      --ds-accent-100: #f5dfc5;
      --ds-accent-050: #fff7ec;

      --ds-success-700: #185a38;
      --ds-success-600: #237a4b;
      --ds-success-100: #dff1e6;
      --ds-warning-700: #7b4b0c;
      --ds-warning-600: #ad701d;
      --ds-warning-100: #faeac8;
      --ds-danger-700: #8c2924;
      --ds-danger-600: #b33b34;
      --ds-danger-100: #f8dedb;

      --ds-ink: #1d2c27;
      --ds-text: #30433b;
      --ds-muted: #5f7069;
      --ds-subtle: #7d8a84;
      --ds-border-strong: #b9c8c1;
      --ds-border: #d5ded9;
      --ds-canvas: #f4f3ed;
      --ds-surface: #fffefa;
      --ds-surface-soft: #f8f8f3;
      --ds-surface-raised: #ffffff;

      --ds-shadow-xs: 0 1px 2px rgba(29, 44, 39, 0.06);
      --ds-shadow-sm: 0 5px 15px rgba(29, 44, 39, 0.08);
      --ds-shadow-md: 0 16px 38px rgba(29, 44, 39, 0.11);
      --ds-shadow-modal: 0 28px 70px rgba(18, 35, 29, 0.22);
      --ds-focus: 0 0 0 3px rgba(47, 111, 94, 0.2);
      --ds-radius-sm: 8px;
      --ds-radius-md: 12px;
      --ds-radius-lg: 18px;
      --ds-transition: 180ms ease;

      /* Existing component aliases now inherit one palette. */
      --primary: var(--ds-primary-600);
      --primary-dark: var(--ds-primary-700);
      --primary-soft: var(--ds-primary-050);
      --secondary: var(--ds-primary-500);
      --secondary-soft: var(--ds-primary-100);
      --ink: var(--ds-ink);
      --muted: var(--ds-muted);
      --line: var(--ds-border);
      --surface: var(--ds-surface);
      --surface-soft: var(--ds-surface-soft);
      --success: var(--ds-success-600);
      --success-soft: var(--ds-success-100);
      --warning: var(--ds-warning-600);
      --focus: rgba(47, 111, 94, 0.2);
      --workflow-active: var(--ds-primary-600);
      --workflow-active-hover: var(--ds-primary-700);
      --workflow-complete: var(--ds-success-600);
      --workflow-complete-soft: var(--ds-success-100);
      --workflow-progress: var(--ds-warning-600);
      --workflow-progress-soft: var(--ds-warning-100);
      --workflow-danger: var(--ds-danger-600);
      --workflow-line: var(--ds-border);
      --workflow-soft: var(--ds-surface-soft);
      --workflow-surface: var(--ds-surface-raised);
      --workflow-hover: var(--ds-primary-050);
      --workflow-ink: var(--ds-ink);
      --workflow-muted: var(--ds-muted);
    }

    html {
      color: var(--ds-text);
      background: var(--ds-canvas) !important;
      scrollbar-color: var(--ds-primary-500) var(--ds-primary-050);
      scrollbar-width: thin;
    }

    body {
      color: var(--ds-text) !important;
      background:
        radial-gradient(circle at 8% 0%, rgba(195, 130, 59, 0.09), transparent 30%),
        linear-gradient(145deg, #f8f7f1 0%, var(--ds-canvas) 58%, #edf4ef 100%) !important;
      font-family:
        Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI",
        Roboto, Helvetica, Arial, sans-serif;
      line-height: 1.5;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }

    *,
    *::before,
    *::after {
      box-sizing: border-box;
    }

    *::-webkit-scrollbar {
      width: 10px;
      height: 10px;
    }

    *::-webkit-scrollbar-track {
      border-radius: 999px;
      background: var(--ds-primary-050);
    }

    *::-webkit-scrollbar-thumb {
      border: 2px solid var(--ds-primary-050);
      border-radius: 999px;
      background: var(--ds-primary-500);
    }

    *::-webkit-scrollbar-thumb:hover {
      background: var(--ds-primary-700);
    }

    ::selection {
      color: #ffffff;
      background: var(--ds-primary-600);
    }

    /* Page shell, header and navigation */
    .card {
      border: 1px solid var(--ds-border) !important;
      border-radius: 22px !important;
      background: rgba(255, 254, 250, 0.97) !important;
      box-shadow: var(--ds-shadow-md) !important;
    }

    .header-title {
      border-bottom: 1px solid var(--ds-border) !important;
      background:
        linear-gradient(120deg, var(--ds-surface-raised), var(--ds-primary-050)) !important;
    }

    .header-title h1,
    .section-title,
    .frames-header-left,
    .field-desc-title,
    .demo-popup-head h3,
    .byte-modal h3,
    .json-save-head h3 {
      color: var(--ds-ink) !important;
      letter-spacing: -0.02em;
    }

    .title-icon,
    .step-number,
    .selected-frame-banner span {
      color: #ffffff !important;
      border-color: var(--ds-primary-600) !important;
      background:
        linear-gradient(145deg, var(--ds-primary-500), var(--ds-primary-700)) !important;
      box-shadow: 0 7px 16px rgba(47, 111, 94, 0.2) !important;
    }

    .brand-badge,
    .meta-icon,
    .field-desc-title-icon,
    .section-title > i,
    .control-label i,
    .interactive-icon {
      color: var(--ds-primary-700) !important;
      border-color: #c8dbd2 !important;
      background: var(--ds-primary-050) !important;
    }

    .product-meta,
    .param-grid,
    .frames-generation-section,
    #commandFramesSection,
    .api-partition-section,
    .field-desc-section,
    .partition-workspace,
    .linked-api-panel,
    .configuration-data-preview {
    border-color: var(--ds-border) !important;
    background: radial-gradient(circle at 100% 0, rgb(80 136 109 / 18%), transparent 28rem), linear-gradient(306deg, #ffffff 0%, #f8fbf9 72%, #f0f7f3 100%) !important;
    box-shadow: -3px -4px 2px 1px rgb(171 219 203 / 69%) !important;
    }

    .meta-item,
    .param-item label,
    .control-label,
    .frame-setting label,
    .form-group label {
      color: var(--ds-muted) !important;
    }

    /* Buttons */
    button,
    .generate-btn,
    .save-btn,
    .continue-btn,
    .add-frame-btn,
    .partition-btn,
    .frame-type-btn,
    .demo-open-btn,
    .back-btn,
    .btn-save-modal,
    .btn-cancel-modal,
    .json-done-btn {
      border-radius: var(--ds-radius-sm) !important;
      font-weight: 750;
      transition:
        color var(--ds-transition),
        background-color var(--ds-transition),
        border-color var(--ds-transition),
        box-shadow var(--ds-transition),
        transform var(--ds-transition) !important;
    }

    .generate-btn,
    .save-btn,
    .continue-btn,
    .btn-save-modal,
    .json-done-btn,
    .command-entry button,
    .partition-mode-done {
      color: #ffffff !important;
      border-color: var(--ds-primary-700) !important;
      background:
      box-shadow: 0 7px 15px rgba(47, 111, 94, 0.2) !important;
    }

    .generate-btn:hover,
    .save-btn:hover,
    .continue-btn:hover,
    .btn-save-modal:hover,
    .json-done-btn:hover,
    .command-entry button:hover,
    .partition-mode-done:hover {
      border-color: #173d34 !important;
      background:
        linear-gradient(135deg, var(--ds-primary-700), #173d34) !important;
      box-shadow: 0 10px 21px rgba(33, 78, 67, 0.24) !important;
      transform: translateY(-2px);
    }

    .generate-btn:active,
    .save-btn:active,
    .continue-btn:active,
    .btn-save-modal:active,
    .json-done-btn:active {
      box-shadow: var(--ds-shadow-xs) !important;
      transform: translateY(0) scale(0.985);
    }

    .demo-open-btn,
    .back-btn,
    .add-frame-btn,
    .partition-btn,
    .btn-cancel-modal,
    .demo-popup-actions button,
    .byte-wise-action {
      color: var(--ds-primary-700) !important;
      border-color: var(--ds-border-strong) !important;
      background: var(--ds-surface-raised) !important;
      box-shadow: var(--ds-shadow-xs) !important;
    }

    .demo-open-btn:hover,
    .back-btn:hover,
    .add-frame-btn:hover,
    .partition-btn:hover,
    .btn-cancel-modal:hover,
    .demo-popup-actions button:hover,
    .byte-wise-action:hover {
      color: var(--ds-primary-700) !important;
      border-color: var(--ds-primary-500) !important;
      background: var(--ds-primary-050) !important;
      box-shadow: var(--ds-shadow-sm) !important;
      transform: translateY(-1px);
    }

    button:disabled,
    .disabled {
      
      box-shadow: none !important;
      cursor: not-allowed !important;
      opacity: 0.78;
      transform: none !important;
      color: #0b1a33 !important;
    border-color: #fffdf8 !important;
    background: #ffffff !important;
    }

    /* Forms and option menus */
    input,
    select,
    textarea,
    .param-item input,
    .param-item select,
    .api-input-wrap input,
    .command-entry input,
    .byte-field-select,
    .byte-modal .form-group input,
    .byte-modal .form-group select {
      color: var(--ds-ink) !important;
      border-color: var(--ds-border-strong) !important;
      border-radius: var(--ds-radius-sm) !important;
      background-color: var(--ds-surface-raised) !important;
      box-shadow: var(--ds-shadow-xs) !important;
      transition:
        border-color var(--ds-transition),
        box-shadow var(--ds-transition),
        background-color var(--ds-transition) !important;
    }

    input:hover,
    select:hover,
    textarea:hover {
      border-color: #8fa79c !important;
    }

    input:focus,
    select:focus,
    textarea:focus,
    button:focus-visible,
    [tabindex]:focus-visible {
      outline: none !important;
      border-color: var(--ds-primary-600) !important;
      box-shadow: var(--ds-focus) !important;
    }

    input::placeholder,
    textarea::placeholder {
      color: var(--ds-subtle) !important;
      opacity: 1;
    }

    select option {
      color: var(--ds-text);
      background: var(--ds-surface-raised);
    }

    select option:nth-child(even) {
      background: var(--ds-surface-soft);
    }

    select option:checked {
      color: #ffffff;
      background: var(--ds-primary-600);
    }

    select option:disabled {
      color: var(--ds-subtle);
      background: #eceeea;
    }

    select optgroup {
      color: var(--ds-primary-700);
      background: var(--ds-primary-050);
    }

    /* Workflow navigation */
    .command-response-error-flow {
      border: 1px solid var(--ds-border) !important;
      background:
        linear-gradient(135deg, var(--ds-surface-soft), var(--ds-primary-050)) !important;
      box-shadow: inset 0 1px 0 #ffffff, var(--ds-shadow-xs) !important;
    }

    .flow-stage {
      color: var(--ds-muted) !important;
      border-color: var(--ds-border) !important;
      background: var(--ds-surface-raised) !important;
      box-shadow: var(--ds-shadow-xs) !important;
    }

    .flow-stage:hover:not(:disabled):not(.active) {
      color: var(--ds-primary-700) !important;
      border-color: var(--ds-primary-500) !important;
      background: var(--ds-primary-050) !important;
      box-shadow: var(--ds-shadow-sm) !important;
    }

    .flow-stage.active {
      color: #ffffff !important;
      border-color: var(--ds-primary-700) !important;
      background:
        linear-gradient(135deg, var(--ds-primary-600), var(--ds-primary-700)) !important;
      box-shadow: 0 9px 22px #659287 !important;
    }

    .flow-stage.active .flow-stage-number {
      color: var(--ds-primary-700) !important;
      background: #ffffff !important;
    }

    .flow-stage.in-progress:not(.active) {
      color: var(--ds-warning-700) !important;
      border-color: #d9ad64 !important;
      background: var(--ds-warning-100) !important;
    }

    .flow-stage.in-progress:not(.active) .flow-stage-number {
      color: #ffffff !important;
      background: var(--ds-warning-600) !important;
    }

    .flow-stage.completed:not(.active),
    .flow-stage.filled:not(.active) {
      color: var(--ds-success-700) !important;
      border-color: #8abb9d !important;
      background: var(--ds-success-100) !important;
    }

    .flow-stage.completed:not(.active) .flow-stage-number,
    .flow-stage.filled:not(.active) .flow-stage-number,
    .flow-stage.active.completed,
    .flow-stage.active.filled {
      color: #ffffff !important;
      border-color: var(--ds-success-600) !important;
      background: var(--ds-success-600) !important;
    }

    .flow-arrow {
      color: var(--ds-accent-600) !important;
    }

    /* Cards and generated frame states */
    #commandFramesContainer {
      gap: clamp(14px, 2vw, 20px) !important;
    }

    .command-frame-card {
      --frame-accent: var(--ds-accent-600);
      --frame-accent-soft: var(--ds-accent-050);
      color: var(--ds-text) !important;
      border-color: var(--ds-border) !important;
      background: var(--ds-surface-raised) !important;
      box-shadow: var(--ds-shadow-sm) !important;
    }

    .command-frame-card.needs-partition {
      --frame-accent: var(--ds-accent-600);
      --frame-accent-soft: var(--ds-accent-050);
    }

    .command-frame-card.frame-in-progress,
    .command-frame-card.awaiting-click {
      --frame-accent: var(--ds-primary-600);
      --frame-accent-soft: var(--ds-primary-050);
      color: var(--ds-text) !important;
      border-color: var(--ds-primary-500) !important;
      background: var(--ds-primary-050) !important;
    }

    .command-frame-card.partition-complete {
      --frame-accent: var(--ds-success-600);
      --frame-accent-soft: var(--ds-success-100);
      border-color: #8abb9d !important;
      background: #f6fbf7 !important;
    }

    .command-frame-card:hover {
      border-color: #9aafa5 !important;
      box-shadow: var(--ds-shadow-md) !important;
    }

    .command-frame-card.selected {
      border-color: var(--frame-accent) !important;
      background:
        linear-gradient(180deg, var(--frame-accent-soft), #ffffff 48%) !important;
    }

    .frame-status-badge.pending {
      color: var(--ds-warning-700) !important;
      border-color: #dfbd82 !important;
      background: var(--ds-warning-100) !important;
    }

    .frame-status-badge.in-progress {
      color: var(--ds-primary-700) !important;
      border-color: #9fc5b5 !important;
      background: var(--ds-primary-100) !important;
    }

    .frame-status-badge.filled {
      color: var(--ds-success-700) !important;
      border-color: #9cc8ab !important;
      background: var(--ds-success-100) !important;
    }

    .frame-settings,
    .frame-direction,
    .frame-code,
    .field-desc-help,
    .partition-instruction,
    .command-entry,
    .selected-frame-banner {
      color: var(--ds-text) !important;
      border-color: var(--ds-border) !important;
      background: var(--ds-surface-soft) !important;
    }

    /* Tables */
    table {
      width: 100%;
      overflow: hidden;
      border: 1px solid var(--ds-border);
      border-collapse: separate;
      border-spacing: 0;
      border-radius: var(--ds-radius-md);
      color: var(--ds-text);
      background: var(--ds-surface-raised);
      box-shadow: var(--ds-shadow-xs);
    }

    table thead th {
      position: sticky;
      top: 0;
      z-index: 2;
      color: var(--ds-primary-700) !important;
      border-bottom: 1px solid var(--ds-border-strong) !important;
      background: var(--ds-primary-050) !important;
      font-size: 0.76rem;
      font-weight: 800;
      letter-spacing: 0.025em;
    }

    table th,
    table td {
      padding: 11px 13px;
      border-right-color: var(--ds-border) !important;
      border-bottom-color: var(--ds-border) !important;
      vertical-align: middle;
    }

    table tbody tr:nth-child(even) {
      background: var(--ds-surface-soft);
    }

    table tbody tr:hover {
      background: var(--ds-primary-050);
    }

    /* Modals, saved preview, alerts and status feedback */
    .byte-modal-overlay,
    .partition-mode-overlay,
    .demo-overlay,
    .json-save-overlay,
    .generate-validation-overlay {
      background: rgba(20, 37, 31, 0.58) !important;
      backdrop-filter: blur(5px);
    }

    .byte-modal,
    .partition-mode-modal,
    .demo-popup,
    .json-save-dialog,
    .generate-validation-dialog,
    .byte-detail-popup {
      color: var(--ds-text) !important;
      border: 1px solid var(--ds-border) !important;
      border-radius: var(--ds-radius-lg) !important;
      background: var(--ds-surface-raised) !important;
      box-shadow: var(--ds-shadow-modal) !important;
    }

    .demo-popup-head,
    .json-save-head,
    .generate-validation-head,
    .byte-detail-popup .popup-head {
      border-bottom-color: var(--ds-border) !important;
      background:
        linear-gradient(120deg, #ffffff, var(--ds-primary-050)) !important;
    }

    .demo-popup-actions,
    .json-save-actions,
    .modal-actions {
      border-top-color: #659287 !important;
    background: #fff !important;
    }

    .api-error,
    .command-error,
    .field-form-warning,
    .dropdown-warning,
    .generate-missing-list {
      color: var(--ds-danger-700) !important;
      border-color: #e1a6a1 !important;
      background: #fff !important;
    }

    .partition-ready-hint,
    .complete,
    .json-copy-status {
      color: var(--ds-success-700) !important;
      border-color: #91bda1 !important;
      background: var(--ds-success-100) !important;
    }

    .ui-preview-toast,
    [role="status"] {
      border-color: var(--ds-border) !important;
      background: var(--ds-surface-raised) !important;
      box-shadow: var(--ds-shadow-md) !important;
    }

    .close-modal,
    .demo-close-btn,
    .json-save-close,
    .byte-detail-popup .close {
      color: var(--ds-muted) !important;
      border-color: transparent !important;
      background: transparent !important;
    }

    .close-modal:hover,
    .demo-close-btn:hover,
    .json-save-close:hover,
    .byte-detail-popup .close:hover {
      color: var(--ds-danger-700) !important;
      border-color: #efc2be !important;
      background: #fff1ef !important;
    }

    footer,
    .footer,
    .card-footer {
      color: var(--ds-muted);
      border-top: 1px solid var(--ds-border);
      background: var(--ds-surface-soft);
    }

    /* Responsive and accessibility refinements */
    @media (max-width: 900px) {
      .card {
        border-radius: 16px !important;
      }

      .header-title,
      .header-actions {
                border-radius: 20px;
        border-bottom: 1px solid #8bb79e !important;
        background: linear-gradient(63deg, #7eb5a9e0, #295147) !important;
        align-items: stretch;
      }

      .param-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
      }

      .configuration-data-preview,
      .api-timeline-scroll {
        overflow-x: auto;
        overscroll-behavior-inline: contain;
      }

      table {
        min-width: 680px;
      }
    }

    @media (max-width: 620px) {
      body {
        background: var(--ds-canvas) !important;
      }

      .card {
        border-radius: 12px !important;
        box-shadow: var(--ds-shadow-sm) !important;
      }

      .header-title {
        padding: 16px !important;
      }

      .header-actions,
      .action-row,
      .modal-actions,
      .json-save-actions,
      .demo-popup-actions {
        gap: 8px !important;
      }

      .header-actions > button,
      .action-row > button {
        min-height: 42px;
      }

      .param-grid,
      .frame-settings {
        grid-template-columns: 1fr !important;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }

    @media (prefers-contrast: more) {
      :root {
        --ds-border: #879b91;
        --ds-border-strong: #667c71;
        --ds-muted: #40544b;
      }

      input,
      select,
      textarea,
      button,
      .flow-stage,
      .command-frame-card {
        border-width: 2px !important;
      }
    }

    /* =========================================================
       Scoped frame-card polish
       Only generated Command / Response / Error cards are affected.
       ========================================================= */
    #commandFramesContainer > .command-frame-card {
      --card-glow: rgba(160, 96, 36, 0.18);
      --card-border: color-mix(in srgb, var(--frame-accent) 30%, #d9e2dd);
      position: relative;
      padding: 18px !important;
      gap: 12px !important;
      overflow: hidden !important;
      border: 1px solid var(--card-border) !important;
      border-radius: 20px !important;
      background:
        linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(250, 252, 250, 0.96)) !important;
      box-shadow:
        0 1px 2px rgba(25, 43, 36, 0.06),
        0 10px 26px rgba(25, 43, 36, 0.09) !important;
      transform: translateZ(0);
      animation: frameCardEnter 440ms cubic-bezier(0.22, 1, 0.36, 1) both;
      transition:
        transform 220ms cubic-bezier(0.22, 1, 0.36, 1),
        border-color 220ms ease,
        box-shadow 220ms ease,
        background 220ms ease !important;
    }

    #commandFramesContainer > .command-frame-card::before {
      inset: 0 0 auto 0 !important;
      width: 100% !important;
      height: 4px !important;
      border-radius: 20px 20px 0 0 !important;
      background:
        linear-gradient(90deg, var(--frame-accent), color-mix(in srgb, var(--frame-accent) 56%, #ffffff)) !important;
      box-shadow: 0 2px 10px var(--card-glow);
    }

    #commandFramesContainer > .command-frame-card::after {
      position: absolute;
      top: -80px;
      right: -72px;
      z-index: -1;
      width: 180px;
      height: 180px;
      border-radius: 50%;
      background:
        radial-gradient(circle, color-mix(in srgb, var(--frame-accent) 11%, transparent), transparent 68%);
      pointer-events: none;
      content: "";
      transition: transform 320ms ease, opacity 220ms ease;
    }

    #commandFramesContainer > .command-frame-card:hover {
      border-color: color-mix(in srgb, var(--frame-accent) 56%, #cad6d0) !important;
      background:
        linear-gradient(145deg, #ffffff, color-mix(in srgb, var(--frame-accent-soft) 38%, #ffffff)) !important;
      box-shadow:
        0 3px 8px rgba(25, 43, 36, 0.07),
        0 18px 42px rgba(25, 43, 36, 0.14),
        0 0 0 3px color-mix(in srgb, var(--frame-accent) 9%, transparent) !important;
      transform: translateY(-5px) !important;
    }

    #commandFramesContainer > .command-frame-card:hover::after {
      opacity: 1;
      transform: scale(1.16);
    }

    #commandFramesContainer > .command-frame-card:active {
      transform: translateY(-2px) scale(0.995) !important;
    }

    #commandFramesContainer > .command-frame-card:focus-within {
      border-color: var(--frame-accent) !important;
      box-shadow:
        0 0 0 4px color-mix(in srgb, var(--frame-accent) 16%, transparent),
        0 16px 36px rgba(25, 43, 36, 0.13) !important;
    }

    #commandFramesContainer > .command-frame-card.selected {
      border-color: var(--frame-accent) !important;
      background:
        linear-gradient(155deg, var(--frame-accent-soft), #ffffff 58%) !important;
      box-shadow:
        0 0 0 3px color-mix(in srgb, var(--frame-accent) 15%, transparent),
        0 18px 40px rgba(25, 43, 36, 0.13) !important;
    }

    #commandFramesContainer > .command-frame-card.needs-partition {
      --card-glow: rgba(160, 96, 36, 0.18);
    }

    #commandFramesContainer > .command-frame-card.frame-in-progress,
    #commandFramesContainer > .command-frame-card.awaiting-click {
      --card-glow: rgba(47, 111, 94, 0.19);
      background:
       linear-gradient(112deg, #c3d9ce, #ffffff 62%) !important
    } 

    #commandFramesContainer > .command-frame-card.partition-complete {
      --card-glow: rgba(35, 122, 75, 0.17);
      background:
        linear-gradient(155deg, var(--ds-success-100), #ffffff 64%) !important;
    }

    #commandFramesContainer > .command-frame-card .frame-card-head {
      position: relative;
      min-height: 42px;
      padding-right: 28px;
    }

    #commandFramesContainer > .command-frame-card .frame-title {
      font-size: 0.96rem !important;
      letter-spacing: -0.018em !important;
    }

    #commandFramesContainer > .command-frame-card .frame-card-icon {
      width: 40px;
      height: 40px;
      flex-basis: 40px;
      border-color: color-mix(in srgb, var(--frame-accent) 32%, #ffffff);
      border-radius: 12px;
      background:
        linear-gradient(145deg, #ffffff, var(--frame-accent-soft));
      box-shadow:
        0 5px 13px color-mix(in srgb, var(--frame-accent) 15%, transparent),
        inset 0 1px 0 rgba(255, 255, 255, 0.9);
      transition: transform 220ms ease, box-shadow 220ms ease;
    }

    #commandFramesContainer > .command-frame-card:hover .frame-card-icon {
      box-shadow:
        0 8px 18px color-mix(in srgb, var(--frame-accent) 21%, transparent),
        inset 0 1px 0 rgba(255, 255, 255, 0.95);
      transform: translateY(-1px) rotate(-3deg);
    }

    #commandFramesContainer > .command-frame-card .frame-status-badge {
      min-height: 27px;
      border-width: 1px !important;
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
    }

    #commandFramesContainer > .command-frame-card .remove-btn {
      top: 13px;
      right: 12px;
      opacity: 0.7;
    }

    #commandFramesContainer > .command-frame-card .frame-settings {
      gap: 11px !important;
      padding: 11px !important;
      border-color: color-mix(in srgb, var(--frame-accent) 16%, var(--ds-border)) !important;
      border-radius: 14px !important;
      background:
        linear-gradient(155deg, #fbfcfb, color-mix(in srgb, var(--frame-accent-soft) 28%, #ffffff)) !important;
      box-shadow: inset 0 1px 0 #ffffff !important;
    }

    #commandFramesContainer > .command-frame-card .frame-setting label {
      color: #52675e !important;
      font-size: 0.69rem !important;
      letter-spacing: 0.01em;
    }

    #commandFramesContainer > .command-frame-card .frame-setting label i {
      color: var(--frame-accent) !important;
      transition: transform 180ms ease;
    }

    #commandFramesContainer > .command-frame-card .frame-setting:focus-within label i {
      transform: scale(1.12);
    }

    #commandFramesContainer > .command-frame-card .frame-setting select {
      min-height: 43px !important;
      border-color: #c6d3cd !important;
      border-radius: 10px !important;
      background-color: rgba(255, 255, 255, 0.96) !important;
      box-shadow:
        0 1px 2px rgba(25, 43, 36, 0.04),
        inset 0 1px 0 #ffffff !important;
      cursor: pointer;
    }

    #commandFramesContainer > .command-frame-card .frame-setting select:hover {
      border-color: color-mix(in srgb, var(--frame-accent) 48%, #aabbb3) !important;
      box-shadow: 0 4px 12px rgba(25, 43, 36, 0.07) !important;
    }

    #commandFramesContainer > .command-frame-card .frame-code {
      min-height: 40px;
      border-color: color-mix(in srgb, var(--frame-accent) 22%, #cbd6d1) !important;
      background: rgba(255, 255, 255, 0.76) !important;
    }

    #commandFramesContainer > .command-frame-card .frame-partition-state {
      min-height: 38px;
      border-radius: 11px !important;
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.72);
    }

    #commandFramesContainer > .command-frame-card .frame-config-btn {
      position: relative;
      min-height: 45px !important;
      overflow: hidden;
      border: 0 !important;
      border-radius: 12px !important;
      background:
        linear-gradient(135deg, var(--frame-accent), color-mix(in srgb, var(--frame-accent) 78%, #263d34)) !important;
      background-image: linear-gradient(251deg, #659287f5 12%, #6592878f 46%, #376f64 90%) !important;
        box-shadow:
        0 9px 20px color-mix(in srgb, var(--frame-accent) 25%, transparent),
        inset 0 1px 0 rgba(255, 255, 255, 0.22) !important;
    }

    #commandFramesContainer > .command-frame-card .frame-config-btn::after {
      position: absolute;
      inset: 0;
      background: linear-gradient(105deg, transparent 30%, rgba(255, 255, 255, 0.24) 50%, transparent 70%);
      content: "";
      transform: translateX(-120%);
      transition: transform 520ms ease;
    }

    #commandFramesContainer > .command-frame-card .frame-config-btn:hover {
      filter: saturate(1.05) brightness(0.96);
      box-shadow:
        0 12px 25px color-mix(in srgb, var(--frame-accent) 31%, transparent),
        inset 0 1px 0 rgba(255, 255, 255, 0.24) !important;
      transform: translateY(-2px) !important;
    }

    #commandFramesContainer > .command-frame-card .frame-config-btn:hover::after {
      transform: translateX(120%);
    }

    #commandFramesContainer > .command-frame-card .frame-config-btn:active {
      box-shadow: 0 5px 11px color-mix(in srgb, var(--frame-accent) 19%, transparent) !important;
      transform: translateY(0) scale(0.99) !important;
    }

    @keyframes frameCardEnter {
      from {
        opacity: 0;
        transform: translateY(12px) scale(0.985);
      }
      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

    @media (max-width: 680px) {
      #commandFramesContainer > .command-frame-card {
        padding: 15px !important;
        gap: 10px !important;
        border-radius: 16px !important;
      }

      #commandFramesContainer > .command-frame-card .frame-card-head {
        padding-right: 34px;
      }

      #commandFramesContainer > .command-frame-card .remove-btn {
        opacity: 1;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      #commandFramesContainer > .command-frame-card,
      #commandFramesContainer > .command-frame-card::after,
      #commandFramesContainer > .command-frame-card .frame-card-icon,
      #commandFramesContainer > .command-frame-card .frame-config-btn,
      #commandFramesContainer > .command-frame-card .frame-config-btn::after {
        animation: none !important;
        transition-duration: 0.01ms !important;
      }
    }

    /* =========================================================
       Step 2 partition workspace polish
       Strictly scoped to #apiPartitionSection. The partition side
       navigation buttons intentionally receive no rules here.
       ========================================================= */
    #apiPartitionSection {
      --step2-ink: #193a33;
      --step2-muted: #5f766f;
      --step2-primary: #47796d;
      --step2-primary-dark: #315e54;
      --step2-primary-soft: #edf6f1;
      --step2-accent: #b8763f;
      --step2-accent-soft: #fff5e9;
      --step2-line: #cbdcd4;
      --step2-surface: #ffffff;
      --step2-surface-soft: #f6faf8;
      --step2-shadow: 0 20px 52px rgba(31, 70, 59, 0.13);
      position: relative;
      isolation: isolate;
      overflow: hidden;
      padding: clamp(20px, 2.8vw, 32px) !important;
      border: 1px solid rgba(129, 169, 153, 0.55) !important;
      border-radius: 24px !important;
      color: var(--step2-ink) !important;
      background:
        radial-gradient(circle at 100% 0, rgba(136, 189, 164, 0.18), transparent 28rem),
        linear-gradient(145deg, #ffffff 0%, #f8fbf9 72%, #f0f7f3 100%) !important;
      box-shadow: var(--step2-shadow) !important;
      animation: step2SectionReveal 480ms cubic-bezier(0.22, 1, 0.36, 1) both;
    }

    #apiPartitionSection::before {
      position: absolute;
      inset: 0 0 auto;
      z-index: -1;
      height: 5px;
      background: linear-gradient(90deg, #315e54, #88bda4 62%, #b8763f);
      content: "";
    }

    #apiPartitionSection .step-heading {
      position: relative;
      gap: 13px !important;
      margin-bottom: 15px !important;
      padding-bottom: 16px !important;
      border-bottom: 1px solid var(--step2-line) !important;
    }

    #apiPartitionSection .step-number {
      min-height: 29px !important;
      padding: 7px 11px !important;
      border: 1px solid rgba(255, 255, 255, 0.2) !important;
      border-radius: 999px !important;
      color: #fff !important;
      background: linear-gradient(135deg, var(--step2-primary), var(--step2-primary-dark)) !important;
      box-shadow: 0 7px 17px rgba(49, 94, 84, 0.24) !important;
      letter-spacing: 0.085em !important;
    }

    #apiPartitionSection .section-title {
      color: var(--step2-ink) !important;
      font-size: clamp(1.02rem, 1.6vw, 1.2rem) !important;
      font-weight: 800 !important;
      letter-spacing: -0.022em !important;
    }

    #apiPartitionSection .section-title i {
      color: var(--step2-accent) !important;
      filter: drop-shadow(0 3px 5px rgba(184, 118, 63, 0.18));
    }

    #apiPartitionSection .partition-frame-label {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      min-height: 34px;
      padding: 7px 12px;
      border: 1px solid #b9d2c6;
      border-radius: 999px;
      color: var(--step2-primary-dark);
      background: rgba(237, 246, 241, 0.9);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9);
      font-weight: 760;
    }

    #apiPartitionSection .partition-frame-label i {
      color: var(--step2-primary);
    }

    #apiPartitionSection .partition-instruction {
      position: relative;
      margin-top: 14px;
      padding: 13px 15px !important;
      overflow: hidden;
      border: 1px solid #c9dbd3 !important;
      border-left: 4px solid var(--step2-primary) !important;
      border-radius: 13px !important;
      color: #425f57 !important;
      background:
        linear-gradient(110deg, var(--step2-primary-soft), #ffffff 78%) !important;
      box-shadow: 0 5px 16px rgba(31, 70, 59, 0.06) !important;
    }

    #apiPartitionSection .partition-instruction i {
      color: var(--step2-primary) !important;
    }

    #apiPartitionSection .partition-instruction strong {
      color: var(--step2-ink);
    }

    #apiPartitionSection .api-entry-row {
      gap: 13px !important;
      margin-top: 18px !important;
      padding: 15px;
      /* border: 1px solid var(--step2-line); */
      border-radius: 16px;
      background: rgba(255, 255, 255, 0.82);
      box-shadow: 0 7px 22px rgb(66 103 93 / 37%);
    }

    #apiPartitionSection .control-label {
      color: #34554c !important;
      font-weight: 760 !important;
    }

    #apiPartitionSection .control-label > i {
      color: var(--step2-accent) !important;
    }

    #apiPartitionSection .api-input-wrap input {
      min-height: 50px !important;
      border-color: #b8cdc4 !important;
      border-radius: 13px !important;
      color: var(--step2-ink) !important;
      background: #fff !important;
      box-shadow:
        inset 0 1px 2px rgba(31, 70, 59, 0.035),
        0 3px 10px rgba(31, 70, 59, 0.05) !important;
      font-weight: 670;
      letter-spacing: 0.045em;
      transition:
        border-color 180ms ease,
        box-shadow 180ms ease,
        transform 180ms ease !important;
    }

    #apiPartitionSection .api-input-wrap input:hover {
      border-color: #8fb2a3 !important;
    }

    #apiPartitionSection .api-input-wrap input:focus {
      border-color: var(--step2-primary) !important;
      box-shadow:
        0 0 0 4px rgba(71, 121, 109, 0.14),
        0 7px 18px rgba(31, 70, 59, 0.08) !important;
    }

    #apiPartitionSection .api-count {
      min-height: 50px;
      border: 1px solid #c5d8cf !important;
      border-radius: 13px !important;
      color: var(--step2-primary-dark) !important;
      background: var(--step2-primary-soft) !important;
      box-shadow: inset 0 1px 0 #fff;
      font-weight: 750;
    }

    #apiPartitionSection .api-count i {
      color: var(--step2-primary);
    }

    #apiPartitionSection .partition-ready-hint {
      margin-top: 10px;
      border-color: #a9cfb8 !important;
      border-radius: 12px;
      color: #246443 !important;
      background: #edf8f1 !important;
      box-shadow: 0 5px 14px rgba(35, 122, 75, 0.07) !important;
    }

    #apiPartitionSection .partition-workspace {
      margin-top: 18px !important;
      padding: clamp(14px, 2.3vw, 22px) !important;
      overflow: visible;
      border: 1px solid #c6d9d0 !important;
      border-radius: 20px !important;
      color: var(--step2-ink) !important;
      background:
        linear-gradient(180deg, #ffffff 0%, #f7faf8 100%) !important;
      box-shadow:
        inset 0 1px 0 #ffffff,
        0 12px 32px rgba(31, 70, 59, 0.085) !important;
    }

    #apiPartitionSection .partition-toolbar {
      align-items: center;
      gap: 9px !important;
      margin-bottom: 15px;
      padding-bottom: 14px;
      border-bottom: 1px dashed #c5d8cf;
    }

    #apiPartitionSection .partition-btn {
      position: relative;
      min-height: 43px !important;
      overflow: hidden;
      border: 1px solid #b5ccc1 !important;
      border-radius: 12px !important;
      color: var(--step2-primary-dark) !important;
      background: #fff !important;
      box-shadow: 0 5px 13px rgba(31, 70, 59, 0.07) !important;
      transition:
        color 180ms ease,
        border-color 180ms ease,
        background-color 180ms ease,
        box-shadow 180ms ease,
        transform 180ms ease !important;
    }

    #apiPartitionSection .partition-btn:hover:not(:disabled) {
      border-color: var(--step2-primary) !important;
      color: var(--step2-primary-dark) !important;
      background: var(--step2-primary-soft) !important;
      box-shadow: 0 8px 18px rgba(31, 70, 59, 0.11) !important;
      transform: translateY(-1px) !important;
    }

    #apiPartitionSection .partition-btn.primary {
      border-color: var(--step2-primary-dark) !important;
      color: #fff !important;
      background:
        linear-gradient(135deg, var(--step2-primary), var(--step2-primary-dark)) !important;
      box-shadow: 0 8px 18px rgba(49, 94, 84, 0.22) !important;
    }

    #apiPartitionSection .partition-btn.primary:hover:not(:disabled) {
      border-color: #244c43 !important;
      color: #fff !important;
      background: linear-gradient(135deg, #3d6e62, #244c43) !important;
      box-shadow: 0 11px 23px rgba(49, 94, 84, 0.27) !important;
    }

    #apiPartitionSection .partition-limit {
      margin-left: auto;
      padding: 7px 10px;
      border: 1px solid #e6d2b9;
      border-radius: 999px;
      color: #79552f !important;
      background: var(--step2-accent-soft);
      font-weight: 690;
    }

    #apiPartitionSection .partition-timeline-shell {
      gap: 10px;
      padding: 12px 0;
    }

    #apiPartitionSection .api-timeline-scroll {
      padding: 12px 10px 18px;
      border: 1px solid #c7d9d1;
      border-radius: 16px;
      background:
        linear-gradient(180deg, #f7fbf9, #ffffff);
      box-shadow:
        inset 0 1px 0 #fff,
        inset 0 -10px 24px rgba(71, 121, 109, 0.035);
      scrollbar-color: #88bda4 #edf4f0;
    }

    #apiPartitionSection .api-timeline {
      min-height: 146px;
      border: 1px solid #bcd0c7 !important;
      border-radius: 14px !important;
      color: var(--step2-ink) !important;
      background:
        repeating-linear-gradient(
          90deg,
          rgba(71, 121, 109, 0.028) 0,
          rgba(71, 121, 109, 0.028) 1px,
          transparent 1px,
          transparent 27px
        ),
        #fbfdfc !important;
      box-shadow: inset 0 1px 3px rgba(31, 70, 59, 0.045) !important;
    }

    #apiPartitionSection .api-byte-cell {
      border-color: #c9d9d2 !important;
      color: var(--step2-ink) !important;
      background: #fff !important;
      box-shadow: 0 4px 10px rgba(31, 70, 59, 0.055);
      transition:
        border-color 170ms ease,
        box-shadow 170ms ease,
        transform 170ms ease;
    }

    #apiPartitionSection .api-byte-cell:hover {
      border-color: #8eb1a2 !important;
      box-shadow: 0 8px 17px rgba(31, 70, 59, 0.11);
      transform: translateY(-2px);
    }

    #apiPartitionSection .api-byte-cell.partition-colored {
      border-color: var(--partition-color) !important;
      background: var(--partition-soft) !important;
      box-shadow:
        inset 0 4px 0 var(--partition-color),
        0 4px 10px rgba(31, 70, 59, 0.055) !important;
    }

    #apiPartitionSection .api-byte-index {
      color: #70857e !important;
    }

    #apiPartitionSection .api-byte-value {
      color: var(--partition-text, var(--step2-ink)) !important;
      font-weight: 850;
    }

    #apiPartitionSection .timeline-empty {
      min-height: 112px;
      border: 1px dashed #b8cec4 !important;
      border-radius: 14px;
      color: var(--step2-muted) !important;
      background:
        linear-gradient(145deg, #ffffff, var(--step2-primary-soft)) !important;
    }

    #apiPartitionSection .timeline-empty::before {
      color: var(--step2-primary) !important;
      filter: drop-shadow(0 4px 8px rgba(71, 121, 109, 0.2));
    }

    /*
       The + is real generated markup inside .cut-chip. Keep it explicitly
       visible even though older style layers suppress the pseudo marker.
    */
    #apiPartitionSection .cut-target:not(.active) .cut-chip,
    #apiPartitionSection .cut-target:not(.active) .cut-chip .fa-plus {
      display: inline-flex !important;
      opacity: 1 !important;
      visibility: visible !important;
    }

    #apiPartitionSection .cut-target:not(.active) .cut-chip {
      min-width: 24px;
      height: 24px;
      padding: 0;
      border: 1px solid #8fb2a3 !important;
      border-radius: 50%;
      color: var(--step2-primary-dark) !important;
      background: #fff !important;
      box-shadow:
        0 4px 11px rgba(31, 70, 59, 0.15),
        0 0 0 4px rgba(136, 189, 164, 0.1);
    }

    #apiPartitionSection .cut-target:not(.active):hover .cut-chip,
    #apiPartitionSection .cut-target:not(.active):focus-visible .cut-chip {
      border-color: var(--step2-accent) !important;
      color: #fff !important;
      background: var(--step2-accent) !important;
      box-shadow:
        0 7px 16px rgba(184, 118, 63, 0.25),
        0 0 0 5px rgba(184, 118, 63, 0.11);
    }

    #apiPartitionSection .cut-target.active .cut-chip {
      box-shadow:
        0 7px 17px rgba(107, 69, 42, 0.22),
        0 0 0 4px rgba(255, 255, 255, 0.75) !important;
    }

    #apiPartitionSection .partition-name-band {
      border-color: var(--partition-color) !important;
      border-radius: 0 0 12px 12px;
      background: var(--partition-soft) !important;
    }

    #apiPartitionSection .partition-name-band select {
      min-height: 39px !important;
      border-color: color-mix(in srgb, var(--partition-color) 58%, #b9cac2) !important;
      border-radius: 9px !important;
      color: var(--partition-text) !important;
      background: rgba(255, 255, 255, 0.94) !important;
      box-shadow: 0 3px 8px rgba(31, 70, 59, 0.06) !important;
    }

    #apiPartitionSection .partition-visual {
      margin-top: 17px;
      padding: 15px;
      border: 1px solid #c3d8ce !important;
      border-radius: 17px !important;
      background:
        radial-gradient(circle at 100% 0, rgba(184, 118, 63, 0.08), transparent 16rem),
        linear-gradient(145deg, #f6fbf8, #ffffff) !important;
      box-shadow: 0 8px 22px rgba(31, 70, 59, 0.065);
    }

    #apiPartitionSection .partition-visual-title {
      gap: 10px;
      padding-bottom: 11px;
      border-bottom: 1px solid #d9e5df;
      color: var(--step2-ink) !important;
    }

    #apiPartitionSection .partition-visual-title i {
      color: var(--step2-accent) !important;
    }

    #apiPartitionSection .partition-visual-legend,
    #apiPartitionSection .partition-visual-empty {
      color: var(--step2-muted);
    }

    #apiPartitionSection .partition-visual-block {
      overflow: hidden;
      border-radius: 13px;
      background: #fff !important;
      box-shadow: 0 6px 17px rgba(31, 70, 59, 0.075);
      transition:
        box-shadow 180ms ease,
        transform 180ms ease;
    }

    #apiPartitionSection .partition-visual-block:hover {
      box-shadow: 0 11px 24px rgba(31, 70, 59, 0.12);
      transform: translateY(-2px);
    }

    #apiPartitionSection .partition-confirm-row {
      gap: 12px !important;
      margin-top: 17px;
      padding-top: 15px;
      border-top: 1px dashed #c3d7cd;
    }

    #apiPartitionSection .partition-status {
      min-height: 42px;
      padding: 10px 12px;
      border: 1px solid #d0ddd7;
      border-radius: 12px;
      color: var(--step2-muted) !important;
      background: #fff;
    }

    #apiPartitionSection .partition-status.complete {
      border-color: #a7cdb6;
      color: #246443 !important;
      background: #edf8f1;
    }

    #apiPartitionSection .partition-status.error {
      border-color: #e3aaa5;
      color: #9c3028 !important;
      background: #fff2f0;
    }

    #apiPartitionSection .continue-btn {
      min-height: 44px !important;
      border: 1px solid var(--step2-primary-dark) !important;
      border-radius: 12px !important;
      color: #fff !important;
      background:
        linear-gradient(135deg, var(--step2-primary), var(--step2-primary-dark)) !important;
      box-shadow: 0 9px 20px rgba(49, 94, 84, 0.23) !important;
      transition:
        box-shadow 180ms ease,
        transform 180ms ease,
        filter 180ms ease !important;
    }

    #apiPartitionSection .continue-btn:hover:not(:disabled) {
      filter: brightness(0.96) saturate(1.05);
      box-shadow: 0 12px 25px rgba(49, 94, 84, 0.28) !important;
      transform: translateY(-2px) !important;
    }

    @keyframes step2SectionReveal {
      from {
        opacity: 0;
        transform: translateY(14px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @media (max-width: 760px) {
      #apiPartitionSection {
        padding: 17px !important;
        border-radius: 18px !important;
      }

      #apiPartitionSection .api-entry-row {
        grid-template-columns: 1fr !important;
        padding: 12px;
      }

      #apiPartitionSection .api-count {
        justify-content: center;
        white-space: normal;
      }

      #apiPartitionSection .partition-toolbar,
      #apiPartitionSection .partition-confirm-row {
        align-items: stretch;
      }

      #apiPartitionSection .partition-limit {
        width: 100%;
        margin-left: 0;
        border-radius: 11px;
        text-align: center;
      }

      #apiPartitionSection .partition-confirm-row {
        flex-direction: column;
      }
    }

    @media (max-width: 480px) {
      #apiPartitionSection {
        padding: 14px !important;
        border-radius: 15px !important;
      }

      #apiPartitionSection .step-heading {
        align-items: flex-start !important;
      }

      #apiPartitionSection .partition-toolbar .partition-btn {
        width: 100%;
      }

      #apiPartitionSection .partition-workspace,
      #apiPartitionSection .partition-visual {
        padding: 12px !important;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      #apiPartitionSection,
      #apiPartitionSection .api-byte-cell,
      #apiPartitionSection .partition-visual-block,
      #apiPartitionSection .partition-btn,
      #apiPartitionSection .continue-btn {
        animation: none !important;
        transition-duration: 0.01ms !important;
      }
    }

    /* Step 1: keep Parameter Name Source + Parameter Name + Frames + action. */
    #parameterCommandSection .parameter-main-row {
      display: grid !important;
      grid-template-columns:
        minmax(215px, 0.72fr)
        minmax(265px, 1fr)
        minmax(175px, 0.5fr)
        minmax(220px, auto) !important;
      gap: 16px !important;
      align-items: end !important;
      justify-content: stretch !important;
      width: 100% !important;
    }

    #parameterCommandSection .parameter-name-choice {
      display: grid;
      gap: 8px;
      width: 100%;
    }

    #parameterCommandSection .parameter-name-control[hidden] {
      display: none !important;
    }

    #parameterCommandSection .parameter-source-note,
    #parameterCommandSection .existing-parameter-note {
      display: flex;
      align-items: flex-start;
      gap: 6px;
      color: #526a64;
      font-size: 0.7rem;
      font-weight: 650;
      line-height: 1.4;
    }

    #parameterCommandSection .parameter-source-note i,
    #parameterCommandSection .existing-parameter-note i {
      margin-top: 2px;
      color: #659287;
    }

    #parameterCommandSection .parameter-source-empty {
      color: #9a6700;
    }

    #parameterCommandSection #parameterNameSourceSelect:disabled,
    #parameterCommandSection #existingParameterNameSelect:disabled,
    #parameterCommandSection #customParameterNameInput:read-only {
      cursor: not-allowed;
      background: #f1f5f3 !important;
      color: #5d6e68 !important;
    }

    #parameterCommandSection .param-generate-item {
      display: flex !important;
      align-items: flex-end !important;
      height: 100%;
    }

    #parameterCommandSection .param-generate-item #generateFramesBtn {
      width: 95% !important;
      min-width: 10px !important;
      /* margin: 0 !important; */
    }

    @media (max-width: 800px) {
      #parameterCommandSection .parameter-main-row {
        grid-template-columns: 1fr !important;
      }

      #parameterCommandSection .param-generate-item #generateFramesBtn {
        min-width: 0 !important;
      }
    }

    /* Step 1: Voice command configuration */
    #parameterCommandSection .voice-command-row {
      display: grid !important;
      grid-template-columns: minmax(220px, 0.42fr) minmax(360px, 1fr) !important;
      gap: 16px !important;
      align-items: start !important;
      width: 100% !important;
      margin-top: 2px;
      padding-top: 14px;
      border-top: 1px solid #dce7e2;
    }

    #parameterCommandSection .voice-command-editor {
      display: grid;
      gap: 9px;
      width: 100%;
    }

    #parameterCommandSection .voice-command-editor[hidden] {
      display: none !important;
    }

    #parameterCommandSection .voice-command-list {
      display: grid;
      gap: 8px;
    }

    #parameterCommandSection .voice-command-input-row {
      display: grid;
      grid-template-columns: minmax(0, 1fr) 44px;
      gap: 8px;
      align-items: center;
    }

    #parameterCommandSection .voice-command-input-row input {
      width: 100% !important;
      min-height: 46px;
      padding: 0.65rem 0.8rem;
      border: 1px solid #9fb9ae;
      border-radius: 10px;
      color: #203b35;
      background: #fff;
      font-size: 0.95rem;
      font-weight: 600;
      outline: none;
    }

    #parameterCommandSection .voice-command-input-row input:focus {
