      box-shadow: 0 0 0 3px rgba(101, 146, 135, 0.18);
    }

    #parameterCommandSection .voice-command-remove,
    #parameterCommandSection .voice-command-add {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 7px;
      min-height: 42px;
      border-radius: 10px;
