    /* =========================================================
       Premium generated-card enhancement
       Strictly scoped to #commandFramesContainer so no other
       page section, markup or application behavior is affected.
       ========================================================= */
    #commandFramesContainer > .command-frame-card {
      --premium-card-shadow:
        0 2px 5px rgba(27, 49, 41, 0.05),
        0 14px 34px rgba(27, 49, 41, 0.1);
      --premium-card-shadow-hover:
        0 6px 14px rgba(27, 49, 41, 0.08),
        0 24px 52px rgba(27, 49, 41, 0.16);
      padding: 20px !important;
      gap: 13px !important;
      border: 1px solid
        color-mix(in srgb, var(--frame-accent) 32%, #d7e1dc) !important;
      border-radius: 22px !important;
      background:
        radial-gradient(
          circle at 100% 0,
          color-mix(in srgb, var(--frame-accent) 10%, transparent),
          transparent 38%
        ),
        linear-gradient(148deg, #ffffff 0%, #fbfdfc 67%, var(--frame-accent-soft) 145%) !important;
      box-shadow: var(--premium-card-shadow) !important;
      transform-origin: 50% 70%;
      animation: premiumFrameCardReveal 480ms
        cubic-bezier(0.16, 1, 0.3, 1) both;
      transition:
        transform 240ms cubic-bezier(0.16, 1, 0.3, 1),
        border-color 220ms ease,
        box-shadow 240ms ease,
        background 240ms ease !important;
    }

    #commandFramesContainer > .command-frame-card::before {
      inset: 0 0 auto 0 !important;
      width: 100% !important;
      height: 5px !important;
      border-radius: 22px 22px 0 0 !important;
      background:
        linear-gradient(
          90deg,
          var(--frame-accent),
          color-mix(in srgb, var(--frame-accent) 52%, #ffffff),
          var(--frame-accent)
        ) !important;
      background-size: 180% 100% !important;
      box-shadow: 0 3px 13px
        color-mix(in srgb, var(--frame-accent) 28%, transparent);
      animation: premiumAccentFlow 4.8s ease-in-out infinite;
    }

    #commandFramesContainer > .command-frame-card::after {
      top: -92px;
      right: -88px;
      width: 210px;
      height: 210px;
      opacity: 0.72;
      background:
        radial-gradient(
          circle,
          color-mix(in srgb, var(--frame-accent) 16%, transparent),
          transparent 67%
        );
      transform: scale(0.92);
      transition:
        opacity 280ms ease,
        transform 380ms cubic-bezier(0.16, 1, 0.3, 1);
    }

    #commandFramesContainer > .command-frame-card:hover {
      border-color: color-mix(in srgb, var(--frame-accent) 62%, #bdcbc4) !important;
      background:
        radial-gradient(
          circle at 100% 0,
          color-mix(in srgb, var(--frame-accent) 15%, transparent),
          transparent 40%
        ),
        linear-gradient(148deg, #ffffff, var(--frame-accent-soft) 145%) !important;
      box-shadow:
        var(--premium-card-shadow-hover),
        0 0 0 3px
          color-mix(in srgb, var(--frame-accent) 10%, transparent) !important;
      transform: translateY(-7px) scale(1.008) !important;
    }

    #commandFramesContainer > .command-frame-card:hover::after {
      opacity: 1;
      transform: scale(1.18) translate(-5px, 5px);
    }

    #commandFramesContainer > .command-frame-card:active {
      box-shadow: var(--premium-card-shadow) !important;
      transform: translateY(-3px) scale(0.997) !important;
    }

    #commandFramesContainer > .command-frame-card:focus-within {
      border-color: var(--frame-accent) !important;
      outline: none;
      box-shadow:
        0 0 0 4px
          color-mix(in srgb, var(--frame-accent) 17%, transparent),
        var(--premium-card-shadow-hover) !important;
    }

    #commandFramesContainer > .command-frame-card.selected {
      border-color: var(--frame-accent) !important;
      background:
        radial-gradient(
          circle at 100% 0,
          color-mix(in srgb, var(--frame-accent) 18%, transparent),
          transparent 42%
        ),
        linear-gradient(150deg, var(--frame-accent-soft), #ffffff 68%) !important;
      box-shadow:
        0 0 0 3px
          color-mix(in srgb, var(--frame-accent) 14%, transparent),
        0 22px 48px rgba(27, 49, 41, 0.15) !important;
    }

    #commandFramesContainer > .command-frame-card .frame-card-head {
      min-height: 46px;
      padding: 2px 3px 3px 0;
    }

    #commandFramesContainer > .command-frame-card .frame-title {
      color: #213b32 !important;
      font-size: 1rem !important;
      font-weight: 820 !important;
      letter-spacing: -0.02em !important;
    }

    #commandFramesContainer > .command-frame-card .frame-card-icon {
      width: 43px;
      height: 43px;
      flex-basis: 43px;
      border: 1px solid
        color-mix(in srgb, var(--frame-accent) 40%, #ffffff) !important;
      border-radius: 14px !important;
      background:
        linear-gradient(145deg, #ffffff, var(--frame-accent-soft)) !important;
      box-shadow:
        0 7px 17px
          color-mix(in srgb, var(--frame-accent) 20%, transparent),
        inset 0 1px 0 rgba(255, 255, 255, 0.94) !important;
      transition:
        transform 260ms cubic-bezier(0.16, 1, 0.3, 1),
        box-shadow 240ms ease !important;
    }

    #commandFramesContainer > .command-frame-card:hover .frame-card-icon {
      box-shadow:
        0 11px 23px
          color-mix(in srgb, var(--frame-accent) 27%, transparent),
        inset 0 1px 0 #ffffff !important;
      transform: translateY(-3px) rotate(-5deg) scale(1.06);
    }

    #commandFramesContainer > .command-frame-card .frame-status-badge {
      min-height: 29px;
      padding: 5px 1px !important;
      border-color: color-mix(in srgb, var(--frame-accent) 34%, #d3ddd8) !important;
      border-radius: 999px !important;
      box-shadow:
        0 3px 9px color-mix(in srgb, var(--frame-accent) 10%, transparent),
        inset 0 1px 0 rgba(255, 255, 255, 0.8) !important;
    }

    #commandFramesContainer > .command-frame-card .remove-btn {
      top: 1px;
      right: 3px;
      width: 30px;
      height: 30px;
      opacity: 0.62;
      transition:
        opacity 180ms ease,
        color 180ms ease,
        background 180ms ease,
        transform 180ms ease !important;
    }

    #commandFramesContainer > .command-frame-card:hover .remove-btn,
    #commandFramesContainer > .command-frame-card .remove-btn:focus-visible {
      opacity: 1;
    }

    #commandFramesContainer > .command-frame-card .remove-btn:hover {
      transform: translateY(-1px) rotate(5deg) scale(1.06) !important;
    }

    #commandFramesContainer > .command-frame-card .frame-settings {
      gap: 12px !important;
      padding: 13px !important;
      border: 1px solid
        color-mix(in srgb, var(--frame-accent) 18%, #d7e1dc) !important;
      border-radius: 15px !important;
      background:
        linear-gradient(
          150deg,
          rgba(255, 255, 255, 0.92),
          color-mix(in srgb, var(--frame-accent-soft) 36%, #ffffff)
        ) !important;
      box-shadow:
        inset 0 1px 0 #ffffff,
        0 4px 13px rgba(27, 49, 41, 0.04) !important;
      transition:
        border-color 200ms ease,
        box-shadow 200ms ease !important;
    }

    #commandFramesContainer > .command-frame-card .frame-settings:focus-within {
      border-color: color-mix(in srgb, var(--frame-accent) 48%, #c3d0ca) !important;
      box-shadow:
        0 0 0 3px
          color-mix(in srgb, var(--frame-accent) 9%, transparent),
        inset 0 1px 0 #ffffff !important;
    }

    #commandFramesContainer > .command-frame-card .frame-setting select {
      min-height: 45px !important;
      border-color: #c4d1cb !important;
      border-radius: 11px !important;
      background-color: rgba(255, 255, 255, 0.97) !important;
      box-shadow:
        0 2px 5px rgba(27, 49, 41, 0.04),
        inset 0 1px 0 #ffffff !important;
      transition:
        border-color 180ms ease,
        box-shadow 180ms ease,
        transform 180ms ease !important;
    }

    #commandFramesContainer > .command-frame-card .frame-setting select:hover {
      border-color: color-mix(in srgb, var(--frame-accent) 54%, #aebeb6) !important;
      box-shadow: 0 6px 15px rgba(27, 49, 41, 0.08) !important;
      transform: translateY(-1px);
    }

    #commandFramesContainer > .command-frame-card .frame-setting select:focus {
      border-color: var(--frame-accent) !important;
      outline: none !important;
      box-shadow:
        0 0 0 3px
          color-mix(in srgb, var(--frame-accent) 16%, transparent),
        0 6px 15px rgba(27, 49, 41, 0.08) !important;
    }

    #commandFramesContainer > .command-frame-card .frame-code,
    #commandFramesContainer > .command-frame-card .frame-partition-state {
      min-height: 41px;
      border-color: color-mix(in srgb, var(--frame-accent) 23%, #d0dcd6) !important;
      border-radius: 12px !important;
      background:
        linear-gradient(
          145deg,
          rgba(255, 255, 255, 0.94),
          color-mix(in srgb, var(--frame-accent-soft) 25%, #ffffff)
        ) !important;
      box-shadow: inset 0 1px 0 #ffffff !important;
    }

    #commandFramesContainer > .command-frame-card .frame-config-btn {
      min-height: 47px !important;
      border-radius: 13px !important;
      letter-spacing: 0.005em;
      box-shadow:
        0 10px 23px
          color-mix(in srgb, var(--frame-accent) 28%, transparent),
        inset 0 1px 0 rgba(255, 255, 255, 0.25) !important;
      transition:
        transform 200ms cubic-bezier(0.16, 1, 0.3, 1),
        filter 200ms ease,
        box-shadow 200ms ease !important;
    }

    #commandFramesContainer > .command-frame-card .frame-config-btn:hover {
      box-shadow:
        0 14px 29px
          color-mix(in srgb, var(--frame-accent) 35%, transparent),
        inset 0 1px 0 rgba(255, 255, 255, 0.28) !important;
      transform: translateY(-3px) !important;
    }

    #commandFramesContainer > .add-frame-card {
      position: relative;
      min-height: 250px;
      overflow: hidden;
      border: 2px dashed #aebfb7 !important;
      border-radius: 22px !important;
      color: #315e50 !important;
      background:
        radial-gradient(circle at 50% 35%, rgba(71, 121, 109, 0.12), transparent 36%),
        linear-gradient(145deg, #fbfdfc, #f1f7f4) !important;
      box-shadow:
        0 2px 5px rgba(27, 49, 41, 0.04),
        0 12px 28px rgba(27, 49, 41, 0.07) !important;
      animation: premiumFrameCardReveal 480ms
        cubic-bezier(0.16, 1, 0.3, 1) both;
      transition:
        color 220ms ease,
        border-color 220ms ease,
        background 220ms ease,
        box-shadow 240ms ease,
        transform 240ms cubic-bezier(0.16, 1, 0.3, 1) !important;
    }

    #commandFramesContainer > .add-frame-card:hover {
      color: #214e43 !important;
      border-color: #47796d !important;
      background:
        radial-gradient(circle at 50% 35%, rgba(71, 121, 109, 0.18), transparent 39%),
        linear-gradient(145deg, #ffffff, #eaf4ef) !important;
      box-shadow:
        0 7px 15px rgba(27, 49, 41, 0.08),
        0 22px 46px rgba(27, 49, 41, 0.14),
        0 0 0 4px rgba(71, 121, 109, 0.08) !important;
      transform: translateY(-6px) scale(1.006) !important;
    }

    #commandFramesContainer > .add-frame-card .add-frame-card-inner {
      gap: 13px;
      font-weight: 800;
    }

    #commandFramesContainer > .add-frame-card .add-frame-card-inner i {
      display: grid;
      width: 54px;
      height: 54px;
      place-items: center;
      border: 1px solid rgba(71, 121, 109, 0.3);
      border-radius: 17px;
      background: rgba(255, 255, 255, 0.86);
      box-shadow:
        0 9px 21px rgba(42, 91, 77, 0.15),
        inset 0 1px 0 #ffffff;
      transition:
        transform 300ms cubic-bezier(0.16, 1, 0.3, 1),
        box-shadow 240ms ease;
    }

    #commandFramesContainer > .add-frame-card:hover .add-frame-card-inner i {
      box-shadow:
        0 13px 27px rgba(42, 91, 77, 0.2),
        inset 0 1px 0 #ffffff;
      transform: rotate(90deg) scale(1.08);
    }

    @keyframes premiumFrameCardReveal {
      from {
        opacity: 0;
        transform: translateY(18px) scale(0.975);
      }
      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

    @keyframes premiumAccentFlow {
      0%,
      100% {
