      backdrop-filter: none !important;
      -webkit-backdrop-filter: none !important;
    }

    /*
     * Warning remains on the left side of the footer.
     * Save state + actions stay on the right.
     */
    .action-row .save-requirement-hint {
      margin-right: auto !important;
    }

    .action-row .save-status-badge {
      flex: 0 0 auto !important;
    }

    .action-row .save-btn {
      flex: 0 0 auto !important;
    }

    /*
     * Keep Delete Configuration immediately to the LEFT of Save Configuration.
     * Grouping them prevents one button from wrapping under the other.
     */
    .action-row .configuration-action-buttons {
      display: flex !important;
      align-items: center !important;
      justify-content: flex-end !important;
      gap: 10px !important;
      flex: 0 0 auto !important;
      margin: 0 !important;
    }

    .action-row .configuration-action-buttons .save-btn {
      margin: 0 !important;
    }

    /* Push Button has Preset Names only, so use the full popup width. */
    #uiConfigToggleSection .ui-config-fields.push-button-preset-only {
      grid-template-columns: minmax(0, 1fr) !important;
    }

    /*
     * Override the old mobile rule:
     * .action-row { bottom: 0 !important; }
     * The footer must scroll naturally on every screen size.
     */
    @media (max-width: 760px) {
      .action-row {
        position: relative !important;
        top: auto !important;
        bottom: auto !important;
        left: auto !important;
        right: auto !important;
        z-index: auto !important;

        flex-direction: column !important;
        align-items: stretch !important;
      }

      .action-row .save-requirement-hint,
      .action-row .save-status-badge,
      .action-row .configuration-action-buttons {
        width: 100% !important;
        margin-right: 0 !important;
      }

      .action-row .configuration-action-buttons .save-btn {
        flex: 1 1 0 !important;
        width: auto !important;
        min-width: 0 !important;
      }

      .action-row .save-status-badge {
        justify-content: center !important;
      }
    }
  </style>


