    /* ============================================================
       Multiple UI True / False popup
       Replaces only the old Multiple UI dropdown.
       ============================================================ */

    .frame-multiple-ui-button {
      width: 100%;
      min-width: 0;
      min-height: 46px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      padding: 8px 11px;
      border: 1px solid #cfdcd6;
      border-radius: 12px;
      background: #fff;
      color: var(--ui-ink, #172b26);
      font-family: inherit;
      text-align: left;
      cursor: pointer;
      box-shadow: var(--ui-control-shadow, 0 1px 2px rgba(29, 65, 56, 0.04));
    }

    .frame-multiple-ui-button:hover {
      border-color: var(--ui-primary, #376f64);
      background: var(--ui-primary-soft, #edf7f3);
    }

    .frame-multiple-ui-button:focus-visible {
      outline: 0;
      border-color: var(--ui-primary, #376f64);
      box-shadow: 0 0 0 4px rgba(55, 111, 100, 0.13);
    }

    .frame-multiple-ui-button.frame-field-error {
      border: 2px solid var(--ui-danger, #c9362b) !important;
      background: var(--ui-danger-soft, #fff2f1) !important;
      box-shadow: 0 0 0 3px rgba(201, 54, 43, 0.11) !important;
    }

    .multiple-ui-button-main {
      min-width: 0;
      display: flex;
      align-items: center;
      gap: 9px;
    }

    .multiple-ui-button-main > i {
      flex: 0 0 auto;
      width: 26px;
      color: var(--ui-primary, #376f64);
      text-align: center;
    }

    .multiple-ui-button-copy {
      min-width: 0;
      display: flex;
      flex-direction: column;
      gap: 2px;
    }

    .multiple-ui-button-copy strong {
      overflow: hidden;
      color: var(--ui-ink, #172b26);
      font-size: 0.76rem;
      font-weight: 800;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .multiple-ui-button-copy small {
      overflow: hidden;
