      padding: 20px;
    }

    .ui-config-section[hidden] {
      display: none !important;
    }

    .ui-config-fields {
      display: grid;
      gap: 14px;
    }

    .ui-config-fields.two-columns {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    #asperUiFieldGroup[hidden] {
      display: none !important;
    }

    #asperUiFieldGroup[hidden] + .ui-values-field-column {
      grid-column: 1 / -1;
    }

    .ui-config-fields .form-group {
      margin: 0;
    }

    .ui-config-fields input,
    .ui-config-fields select {
      width: 100%;
      min-height: 46px;
      padding: 0.65rem 0.8rem;
      border: 1px solid #9fb9ae;
      border-radius: 10px;
      background: #fff;
      color: #203b35;
      font-size: 0.92rem;
      outline: none;
    }

    .ui-config-fields input:focus,
    .ui-config-fields select:focus {
      border-color: #659287;
      box-shadow: 0 0 0 3px rgba(101, 146, 135, 0.18);
    }

    /* Toggle As Per UI: preset selector + Custom mode. */
    .toggle-asper-ui-control-row {
      display: flex;
      align-items: stretch;
      gap: 8px;
      width: 100%;
    }

    /* The preset selector + Custom button belong to Toggle Switch only.
       Author CSS must not override the HTML hidden attribute for other UI types. */
    .toggle-asper-ui-control-row[hidden] {
      display: none !important;
    }

    .toggle-asper-ui-control-row > select,
    .toggle-asper-ui-control-row > input {
      flex: 1 1 auto;
      min-width: 0;
    }

    .toggle-asper-ui-control-row > [hidden] {
      display: none !important;
    }

    .toggle-custom-mode-btn {
      flex: 0 0 auto;
      min-height: 46px;
      padding: 0 14px;
      border: 1px solid #79a99c;
      border-radius: 10px;
      background: #f2faf7;
      color: #245c50;
      font-size: 0.82rem;
      font-weight: 800;
      cursor: pointer;
      white-space: nowrap;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      transition: 0.18s ease;
    }

    .toggle-custom-mode-btn:hover,
    .toggle-custom-mode-btn:focus-visible {
      border-color: #3f7f70;
      background: #e7f5f0;
      box-shadow: 0 0 0 3px rgba(101, 146, 135, 0.16);
      outline: none;
    }

    .toggle-custom-mode-btn.is-active {
      background: #2f6f60;
      border-color: #2f6f60;
      color: #fff;
    }

    .toggle-custom-mode-btn:disabled {
      opacity: 0.55;
      cursor: not-allowed;
    }

    .ui-config-preview-card {
      margin-top: 16px;
      padding: 15px;
      border: 1px solid #b8cdc4;
      border-radius: 14px;
      background: #f8fbfa;
    }

    .ui-slider-live-demo {
      --slider-track: linear-gradient(90deg, #111827 0%, #f59e0b 70%, #fff7ed 100%);
      --slider-thumb: #f59e0b;
      --slider-accent: #2563eb;
      --slider-icon-bg: #fff7ed;
      --slider-icon-color: #f59e0b;
      display: grid;
      gap: 16px;
      padding: 18px 20px 20px;
      border: 1px solid #dce5ef;
      border-radius: 20px;
      background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9);
    }

    .ui-slider-preview-title {
      display: flex;
      align-items: center;
      gap: 9px;
      color: #64748b;
      font-size: 0.78rem;
      font-weight: 850;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .ui-slider-preview-icon {
      display: inline-grid;
      place-items: center;
      width: 27px;
      height: 27px;
      border-radius: 9px;
      background: var(--slider-icon-bg);
      color: var(--slider-icon-color);
      font-size: 0.78rem;
    }

    .ui-slider-preview-reading {
      display: grid;
      grid-template-columns: minmax(70px, 1fr) auto minmax(70px, 1fr);
      align-items: center;
      gap: 12px;
      margin-top: -1px;
    }

    .ui-slider-edge-label {
      color: #64748b;
      font-size: 0.82rem;
      font-weight: 850;
      letter-spacing: 0.02em;
      text-transform: uppercase;
    }

    .ui-slider-edge-label:last-child {
      text-align: right;
    }

    #uiSliderPreviewValue {
      color: var(--slider-accent);
      font-size: clamp(1.45rem, 4vw, 1.9rem);
      font-weight: 900;
      line-height: 1;
      text-align: center;
      white-space: nowrap;
    }

    .ui-slider-track-wrap {
      position: relative;
      padding: 5px 1px 1px;
    }

    #uiSliderPreview {
      width: 100%;
      height: 30px;
      margin: 0;
      appearance: none;
      -webkit-appearance: none;
      background: transparent;
      cursor: pointer;
      outline: none;
    }

    #uiSliderPreview::-webkit-slider-runnable-track {
      height: 9px;
      border: 1px solid rgba(15, 23, 42, 0.08);
      border-radius: 999px;
      background: var(--slider-track);
      box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.14);
    }

    #uiSliderPreview::-webkit-slider-thumb {
      width: 27px;
      height: 27px;
      margin-top: -10px;
      border: 3px solid #fff;
      border-radius: 50%;
      background: var(--slider-thumb);
      box-shadow:
        0 3px 8px rgba(15, 23, 42, 0.23),
        0 0 0 1px rgba(15, 23, 42, 0.05);
      appearance: none;
      -webkit-appearance: none;
    }

    #uiSliderPreview::-moz-range-track {
      height: 9px;
      border: 1px solid rgba(15, 23, 42, 0.08);
      border-radius: 999px;
      background: var(--slider-track);
      box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.14);
    }

    #uiSliderPreview::-moz-range-thumb {
      width: 26px;
      height: 26px;
      border: 3px solid #fff;
      border-radius: 50%;
      background: var(--slider-thumb);
      box-shadow:
        0 3px 8px rgba(15, 23, 42, 0.23),
        0 0 0 1px rgba(15, 23, 42, 0.05);
    }

    .ui-slider-preview-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px 14px;
      flex-wrap: wrap;
      padding-top: 2px;
      color: #7b8a9e;
      font-size: 0.68rem;
      font-weight: 750;
    }

    .ui-slider-preview-meta strong {
      color: #415269;
    }

    @media (max-width: 560px) {
      .ui-slider-live-demo {
        padding: 15px;
      }

      .ui-slider-preview-reading {
        grid-template-columns: 1fr auto 1fr;
        gap: 8px;
      }

      .ui-slider-edge-label {
        font-size: 0.72rem;
      }

      #uiSliderPreviewValue {
        font-size: 1.45rem;
      }
    }

    /* Hue Circle live preview - reference gauge style */
    .ui-slider-live-demo[hidden],
    .ui-hue-circle-live-demo[hidden],
    .ui-auto-timer-live-demo[hidden] {
      display: none !important;
    }

    .ui-hue-circle-live-demo {
      display: grid;
      gap: 10px;
      padding: 12px;
      border: 1px solid #dce6f2;
      border-radius: 20px;
      background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.94),
        0 10px 28px -24px rgba(30, 64, 175, 0.42);
    }

    .ui-hue-circle-header {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 1px 2px 0;
    }

    .ui-hue-circle-header-icon {
      display: grid;
      place-items: center;
      flex: 0 0 34px;
      width: 34px;
      height: 34px;
      border: 1px solid #d9e5fb;
      border-radius: 50%;
      background: #eef4ff;
      color: #2f6ff0;
      box-shadow: inset 0 0 0 4px rgba(47, 111, 240, 0.04);
    }

    .ui-hue-circle-header-copy {
      display: grid;
      gap: 2px;
      min-width: 0;
    }

    .ui-hue-circle-header-copy strong {
      color: #61728a;
      font-size: 0.76rem;
      font-weight: 900;
      letter-spacing: 0.055em;
      text-transform: uppercase;
    }

    .ui-hue-circle-header-copy span {
      color: #111827;
      font-size: 1.02rem;
      font-weight: 900;
      line-height: 1.05;
    }

    .ui-hue-circle-panel {
      display: grid;
      justify-items: center;
      gap: 6px;
      padding: 10px 12px 10px;
      border: 1px solid #dbe5f0;
      border-radius: 18px;
      background: linear-gradient(180deg, #f9fbfe 0%, #f3f7fb 100%);
      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.95),
        0 8px 22px -20px rgba(15, 23, 42, 0.28);
    }

    .ui-hue-circle-level-label {
      color: #66778f;
      font-size: 0.74rem;
      font-weight: 900;
      letter-spacing: 0.075em;
      text-transform: uppercase;
    }

    .ui-hue-circle-gauge {
      --hue-circle-angle: 135deg;
      position: relative;
      width: min(190px, 62vw);
      aspect-ratio: 1;
      display: grid;
      place-items: center;
      border-radius: 50%;
      cursor: grab;
      touch-action: none;
      outline: none;
      user-select: none;
    }

    .ui-hue-circle-gauge.is-dragging {
      cursor: grabbing;
    }

    .ui-hue-circle-gauge:focus-visible {
      box-shadow: 0 0 0 4px rgba(47, 111, 240, 0.16);
    }

    .ui-hue-circle-svg {
      width: 100%;
      height: 100%;
      overflow: visible;
      transform: rotate(0.001deg);
    }

    .ui-hue-circle-track,
    .ui-hue-circle-progress {
      fill: none;
      stroke-width: 18;
      stroke-linecap: round;
      transform: rotate(135deg);
      transform-origin: 120px 120px;
    }

    .ui-hue-circle-track {
      stroke: #dfe6ef;
      stroke-dasharray: 402 515.22;
    }

    .ui-hue-circle-progress {
      stroke: url(#uiHueCircleGradient);
      stroke-dasharray: 201 515.22;
      transition: stroke-dasharray 120ms ease;
      filter: drop-shadow(0 2px 3px rgba(37, 99, 235, 0.12));
    }

    .ui-hue-circle-needle-wrap {
      position: absolute;
      left: 50%;
      top: 50%;
      width: 0;
      height: 0;
      transform: translate(-50%, -50%) rotate(var(--hue-circle-angle));
      transform-origin: center;
      transition: transform 120ms ease;
      pointer-events: none;
    }

    .ui-hue-circle-needle {
      position: absolute;
      left: 0;
      top: 0;
      width: 26px;
      height: 50px;
      transform: translate(-50%, -100%);
      clip-path: polygon(50% 0, 100% 100%, 0 100%);
      background: linear-gradient(180deg, #2f6ff0 0%, #2563eb 100%);
      filter: drop-shadow(0 3px 3px rgba(37, 99, 235, 0.16));
    }

    .ui-hue-circle-hub {
      position: absolute;
      left: 0;
      top: 0;
      width: 26px;
      height: 26px;
      transform: translate(-50%, -50%);
      border: 4px solid #fff;
      border-radius: 50%;
      background: #f8fafc;
      box-shadow:
        0 4px 10px rgba(15, 23, 42, 0.16),
        inset 0 0 0 1px #dce5ef;
    }

    .ui-hue-circle-readout {
      display: inline-flex;
      align-items: baseline;
      justify-content: center;
      gap: 7px;
      margin-top: -2px;
      color: #111827;
      font-weight: 900;
    }

    .ui-hue-circle-readout strong {
      color: #2f6ff0;
      font-size: clamp(1.45rem, 4vw, 1.8rem);
      line-height: 1;
    }

    .ui-hue-circle-readout span {
      font-size: 0.95rem;
    }

    .ui-hue-circle-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px 14px;
      flex-wrap: wrap;
      color: #7b8a9e;
      font-size: 0.68rem;
      font-weight: 750;
    }

    .ui-hue-circle-meta strong {
      color: #415269;
    }

    .ui-hue-circle-help {
      display: flex;
      align-items: flex-start;
      gap: 7px;
      padding: 9px 10px;
      border-radius: 10px;
      background: #eef4ff;
      color: #516781;
      font-size: 0.68rem;
      font-weight: 700;
      line-height: 1.4;
    }

    .ui-hue-circle-help i {
      margin-top: 2px;
      color: #2f6ff0;
    }

    @media (max-width: 560px) {
      .ui-hue-circle-live-demo {
        padding: 14px;
      }

      .ui-hue-circle-panel {
        padding-left: 8px;
        padding-right: 8px;
      }

      .ui-hue-circle-gauge {
        width: min(175px, 58vw);
      }
    }

    /* Auto Trigger With Timer live preview - compact timer card style */
    .ui-auto-timer-live-demo {
      display: grid;
      gap: 10px;
      padding: 12px;
      border: 1px solid #dce6f2;
      border-radius: 18px;
      background: #ffffff;
      box-shadow: 0 8px 24px -22px rgba(30, 64, 175, 0.36);
    }

    .ui-auto-timer-header {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .ui-auto-timer-header-icon {
      display: grid;
      place-items: center;
      flex: 0 0 32px;
      width: 32px;
      height: 32px;
      border: 1px solid #d9e5fb;
      border-radius: 50%;
      background: #eef4ff;
      color: #2f6ff0;
    }

    .ui-auto-timer-header-copy {
      display: grid;
      gap: 1px;
      min-width: 0;
    }

    .ui-auto-timer-header-copy strong {
      color: #61728a;
      font-size: 0.7rem;
      font-weight: 900;
      letter-spacing: 0.055em;
      text-transform: uppercase;
    }

    .ui-auto-timer-header-copy span {
      color: #111827;
      font-size: 0.95rem;
      font-weight: 900;
      line-height: 1.05;
    }

    .ui-auto-timer-panel {
      padding: 12px;
      border: 1px solid #dbe5f0;
      border-radius: 15px;
      background: linear-gradient(180deg, #f9fbfe 0%, #f4f8fc 100%);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.95);
    }

    .ui-auto-timer-title {
      display: flex;
      align-items: center;
      gap: 7px;
      margin-bottom: 8px;
      color: #66778f;
      font-size: 0.67rem;
      font-weight: 900;
      letter-spacing: 0.055em;
      text-transform: uppercase;
    }

    .ui-auto-timer-title i { color: #10a67d; }

    .ui-auto-timer-reading {
      display: grid;
      grid-template-columns: 1fr auto 1fr;
      align-items: center;
      gap: 8px;
      margin-bottom: 8px;
      color: #66778f;
      font-size: 0.68rem;
      font-weight: 850;
      text-transform: uppercase;
    }

    .ui-auto-timer-reading span:last-child { text-align: right; }

    .ui-auto-timer-reading strong {
      color: #2563eb;
      font-size: 1.35rem;
      font-weight: 900;
      line-height: 1;
      text-transform: none;
    }

    .ui-auto-timer-range {
      width: 100%;
      height: 26px;
      margin: 0;
      appearance: none;
      -webkit-appearance: none;
      background: transparent;
      cursor: pointer;
    }

    .ui-auto-timer-range::-webkit-slider-runnable-track {
      height: 7px;
      border-radius: 999px;
      background: linear-gradient(90deg, #c6f1e5 0%, #79d7bd 100%);
    }

    .ui-auto-timer-range::-webkit-slider-thumb {
      width: 20px;
      height: 20px;
      margin-top: -6.5px;
      appearance: none;
      -webkit-appearance: none;
      border: 3px solid #ffffff;
      border-radius: 50%;
      background: #10a67d;
      box-shadow: 0 2px 6px rgba(15, 118, 90, 0.28);
    }

    .ui-auto-timer-range::-moz-range-track {
      height: 7px;
      border: 0;
      border-radius: 999px;
      background: linear-gradient(90deg, #c6f1e5 0%, #79d7bd 100%);
    }

    .ui-auto-timer-range::-moz-range-thumb {
      width: 16px;
      height: 16px;
      border: 3px solid #ffffff;
      border-radius: 50%;
      background: #10a67d;
      box-shadow: 0 2px 6px rgba(15, 118, 90, 0.28);
    }

    .ui-auto-timer-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px 14px;
      flex-wrap: wrap;
      color: #7b8a9e;
      font-size: 0.66rem;
      font-weight: 750;
    }

    .ui-auto-timer-meta strong { color: #415269; }

    .ui-auto-timer-help {
      display: flex;
      align-items: flex-start;
      gap: 7px;
      padding: 8px 9px;
      border-radius: 10px;
      background: #eefaf6;
      color: #516781;
      font-size: 0.67rem;
      font-weight: 700;
      line-height: 1.4;
    }

    .ui-auto-timer-help i {
      margin-top: 2px;
      color: #10a67d;
    }

    /* Push Button / Button live preview - reference card style */
    .ui-button-live-demo {
      display: grid;
      gap: 12px;
      padding: 16px;
      border: 1px solid #dce6f2;
      border-radius: 18px;
      background: #f7faff;
    }

    /* Never show Button / Push Button preview for other UI types (for example Toggle). */
    .ui-button-live-demo[hidden] {
      display: none !important;
    }

    .ui-button-preview-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      flex-wrap: wrap;
    }

    .ui-button-preview-title {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      color: #31485f;
      font-size: 0.78rem;
      font-weight: 850;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .ui-button-preview-title i {
      color: #2f6ff0;
    }

    .ui-button-preview-badge {
      display: inline-flex;
      align-items: center;
      min-height: 32px;
      padding: 4px 9px;
      border: 1px solid #d6e0ec;
      border-radius: 999px;
      background: #fff;
      color: #66788e;
      font-size: 0.64rem;
      font-weight: 800;
    }

    .ui-button-preview-stage {
      display: block;
      min-height: 0;
      padding: 0;
      border: 0;
      background: transparent;
    }

    /* Exact card-style preview requested for Button / Push Button. */
    .ui-button-reference-card {
      width: 50%;
      min-height: 88px;
      display: grid;
      grid-template-columns: 44px minmax(0, 1fr) auto;
      align-items: center;
      gap: 12px;
      padding: 12px 16px;
      border: 1px solid #d9e3ee;
      border-radius: 18px;
      background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
      box-shadow:
        0 8px 18px rgba(32, 59, 95, 0.08),
        inset 0 1px 0 rgba(255, 255, 255, 0.96);
    }

    .ui-button-reference-left-icon {
      width: 42px;
      height: 42px;
      display: grid;
      place-items: center;
      border: 1px solid #d7e3f8;
      border-radius: 50%;
      background: #eef4ff;
      color: #2e6df6;
      box-shadow: inset 0 0 0 4px rgba(46, 109, 246, 0.035);
      font-size: 0.95rem;
    }

    .ui-button-reference-copy {
      min-width: 0;
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      justify-content: center;
      gap: 2px;
    }

    .ui-button-reference-name {
      display: block;
      max-width: 100%;
      overflow: hidden;
      color: #687d98;
      font-size: 0.72rem;
      font-weight: 850;
      letter-spacing: 0.055em;
      line-height: 1.2;
      text-overflow: ellipsis;
      text-transform: uppercase;
      white-space: nowrap;
    }

    .ui-button-reference-state {
      display: block;
      color: #1d2d3f;
      font-size: 0.82rem;
      font-weight: 900;
      line-height: 1.2;
      text-transform: uppercase;
    }

    .ui-button-preview-control {
      position: relative;
      flex: 0 0 auto;
      width: 48px;
      height: 48px;
      min-width: 48px;
      min-height: 48px;
      display: grid;
      place-items: center;
      padding: 0;
      border: 3px solid #2563eb;
      border-radius: 50%;
      background: #ffffff;
      color: #61728a;
      box-shadow:
        0 0 0 3px rgba(37, 99, 235, 0.08),
        0 6px 14px rgba(37, 99, 235, 0.18),
        inset 0 0 0 1px #e5edf7;
      cursor: pointer;
      user-select: none;
      transition:
        transform 0.16s ease,
        box-shadow 0.16s ease,
        background-color 0.16s ease,
        color 0.16s ease;
    }

    .ui-button-preview-control i {
      font-size: 1.22rem;
      transition: transform 0.16s ease;
    }

    .ui-button-preview-control:hover:not(:disabled) {
      transform: translateY(-1px) scale(1.035) !important;
      box-shadow:
        0 0 0 4px rgba(37, 99, 235, 0.1),
        0 8px 18px rgba(37, 99, 235, 0.22),
        inset 0 0 0 1px #e5edf7;
    }

    .ui-button-preview-control:active:not(:disabled),
    .ui-button-preview-control.is-pressed {
      transform: translateY(1px) scale(0.96) !important;
      box-shadow:
        0 0 0 2px rgba(37, 99, 235, 0.09),
        0 3px 8px rgba(37, 99, 235, 0.18),
        inset 0 0 0 1px #dce8f7;
    }

    .ui-button-preview-control.is-on,
    .ui-button-preview-control.is-pressed.push-button-preview {
      background: #2563eb;
      color: #ffffff;
    }

    /* Push Button keeps the same premium card layout, with a hand icon. */
    .ui-button-preview-control.push-button-preview {
      border-color: #2563eb;
    }

    .ui-button-preview-control:disabled {
      opacity: 0.48;
      cursor: not-allowed;
      box-shadow:
        0 0 0 2px rgba(148, 163, 184, 0.08),
        inset 0 0 0 1px #e5e7eb;
    }

    .ui-button-preview-output {
      display: flex;
      align-items: center;
      justify-content: flex-start;
      gap: 8px;
      flex-wrap: wrap;
