    /* Text / Enter Text / Console / Notification live message preview. */
    .ui-message-live-demo[hidden] {
      display: none !important;
    }

    .ui-message-live-demo {
      display: grid;
      gap: 10px;
      margin-top: 14px;
      padding: 12px;
      border: 1px solid #dce6f2;
      border-radius: 18px;
      background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.94),
        0 9px 24px -22px rgba(37, 99, 235, 0.4);
    }

    .ui-message-preview-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      color: #61728a;
      font-size: 0.72rem;
      font-weight: 850;
      letter-spacing: 0.045em;
      text-transform: uppercase;
    }

    .ui-message-preview-head > span:first-child {
      display: inline-flex;
      align-items: center;
      gap: 7px;
    }

    .ui-message-preview-badge {
      padding: 4px 8px;
      border: 1px solid #d8e4f7;
      border-radius: 999px;
      background: #f6f9ff;
      color: #5f7190;
      font-size: 0.58rem;
      font-weight: 900;
      letter-spacing: 0.045em;
    }

    .ui-message-reference-card {
      display: grid;
      grid-template-columns: 38px minmax(0, 1fr);
      align-items: center;
      gap: 10px;
      min-height: 68px;
      padding: 10px 12px;
      border: 1px solid #d9e3ef;
      border-radius: 15px;
      background: linear-gradient(180deg, #ffffff 0%, #fbfdff 100%);
      box-shadow:
        0 6px 16px rgba(15, 23, 42, 0.06),
        inset 0 1px 0 rgba(255, 255, 255, 0.95);
    }

    .ui-message-reference-icon {
      display: grid;
      place-items: center;
      width: 36px;
      height: 36px;
      border: 1px solid #d7e3fb;
      border-radius: 50%;
      background: #eef4ff;
      color: #3975f4;
      font-size: 0.78rem;
      box-shadow: inset 0 0 0 4px rgba(57, 117, 244, 0.035);
    }

    .ui-message-reference-copy {
      display: grid;
      gap: 4px;
      min-width: 0;
    }

    .ui-message-reference-label {
      color: #66778f;
      font-size: 0.64rem;
      font-weight: 900;
      letter-spacing: 0.055em;
      text-transform: uppercase;
    }

    .ui-message-reference-input {
      width: 200px;
      min-width: 0;
      min-height: 35px;
      padding: 6px 10px;
      border: 1px solid #cbd9e9;
      border-radius: 9px;
      background: #fff;
      color: #20334d;
      font-size: 0.82rem;
      font-weight: 750;
      outline: none;
      box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.025);
    }

    .ui-message-reference-input:focus {
      border-color: #7da6f6;
      box-shadow: 0 0 0 3px rgba(61, 117, 239, 0.12);
    }

    .ui-message-preview-help {
      display: flex;
      align-items: flex-start;
      gap: 7px;
      padding: 8px 10px;
      border-radius: 10px;
      background: #eef5ff;
      color: #526983;
      font-size: 0.67rem;
      font-weight: 700;
      line-height: 1.4;
    }

    .ui-message-preview-help i {
      margin-top: 2px;
      color: #3975f4;
    }

    /* Keep UI Values compact for normal controls, but allow full multiline
       console data when Console is the selected UI type. */
    #fUiValues {
      min-height: 46px !important;
      height: 46px;
      padding: 0.65rem 0.8rem;
      resize: none;
      overflow: hidden;
      line-height: 1.35;
      white-space: pre-wrap;
          width: 222px;
    }

    #fUiValues.console-ui-values {
      height: 100px;
      padding: 12px 14px;
      resize: vertical;
      overflow: auto;
      border-color: #2f3a3a !important;
      background: #2b2727 !important;
      color: #f4f4f4 !important;
      caret-color: #55e690;
      font-family: Consolas, Monaco, "Courier New", monospace !important;
      font-size: 0.78rem;
      font-weight: 600;
      line-height: 1.35;
      tab-size: 2;
      white-space: pre-wrap;
    }

    #fUiValues.console-ui-values::placeholder {
      color: #aeb8b3 !important;
    }

    .ui-message-preview-input-row {
      position: relative;
      display: block;
      width: min(100%, 360px);
    }

    .ui-message-preview-input-row[hidden],
    .ui-message-send-button[hidden],
    .ui-console-preview[hidden] {
      display: none !important;
    }

    .ui-message-preview-input-row .ui-message-reference-input {
      width: 100%;
    }

    /* Enter Text: keep the Send action INSIDE the same input box. */
    .ui-message-preview-input-row.has-send .ui-message-reference-input {
      padding-right: 46px;
    }

    .ui-message-send-button {
      position: absolute;
      z-index: 2;
      top: 50%;
      right: 5px;
      display: grid;
      place-items: center;
      width: 32px;
      min-width: 32px;
      height: 30px;
      min-height: 30px;
      padding: 0;
      transform: translateY(-50%);
      border: 0;
      border-radius: 7px;
      background: transparent;
      color: #10b85c;
      cursor: pointer;
      box-shadow: none;
    }

    .ui-message-send-button i {
      font-size: 1rem;
      transform: rotate(-8deg);
    }

    .ui-message-send-button:hover {
      border: 0;
      background: #eaf9f0;
      color: #079548;
    }

    .ui-message-send-button.sent {
      transform: translateY(-50%) scale(0.9);
      background: #dcf7e7;
      color: #067a3d;
    }

    .ui-console-preview {
      width: 100%;
      min-height: 155px;
      max-height: 260px;
      margin: 0;
      padding: 12px 14px;
      overflow: auto;
      border: 1px solid #202626;
      border-radius: 10px;
      background: #2b2727;
      color: #f3f3f3;
      font-family: Consolas, Monaco, "Courier New", monospace;
      font-size: 0.72rem;
      font-weight: 600;
      line-height: 1.35;
      white-space: pre-wrap;
      overflow-wrap: anywhere;
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
    }

    .ui-message-live-demo.is-console .ui-message-reference-card {
      grid-template-columns: 38px minmax(0, 1fr);
      align-items: start;
    }

    @media (max-width: 560px) {
      .ui-message-live-demo {
        padding: 10px;
      }

      .ui-message-reference-card {
        grid-template-columns: 34px minmax(0, 1fr);
        gap: 9px;
        padding: 9px 10px;
      }

      .ui-message-reference-icon {
        width: 34px;
        height: 34px;
      }
    }

    /* Display / Toast Display live preview. */
    .ui-display-toast-live-demo[hidden] {
      display: none !important;
    }

    .ui-display-toast-live-demo {
      display: grid;
      gap: 10px;
      margin-top: 14px;
      padding: 12px;
      border: 1px solid #dce6f2;
      border-radius: 18px;
      background: linear-gradient(180deg, #ffffff 0%, #f8fbff 100%);
      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.94),
        0 9px 24px -22px rgba(37, 99, 235, 0.4);
    }

    .ui-display-toast-preview-head {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      color: #61728a;
      font-size: 0.72rem;
      font-weight: 850;
