    }

    .ui-display-toast-preview-help {
      display: flex;
      align-items: flex-start;
      gap: 7px;
      padding: 8px 10px;
      border-radius: 10px;
      background: #edf7f3;
      color: #526983;
      font-size: 0.67rem;
      font-weight: 700;
      line-height: 1.4;
    }

    .ui-display-toast-preview-help i {
      margin-top: 2px;
