    .ui-config-generic-preview {
      display: grid;
      place-items: center;
      min-height: 210px;
      gap: 9px;
      padding: 24px;
      border: 1px dashed #a9c1b7;
      border-radius: 14px;
      background: #f8fbfa;
      color: #667972;
      text-align: center;
    }

    .ui-config-generic-icon {
      display: grid;
      place-items: center;
      width: 72px;
      height: 58px;
      border: 1px solid #b8cdc4;
      border-radius: 14px;
      background: #fff;
      color: #376f64;
      font-size: 1.25rem;
    }

    .ui-config-generic-preview strong {
      color: #203b35;
      font-size: 0.92rem;
    }

    .ui-config-actions {
      display: flex;
      justify-content: flex-end;
      gap: 10px;
      padding: 14px 20px 18px;
      border-top: 1px solid #dce7e2;
      background: #fff;
    }

    .ui-config-edit-btn,
    .ui-config-done-btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 7px;
      min-height: 42px;
      padding: 9px 16px;
      border-radius: 10px;
      font-size: 0.82rem;
      font-weight: 800;
      cursor: pointer;
    }

    .ui-config-edit-btn {
      border: 1px solid #88bda4;
      background: #fff;
      color: #376f64;
    }

    .ui-config-done-btn {
      border: 1px solid #376f64;
      background: #376f64;
      color: #fff;
    }

    .ui-config-edit-btn:hover {
      background: #edf7f3;
    }

    .ui-config-done-btn:hover {
      background: #28584f;
    }

    .ui-config-overlay .form-group.field-invalid input,
    .ui-config-overlay .form-group.field-invalid select {
      border: 2px solid #d92d20 !important;
      background: #fff8f7 !important;
      box-shadow: 0 0 0 3px rgba(217, 45, 32, 0.1);
    }

    @media (max-width: 700px) {
      .ui-config-overlay {
        padding: 8px;
      }

      .ui-config-modal {
        width: 100%;
        max-height: 96vh;
      }

      .ui-config-fields.two-columns {
        grid-template-columns: 1fr;
      }

      .ui-config-actions {
        flex-direction: column-reverse;
      }

      .ui-config-edit-btn,
      .ui-config-done-btn {
        width: 100%;
      }
