    /* Dropdown UI configuration: key -> display label mapping + live preview. */
    .dropdown-ui-mapping-editor[hidden],
    .dropdown-live-demo[hidden] {
      display: none !important;
    }

    /* Dropdown UI Values stay inside the existing UI Values field. */
    .dropdown-inline-ui-values[hidden],
    .dropdown-inline-ui-values-hint[hidden] {
      display: none !important;
    }

    .dropdown-inline-ui-values {
      display: grid;
      gap: 8px;
      width: 100%;
    }

    /* Text UI configuration:
       No. of Messages drives exactly how many message inputs are shown. */
    .text-message-inline-editor[hidden],
    .text-message-count-hint[hidden],
    .ui-text-multiple-preview[hidden] {
      display: none !important;
    }

    .text-message-inline-editor {
      display: grid;
      gap: 8px;
      width: 100%;
    }

    .text-message-rows {
      display: grid;
      gap: 8px;
      width: 100%;
    }

    .text-message-row {
      display: grid;
      grid-template-columns: 74px minmax(0, 1fr);
      align-items: center;
      gap: 9px;
      width: 100%;
      padding: 7px;
      border: 1px solid #c9d9d3;
      border-radius: 10px;
      background: #f8fbfa;
    }

    .text-message-row-label {
      color: #355c53;
      font-size: 0.72rem;
      font-weight: 850;
      white-space: nowrap;
    }

    .text-message-input {
      width: 100% !important;
      min-width: 0 !important;
      min-height: 40px !important;
      padding: 0.55rem 0.7rem !important;
      border: 1px solid #9fb9ae !important;
      border-radius: 9px !important;
      background: #fff !important;
      color: #203b35 !important;
      font-size: 0.9rem !important;
      font-weight: 650 !important;
    }

    .text-message-input:focus {
      border-color: #659287 !important;
      box-shadow: 0 0 0 3px rgba(101, 146, 135, 0.18) !important;
      outline: none;
    }

    .text-message-input[aria-invalid="true"] {
      border-color: #d92d20 !important;
      background: #fff8f7 !important;
      box-shadow: 0 0 0 3px rgba(217, 45, 32, 0.08) !important;
    }

    .text-message-count-hint {
      display: flex;
      align-items: center;
      gap: 6px;
      margin-top: 6px;
      color: #5a7394;
      font-size: 0.68rem;
      font-weight: 700;
      line-height: 1.35;
    }

    .text-message-count-hint i {
      color: #659287;
    }

    /* Keep the existing Text preview design, but repeat the same input
       appearance when No. of Messages is greater than one. */
    .ui-text-multiple-preview {
      display: grid;
      gap: 7px;
      width: min(100%, 430px);
    }

    .ui-text-multiple-preview-row {
      display: grid;
      grid-template-columns: 66px minmax(0, 1fr);
      align-items: center;
      gap: 8px;
    }

    .ui-text-multiple-preview-label {
      color: #66778f;
      font-size: 0.58rem;
      font-weight: 900;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      white-space: nowrap;
    }

    .ui-text-multiple-preview-row .ui-message-reference-input {
      width: 100%;
      max-width: none;
    }

    @media (max-width: 650px) {
      .text-message-row {
        grid-template-columns: 1fr;
      }

      .ui-text-multiple-preview-row {
        grid-template-columns: 1fr;
      }
    }

    .dropdown-inline-ui-row {
      display: grid;
      grid-template-columns: minmax(90px, 0.34fr) minmax(0, 1fr);
      align-items: center;
      gap: 9px;
      width: 100%;
      padding: 7px;
      border: 1px solid #c9d9d3;
      border-radius: 10px;
      background: #f8fbfa;
    }

    .dropdown-inline-ui-key {
      display: flex;
      align-items: center;
      gap: 7px;
      min-width: 0;
      color: #355c53;
      font-size: 0.74rem;
      font-weight: 800;
    }

    .dropdown-inline-ui-key::before {
      content: "Content No.";
      color: #6a7f78;
      font-size: 0.62rem;
      font-weight: 750;
      white-space: nowrap;
    }

    .dropdown-inline-ui-key code {
      display: inline-grid;
      place-items: center;
      min-width: 30px;
      min-height: 30px;
      padding: 0 7px;
      border: 1px solid #88bda4;
      border-radius: 8px;
      background: #e6f2dd;
      color: #203b35;
      font: 800 0.78rem Consolas, Monaco, monospace;
    }

    .dropdown-inline-ui-input {
      width: 100% !important;
      min-width: 0 !important;
      min-height: 40px !important;
      padding: 0.55rem 0.7rem !important;
      border: 1px solid #9fb9ae !important;
      border-radius: 9px !important;
      background: #fff !important;
      color: #203b35 !important;
      font-size: 0.9rem !important;
      font-weight: 650 !important;
    }

    .dropdown-inline-ui-input:focus {
      border-color: #659287 !important;
      box-shadow: 0 0 0 3px rgba(101, 146, 135, 0.18) !important;
      outline: none;
