    .dropdown-ui-map-list:empty {
      display: none;
    }

    .dropdown-ui-map-chip {
      cursor: pointer;
    }

    .dropdown-ui-map-chip.empty-value {
      border-style: dashed;
      color: #7b6b36;
      background: #fffaf0;
    }

    .dropdown-inline-ui-empty {
      display: flex;
      align-items: center;
      gap: 7px;
      min-height: 44px;
      padding: 9px 11px;
      border: 1px dashed #b8cdc4;
      border-radius: 9px;
      background: #f8fbfa;
      color: #60756e;
      font-size: 0.74rem;
      font-weight: 650;
    }

    @media (max-width: 650px) {
      .dropdown-inline-ui-row {
        grid-template-columns: 1fr;
      }
    }

    .dropdown-ui-mapping-editor {
      margin-top: 14px;
      padding: 14px;
      border: 1px solid #c8dcd4;
      border-radius: 14px;
      background: #f7fbf9;
    }

    .dropdown-ui-mapping-head {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 11px;
    }

    .dropdown-ui-mapping-head strong {
      display: block;
      color: #203b35;
