  <style id="radioCardUiUpgrade">
    /* Radio-card upgrade for Parameter Name Source and Voice Command.
       The original selects remain in the DOM as compatibility proxies. */
    .radio-select-proxy {
      position: absolute !important;
      width: 1px !important;
      height: 1px !important;
      margin: -1px !important;
      padding: 0 !important;
      overflow: hidden !important;
      clip: rect(0 0 0 0) !important;
      clip-path: inset(50%) !important;
      white-space: nowrap !important;
      border: 0 !important;
      opacity: 0 !important;
      pointer-events: none !important;
    }

    #parameterCommandSection .parameter-source-item,
    #parameterCommandSection .voice-command-row > .param-item:first-child {
      min-width: 0;
    }

    .radio-card-group {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 10px;
      width: 100%;
    }

    .radio-card-option {
      position: relative;
      display: block;
      min-width: 0;
      min-height: 84px;
      padding: 12px 12px 12px 40px;
      border: 1px solid #d7e4dd;
      border-radius: 14px;
      background: linear-gradient(180deg, #ffffff 0%, #fbfdfc 100%);
      color: #243b34;
      cursor: pointer;
      box-shadow: 0 5px 16px rgba(31, 74, 61, 0.045);
      transition: border-color 160ms ease, background 160ms ease, box-shadow 160ms ease, transform 160ms ease;
      user-select: none;
    }

    .radio-card-option:hover {
      border-color: #8fb7a3;
      background: #f6fbf8;
      box-shadow: 0 9px 22px rgba(31, 74, 61, 0.09);
      transform: translateY(-1px);
    }

    .radio-card-option > input[type="radio"] {
      position: absolute;
      width: 1px !important;
      height: 1px !important;
      opacity: 0;
      pointer-events: none;
    }

    .radio-card-mark {
      position: absolute;
      top: 50%;
      left: 13px;
      width: 18px;
      height: 18px;
      border: 2px solid #9eb5aa;
      border-radius: 50%;
      background: #fff;
      transform: translateY(-50%);
      box-shadow: inset 0 0 0 4px #fff;
      transition: border-color 160ms ease, background 160ms ease, box-shadow 160ms ease;
    }

    .radio-card-content {
      display: flex;
      align-items: center;
      gap: 10px;
      min-width: 0;
    }

    .radio-card-icon {
      display: grid;
      place-items: center;
      flex: 0 0 38px;
      width: 38px;
      height: 38px;
      border: 1px solid #d7e7df;
      border-radius: 11px;
      background: #eef7f2;
      color: #416c59;
      transition: color 160ms ease, background 160ms ease, border-color 160ms ease, transform 160ms ease;
    }

    .radio-card-copy {
      display: block;
      min-width: 0;
      line-height: 1.25;
    }

    .radio-card-copy strong {
      display: block;
      margin-bottom: 4px;
      color: #203b35;
      font-size: 0.82rem;
      font-weight: 800;
    }

    .radio-card-copy small {
      display: block;
      color: #688078;
      font-size: 0.68rem;
      font-weight: 600;
      line-height: 1.35;
    }

    .radio-card-option:has(input[type="radio"]:checked) {
      border-color: #4f806b;
      background: linear-gradient(135deg, #eff8f3 0%, #ffffff 100%);
