    /* =========================================================
       GLOBAL CUSTOM DROPDOWN STYLE
       Mirrors the white Actions popup: white card, warm accent icons,
       subtle border/shadow and clean hover rows.
       The real <select> remains in the DOM for all existing JS/backend logic.
       ========================================================= */
    .ef-custom-select {
      position: relative;
      display: inline-block;
      width: 100%;
      min-width: 0;
      vertical-align: middle;
    }

    .ef-native-select-hidden {
      position: absolute !important;
      left: 0 !important;
      bottom: 0 !important;
      width: 1px !important;
      min-width: 1px !important;
      height: 1px !important;
      min-height: 1px !important;
      margin: 0 !important;
      padding: 0 !important;
      opacity: 0 !important;
      pointer-events: none !important;
      border: 0 !important;
      clip: rect(0 0 0 0) !important;
      clip-path: inset(50%) !important;
      overflow: hidden !important;
      white-space: nowrap !important;
    }

    .ef-custom-select-trigger {
      position: relative;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      width: 100%;
      min-width: 0;
      min-height: 44px;
      padding: 0.64rem 2.55rem 0.64rem 0.86rem;
      border: 1px solid #d9c6b7;
      border-radius: 11px;
      color: #17212b;
      background: #ffffff;
      box-shadow: 0 3px 9px rgba(73, 53, 40, 0.045);
      font: inherit;
      font-size: 0.86rem;
      font-weight: 650;
      line-height: 1.2;
      text-align: left;
      cursor: pointer;
      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
    }

    .select-with-icon > i + select + .ef-custom-select .ef-custom-select-trigger {
      padding-left: 2.35rem;
    }

    .select-with-icon:focus-within > i {
      color: #c77943 !important;
    }

    .ef-custom-select-trigger::after {
      content: "";
      position: absolute;
      right: 0.92rem;
      top: 50%;
      width: 7px;
      height: 7px;
      border-right: 2px solid #bf7442;
      border-bottom: 2px solid #bf7442;
      transform: translateY(-68%) rotate(45deg);
      transition: transform 160ms ease;
      pointer-events: none;
    }

    .ef-custom-select.is-open .ef-custom-select-trigger::after {
      transform: translateY(-30%) rotate(225deg);
    }

    .ef-custom-select-trigger:hover:not(:disabled) {
      border-color: #ce966f;
      background: #fffdfb;
      box-shadow: 0 6px 14px rgba(73, 53, 40, 0.075);
    }

    .ef-custom-select-trigger:focus-visible {
      outline: 3px solid rgba(207, 126, 72, 0.17) !important;
      outline-offset: 2px;
      border-color: #c97843 !important;
    }

    .ef-custom-select-trigger:disabled,
    .ef-custom-select.is-disabled .ef-custom-select-trigger {
      color: #8b918f;
      background: #f4f5f4;
      border-color: #d9dedb;
      cursor: not-allowed;
      box-shadow: none;
    }

    .ef-custom-select.has-error .ef-custom-select-trigger {
      border-color: #d92d20 !important;
      background: #fff9f8 !important;
      box-shadow: 0 0 0 3px rgba(217, 45, 32, 0.10) !important;
    }

    .ef-custom-select-trigger-text {
      display: block;
      min-width: 0;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .ef-dropdown-portal {
      position: fixed;
      z-index: 2147483000;
      display: none;
      min-width: 190px;
      max-height: min(330px, calc(100vh - 28px));
      padding: 8px 6px;
      overflow-x: hidden;
      overflow-y: auto;
      border: 1px solid #e3c8b4;
      border-radius: 14px;
      color: #111827;
      background: #ffffff;
      box-shadow:
        0 18px 40px rgba(62, 43, 30, 0.16),
        0 3px 10px rgba(62, 43, 30, 0.08);
      overscroll-behavior: contain;
    }

    .ef-dropdown-portal.is-open {
      display: block;
      animation: efDropdownIn 130ms ease-out both;
    }

    .ef-dropdown-option,
    .ef-dropdown-group-label {
      width: 100%;
      min-height: 38px;
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 0.55rem 0.72rem;
      border: 0;
      border-radius: 9px;
      background: transparent;
      font-family: inherit;
      text-align: left;
    }

    .ef-dropdown-option {
      color: #111827;
      font-size: 0.82rem;
      font-weight: 650;
      cursor: pointer;
    }

    .ef-dropdown-option-icon {
      flex: 0 0 22px;
      width: 22px;
      height: 22px;
      display: inline-grid;
      place-items: center;
      border-radius: 7px;
      color: #c77943;
      background: #fff5ee;
      font-size: 0.66rem;
    }

    .ef-dropdown-option:hover,
    .ef-dropdown-option:focus-visible {
      color: #1c242c;
      background: #fff5ee;
      outline: none;
    }

    .ef-dropdown-option.is-selected {
      color: #26463c;
      background: #edf5f1;
      font-weight: 800;
    }

    .ef-dropdown-option.is-selected .ef-dropdown-option-icon {
      color: #ffffff;
      background: #3f7464;
    }

    .ef-dropdown-option:disabled,
    .ef-dropdown-option.is-disabled {
      color: #9ca3af;
      background: transparent;
      cursor: not-allowed;
      opacity: 0.75;
    }

    .ef-dropdown-option:disabled .ef-dropdown-option-icon,
    .ef-dropdown-option.is-disabled .ef-dropdown-option-icon {
      color: #a8aaa9;
      background: #f1f2f2;
    }

    .ef-dropdown-group-label {
      min-height: 30px;
      margin-top: 3px;
      color: #9b5f38;
      background: #fff9f4;
      font-size: 0.68rem;
      font-weight: 900;
      letter-spacing: 0.045em;
      text-transform: uppercase;
      cursor: default;
    }

    .ef-dropdown-empty {
      padding: 0.7rem 0.8rem;
      color: #8a918e;
      font-size: 0.78rem;
      text-align: center;
    }

    .ef-dropdown-portal::-webkit-scrollbar {
      width: 7px;
    }

    .ef-dropdown-portal::-webkit-scrollbar-track {
      background: transparent;
    }

    .ef-dropdown-portal::-webkit-scrollbar-thumb {
      border-radius: 999px;
      background: #cb8454;
    }

    @keyframes efDropdownIn {
      from {
        opacity: 0;
        transform: translateY(-4px) scale(0.985);
      }
      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

