              <button type="button" class="field-choice-button no-choice" data-notification-value="No">
                <i class="fas fa-circle-xmark"></i> No
              </button>
            </div>
            <select id="fNotificationEnable" class="field-reference-native-control" required aria-label="Notification Enable">
              <option value="" selected disabled>Select Notification Enable</option>
              <option value="Yes">Yes</option>
              <option value="No">No</option>
            </select>
            <small class="field-setup-hint" id="notificationEnableHint">Choose Yes or No.</small>
          </section>

          <section class="field-config-panel field-config-choice-panel form-group" id="uiInOutChoicePanel">
            <div class="field-config-section-title">
              <span class="field-config-section-icon" style="background:linear-gradient(135deg,#7d58ff,#9b72ff)"><i class="fas fa-arrow-right-arrow-left"></i></span>
              <div>
                <strong>UI In/Output</strong>
                <small>Select how this field exchanges data with the UI.</small>
              </div>
            </div>
            <div class="field-choice-buttons four" id="uiInOutChoiceButtons" role="radiogroup" aria-label="UI In/Output options">
              <button type="button" class="field-choice-button ui-io-choice" data-ui-inout-value="read" aria-pressed="false">
                <i class="fas fa-eye"></i><span>Read</span>
              </button>
              <button type="button" class="field-choice-button ui-io-choice" data-ui-inout-value="write" aria-pressed="false">
                <i class="fas fa-pen"></i><span>Write</span>
              </button>
              <button type="button" class="field-choice-button ui-io-choice" data-ui-inout-value="read/write" aria-pressed="false">
                <i class="fas fa-arrows-left-right"></i><span>Read/Write</span>
              </button>
              <button type="button" class="field-choice-button ui-io-choice" data-ui-inout-value="none" aria-pressed="false">
                <i class="fas fa-ban"></i><span>None</span>
              </button>
            </div>
            <div class="field-choice-selection-status" id="uiInOutSelectionStatus" aria-live="polite">
              <i class="fas fa-circle-info"></i>
              <span>Select one option: Read, Write, Read/Write, or None.</span>
            </div>
            <select id="fUiInOut" class="field-reference-native-control" aria-label="UI In/Output" required>
              <option value="" selected disabled>Select In/Output</option>
              <option value="read">Read</option>
              <option value="write">Write</option>
              <option value="read/write">Read/Write</option>
              <option value="none">None</option>
            </select>
          </section>
        </div>

        <div class="form-group field-dynamic-group" id="messageFieldGroup" hidden>
          <label class="control-label" for="fMessage"><i class="fas fa-message"></i> Message</label>
          <input type="text" id="fMessage" placeholder="Enter message" />
        </div>

        <section class="field-config-panel field-config-notes-panel form-group field-notes-group">
          <div class="field-config-section-title">
            <span class="field-config-section-icon" style="background:linear-gradient(135deg,#7764ff,#8a75ff)"><i class="fas fa-note-sticky"></i></span>
            <div>
              <strong>Notes</strong>
              <small>Add any additional notes (optional).</small>
            </div>
          </div>
          <div class="field-notes-wrap">
            <textarea id="fNotes" rows="3" maxlength="500" placeholder="Enter notes here..."></textarea>
            <span class="field-notes-count" id="fieldNotesCount">0/500</span>
          </div>
        </section>
