  <!-- Dedicated UI Configuration Modal -->
  <div id="uiConfigurationModal" class="ui-config-overlay" aria-hidden="true">
    <div class="ui-config-modal" role="dialog" aria-modal="true" aria-labelledby="uiConfigTitle">
      <div class="ui-config-head">
        <div>
          <span class="ui-config-eyebrow"><i class="fas fa-display"></i> UI Configuration</span>
          <h3 id="uiConfigTitle">Configure UI</h3>
          <p id="uiConfigSubtitle">Configure only the values required by the selected UI type.</p>
        </div>
        <button type="button" class="ui-config-close" id="closeUiConfigurationModal" aria-label="Close UI Configuration">
          <i class="fas fa-xmark"></i>
        </button>
      </div>

      <div class="ui-config-warning" id="uiConfigWarning" role="alert" hidden></div>

      <div class="ui-config-body">
        <!-- UI-specific value configuration, live preview and Edit Values. -->
        <section id="uiConfigToggleSection" class="ui-config-section" hidden>
          <div class="ui-config-fields two-columns">
            <div class="form-group" id="asperUiFieldGroup">
              <label class="control-label" id="asperUiFieldLabel" for="fAsperUi">
                <i class="fas fa-wand-magic-sparkles"></i> Preset Names
              </label>
              <input type="text" id="fAsperUi" readonly placeholder="Select configuration" />

              <div class="toggle-asper-ui-control-row" id="toggleAsperUiControlRow" hidden>
                <select id="fToggleAsperUi" aria-label="Toggle Preset Names">
                  <option value="" disabled>Select Preset Names</option>
                  <option value="off,on">ON / OFF</option>
                  <option value="false,true">TRUE / FALSE</option>
                  <option value="disable,enable">ENABLE / DISABLE</option>
                </select>

                <input
                  type="text"
                  id="fToggleCustomAsperUiInput"
                  placeholder="Enter custom values, e.g. CLOSE,OPEN"
                  autocomplete="off"
                  aria-label="Custom Toggle Preset Names"
                  hidden
                />

                <button
                  type="button"
                  class="toggle-custom-mode-btn"
                  id="fToggleCustomAsperUiBtn"
                  aria-pressed="false"
                  title="Enter custom Preset Names"
                >
                  <i class="fas fa-pen"></i>
                  <span>Custom</span>
                </button>
              </div>

              <small class="field-setup-hint" id="toggleAsperUiHint" hidden>
                <i class="fas fa-toggle-on"></i> Choose a preset or click Custom and enter any two names such as CLOSE,OPEN.
              </small>
            </div>

            <div class="form-group ui-values-field-column">
              <label class="control-label" id="uiValuesFieldLabel" for="fUiValues">
                <i class="fas fa-list"></i> UI Values
              </label>

              <!--
                fUiValues remains the real backend field. For Dropdown it is
                hidden from the user and is automatically maintained as a
                comma-separated value list (example: Fan,AC,Phone).
              -->
              <textarea
                id="fUiValues"
                rows="1"
                placeholder="Enter UI values"
                autocomplete="off"
                spellcheck="false"
              ></textarea>

              <!-- Dropdown editor stays INSIDE the existing UI Values field.
                   Example: No. of Contents = 3 -> select 1/2/3 and enter Fan/AC/Phone. -->
              <div class="dropdown-inline-ui-values" id="dropdownInlineUiValues" hidden>
                <div class="dropdown-inline-ui-row">
                  <div class="dropdown-inline-ui-control">
                    <label for="dropdownUiValueIndex">Content No.</label>
                    <select id="dropdownUiValueIndex" aria-label="Select Dropdown value number">
                      <option value="">Enter No. of Contents first</option>
                    </select>
                  </div>

                  <div class="dropdown-inline-ui-control">
                    <label for="dropdownUiValueEditor">Content</label>
                    <input
                      type="text"
                      id="dropdownUiValueEditor"
                      class="dropdown-inline-ui-input"
                      placeholder="Enter value, e.g. Fan"
                      autocomplete="off"
                      disabled
                    />
                  </div>
                </div>

                <div class="dropdown-ui-map-list" id="dropdownUiValueSummary" aria-live="polite"></div>
              </div>

              <!-- Text UI:
                   No. of Messages in fAsperUi creates exactly N message inputs.
                   fUiValues remains the real backend field and stores the
                   generated messages as comma-separated values, e.g. 22,dd,aa. -->
              <div class="text-message-inline-editor" id="textMessageInlineEditor" hidden>
                <div class="text-message-rows" id="textMessageRows" aria-live="polite"></div>
              </div>

              <small class="text-message-count-hint" id="textMessageCountHint" hidden>
                <i class="fas fa-message"></i>
                <span>Enter No. of Messages first. The same number of Message fields will be created automatically.</span>
              </small>

              <small class="field-setup-hint" id="dropdownUiValuesHint" hidden>
                <i class="fas fa-list-check"></i> Enter the number of contents, for example 3. Then select 1, 2, 3 and enter Fan, AC, Phone.
              </small>

              <small class="field-setup-hint" id="toggleUiValuesHint" hidden>
                <i class="fas fa-toggle-on"></i> Enter exactly two numeric Functioning Names, for example: 01,02.
              </small>
            </div>
          </div>

          <div class="toggle-live-demo ui-config-preview-card" id="toggleLiveDemo" hidden>
            <div class="toggle-live-demo-head">
              <div class="toggle-live-demo-title">
                <i class="fas fa-toggle-on"></i> Preview Toggle
              </div>
              <div class="toggle-live-demo-help" id="toggleLiveDemoHelp"></div>
            </div>
            <div class="toggle-live-stage">
              <button type="button" class="toggle-live-switch-btn" id="toggleLiveSwitch" aria-pressed="false" aria-label="Try the Toggle preview">
                <span class="toggle-live-switch-track" aria-hidden="true">
                  <span class="toggle-live-switch-knob"></span>
                </span>
                <span class="toggle-live-switch-state" id="toggleLiveStateLabel">False / OFF</span>
              </button>
            </div>
            <div class="toggle-live-current">
              Current UI output value: <code id="toggleCurrentValue">—</code>
            </div>
            <small class="toggle-live-demo-status" id="toggleLiveDemoStatus">
              <i class="fas fa-circle-info"></i>
              <span>Enter exactly two Functioning Names, for example 01,02.</span>
            </small>
          </div>

          <!-- Push Button / Button: UI Values + reference-style live preview. -->
          <div class="ui-button-live-demo ui-config-preview-card" id="buttonLiveDemo" hidden>
            <div class="ui-button-preview-head">
              <div class="ui-button-preview-title">
                <i class="fas fa-eye"></i>
                <span id="buttonPreviewTitle">Preview Button</span>
              </div>
              <span class="ui-button-preview-badge" id="buttonPreviewTypeBadge">BUTTON</span>
            </div>

            <div class="ui-button-preview-stage">
              <div class="ui-button-reference-card" id="buttonReferenceCard">
                <div class="ui-button-reference-left-icon" aria-hidden="true">
                  <i class="fas fa-gauge-high"></i>
                </div>

                <div class="ui-button-reference-copy">
                  <span class="ui-button-reference-name" id="buttonPreviewLabel">BUTTON</span>
                  <strong class="ui-button-reference-state" id="buttonPreviewState">OFF</strong>
                </div>

                <button type="button"
                  class="ui-button-preview-control"
                  id="buttonPreviewControl"
                  aria-label="Try the selected button preview"
                  aria-pressed="false">
                  <i class="fas fa-power-off" id="buttonPreviewIcon"></i>
                </button>
              </div>
            </div>

            <div class="ui-button-preview-output">
              UI output value:
              <code id="buttonPreviewCurrentValue">—</code>
            </div>

            <small class="ui-button-preview-help" id="buttonPreviewHelp">
              <i class="fas fa-circle-info"></i>
              <span>Enter a UI Value, then press the preview button to test it.</span>
            </small>
          </div>

          <!-- Dropdown uses No. of Contents + List of Contents.
               Example: No. of Contents = 3; inside List of Contents select
               1 -> Fan, 2 -> AC, 3 -> Phone. -->
          <!-- Text / Enter Text / Console / Notification: Message or Command + compact preview. -->
          <div class="ui-message-live-demo ui-config-preview-card" id="messageLiveDemo" hidden>
            <div class="ui-message-preview-head">
              <span><i class="fas fa-eye"></i> <span id="messagePreviewTitle">Message Preview</span></span>
              <span class="ui-message-preview-badge" id="messagePreviewBadge">TEXT</span>
            </div>

            <div class="ui-message-reference-card">
              <span class="ui-message-reference-icon" aria-hidden="true">
                <i class="fas fa-gauge-high" id="messagePreviewIcon"></i>
              </span>

              <div class="ui-message-reference-copy">
                <span class="ui-message-reference-label" id="messagePreviewLabel">TEXT</span>

                <div class="ui-message-preview-input-row" id="messagePreviewInputRow">
                  <input
                    type="text"
                    class="ui-message-reference-input"
                    id="messagePreviewInput"
                    value="Command"
                    aria-label="Message live preview"
                    readonly
                  />
                  <button
                    type="button"
                    class="ui-message-send-button"
                    id="messageSendButton"
                    aria-label="Send Enter Text preview"
                    title="Send"
                    hidden
                  >
                    <i class="fas fa-paper-plane"></i>
                  </button>
                </div>

                <div
                  class="ui-text-multiple-preview"
                  id="messageTextMultiplePreview"
                  aria-label="Multiple Text messages live preview"
                  hidden
                ></div>

                <pre class="ui-console-preview" id="messageConsolePreview" aria-label="Console live preview" hidden>Command</pre>
              </div>
            </div>

            <small class="ui-message-preview-help" id="messagePreviewHelp">
              <i class="fas fa-circle-info"></i>
              <span>Enter the Message or Command above to update this preview.</span>
            </small>
          </div>


          <!-- Display / Toast Display: Message or Command + dedicated live preview. -->
          <div class="ui-display-toast-live-demo ui-config-preview-card" id="displayToastLiveDemo" hidden>
            <div class="ui-display-toast-preview-head">
              <span><i class="fas fa-eye"></i> <span id="displayToastPreviewTitle">Preview Display</span></span>
              <span class="ui-display-toast-preview-badge" id="displayToastPreviewBadge">DISPLAY</span>
            </div>

            <div class="ui-display-toast-stage">
              <div class="ui-display-toast-reference-card" id="displayToastReferenceCard">
                <span class="ui-display-toast-reference-icon" aria-hidden="true">
                  <i class="fas fa-display" id="displayToastPreviewIcon"></i>
                </span>
                <div class="ui-display-toast-reference-copy">
                  <span class="ui-display-toast-reference-label" id="displayToastPreviewLabel">DISPLAY</span>
                  <strong class="ui-display-toast-reference-value" id="displayToastPreviewValue">Value</strong>
                </div>
              </div>
            </div>

            <div class="ui-display-toast-preview-output">
              <span>Message or Command: <code id="displayToastPreviewOutputValue">—</code></span>
            </div>

            <small class="ui-display-toast-preview-help" id="displayToastPreviewHelp">
              <i class="fas fa-circle-info"></i>
              <span>Enter a Message or Command above to update this preview.</span>
            </small>
          </div>
        </section>

        <!--
          Shared Display Min / Display Max.
          These two existing backend fields are now also shown for Text and
          Enter Text so the entered values continue to save into
          api_frame_fields.display_value_min / display_value_max.
        -->
        <section id="uiConfigDisplayRangeSection" class="ui-config-section" hidden>
          <div class="ui-config-fields two-columns">
            <div class="form-group" id="displayMinFieldGroup">
              <label class="control-label" for="fDisplayMin">
                <i class="fas fa-arrow-down-1-9"></i> Display Min
              </label>
              <input type="number" id="fDisplayMin" class="number-no-spinner" step="any" inputmode="decimal" placeholder="Enter display minimum" />
            </div>

            <div class="form-group" id="displayMaxFieldGroup">
              <label class="control-label" for="fDisplayMax">
                <i class="fas fa-arrow-up-9-1"></i> Display Max
              </label>
              <input type="number" id="fDisplayMax" class="number-no-spinner" step="any" inputmode="decimal" placeholder="Enter display maximum" />
            </div>
          </div>
        </section>

        <!-- Any slider UI: Slider Step, Scaling and the existing preview. -->
        <section id="uiConfigSliderSection" class="ui-config-section" hidden>
          <div class="ui-config-fields two-columns">
            <div class="form-group" id="sliderStepFieldGroup">
              <label class="control-label" for="fSliderStep">
                <i class="fas fa-sliders"></i> Slider Step
              </label>
              <input type="number" id="fSliderStep" min="0" step="any" inputmode="decimal" placeholder="Enter slider step" />
            </div>

            <div class="form-group" id="scalingFieldGroup">
              <label class="control-label" for="fScalling">
                <i class="fas fa-scale-balanced"></i> Scaling
              </label>
              <input type="text" id="fScalling" placeholder="e.g. *1.0, /10" />
            </div>
          </div>

          <div class="ui-slider-live-demo ui-config-preview-card" id="uiSliderPreviewCard">
            <div class="ui-slider-preview-title">
              <span class="ui-slider-preview-icon" id="uiSliderPreviewIcon">
                <i class="fas fa-sliders"></i>
              </span>
              <span id="uiSliderPreviewTitle">SLIDER</span>
            </div>

            <div class="ui-slider-preview-reading">
              <span class="ui-slider-edge-label" id="uiSliderPreviewLeftLabel">MIN</span>
              <span id="uiSliderPreviewValue">50</span>
              <span class="ui-slider-edge-label" id="uiSliderPreviewRightLabel">MAX</span>
            </div>

            <div class="ui-slider-track-wrap">
              <input type="range" id="uiSliderPreview" min="0" max="100" step="1" value="50" aria-label="Slider preview" />
            </div>

            <div class="ui-slider-preview-meta">
              <span>Min: <strong id="uiSliderPreviewMin">0</strong></span>
              <span>Step: <strong id="uiSliderPreviewStep">1</strong></span>
              <span>Max: <strong id="uiSliderPreviewMax">100</strong></span>
              <span>Scaling: <strong id="uiSliderPreviewScaling">—</strong></span>
            </div>
          </div>

          <!-- Hue Circle gets the same Min / Max / Step / Scaling fields,
               but uses the circular LEVEL preview requested by the UI design. -->
          <div class="ui-hue-circle-live-demo ui-config-preview-card" id="uiHueCirclePreviewCard" hidden>
            <div class="ui-hue-circle-header">
              <span class="ui-hue-circle-header-icon" aria-hidden="true">
                <i class="fas fa-gauge-high"></i>
              </span>
              <div class="ui-hue-circle-header-copy">
                <strong>Hue Circle</strong>
                <span id="uiHueCircleHeaderValue">50</span>
              </div>
            </div>

            <div class="ui-hue-circle-panel">
              <div class="ui-hue-circle-level-label">LEVEL</div>

              <div class="ui-hue-circle-gauge" id="uiHueCircleGauge"
                role="slider" tabindex="0" aria-label="Hue Circle preview"
                aria-valuemin="0" aria-valuemax="100" aria-valuenow="50">
                <svg class="ui-hue-circle-svg" viewBox="0 0 240 240" aria-hidden="true">
                  <defs>
                    <linearGradient id="uiHueCircleGradient" x1="0" y1="0" x2="1" y2="1">
                      <stop offset="0%" stop-color="#5b8df8" />
                      <stop offset="55%" stop-color="#3478f6" />
                      <stop offset="100%" stop-color="#1f64ec" />
                    </linearGradient>
                  </defs>
                  <circle class="ui-hue-circle-track" cx="120" cy="120" r="82"></circle>
                  <circle class="ui-hue-circle-progress" id="uiHueCircleProgress" cx="120" cy="120" r="82"></circle>
                </svg>

                <div class="ui-hue-circle-needle-wrap" id="uiHueCircleNeedle">
                  <span class="ui-hue-circle-needle"></span>
                  <span class="ui-hue-circle-hub"></span>
                </div>
              </div>

              <div class="ui-hue-circle-readout">
                <strong id="uiHueCircleCurrentValue">50</strong>
                <span>/</span>
                <span id="uiHueCircleMaxValue">100</span>
              </div>
            </div>

            <div class="ui-hue-circle-meta">
              <span>Min: <strong id="uiHueCircleMin">0</strong></span>
              <span>Step: <strong id="uiHueCircleStep">1</strong></span>
              <span>Max: <strong id="uiHueCircleMax">100</strong></span>
              <span>Scaling: <strong id="uiHueCircleScaling">—</strong></span>
            </div>

            <small class="ui-hue-circle-help">
              <i class="fas fa-circle-info"></i>
              <span>Click or drag around the circle to test the configured Hue Circle range.</span>
            </small>
          </div>

          <!-- Auto Trigger With Timer uses Min / Max / Step / Scaling plus a live timer preview. -->
          <div class="ui-auto-timer-live-demo ui-config-preview-card" id="uiAutoTimerPreviewCard" hidden>
            <div class="ui-auto-timer-header">
              <span class="ui-auto-timer-header-icon" aria-hidden="true"><i class="fas fa-clock"></i></span>
              <div class="ui-auto-timer-header-copy">
                <strong>Auto Trigger With Timer</strong>
                <span id="uiAutoTimerHeaderValue">0s</span>
              </div>
            </div>

            <div class="ui-auto-timer-panel">
              <div class="ui-auto-timer-title"><i class="far fa-clock"></i><span>TIMER</span></div>
              <div class="ui-auto-timer-reading">
                <span id="uiAutoTimerMinLabel">0s</span>
                <strong id="uiAutoTimerCurrentValue">0s</strong>
                <span id="uiAutoTimerMaxLabel">255s</span>
              </div>
              <input type="range" class="ui-auto-timer-range" id="uiAutoTimerPreview" min="0" max="255" step="1" value="0" aria-label="Auto Trigger timer preview" />
            </div>

            <div class="ui-auto-timer-meta">
              <span>Min: <strong id="uiAutoTimerMin">0</strong></span>
              <span>Step: <strong id="uiAutoTimerStep">1</strong></span>
              <span>Max: <strong id="uiAutoTimerMax">255</strong></span>
              <span>Scaling: <strong id="uiAutoTimerScaling">—</strong></span>
            </div>

            <small class="ui-auto-timer-help">
              <i class="fas fa-circle-info"></i>
              <span>Drag the timer slider to test the configured Auto Trigger time in seconds.</span>
            </small>
          </div>
        </section>

        <!-- Other UI types intentionally have no extra fields in this popup. -->
        <section id="uiConfigGenericSection" class="ui-config-section" hidden>
          <div class="ui-config-generic-preview">
            <div class="ui-config-generic-icon" id="uiConfigGenericPreview"></div>
            <strong id="uiConfigGenericLabel">Selected UI</strong>
            <span>No additional UI values are required for this UI type.</span>
          </div>
        </section>
      </div>

      <div class="ui-config-actions">
        <button type="button" class="ui-config-edit-btn" id="editUiConfigValues">
          <i class="fas fa-pen"></i> Edit Values
        </button>
        <button type="button" class="ui-config-done-btn" id="doneUiConfigurationModal">
          <i class="fas fa-circle-check"></i> Done
        </button>
      </div>
    </div>
  </div>


  <script>
    window.API_CONFIGURATION_APP = <?= json_encode([
      'id' => $configurationId,
      'itemId' => $itemId,
      'product' => [
        'brandname' => $brandValue,
        'productname' => $productValue,
        'modelname' => $modelValue,
        'version' => $versionValue,
        'batch' => $batchValue,
        'brand_image' => $brandImageValue,
        'product_image' => $productImageValue,
        // UI-only compatibility aliases from the old form.
        'brand' => $brandValue,
        'category' => $productValue,
        'model_name' => $modelValue,
      ],
      // Dedicated metadata endpoint handled by ApiConfiguration::vendorMeta().
      'vendorListUrl' => site_url('items/modal_api_vendor_meta/' . $itemId),
      // Same fallback folder used by the Vendor page when only a filename is returned.
      'vendorImageBaseUrl' => base_url('files/brand_logo/'),
      'saveUrl' => site_url('items/saveapi'),
      'csrfHeader' => csrf_header(),
      'readUrl' => null,
      'listUrl' => site_url('items/viewapis/' . $itemId),
      // Used by the Existing Parameter dropdown to remove parameters that
      // are already assigned to another saved API for this same product.
      'usedParameterListUrl' => site_url('items/list_data2/' . $itemId),
      'deleteUrl' => $configurationId
        ? site_url('items/delete_api_config/' . $configurationId)
        : null,
      'createUrl' => site_url('items/modal_api/' . $itemId),
      'initialConfiguration' => $initialConfiguration,
      'isEditMode' => $isEditMode,
      'commandGetStatusEditLocked' => $commandGetStatusEditLocked,
      'fixedCommandValue' => 'A1E70A',
      'existingParameterNames' => $existingParameterNames,
    ], JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_UNESCAPED_SLASHES) ?>;

    (function () {
      const serverApp = window.API_CONFIGURATION_APP;

      /* =======================================================
       * BRAND / PRODUCT IMAGES FROM DATABASE
       * -------------------------------------------------------
       * Images are resolved by model_apiform from:
       *   vendorproducts.brand -> brands.name -> brands.brandlogo/img_path
       *   vendorproducts.category -> productcats.name -> Product_image/img_path
       * The PHP HTML renders them immediately; this JS remains as a fallback.
       * ======================================================= */
      function resolveVendorMetaImageUrl(value) {
        value = String(value || "").trim();
        if (!value) return "";

        if (/^(https?:)?\/\//i.test(value) || value.charAt(0) === "/") {
          return value;
        }

        // Keep the same filename fallback behaviour as the Vendor cards.
        const filename = value.split(/[\\/]/).pop();
        return String(serverApp.vendorImageBaseUrl || "") + encodeURIComponent(filename);
      }

      function setMetaDatabaseImage(slotId, imageValue, altText) {
        const slot = document.getElementById(slotId);
        const imageUrl = resolveVendorMetaImageUrl(imageValue);
        if (!slot || !imageUrl) return false;

        const img = new Image();
        img.className = "meta-db-image";
        img.alt = altText || "";
        img.decoding = "async";

        img.onload = function () {
          slot.replaceChildren(img);
          slot.classList.add("has-db-image");
        };

        img.onerror = function () {
          console.warn("Unable to load DB image for " + slotId + ":", imageUrl);
          // Leave the original Font Awesome fallback icon in place.
        };

        img.src = imageUrl;
        return true;
      }

      function normalizeMetaMatch(value) {
        return String(value || "").trim().toLowerCase();
      }

      function findCurrentVendorImageRow(rows) {
        const itemId = Number(serverApp.itemId || 0);
        const product = serverApp.product || {};
        const brandName = normalizeMetaMatch(product.brandname || product.brand);
        const productName = normalizeMetaMatch(product.productname || product.category);
        const modelName = normalizeMetaMatch(product.modelname || product.model_name);

        // Best match: same model/vendor row id.
        if (itemId > 0) {
          const idMatch = rows.find(function (row) {
            return Number(row && row.id) === itemId;
          });
          if (idMatch) return idMatch;
        }

        // Next: model number or model name.
        if (modelName) {
          const modelMatch = rows.find(function (row) {
            return normalizeMetaMatch(row && row.model_no) === modelName ||
              normalizeMetaMatch(row && row.model_name) === modelName;
          });
          if (modelMatch) return modelMatch;
        }

        // Last safe match: selected brand + selected product.
        if (brandName || productName) {
          return rows.find(function (row) {
            const rowBrand = normalizeMetaMatch(row && row.brand_name);
            const rowProduct = normalizeMetaMatch(row && row.product_name);
            return (!brandName || rowBrand === brandName) &&
              (!productName || rowProduct === productName);
          }) || null;
        }

        return null;
      }

      async function loadBrandAndProductMetaImages() {
        const product = serverApp.product || {};

        // Instant path if the current backend already supplied these values.
        let brandLoaded = setMetaDatabaseImage(
          "brandMetaIcon",
          product.brand_image || product.brand_logo || product.brandlogo || "",
          (product.brandname || product.brand || "Brand") + " logo"
        );
        let productLoaded = setMetaDatabaseImage(
          "productMetaIcon",
          product.product_image || product.Product_image || product.prodimg || "",
          (product.productname || product.category || "Product") + " image"
        );

        // Fetch the same DB-backed Vendor data if either image wasn't supplied.
        if (brandLoaded && productLoaded) return;
        if (!serverApp.vendorListUrl) return;

        try {
          const separator = serverApp.vendorListUrl.indexOf("?") >= 0 ? "&" : "?";
          const response = await fetch(
            serverApp.vendorListUrl + separator + "_ts=" + Date.now(),
            {
              method: "GET",
              credentials: "same-origin",
              cache: "no-store",
              headers: { "Accept": "application/json" }
            }
          );

          if (!response.ok) {
            throw new Error("HTTP " + response.status);
          }

          const payload = await response.json();
          const rows = Array.isArray(payload)
            ? payload
            : (payload && Array.isArray(payload.data) ? payload.data : []);
          const row = findCurrentVendorImageRow(rows);

          if (!row) {
            console.warn("No matching Vendor row found for brand/product images.");
            return;
          }

          if (!brandLoaded) {
            brandLoaded = setMetaDatabaseImage(
              "brandMetaIcon",
              row.brand_image || row.brand_logo || row.brandlogo || "",
              (row.brand_name || product.brandname || "Brand") + " logo"
            );
          }

          if (!productLoaded) {
            productLoaded = setMetaDatabaseImage(
              "productMetaIcon",
              row.product_image || row.Product_image || row.prodimg || "",
              (row.product_name || product.productname || "Product") + " image"
            );
          }
        } catch (error) {
          console.warn("Unable to load Brand/Product images from Vendor DB data:", error);
        }
      }

      // Script is placed after the meta HTML, so the image slots already exist.
      loadBrandAndProductMetaImages();
      let bytes = [];
      let selectedFrameIndex = null;
      let frameCodes = [];
      let frameValueGroups = [];
      let fieldDescriptions = {};
      let byteDescriptions = {};
      let fieldViewModes = {};
      let fullApiValue = "00";
      // Database-reconstructed edit rows retain byte ranges even when the
      // original hexadecimal frame value is not present in the edit payload.
      // Keep that layout count separate so restoring the UI never invents or
      // saves a fake hexadecimal value.
      let restoredByteCount = 0;
      let partitionCuts = [];
      let partitionLabels = {};
      let partitionViewModes = {};
      let partitionFieldConfigurations = {};
      let selectedBitGroups = {};
      let partitionsConfirmed = false;
      let suppressCutClick = false;
      let activePartitionFrameIndex = null;
      let framePartitionStates = [];
      let frameConfigurations = [];
      let showSetupWarnings = false;
      let showPartitionWarnings = false;
      let awaitingFrameClick = false;
      let frameGenerationRevealed = Boolean(serverApp.id);
      let activeFrameType = "command";

      // Command / Response / Error do not use a hardcoded protocol frame value.
      // Each frame starts with one editable 00 byte. The user owns every byte
      // and can add/remove bytes with the controls around each byte box.
      let hexEditorDraftBytes = ["00"];
      // Keep the partition workspace visible while a newly inserted byte is
      // still empty/partial. fullApiValue remains empty until every byte is
      // valid, so save validation stays strict.
      let hexEditorDraftIsIncomplete = false;

      const FRAME_TYPE_LABELS = {
        command: "Command",
        response: "Response",
        error: "Error",
      };
      const frameTypeStores = {
        command: createEmptyFrameTypeStore(),
        response: createEmptyFrameTypeStore(),
        error: createEmptyFrameTypeStore(),
      };

      /* =======================================================
       * EDIT-ONLY COMMAND GET STATUS COMMAND LOCK
       * ======================================================= */
      const COMMAND_GET_STATUS_FIXED_VALUE = "A1E70A";
      const COMMAND_GET_STATUS_FIXED_BYTES = ["A1", "E7", "0A"];
      const COMMAND_GET_STATUS_EDIT_LOCKED = Boolean(
        serverApp.isEditMode && serverApp.commandGetStatusEditLocked,
      );

      const EXISTING_PARAMETER_NAMES = Array.isArray(serverApp.existingParameterNames)
        ? serverApp.existingParameterNames
            .map((name) => String(name || "").trim())
            .filter(Boolean)
        : [];

      function normalizeParameterLookup(value) {
        return String(value || "").trim().replace(/\s+/g, " ").toLowerCase();
      }

      /*
       * ALREADY-USED EXISTING PARAMETER FILTER
       * --------------------------------------
       * EXISTING_PARAMETER_NAMES contains the names from:
       * Command Get Status -> Response frame.
       *
       * items/list_data2/<itemid> contains APIs already saved for this product.
       * If one of those saved API parameter names matches an Existing Parameter,
       * do not show it again while adding the next API.
       *
       * Edit mode is handled separately: the current API's own parameter remains
       * available, but a parameter used by any OTHER API remains hidden.
       */
      const USED_EXISTING_PARAMETER_NAMES = new Set();
      let USED_EXISTING_PARAMETERS_READY = false;

      function extractParameterNameFromApiListCell(cellValue) {
        const raw = String(cellValue ?? "").trim();
        if (!raw) return "";

        const holder = document.createElement("div");
        holder.innerHTML = raw;

        // Current list_data2 rows render the parameter inside <b>...</b>.
        const boldName = holder.querySelector("b")?.textContent?.trim();
        if (boldName) return boldName;

        // Compatibility fallback if the list endpoint later returns plain text.
        return String(holder.textContent || raw)
          .replace(/\s+(?:V2|Legacy)\s*$/i, "")
          .trim();
      }

      function extractConfigIdFromApiListRow(row) {
        if (!Array.isArray(row)) return 0;

        for (const cell of row) {
          const raw = String(cell ?? "");
          if (!raw.includes("data-config-id")) continue;

          const holder = document.createElement("div");
          holder.innerHTML = raw;
          const node = holder.querySelector("[data-config-id]");
          const id = Number.parseInt(node?.getAttribute("data-config-id") || "0", 10);
          if (Number.isInteger(id) && id > 0) return id;
        }

        return 0;
      }

      function isExistingParameterAlreadyUsed(parameterName) {
        const key = normalizeParameterLookup(parameterName);
        return Boolean(key && USED_EXISTING_PARAMETER_NAMES.has(key));
      }

      function refreshExistingParameterOptions() {
        const source = document.getElementById("parameterNameSourceSelect");
        const select = document.getElementById("existingParameterNameSelect");
        const note = document.querySelector(
          "#existingParameterNameControl .existing-parameter-note",
        );

        if (!select) return;

        const currentCanonical =
          document.getElementById("paramNameInput")?.value?.trim() || "";
        const currentCanonicalKey = normalizeParameterLookup(currentCanonical);

        let availableCount = 0;

        Array.from(select.options).forEach((option, optionIndex) => {
          if (optionIndex === 0 || !option.value) return;

          const optionKey = normalizeParameterLookup(option.value);

          /*
           * loadUsedExistingParameterNames() already excludes the current V2
           * config by config id. This additional edit exception protects older
           * records where the list row does not expose a config id.
           */
          const isOwnEditParameter =
            Boolean(serverApp.isEditMode) &&
            optionKey === currentCanonicalKey;

          const alreadyUsed =
            !isOwnEditParameter &&
            isExistingParameterAlreadyUsed(option.value);

          option.hidden = alreadyUsed;
          option.disabled = alreadyUsed;
          option.dataset.alreadyUsed = alreadyUsed ? "true" : "false";

          if (!alreadyUsed) availableCount += 1;
        });

        // A stale browser selection must never remain selected after refresh.
        const selectedOption = select.selectedOptions?.[0];
        if (
          selectedOption &&
          selectedOption.dataset.alreadyUsed === "true"
        ) {
          select.value = "";
          setCanonicalParameterName("", false);
        }

        const existingSourceOption = source?.querySelector(
          'option[value="existing"]',
        );

        if (existingSourceOption && !COMMAND_GET_STATUS_EDIT_LOCKED) {
          existingSourceOption.disabled =
            USED_EXISTING_PARAMETERS_READY && availableCount === 0;
        }

        if (note && USED_EXISTING_PARAMETERS_READY) {
          note.classList.toggle(
            "parameter-source-empty",
            availableCount === 0,
          );

          note.innerHTML =
            availableCount > 0
              ? ``
              : '<i class="fas fa-triangle-exclamation"></i> All Get Status Response parameters are already selected by saved APIs.';
        }

        if (
          source?.value === "existing" &&
          availableCount === 0 &&
          !serverApp.isEditMode
        ) {
          source.value = "";
          document
            .getElementById("existingParameterNameControl")
            ?.setAttribute("hidden", "");
          setCanonicalParameterName("", false);
        }
      }

      async function loadUsedExistingParameterNames() {
        const source = document.getElementById("parameterNameSourceSelect");
        const select = document.getElementById("existingParameterNameSelect");
        const note = document.querySelector(
          "#existingParameterNameControl .existing-parameter-note",
        );

        USED_EXISTING_PARAMETERS_READY = false;

        if (select && !COMMAND_GET_STATUS_EDIT_LOCKED) {
          select.disabled = true;
        }

        if (note && !COMMAND_GET_STATUS_EDIT_LOCKED) {
          note.classList.remove("parameter-source-empty");
          note.innerHTML =
            '<i class="fas fa-spinner fa-spin"></i> Checking parameters already used by saved APIs...';
        }

        USED_EXISTING_PARAMETER_NAMES.clear();

        if (!serverApp.usedParameterListUrl) {
          USED_EXISTING_PARAMETERS_READY = true;
          if (select && !COMMAND_GET_STATUS_EDIT_LOCKED) {
            select.disabled = false;
          }
          refreshExistingParameterOptions();
          return;
        }

        try {
          const separator =
            serverApp.usedParameterListUrl.includes("?") ? "&" : "?";

          const response = await fetch(
            serverApp.usedParameterListUrl +
              separator +
              "_ts=" +
              Date.now(),
            {
              method: "GET",
              credentials: "same-origin",
              cache: "no-store",
              headers: {
                Accept: "application/json",
                "X-Requested-With": "XMLHttpRequest",
              },
            },
          );

          if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
          }

          const payload = await response.json();
          const rows = Array.isArray(payload)
            ? payload
            : Array.isArray(payload?.data)
              ? payload.data
              : [];

          rows.forEach((row) => {
            if (!Array.isArray(row) || row.length === 0) return;

            const rowConfigId = extractConfigIdFromApiListRow(row);

            // Editing an existing V2 API: do not mark its own parameter as used.
            if (
              serverApp.id &&
              rowConfigId &&
              Number(rowConfigId) === Number(serverApp.id)
            ) {
              return;
            }

            const parameterName = extractParameterNameFromApiListCell(row[0]);
            const matchedExistingName = findExistingParameterName(parameterName);

            // Only Get Status Response parameter names are filtered.
            if (matchedExistingName) {
              USED_EXISTING_PARAMETER_NAMES.add(
                normalizeParameterLookup(matchedExistingName),
              );
            }
          });
        } catch (error) {
          /*
           * Do not break the Add API page if the helper list request fails.
           * The save-time duplicate check below will try the request again.
           */
          console.error(
            "Unable to load already-used Existing Parameters.",
            error,
          );
        } finally {
          USED_EXISTING_PARAMETERS_READY = true;

          if (select && !COMMAND_GET_STATUS_EDIT_LOCKED) {
            select.disabled = false;
          }

          refreshExistingParameterOptions();

          /*
           * If there are zero available Existing Parameters, keep the source
           * option disabled. Otherwise make sure it is selectable again.
           */
          const existingSourceOption = source?.querySelector(
            'option[value="existing"]',
          );
          if (
            existingSourceOption &&
            !COMMAND_GET_STATUS_EDIT_LOCKED &&
            Array.from(select?.options || []).some(
              (option, index) =>
                index > 0 &&
                option.value &&
                !option.disabled,
            )
          ) {
            existingSourceOption.disabled = false;
          }
        }
      }

      function findExistingParameterName(value) {
        const normalized = normalizeParameterLookup(value);
        if (!normalized) return "";
        return EXISTING_PARAMETER_NAMES.find(
          (name) => normalizeParameterLookup(name) === normalized,
        ) || "";
      }

      function setCanonicalParameterName(value, dispatchInput = true) {
        const canonical = document.getElementById("paramNameInput");
        if (!canonical) return;
        const nextValue = COMMAND_GET_STATUS_EDIT_LOCKED
          ? "Command Get Status"
          : String(value || "");
        const changed = canonical.value !== nextValue;
        canonical.value = nextValue;
        if (dispatchInput && changed) {
          canonical.dispatchEvent(new Event("input", { bubbles: true }));
        }
      }

      function syncParameterNameChooserFromCanonical(options = {}) {
        const dispatchInput = options.dispatchInput === true;
        const source = document.getElementById("parameterNameSourceSelect");
        const existingControl = document.getElementById("existingParameterNameControl");
        const customControl = document.getElementById("customParameterNameControl");
        const existingSelect = document.getElementById("existingParameterNameSelect");
        const customInput = document.getElementById("customParameterNameInput");
        const canonical = document.getElementById("paramNameInput");
        if (!source || !existingControl || !customControl || !canonical) return;

        if (COMMAND_GET_STATUS_EDIT_LOCKED) {
          source.value = "custom";
          source.disabled = true;
          existingControl.hidden = true;
          customControl.hidden = false;
          if (customInput) {
            customInput.value = "Command Get Status";
            customInput.readOnly = true;
          }
          setCanonicalParameterName("Command Get Status", dispatchInput);
          return;
        }

        const savedValue = String(canonical.value || "").trim();
        const existingMatch = findExistingParameterName(savedValue);
        if (savedValue && existingMatch) {
          source.value = "existing";
          existingControl.hidden = false;
          customControl.hidden = true;
          if (existingSelect) existingSelect.value = existingMatch;
          setCanonicalParameterName(existingMatch, dispatchInput);
          return;
        }
        if (savedValue) {
          source.value = "custom";
          existingControl.hidden = true;
          customControl.hidden = false;
          if (customInput) customInput.value = savedValue;
          setCanonicalParameterName(savedValue, dispatchInput);
          return;
        }
        source.value = "";
        existingControl.hidden = true;
        customControl.hidden = true;
        if (existingSelect) existingSelect.value = "";
        if (customInput) customInput.value = "";
        setCanonicalParameterName("", dispatchInput);
      }

      function applyParameterNameSourceSelection(dispatchInput = true) {
        const source = document.getElementById("parameterNameSourceSelect");
        const existingControl = document.getElementById("existingParameterNameControl");
        const customControl = document.getElementById("customParameterNameControl");
        const existingSelect = document.getElementById("existingParameterNameSelect");
        const customInput = document.getElementById("customParameterNameInput");
        if (!source || !existingControl || !customControl) return;

        existingControl.hidden = source.value !== "existing";
        customControl.hidden = source.value !== "custom";
        if (source.value === "existing") {
          setCanonicalParameterName(existingSelect?.value || "", dispatchInput);
        } else if (source.value === "custom") {
          setCanonicalParameterName(customInput?.value || "", dispatchInput);
        } else {
          setCanonicalParameterName("", dispatchInput);
        }
        updateRequiredDropdownWarnings(showSetupWarnings);
      }

      function initializeParameterNameChooser() {
        syncParameterNameChooserFromCanonical({ dispatchInput: false });

        // DB-backed filter: remove Existing Parameters already used by APIs.
        loadUsedExistingParameterNames();

        document.getElementById("parameterNameSourceSelect")?.addEventListener("change", function () {
          if (this.value === "existing") {
            refreshExistingParameterOptions();
          }
          applyParameterNameSourceSelection(true);
        });
        document.getElementById("existingParameterNameSelect")?.addEventListener("change", function () {
          if (document.getElementById("parameterNameSourceSelect")?.value === "existing") {
            setCanonicalParameterName(this.value, true);
            updateRequiredDropdownWarnings(showSetupWarnings);
          }
        });
        document.getElementById("customParameterNameInput")?.addEventListener("input", function () {
          if (document.getElementById("parameterNameSourceSelect")?.value === "custom") {
            setCanonicalParameterName(this.value, true);
            updateRequiredDropdownWarnings(showSetupWarnings);
          }
        });
      }

      function isCommandGetStatusCommandLocked(frameType = activeFrameType) {
        return COMMAND_GET_STATUS_EDIT_LOCKED && frameType === "command";
      }

      function isCommandGetStatusResponseFrame(frameType = activeFrameType) {
        return COMMAND_GET_STATUS_EDIT_LOCKED && frameType === "response";
      }

      function getCommandGetStatusResponseDraftBytes() {
        let values = Array.isArray(hexEditorDraftBytes)
          ? hexEditorDraftBytes.map((value) => normalizeHex(String(value || "")).slice(0, 2))
          : [];

        if (
          values.length >= 3 &&
          values[0] === "DE" &&
          values[1] === "E7" &&
          values[values.length - 1] === "0A"
        ) {
          return values;
        }

        const saved = normalizeHex(String(fullApiValue || ""));
        const savedBytes = saved.match(/[0-9A-F]{2}/g) || [];
        if (
          savedBytes.length >= 3 &&
          savedBytes[0] === "DE" &&
          savedBytes[1] === "E7" &&
          savedBytes[savedBytes.length - 1] === "0A"
        ) {
          return savedBytes;
        }

        return ["DE", "E7", "0A"];
      }

      function syncCommandGetStatusResponseValue(values, markChanged = true) {
        const responseBytes = Array.isArray(values) && values.length >= 3
          ? [...values]
          : ["DE", "E7", "0A"];

        responseBytes[0] = "DE";
        responseBytes[1] = "E7";
        responseBytes[responseBytes.length - 1] = "0A";
        hexEditorDraftBytes = responseBytes;

        const allComplete = responseBytes.every((value) => /^[0-9A-F]{2}$/.test(value));
        if (allComplete) {
          fullApiValue = responseBytes.join("");
          hexEditorDraftIsIncomplete = false;
          restoredByteCount = responseBytes.length;
          const hiddenInput = document.getElementById("fullApiInput");
          if (hiddenInput) hiddenInput.value = fullApiValue;
          if (markChanged) {
            partitionsConfirmed = false;
            setPartitionChanged();
          }
        } else {
          fullApiValue = "";
          hexEditorDraftIsIncomplete = true;
          restoredByteCount = responseBytes.length;
          const hiddenInput = document.getElementById("fullApiInput");
          if (hiddenInput) hiddenInput.value = "";
          if (markChanged) {
            partitionsConfirmed = false;
            setPartitionChanged();
          }
        }

        return allComplete;
      }

      function getCommandGetStatusFixedPartitionName(range) {
        if (!COMMAND_GET_STATUS_EDIT_LOCKED || !range) return "";

        if (activeFrameType === "command") {
          if (range.start === 0 && range.end === 1) return "commandId";
          if (range.start === 1 && range.end === 2) return "functionCode";
          if (range.start === 2 && range.end === 3) return "terminatorCrc";
          return "";
        }

        if (activeFrameType === "response") {
          const byteCount = getApiBytes().length;
          if (range.start === 0 && range.end === 1) return "commandId";
          if (range.start === 1 && range.end === 2) return "functionCode";
          if (byteCount >= 3 && range.start === byteCount - 1 && range.end === byteCount) {
            return "terminatorCrc";
          }
        }

        return "";
      }

      function isCommandGetStatusLockedResponsePartitionRange(range) {
        return Boolean(
          COMMAND_GET_STATUS_EDIT_LOCKED &&
          activeFrameType === "response" &&
          range &&
          getCommandGetStatusFixedPartitionName(range),
        );
      }

      function isCommandGetStatusLockedResponsePartitionKey(key) {
        if (!COMMAND_GET_STATUS_EDIT_LOCKED || activeFrameType !== "response") {
          return false;
        }
        const range = getPartitionRanges().find(
          (item) => partitionKey(item) === String(key || ""),
        );
        return isCommandGetStatusLockedResponsePartitionRange(range);
      }

      function isCommandGetStatusLockedResponseByteIndex(byteIndex) {
        if (!COMMAND_GET_STATUS_EDIT_LOCKED || activeFrameType !== "response") {
          return false;
        }
        const bytes = getApiBytes();
        const index = Number(byteIndex);
        if (!Number.isInteger(index) || bytes.length < 3) return false;
        return index === 0 || index === 1 || index === bytes.length - 1;
      }

      function isCommandGetStatusProtectedCut(cutPosition) {
        if (!COMMAND_GET_STATUS_EDIT_LOCKED) return false;
        if (activeFrameType === "command") return true;
        if (activeFrameType !== "response") return false;

        const byteCount = getApiBytes().length;
        const terminatorCut = byteCount - 1;
        return cutPosition === 1 || cutPosition === 2 || cutPosition === terminatorCut;
      }

      function enforceCommandGetStatusPartitionRules() {
        if (!COMMAND_GET_STATUS_EDIT_LOCKED) return;
        const byteCount = getApiBytes().length;
        if (byteCount < 3) return;

        if (activeFrameType === "command") {
          partitionCuts = [1, 2];
          partitionLabels["0-1"] = "commandId";
          partitionLabels["1-2"] = "functionCode";
          partitionLabels["2-3"] = "terminatorCrc";
          return;
        }

        if (activeFrameType === "response") {
          const terminatorCut = byteCount - 1;
          const payloadCuts = partitionCuts.filter(
            (cut) => Number.isInteger(Number(cut)) && Number(cut) > 2 && Number(cut) < terminatorCut,
          ).map(Number);
          partitionCuts = [...new Set([1, 2, ...(terminatorCut > 2 ? [terminatorCut] : []), ...payloadCuts])]
            .sort((a, b) => a - b);
          partitionLabels["0-1"] = "commandId";
          partitionLabels["1-2"] = "functionCode";
          partitionLabels[`${byteCount - 1}-${byteCount}`] = "terminatorCrc";
        }
      }


      /*
       * RESPONSE BYTE STRUCTURE REMAP
       * -----------------------------
       * Partition Field Configuration is stored by byte-range key, for example:
       *   "2-3" => { byte: { ... } }
       *
       * When a new payload byte is inserted before 0A, the old 0A partition
       * moves one byte to the right. If those keyed objects are not remapped,
       * the old 0A Field Configuration remains at "2-3" and is incorrectly
       * shown on the newly inserted payload byte.
       *
       * These helpers move EXISTING byte configurations with their original
       * bytes while deliberately leaving the NEW byte with a completely empty
       * Field Configuration.
       */
      function parsePartitionRangeKey(key) {
        const match = String(key || "").match(/^(\d+)-(\d+)$/);
        if (!match) return null;
        return {
          start: Number.parseInt(match[1], 10),
          end: Number.parseInt(match[2], 10),
        };
      }

      function remapPartitionObjectForInsertedByte(source, insertAt, clearSpanningValue = false) {
        const result = {};
        if (!source || typeof source !== "object") return result;

        Object.entries(source).forEach(([key, value]) => {
          const range = parsePartitionRangeKey(key);
          if (!range) {
            // Preserve non-range metadata keys if any exist.
            result[key] = clonePartitionObject(value);
            return;
          }

          let nextStart = range.start;
          let nextEnd = range.end;
          let spanningInsertion = false;

          if (range.start >= insertAt) {
            nextStart += 1;
            nextEnd += 1;
          } else if (range.end > insertAt) {
            // The new byte was inserted inside an existing multi-byte partition.
            // Expand the range but clear its Field Configuration because the
            // structure changed and the new byte must never inherit old values.
            nextEnd += 1;
            spanningInsertion = true;
          }

          const nextKey = `${nextStart}-${nextEnd}`;
          result[nextKey] = clearSpanningValue && spanningInsertion
            ? {}
            : clonePartitionObject(value);
        });

        // Most important rule: the newly inserted byte starts with NO saved
        // partition/configuration state of its own.
        const newByteKey = `${insertAt}-${insertAt + 1}`;
        delete result[newByteKey];

        return result;
      }

      function remapPartitionObjectForRemovedByte(source, removeAt, clearSpanningValue = false) {
        const result = {};
        if (!source || typeof source !== "object") return result;

        Object.entries(source).forEach(([key, value]) => {
          const range = parsePartitionRangeKey(key);
          if (!range) {
            result[key] = clonePartitionObject(value);
            return;
          }

          // Configuration that belonged only to the removed byte is discarded.
          if (range.start === removeAt && range.end === removeAt + 1) {
            return;
          }

          let nextStart = range.start;
          let nextEnd = range.end;
          let spanningRemoval = false;

          if (range.start > removeAt) {
            nextStart -= 1;
            nextEnd -= 1;
          } else if (range.end > removeAt) {
            nextEnd -= 1;
            spanningRemoval = true;
          }

          if (nextEnd <= nextStart) return;

          const nextKey = `${nextStart}-${nextEnd}`;
          result[nextKey] = clearSpanningValue && spanningRemoval
            ? {}
            : clonePartitionObject(value);
        });

        return result;
      }

      function remapCommandGetStatusResponseStateForInsertedByte(insertAt) {
        if (!isCommandGetStatusResponseFrame()) return;

        /*
         * IMPORTANT INVARIANT
         * -------------------
         * Existing byte configuration follows the EXISTING byte.
         * Example: before insert, 0A is key 2-3. If a new byte is inserted
         * at index 2, 0A becomes byte 4 and its saved configuration MUST move
         * to key 3-4. The new key 2-3 must start empty.
         */

        partitionLabels = remapPartitionObjectForInsertedByte(
          partitionLabels,
          insertAt,
          false,
        );
        partitionViewModes = remapPartitionObjectForInsertedByte(
          partitionViewModes,
          insertAt,
          false,
        );
        partitionFieldConfigurations = remapPartitionObjectForInsertedByte(
          partitionFieldConfigurations,
          insertAt,
          true,
        );
        selectedBitGroups = remapPartitionObjectForInsertedByte(
          selectedBitGroups,
          insertAt,
          true,
        );

        // The NEW byte must be completely fresh: no name, no view mode,
        // no bit selection and, most importantly, no Field Configuration.
        const newByteKey = `${insertAt}-${insertAt + 1}`;
        delete partitionLabels[newByteKey];
        delete partitionViewModes[newByteKey];
        delete partitionFieldConfigurations[newByteKey];
        delete selectedBitGroups[newByteKey];

        // Close a currently open field/config popup so stale 0A values cannot
        // stay visible after the byte structure changes.
        closeByteFieldModal?.();
        closePartitionModePopup?.();
        currentModalPartitionKey = null;
        currentModalByteKey = null;
        currentModalByteIndex = null;
        currentModalBitPosition = null;
        currentModalBitPositions = null;
      }

      function remapCommandGetStatusResponseStateForRemovedByte(removeAt) {
        if (!isCommandGetStatusResponseFrame()) return;

        partitionLabels = remapPartitionObjectForRemovedByte(
          partitionLabels,
          removeAt,
          false,
        );
        partitionViewModes = remapPartitionObjectForRemovedByte(
          partitionViewModes,
          removeAt,
          false,
        );
        partitionFieldConfigurations = remapPartitionObjectForRemovedByte(
          partitionFieldConfigurations,
          removeAt,
          true,
        );
        selectedBitGroups = remapPartitionObjectForRemovedByte(
          selectedBitGroups,
          removeAt,
          true,
        );

        closeByteFieldModal?.();
        closePartitionModePopup?.();
        currentModalPartitionKey = null;
        currentModalByteKey = null;
        currentModalByteIndex = null;
        currentModalBitPosition = null;
        currentModalBitPositions = null;
      }

      function enforceCommandGetStatusCommandState(syncDom = true) {
        if (!COMMAND_GET_STATUS_EDIT_LOCKED) return false;

        const store = frameTypeStores.command;
        const existingPartition =
          store.framePartitionStates?.[0] &&
          typeof store.framePartitionStates[0] === "object"
            ? store.framePartitionStates[0]
            : {};
        const existingConfiguration =
          store.frameConfigurations?.[0] &&
          typeof store.frameConfigurations[0] === "object"
            ? store.frameConfigurations[0]
            : { dataFlowDirection: "", multipleUi: "" };

        existingPartition.fullApiValue = COMMAND_GET_STATUS_FIXED_VALUE;
        existingPartition.inferredByteCount = 3;

        store.count = 1;
        store.frameCodes = [COMMAND_GET_STATUS_FIXED_VALUE];
        store.frameValueGroups = [COMMAND_GET_STATUS_FIXED_BYTES.slice()];
        store.framePartitionStates = [existingPartition];
        store.frameConfigurations = [existingConfiguration];

        const parameterInput = document.getElementById("paramNameInput");
        if (parameterInput) {
          parameterInput.value = "Command Get Status";
          parameterInput.readOnly = true;
          parameterInput.setAttribute("aria-readonly", "true");
          parameterInput.title = "Command Get Status is a protected system API";
        }

        const commandCheckbox = getFrameIncludeCheckbox("command");
        if (commandCheckbox) {
          commandCheckbox.checked = true;
          commandCheckbox.disabled = true;
          commandCheckbox.setAttribute("aria-disabled", "true");
        }

        if (activeFrameType === "command") {
          frameCodes = store.frameCodes;
          frameValueGroups = store.frameValueGroups;
          framePartitionStates = store.framePartitionStates;
          frameConfigurations = store.frameConfigurations;
          fullApiValue = COMMAND_GET_STATUS_FIXED_VALUE;
          hexEditorDraftBytes = COMMAND_GET_STATUS_FIXED_BYTES.slice();
          hexEditorDraftIsIncomplete = false;
          restoredByteCount = 3;

          if (syncDom) {
            const countInput = document.getElementById("cmdFrameCountInput");
            if (countInput) {
              countInput.value = "1";
              countInput.readOnly = true;
              countInput.setAttribute("aria-readonly", "true");
            }
            const hiddenApi = document.getElementById("fullApiInput");
            if (hiddenApi) hiddenApi.value = COMMAND_GET_STATUS_FIXED_VALUE;
          }
        }

        return true;
      }

      function syncCommandGetStatusLockUi() {
        if (!COMMAND_GET_STATUS_EDIT_LOCKED) return;
        enforceCommandGetStatusCommandState(true);

        const lockActiveCommand = isCommandGetStatusCommandLocked();
        const countInput = document.getElementById("cmdFrameCountInput");
        if (countInput) {
          countInput.readOnly = lockActiveCommand;
          if (lockActiveCommand) countInput.value = "1";
        }

        ["addCommandFrameBottom", "addCommandFrameBtn", "generateFramesBtn"].forEach((id) => {
          const button = document.getElementById(id);
          if (!button) return;
          button.hidden = lockActiveCommand;
          button.disabled = lockActiveCommand;
        });
      }

      function enforceLockedCommandOnConfiguration(configuration) {
        if (!COMMAND_GET_STATUS_EDIT_LOCKED || !configuration) {
          return configuration;
        }

        const commands = Array.isArray(configuration.commands)
          ? configuration.commands
          : [];
        const first = commands[0] && typeof commands[0] === "object"
          ? commands[0]
          : {};

        first.frameNumber = 1;
        first.frameType = "command";
        first.frameCode = COMMAND_GET_STATUS_FIXED_VALUE;
        first.commandCode = COMMAND_GET_STATUS_FIXED_VALUE;
        first.commandValue = COMMAND_GET_STATUS_FIXED_VALUE;
        first.partition = first.partition && typeof first.partition === "object"
          ? first.partition
          : {};
        first.partition.fullApiValue = COMMAND_GET_STATUS_FIXED_VALUE;
        first.partition.inferredByteCount = 3;

        configuration.commands = [first];

        if (Array.isArray(configuration.responses) && configuration.responses.length) {
          const response = configuration.responses[0] && typeof configuration.responses[0] === "object"
            ? configuration.responses[0]
            : {};
          const codeCandidates = [
            response.frameCode,
            response.commandCode,
            response.commandValue,
            response.partition?.fullApiValue,
          ];
          let responseCode = "";
          for (const candidate of codeCandidates) {
            const clean = normalizeHex(String(candidate || ""));
            if (clean.length >= 6 && clean.length % 2 === 0 && clean.startsWith("DEE7") && clean.endsWith("0A")) {
              responseCode = clean;
              break;
            }
          }
          if (!responseCode) responseCode = "DEE70A";
          const responseByteCount = responseCode.length / 2;
          const terminatorIndex = responseByteCount - 1;
          response.frameCode = responseCode;
          response.commandCode = responseCode;
          response.commandValue = responseCode;
          response.partition = response.partition && typeof response.partition === "object" ? response.partition : {};
          response.partition.fullApiValue = responseCode;
          response.partition.inferredByteCount = responseByteCount;
          const existingCuts = Array.isArray(response.partition.partitionCuts) ? response.partition.partitionCuts.map(Number) : [];
          const payloadCuts = existingCuts.filter((cut) => Number.isInteger(cut) && cut > 2 && cut < terminatorIndex);
          response.partition.partitionCuts = [...new Set([1, 2, ...(terminatorIndex > 2 ? [terminatorIndex] : []), ...payloadCuts])].sort((a, b) => a - b);
          response.partition.partitionLabels = response.partition.partitionLabels && typeof response.partition.partitionLabels === "object"
            ? response.partition.partitionLabels
            : {};
          response.partition.partitionLabels["0-1"] = "commandId";
          response.partition.partitionLabels["1-2"] = "functionCode";
          response.partition.partitionLabels[`${terminatorIndex}-${responseByteCount}`] = "terminatorCrc";
          configuration.responses[0] = response;
        }

        configuration.product = configuration.product || {};
        configuration.product.parameter_name = "Command Get Status";
        configuration.product.command_frame_count = 1;
        return configuration;
      }

      /*
       * Frame inclusion state
       * ---------------------
       * The checkboxes are connected to the same existing frameTypeStores.
       * No new backend payload format is introduced.
       */
      function getFrameIncludeCheckbox(frameType) {
        return document.querySelector(
          `.frame-include-checkbox[data-frame-type="${frameType}"]`,
        );
      }

      function isFrameTypeIncluded(frameType) {
        return Boolean(getFrameIncludeCheckbox(frameType)?.checked);
      }

      function getIncludedFrameTypes() {
        return Object.keys(FRAME_TYPE_LABELS).filter((frameType) =>
          isFrameTypeIncluded(frameType),
        );
      }

      function renderSelectedFrameTypeChips() {
        const container = document.getElementById("selectedFrameTypeChips");
        if (!container) return;

        const selectedTypes = getIncludedFrameTypes();
        container.replaceChildren();

        selectedTypes.forEach((frameType) => {
          const chip = document.createElement("span");
          chip.className = "selected-frame-type-chip";

          const label = document.createElement("span");
          label.textContent = FRAME_TYPE_LABELS[frameType];

          const remove = document.createElement("button");
          remove.type = "button";
          remove.dataset.removeFrameType = frameType;
          remove.setAttribute(
            "aria-label",
            `Remove ${FRAME_TYPE_LABELS[frameType]} frame`,
          );
          remove.innerHTML = '<i class="fas fa-xmark" aria-hidden="true"></i>';

          if (COMMAND_GET_STATUS_EDIT_LOCKED && frameType === "command") {
            remove.hidden = true;
            remove.disabled = true;
          }

          chip.append(label, remove);
          container.appendChild(chip);
        });

        if (!selectedTypes.length) {
          const empty = document.createElement("span");
          empty.className = "selected-frame-type-chip";
          empty.textContent = "None";
          container.appendChild(empty);
        }
      }

      function syncSelectedFrameFlow(selectedTypes) {
        const flow = document.getElementById("commandResponseErrorFlow");
        if (!flow) return;

        const canonicalOrder = ["command", "response", "error"];

        const stages = canonicalOrder
          .map((frameType) =>
            flow.querySelector(
              `.flow-stage[data-flow-frame-type="${frameType}"]`,
            ),
          )
          .filter(Boolean);

        const arrows = Array.from(
          flow.querySelectorAll(".flow-arrow"),
        );

        const visibleStages = stages.filter((stage) =>
          selectedTypes.includes(stage.dataset.flowFrameType),
        );

        /* Reset all positions/connectors first. */
        stages.forEach((stage) => {
          stage.style.order = "";
        });

        arrows.forEach((arrow) => {
          arrow.classList.add("flow-arrow-hidden");
          arrow.style.order = "";
        });

        /*
         * Place only selected stages consecutively:
         * Response + Error => Response -> Error
         * Command + Error  => Command  -> Error
         */
        visibleStages.forEach((stage, visibleIndex) => {
          stage.style.order = String(visibleIndex * 2);

          if (visibleIndex < visibleStages.length - 1) {
            const arrow = arrows[visibleIndex];
            if (arrow) {
              arrow.style.order = String(visibleIndex * 2 + 1);
              arrow.classList.remove("flow-arrow-hidden");
            }
          }
        });
      }

      function syncFrameInclusionUi() {
        const selectedTypes = getIncludedFrameTypes();

        /*
         * Row 3 mirrors Row 2 exactly.
         */
        syncSelectedFrameFlow(selectedTypes);

        document
          .querySelectorAll(".frame-include-checkbox")
          .forEach((checkbox) => {
            const frameType = checkbox.dataset.frameType;
            const card = checkbox.closest(".frame-choice-card");
            card?.classList.toggle("selected", checkbox.checked);

            const currentStore = frameTypeStores[frameType];
            if (
              !checkbox.checked ||
              Math.max(0, Number(currentStore?.count) || 0) > 0
            ) {
              card?.classList.remove("selected-frame-incomplete");
            }

            const stage = document.querySelector(
              `.flow-stage[data-flow-frame-type="${frameType}"]`,
            );
            if (stage) {
              stage.classList.toggle(
                "frame-not-included",
                !checkbox.checked,
              );
              stage.setAttribute(
                "aria-disabled",
                String(!checkbox.checked),
              );
              stage.disabled = !checkbox.checked;
            }
          });

        const selectAllButton =
          document.getElementById("selectAllFrameTypesBtn");

        if (selectAllButton) {
          const allSelected =
            selectedTypes.length === Object.keys(FRAME_TYPE_LABELS).length;

          selectAllButton.classList.toggle(
            "all-selected",
            allSelected,
          );

          selectAllButton.innerHTML = allSelected
            ? '<i class="fas fa-square-check" aria-hidden="true"></i><span>All Selected</span>'
            : '<i class="far fa-square" aria-hidden="true"></i><span>Select All</span>';
        }

        renderSelectedFrameTypeChips();
      }

      function initializeFrameInclusionFromStores() {
        const storedTypes = Object.keys(FRAME_TYPE_LABELS).filter(
          (frameType) => {
            const store = frameTypeStores[frameType];
            return Math.max(
              0,
              Number(store?.count) || 0,
              store?.frameCodes?.length || 0,
              store?.framePartitionStates?.length || 0,
            ) > 0;
          },
        );

        /*
         * New Add form: Command is selected by default.
         * Edit form: restore exactly the frame types that really contain
         * saved frames; optional Response/Error remain unchecked when absent.
         */
        const selectedTypes = storedTypes.length
          ? storedTypes
          : ["command"];

        Object.keys(FRAME_TYPE_LABELS).forEach((frameType) => {
          const checkbox = getFrameIncludeCheckbox(frameType);
          if (!checkbox) return;
          checkbox.checked = selectedTypes.includes(frameType);
        });

        if (!selectedTypes.includes(activeFrameType)) {
          activeFrameType = selectedTypes[0] || "command";
        }

        syncFrameInclusionUi();
      }

      function setFrameTypeIncluded(frameType, included) {
        if (!FRAME_TYPE_LABELS[frameType]) return;
        if (
          COMMAND_GET_STATUS_EDIT_LOCKED &&
          frameType === "command" &&
          !included
        ) {
          enforceCommandGetStatusCommandState(true);
          syncFrameInclusionUi();
          return;
        }

        const checkbox = getFrameIncludeCheckbox(frameType);
        const store = frameTypeStores[frameType];

        if (!checkbox || !store) return;

        /*
         * Save the active editor before modifying its count.
         */
        if (frameType === activeFrameType) {
          captureActiveFramePartitionState();
          saveActiveFrameTypeStore();
        }

        /*
         * Keep at least one frame type included.
         * If this is the final selected type, do not delete it here.
         */
        if (!included) {
          const otherIncludedTypes = getIncludedFrameTypes().filter(
            (type) => type !== frameType,
          );

          if (!otherIncludedTypes.length) {
            checkbox.checked = true;
            syncFrameInclusionUi();
            return;
          }
        }

        checkbox.checked = Boolean(included);

        if (included) {
          /*
           * A frame type that was removed is treated as a new empty type when
           * selected again. The user must explicitly create its frames.
           */
          if (Math.max(0, Number(store.count) || 0) < 1) {
            store.count = 0;
          }
        } else {
          /*
           * REAL DELETE
           * -----------
           * Removing Response/Error/Command means its complete editor state
           * is cleared. This prevents old Edit data from returning on Save.
           */
          frameTypeStores[frameType] = createEmptyFrameTypeStore();
          checkbox.dataset.previousCount = "0";

          if (frameType === activeFrameType) {
            document.getElementById("cmdFrameCountInput").value = "0";

            frameCodes = [];
            frameValueGroups = [];
            framePartitionStates = [];
            frameConfigurations = [];
            fieldDescriptions = {};
            byteDescriptions = {};
            fieldViewModes = {};
          }
        }

        const includedTypes = getIncludedFrameTypes();

        syncFrameInclusionUi();

        if (!isFrameTypeIncluded(activeFrameType)) {
          const fallback =
            getIncludedFrameTypes()[0] || "command";
          switchFrameType(fallback, false);
        } else if (frameType === activeFrameType) {
          loadFrameTypeStore(activeFrameType);
          updateFrameTypeUi();
        }
      }

      const LOCAL_STORAGE_KEY = "efactor_api_product_configuration_v3";

      function createEmptyFrameTypeStore() {
        return {
          count: 0,
          frameCodes: [],
          frameValueGroups: [],
          fieldDescriptions: {},
          byteDescriptions: {},
          fieldViewModes: {},
          framePartitionStates: [],
          frameConfigurations: [],
          voiceCommandEnabled: "",
          voiceCommands: [],
        };
      }

      function getActiveFrameLabel() {
        return FRAME_TYPE_LABELS[activeFrameType] || "Command";
      }

      function normalizeVoiceCommandEnabled(value, commands = []) {
        const normalized = String(value ?? "").trim().toLowerCase();
        if (["yes", "true", "1", "on"].includes(normalized)) return "Yes";
        if (["no", "false", "0", "off"].includes(normalized)) return "No";
        if (!normalized) {
          return Array.isArray(commands) && commands.length ? "Yes" : "";
        }
        return Array.isArray(commands) && commands.length ? "Yes" : "";
      }

      function normalizeVoiceCommandList(value) {
        if (Array.isArray(value)) {
          return value
            .map((item) => String(item ?? "").trim())
            .filter(Boolean);
        }

        const raw = String(value ?? "").trim();
        if (!raw) return [];

        try {
          const decoded = JSON.parse(raw);
          if (Array.isArray(decoded)) {
            return decoded
              .map((item) => String(item ?? "").trim())
              .filter(Boolean);
          }
        } catch (error) {
          // Older records stored one instruction as plain text.
        }

        return raw
          .split(/\r?\n/)
          .map((item) => item.trim())
          .filter(Boolean);
      }

      function collectVoiceCommandsFromUi() {
        const enabled = normalizeVoiceCommandEnabled(
          document.getElementById("voiceCommandEnableSelect")?.value || "",
        );
        const commands = Array.from(
          document.querySelectorAll("#voiceCommandList .voice-command-input"),
        )
          .map((input) => input.value.trim())
          .filter(Boolean);

        return {
          enabled,
          commands: enabled === "Yes" ? commands : [],
        };
      }

      function updateVoiceCommandCount() {
        const count = Array.from(
          document.querySelectorAll("#voiceCommandList .voice-command-input"),
        ).filter((input) => input.value.trim()).length;
        const target = document.getElementById("voiceCommandCount");
        if (target) {
          target.textContent = `${count} voice command${count === 1 ? "" : "s"}`;
        }
      }

      function addVoiceCommandInput(value = "", focusInput = false) {
        const list = document.getElementById("voiceCommandList");
        if (!list) return;

        const row = document.createElement("div");
        row.className = "voice-command-input-row";

        const input = document.createElement("input");
        input.type = "text";
        input.className = "voice-command-input";
        input.placeholder = "e.g. Turn on the fan";
        input.value = String(value ?? "");
        input.autocomplete = "off";
        input.setAttribute("aria-label", "Voice command phrase");

        const remove = document.createElement("button");
        remove.type = "button";
        remove.className = "voice-command-remove";
        remove.title = "Remove voice command";
        remove.setAttribute("aria-label", "Remove voice command");
        remove.innerHTML = '<i class="fas fa-trash-can" aria-hidden="true"></i>';

        input.addEventListener("input", () => {
          updateVoiceCommandCount();
          updateRequiredDropdownWarnings(showSetupWarnings);
          if (typeof markConfigurationUnsaved === "function") {
            markConfigurationUnsaved();
          }
        });

        remove.addEventListener("click", () => {
          row.remove();
          if (!list.querySelector(".voice-command-input")) {
            addVoiceCommandInput("", true);
          }
          updateVoiceCommandCount();
          updateRequiredDropdownWarnings(showSetupWarnings);
          if (typeof markConfigurationUnsaved === "function") {
            markConfigurationUnsaved();
          }
        });

        row.append(input, remove);
        list.appendChild(row);
        updateVoiceCommandCount();
        if (focusInput) input.focus();
      }

      function renderVoiceCommandUiFromStore(store) {
        const select = document.getElementById("voiceCommandEnableSelect");
        const editor = document.getElementById("voiceCommandEditor");
        const list = document.getElementById("voiceCommandList");
        if (!select || !editor || !list) return;

        const commands = normalizeVoiceCommandList(store?.voiceCommands || []);
        const enabled = normalizeVoiceCommandEnabled(
          store?.voiceCommandEnabled,
          commands,
        );

        select.value = enabled;
        editor.hidden = enabled !== "Yes";
        list.replaceChildren();

        if (enabled === "Yes") {
          (commands.length ? commands : [""]).forEach((command) =>
            addVoiceCommandInput(command),
          );
        }
        updateVoiceCommandCount();
      }

      function syncVoiceCommandVisibility() {
        const select = document.getElementById("voiceCommandEnableSelect");
        const editor = document.getElementById("voiceCommandEditor");
        const list = document.getElementById("voiceCommandList");
        if (!select || !editor || !list) return;

        const enabled = normalizeVoiceCommandEnabled(select.value);
        editor.hidden = enabled !== "Yes";

        if (enabled === "Yes" && !list.querySelector(".voice-command-input")) {
          addVoiceCommandInput("");
        }

        if (enabled !== "Yes") {
          list.replaceChildren();
        }
        updateVoiceCommandCount();
      }

      function saveActiveFrameTypeStore() {
        const store = frameTypeStores[activeFrameType];
        if (!store) return;

        /*
         * EDIT DELETE FIX
         * ---------------
         * switchFrameType() calls this function while leaving the old editor.
         * If the user has just removed the active frame type, do not copy its
         * old frame count/arrays back into frameTypeStores.
         */
        if (!isFrameTypeIncluded(activeFrameType)) {
          frameTypeStores[activeFrameType] = createEmptyFrameTypeStore();
          return;
        }

        store.count =
          parseInt(document.getElementById("cmdFrameCountInput")?.value, 10) ||
          frameCodes.length ||
          0;
        store.frameCodes = frameCodes;
        store.frameValueGroups = frameValueGroups;
        store.fieldDescriptions = fieldDescriptions;
        store.byteDescriptions = byteDescriptions;
        store.fieldViewModes = fieldViewModes;
        store.framePartitionStates = framePartitionStates;
        store.frameConfigurations = frameConfigurations;
        const voiceState = collectVoiceCommandsFromUi();
        store.voiceCommandEnabled = voiceState.enabled;
        store.voiceCommands = voiceState.commands;

        if (isCommandGetStatusCommandLocked(activeFrameType)) {
          enforceCommandGetStatusCommandState(true);
        }
      }

      function loadFrameTypeStore(frameType) {
        if (isCommandGetStatusCommandLocked(frameType)) {
          enforceCommandGetStatusCommandState(false);
        }
        const store = frameTypeStores[frameType] || createEmptyFrameTypeStore();
        frameCodes = store.frameCodes || [];
        frameValueGroups = store.frameValueGroups || [];
        fieldDescriptions = store.fieldDescriptions || {};
        byteDescriptions = store.byteDescriptions || {};
        fieldViewModes = store.fieldViewModes || {};
        framePartitionStates = store.framePartitionStates || [];
        frameConfigurations = store.frameConfigurations || [];
        document.getElementById("cmdFrameCountInput").value = store.count || 0;
        renderVoiceCommandUiFromStore(store);
        syncCommandGetStatusLockUi();
      }

      function getFrameTypeFillStatus(frameType) {
        const store = frameTypeStores[frameType] || createEmptyFrameTypeStore();
        const count = Math.max(
          0,
          Number(store.count) || store.frameCodes?.length || 0,
        );
        let hasEnteredData = false;
        let completedFrames = 0;

        for (let index = 0; index < count; index++) {
          const partition = store.framePartitionStates?.[index] || {};
          const configuration = store.frameConfigurations?.[index] || {};
          const code = String(
            store.frameCodes?.[index] || partition.fullApiValue || "",
          ).trim();
          const labels = partition.partitionLabels || {};
          const fieldConfigurations =
            partition.partitionFieldConfigurations || {};
          const hasPartitionData =
            Object.keys(labels).length > 0 ||
            Object.keys(fieldConfigurations).length > 0;
          const partitionReady =
            Boolean(partition.partitionsConfirmed) ||
            (Boolean(code) &&
              Object.keys(labels).length > 0 &&
              Object.values(labels).every(Boolean) &&
              Object.keys(fieldConfigurations).length > 0);

          if (
            code ||
            configuration.dataFlowDirection ||
            configuration.multipleUi ||
            hasPartitionData
          ) {
            hasEnteredData = true;
          }

          if (
            code &&
            configuration.dataFlowDirection &&
            configuration.multipleUi &&
            partitionReady
          ) {
            completedFrames++;
          }
        }

        if (count > 0 && completedFrames === count) return "completed";
        if (hasEnteredData) return "in-progress";
        return "pending";
      }

      function updateFlowStageFillState(stage) {
        const frameType = stage.dataset.flowFrameType;
        const status = getFrameTypeFillStatus(frameType);
        const number = stage.querySelector(".flow-stage-number");
        const statusText = stage.querySelector(".flow-stage-status");
        const stepNumber = number?.dataset.stepNumber || "";

        stage.classList.toggle("completed", status === "completed");
        stage.classList.toggle("in-progress", status === "in-progress");
        stage.dataset.fillStatus = status;

        if (number) {
          number.innerHTML =
            status === "completed"
              ? '<i class="fas fa-check" aria-hidden="true"></i>'
              : stepNumber;
        }
        if (statusText) {
          statusText.innerHTML =
            status === "completed"
              ? '<i class="fas fa-circle-check"></i> Filled'
              : status === "in-progress"
                ? '<i class="fas fa-pen"></i> In progress'
                : '<i class="fas fa-circle"></i> Not filled';
        }
        stage.setAttribute(
          "aria-label",
          `${FRAME_TYPE_LABELS[frameType]}: ${
            status === "completed"
              ? "filled"
              : status === "in-progress"
                ? "in progress"
                : "not filled"
          }`,
        );
      }

      function updateFrameTypeUi() {
        const label = getActiveFrameLabel();
        document.getElementById("parameterSetupTitle").innerHTML =
          `<i class="fas fa-sliders-h"></i> Parameter & ${label} Setup`;
        document
        .getElementById("cmdFrameCountInput")
        ?.addEventListener("input", function () {
          const numericCount = Math.max(0, Number(this.value) || 0);

          if (numericCount > 0) {
            this.closest(".input-with-icon")?.classList.remove("input-error");
            this.setAttribute("aria-invalid", "false");

            document
              .querySelector(
                `.frame-choice-card[data-frame-choice="${activeFrameType}"]`,
              )
              ?.classList.remove("selected-frame-incomplete");
          }
        });

      document.querySelectorAll(".frame-type-btn").forEach((button) => {
          const isActive = button.dataset.frameType === activeFrameType;
          button.classList.toggle("active", isActive);
          button.setAttribute("aria-selected", String(isActive));
        });
        document
          .querySelectorAll("[data-flow-frame-type]")
          .forEach((stage) => {
            const isActive =
              stage.dataset.flowFrameType === activeFrameType;
            stage.classList.toggle("active", isActive);
            stage.setAttribute("aria-selected", String(isActive));
            updateFlowStageFillState(stage);
          });
        document.getElementById("generateFramesBtn").innerHTML =
          `<i class="fas fa-sync-alt"></i> Generate ${label} Frames`;
        document.getElementById("activeFramesTitle").textContent =
          `${label.toUpperCase()} FRAMES`;
        document.getElementById("addFrameButtonText").textContent =
          `Add ${label} Frame`;
        document.getElementById("addCommandFrameBtn").title =
          `Add a new ${label.toLowerCase()} frame`;
        document.getElementById("activeFrameHelp").innerHTML =
          `<i class="fas fa-hand-pointer"></i> Click a ${label} Frame card to open Step 2 and enter its full API.`;
        document.getElementById("partitionStepFrameName").textContent =
          `${label} Frame`;
        document.getElementById("popupFrameName").textContent =
          `${label} Frame 1`;
        const fieldDescFrameSelectLabel = document.getElementById(
          "fieldDescFrameSelectLabel",
        );
        if (fieldDescFrameSelectLabel) {
          fieldDescFrameSelectLabel.textContent = `${label} Frame`;
        }
        // The compact modal uses the top flow buttons and intentionally
        // omits the optional second-row count badges.
        const commandTypeCount = document.getElementById("commandTypeCount");
        const responseTypeCount =
          document.getElementById("responseTypeCount");
        const errorTypeCount = document.getElementById("errorTypeCount");
        if (commandTypeCount) {
          commandTypeCount.textContent = frameTypeStores.command.count || 0;
        }
        if (responseTypeCount) {
          responseTypeCount.textContent = frameTypeStores.response.count || 0;
        }
        if (errorTypeCount) {
          errorTypeCount.textContent = frameTypeStores.error.count || 0;
        }

        const frameCountHintText =
          document.getElementById("frameCountSetupHintText");

        if (frameCountHintText) {
          frameCountHintText.textContent =
            `Enter 1 or more only when you want to create ${getActiveFrameLabel().toLowerCase()} frames.`;
        }

        syncFrameInclusionUi();
        syncCommandGetStatusLockUi();
      }

      function switchFrameType(nextType, revealFullEditor = false) {
        if (!FRAME_TYPE_LABELS[nextType]) return;
        if (!isFrameTypeIncluded(nextType)) return;
        captureActiveFramePartitionState();
        saveActiveFrameTypeStore();
        activeFrameType = nextType;
        loadFrameTypeStore(nextType);
        selectedFrameIndex = null;
        activePartitionFrameIndex = null;
        fullApiValue = "00";
        hexEditorDraftBytes = ["00"];
        hexEditorDraftIsIncomplete = false;
        restoredByteCount = 1;
        partitionCuts = [];
        partitionLabels = {};
        partitionViewModes = {};
        partitionFieldConfigurations = {};
        selectedBitGroups = {};
        partitionsConfirmed = false;
        document.getElementById("fullApiInput").value = "00";
        document.getElementById("byteDetailPopup").style.display = "none";
        document
          .getElementById("apiPartitionSection")
          .classList.remove("frame-partition-active");
        const framesContainer = document.getElementById(
          "commandFramesContainer",
        );
        framesContainer.replaceChildren();
        framesContainer.dataset.visibleFrameType = nextType;
        framesContainer.setAttribute(
          "aria-label",
          `${FRAME_TYPE_LABELS[nextType]} frames only`,
        );
        updateFrameTypeUi();
        const count = frameTypeStores[nextType].count || 0;
        if (count > 0) {
          generateCommandFrames(count, true);

          /*
           * Command, Response and Error share the same complete partition
           * workspace.  Previously a type switch rendered its frame cards but
           * left that workspace hidden until the user clicked a card.  Reveal
           * the first frame immediately so every flow tab displays the full
           * page and restores its saved partition/field configuration.
           */
          const firstConfiguredFrame = framePartitionStates.findIndex(
            (state, index) =>
              Boolean(
                frameCodes[index] ||
                state?.fullApiValue ||
                state?.partitionCuts?.length ||
                Object.keys(state?.partitionLabels || {}).length ||
                Object.keys(
                  state?.partitionFieldConfigurations || {},
                ).length,
              ),
          );
          const frameIndex =
            firstConfiguredFrame >= 0 ? firstConfiguredFrame : 0;

          activePartitionFrameIndex = frameIndex;
          selectedFrameIndex = frameIndex;
          loadFramePartitionState(frameIndex);

          const partitionSection =
            document.getElementById("apiPartitionSection");
          partitionSection?.classList.add("frame-partition-active");
          document
            .querySelectorAll(
              "#commandFramesContainer .command-frame-card",
            )
            .forEach((card, index) => {
              card.classList.toggle("selected", index === frameIndex);
            });

          const fieldFrameSelect =
            document.getElementById("fieldDescFrameSelect");
          if (
            fieldFrameSelect?.querySelector(
              `option[value="${frameIndex}"]`,
            )
          ) {
            fieldFrameSelect.value = String(frameIndex);
          }
          renderFieldDescription();

          if (revealFullEditor && partitionSection) {
            partitionSection.classList.add("section-highlight");
            partitionSection.scrollIntoView({
              behavior: "smooth",
              block: "start",
            });
            setTimeout(
              () =>
                partitionSection.classList.remove("section-highlight"),
              1200,
            );
          }
        } else {
          updateCommandFrameCount();
          updateFieldDescFrameSelect();
          renderFieldDescription();
        }
        renderApiPartitionEditor();
      }

