      ]);

      // Display and Toast Display use the same As Per UI + UI Values
      // configuration fields, but have their own live preview card.
      const DISPLAY_TOAST_UI_TYPES = new Set([
        "display",
        "toast display",
      ]);

      const UI_TYPE_VALUES_ENDPOINT = <?= json_encode(site_url("items/get_ui_type_auto_values")) ?>;
      const UI_TYPE_MODEL_NAME = <?= json_encode($modelValue, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>;
      const UI_TYPE_ITEM_ID = <?= (int) $itemId ?>;
      let uiTypeLookupRequestId = 0;

      function clearUiTypeBackendInputs() {
        const asperUiInput = document.getElementById("fAsperUi");
        const toggleAsperUiSelect = document.getElementById("fToggleAsperUi");
        const toggleCustomAsperUiInput = document.getElementById("fToggleCustomAsperUiInput");
        const toggleCustomAsperUiBtn = document.getElementById("fToggleCustomAsperUiBtn");
        const toggleAsperUiControlRow = document.getElementById("toggleAsperUiControlRow");
        const serialNoInput = document.getElementById("fUiSerialNo");
        const uiValuesInput = document.getElementById("fUiValues");
        const dropdownUiValuesHint = document.getElementById("dropdownUiValuesHint");

        if (asperUiInput) asperUiInput.value = "";
        if (toggleAsperUiSelect) {
          toggleAsperUiSelect.value = "";
          toggleAsperUiSelect.hidden = false;
        }
        if (toggleCustomAsperUiInput) {
          toggleCustomAsperUiInput.value = "";
          toggleCustomAsperUiInput.hidden = true;
        }
        if (toggleCustomAsperUiBtn) {
          toggleCustomAsperUiBtn.classList.remove("is-active");
          toggleCustomAsperUiBtn.setAttribute("aria-pressed", "false");
          const label = toggleCustomAsperUiBtn.querySelector("span");
          if (label) label.textContent = "Custom";
        }
        if (toggleAsperUiControlRow) toggleAsperUiControlRow.hidden = true;
        if (serialNoInput) serialNoInput.value = "";
        if (uiValuesInput) {
          uiValuesInput.value = "";
          delete uiValuesInput.dataset.messageInitialRestoreDone;
          uiValuesInput.hidden = false;
          uiValuesInput.removeAttribute("aria-hidden");
        }
        if (dropdownUiValuesHint) dropdownUiValuesHint.hidden = true;
      }

      function setUiTypeBackendLoading(isLoading) {
        ["fAsperUi", "fUiSerialNo"].forEach((id) => {
          const input = document.getElementById(id);
          if (!input) return;
          input.readOnly = true;
          input.classList.toggle("backend-value-loading", isLoading);
          input.setAttribute("aria-busy", isLoading ? "true" : "false");
        });

        const toggleAsperUiSelect = document.getElementById("fToggleAsperUi");
        if (toggleAsperUiSelect) {
          toggleAsperUiSelect.disabled = isLoading;
          toggleAsperUiSelect.classList.toggle("backend-value-loading", isLoading);
          toggleAsperUiSelect.setAttribute("aria-busy", isLoading ? "true" : "false");
        }

        const toggleCustomAsperUiInput = document.getElementById("fToggleCustomAsperUiInput");
        if (toggleCustomAsperUiInput) {
          toggleCustomAsperUiInput.disabled = isLoading;
          toggleCustomAsperUiInput.classList.toggle("backend-value-loading", isLoading);
          toggleCustomAsperUiInput.setAttribute("aria-busy", isLoading ? "true" : "false");
        }

        const toggleCustomAsperUiBtn = document.getElementById("fToggleCustomAsperUiBtn");
        if (toggleCustomAsperUiBtn) toggleCustomAsperUiBtn.disabled = isLoading;

        // UI Values may receive an automatic starting value, but the user
        // must always be able to edit/replace it.
        const uiValuesInput = document.getElementById("fUiValues");
        if (uiValuesInput) {
          uiValuesInput.readOnly = false;
          uiValuesInput.classList.toggle("backend-value-loading", isLoading);
          uiValuesInput.setAttribute("aria-busy", isLoading ? "true" : "false");
        }
      }

      // UI-only compatibility bridge copied from the OLD working form.
      // It restores the automatic field defaults without changing the NEW UI.
      function getOldFormUiTypeDefaults(uiType) {
        const normalizedType = String(uiType || "none")
          .trim()
          .toLowerCase();

        if (!normalizedType || normalizedType === "none") {
          return {
            dataType: "",
            valueDef: "",
            asperui: "",
            sno_asperui: "",
            asperuivalue: "",
          };
        }

        if (normalizedType === "toggle switch") {
          return {
            dataType: "UnsignedInt",
            valueDef: "Fixed Value",
            asperui: "false,true",
            sno_asperui: "1",
            asperuivalue: "00,01",
          };
        }

        if (normalizedType === "button") {
          return {
            dataType: "",
            valueDef: "",
            // Button now uses the same Preset Names + Functioning Names
            // configuration as Toggle Switch.
            asperui: "false,true",
            sno_asperui: "1",
            asperuivalue: "00,01",
          };
        }

        if (normalizedType === "push button") {
          return {
            dataType: "",
            valueDef: "",
            // Push Button shows only Preset Names in the UI Configuration popup.
            // Keep the existing hidden UI value compatibility default.
            asperui: "false,true",
            sno_asperui: "1",
            asperuivalue: "1",
          };
        }

        if (normalizedType === "dropdown") {
          return {
            dataType: "UnsignedInt",
            valueDef: "Fixed Value",
            asperui: "",
            sno_asperui: "1",
            asperuivalue: "",
          };
        }

        if (MESSAGE_UI_TYPES.has(normalizedType)) {
          return {
            dataType: "",
            valueDef: "",
            asperui: "1",
            sno_asperui: "1",
            // Message-style UIs are entered by the user in UI Values.
            asperuivalue: "",
          };
        }

        if (DISPLAY_TOAST_UI_TYPES.has(normalizedType)) {
          return {
            dataType: "",
            valueDef: "",
            asperui: "1",
            sno_asperui: "1",
            // Display and Toast Display values are configured by the user.
            asperuivalue: "",
          };
        }

        if (
          normalizedType.includes("slider") ||
          normalizedType === "hue circle" ||
          normalizedType === "auto trigger with timer"
        ) {
          return {
            dataType: "UnsignedInt",
            valueDef: "Range Value",
            asperui: "0,0",
            sno_asperui: "1",
            asperuivalue: "1",
          };
        }

        return {
          dataType: "",
          valueDef: "",
          asperui: "1",
          sno_asperui: "1",
          asperuivalue: "1",
        };
      }

      function assignOldFormUiTypeDefaults(uiType, force = false) {
        const defaults = getOldFormUiTypeDefaults(uiType);
        const dataTypeInput = document.getElementById("fDataType");
        const valueDefInput = document.getElementById("fValueDef");
        const asperUiInput = document.getElementById("fAsperUi");
        const serialNoInput = document.getElementById("fUiSerialNo");
        const uiValuesInput = document.getElementById("fUiValues");

        // Data Type and Value Definition are user selections. Changing UI Type
        // must NEVER clear or overwrite values the user already selected.
        // Old-form defaults are applied only when these fields are still empty.
        if (dataTypeInput && defaults.dataType && !dataTypeInput.value) {
          dataTypeInput.value = defaults.dataType;
        }
        if (valueDefInput && defaults.valueDef && !valueDefInput.value) {
          valueDefInput.value = defaults.valueDef;
        }
        if (asperUiInput && (force || !asperUiInput.value.trim())) {
          asperUiInput.value = defaults.asperui;
        }
        if (serialNoInput && (force || !serialNoInput.value.trim())) {
          serialNoInput.value = defaults.sno_asperui;
        }
        if (uiValuesInput && (force || !uiValuesInput.value.trim())) {
          uiValuesInput.value = defaults.asperuivalue;
        }

        [asperUiInput, serialNoInput].forEach((input) => {
          if (input) {
            input.readOnly = true;
            input.placeholder = "Loaded automatically";
            input.classList.remove("backend-value-loading");
            input.setAttribute("aria-busy", "false");
          }
        });

        if (uiValuesInput) {
          uiValuesInput.readOnly = false;
          uiValuesInput.placeholder = "Enter UI values";
          uiValuesInput.classList.remove("backend-value-loading");
          uiValuesInput.setAttribute("aria-busy", "false");
        }
      }

      async function applyUiTypeAutoValues(uiType, force = false) {
        const normalizedType = String(uiType || "none").trim().toLowerCase();
        const asperUiInput = document.getElementById("fAsperUi");
        const serialNoInput = document.getElementById("fUiSerialNo");
        const uiValuesInput = document.getElementById("fUiValues");

        if (!asperUiInput || !serialNoInput || !uiValuesInput) return;

        // Preserve values restored from an existing database configuration.
        if (
          !force &&
          (
            asperUiInput.value.trim() ||
            serialNoInput.value.trim() ||
            uiValuesInput.value.trim()
          )
        ) {
          return;
        }

        if (!normalizedType || normalizedType === "none") {
          clearUiTypeBackendInputs();
          return;
        }

        // FIRST: restore the exact automatic-value behavior of the OLD form.
        // This requires no controller/model/route changes.
        assignOldFormUiTypeDefaults(normalizedType, force);
      }

      function isSliderUiType(uiType) {
        const normalized = String(uiType || "").trim().toLowerCase();
        return (
          normalized.includes("slider") ||
          normalized === "hue circle" ||
          normalized === "auto trigger with timer"
        );
      }

      function isHueCircleUiType(uiType) {
        return String(uiType || "").trim().toLowerCase() === "hue circle";
      }

      function isAutoTimerUiType(uiType) {
        return String(uiType || "").trim().toLowerCase() === "auto trigger with timer";
      }

      function isButtonUiType(uiType) {
        const normalized = String(uiType || "").trim().toLowerCase();
        return normalized === "push button" || normalized === "button";
      }

      function isStandardButtonUiType(uiType) {
        return String(uiType || "").trim().toLowerCase() === "button";
      }

      function isPushButtonUiType(uiType) {
        return String(uiType || "").trim().toLowerCase() === "push button";
      }

      function usesPresetNamesUiType(uiType) {
        return (
          isToggleUiType(uiType) ||
          isStandardButtonUiType(uiType) ||
          isPushButtonUiType(uiType)
        );
      }

      function isDropdownUiType(uiType) {
        return String(uiType || "").trim().toLowerCase() === "dropdown";
      }

      function isMessagePreviewUiType(uiType) {
        return MESSAGE_UI_TYPES.has(String(uiType || "").trim().toLowerCase());
      }

      function isDisplayUiType(uiType) {
        return String(uiType || "").trim().toLowerCase() === "display";
      }

      function isToastDisplayUiType(uiType) {
        return String(uiType || "").trim().toLowerCase() === "toast display";
      }

      function isDisplayToastUiType(uiType) {
        return DISPLAY_TOAST_UI_TYPES.has(String(uiType || "").trim().toLowerCase());
      }

      function getUiTypeOption(uiType) {
        const normalized = String(uiType || "none").trim().toLowerCase();
        return UI_TYPE_OPTIONS.find((option) => option.value === normalized) || UI_TYPE_OPTIONS[0];
      }

      function clearUiConfigurationWarning() {
        const warning = document.getElementById("uiConfigWarning");
        if (!warning) return;
        warning.hidden = true;
        warning.innerHTML = "";
        document
          .querySelectorAll("#uiConfigurationModal .form-group.field-invalid")
          .forEach((group) => group.classList.remove("field-invalid"));
        document
          .querySelectorAll('#uiConfigurationModal [aria-invalid="true"]')
          .forEach((control) => control.setAttribute("aria-invalid", "false"));
      }

