      function formatSliderPreviewValue(value, theme) {
        const numberValue = Number(value);
        if (!Number.isFinite(numberValue)) return "—";

        const rounded = Number.isInteger(numberValue)
          ? String(numberValue)
          : String(Number(numberValue.toFixed(2)));

        return `${rounded}${theme.unit || ""}`;
      }

      function applySliderPreviewTheme(uiType) {
        const card = document.getElementById("uiSliderPreviewCard");
        const title = document.getElementById("uiSliderPreviewTitle");
        const icon = document.querySelector("#uiSliderPreviewIcon i");
        const leftLabel = document.getElementById("uiSliderPreviewLeftLabel");
        const rightLabel = document.getElementById("uiSliderPreviewRightLabel");

        const theme = getSliderPreviewTheme(uiType);

        if (card) {
          card.style.setProperty("--slider-track", theme.track);
          card.style.setProperty("--slider-thumb", theme.thumb);
          card.style.setProperty("--slider-accent", theme.accent);
          card.style.setProperty("--slider-icon-bg", theme.iconBg);
          card.style.setProperty("--slider-icon-color", theme.iconColor);
        }

        if (title) title.textContent = theme.title;
        if (icon) icon.className = `fas ${theme.icon}`;
        if (leftLabel) leftLabel.textContent = theme.left;
        if (rightLabel) rightLabel.textContent = theme.right;

        return theme;
      }

      function renderSliderUiLiveDemo() {
        const uiType = document.getElementById("fUiType")?.value || "";
        if (!isSliderUiType(uiType)) return;

        const minInput = document.getElementById("fDisplayMin");
        const maxInput = document.getElementById("fDisplayMax");
        const stepInput = document.getElementById("fSliderStep");
        const scalingInput = document.getElementById("fScalling");
        const preview = document.getElementById("uiSliderPreview");
        if (!preview) return;

        const timerMode = isAutoTimerUiType(uiType);
        const parsedMin = Number(minInput?.value);
        const parsedMax = Number(maxInput?.value);
        const parsedStep = Number(stepInput?.value);

        const min = String(minInput?.value ?? "").trim() !== "" && Number.isFinite(parsedMin)
          ? parsedMin
          : 0;
        let max = String(maxInput?.value ?? "").trim() !== "" && Number.isFinite(parsedMax)
          ? parsedMax
          : (timerMode ? 255 : 100);
        if (max <= min) max = min + (timerMode ? 255 : 100);

        const step = Number.isFinite(parsedStep) && parsedStep > 0 ? parsedStep : 1;
        const previousValue = Number(preview.value);
        const fallbackValue = timerMode ? min : min + (max - min) / 2;
        const nextValue = Number.isFinite(previousValue)
          ? Math.min(max, Math.max(min, previousValue))
          : fallbackValue;

        preview.min = String(min);
        preview.max = String(max);
        preview.step = String(step);
        preview.value = String(nextValue);

        const sliderCard = document.getElementById("uiSliderPreviewCard");
        const hueCircleCard = document.getElementById("uiHueCirclePreviewCard");
        const timerCard = document.getElementById("uiAutoTimerPreviewCard");
        const hueCircleMode = isHueCircleUiType(uiType);

        if (sliderCard) sliderCard.hidden = hueCircleMode || timerMode;
        if (hueCircleCard) hueCircleCard.hidden = !hueCircleMode;
        if (timerCard) timerCard.hidden = !timerMode;

        if (timerMode) {
          const timerPreview = document.getElementById("uiAutoTimerPreview");
          const timerPrevious = Number(timerPreview?.value);
          const timerCurrent = Number.isFinite(timerPrevious)
            ? Math.min(max, Math.max(min, timerPrevious))
            : min;

          if (timerPreview) {
            timerPreview.min = String(min);
            timerPreview.max = String(max);
            timerPreview.step = String(step);
            timerPreview.value = String(timerCurrent);
          }
          preview.value = String(timerCurrent);

          const formatSeconds = (value) => {
            const n = Number(value);
            const clean = Number.isInteger(n) ? String(n) : String(Number(n.toFixed(2)));
            return `${clean}s`;
          };

          const headerValue = document.getElementById("uiAutoTimerHeaderValue");
          const currentValue = document.getElementById("uiAutoTimerCurrentValue");
          const minLabel = document.getElementById("uiAutoTimerMinLabel");
          const maxLabel = document.getElementById("uiAutoTimerMaxLabel");
          const minMeta = document.getElementById("uiAutoTimerMin");
          const maxMeta = document.getElementById("uiAutoTimerMax");
          const stepMeta = document.getElementById("uiAutoTimerStep");
          const scalingMeta = document.getElementById("uiAutoTimerScaling");

          if (headerValue) headerValue.textContent = formatSeconds(timerCurrent);
          if (currentValue) currentValue.textContent = formatSeconds(timerCurrent);
          if (minLabel) minLabel.textContent = formatSeconds(min);
          if (maxLabel) maxLabel.textContent = formatSeconds(max);
          if (minMeta) minMeta.textContent = String(min);
          if (maxMeta) maxMeta.textContent = String(max);
          if (stepMeta) stepMeta.textContent = String(step);
          if (scalingMeta) scalingMeta.textContent = String(scalingInput?.value || "").trim() || "—";
          return;
        }

        if (hueCircleMode) {
          const current = Number(preview.value);
          const safeCurrent = Number.isFinite(current) ? current : fallbackValue;
          const ratio = max > min ? Math.min(1, Math.max(0, (safeCurrent - min) / (max - min))) : 0;
          // SVG circle angles are measured from the 3 o'clock axis.
          // The needle artwork itself points upward at rotate(0deg), therefore
          // it needs a +90deg visual offset to point at the exact same location
          // as the clicked/dragged point on the SVG arc.
          const startAngle = 135;
          const sweepAngle = 281;
          const arcAngle = startAngle + (ratio * sweepAngle);
          const needleAngle = arcAngle + 90;
          const arcLength = 402;
          const circumference = 515.22;
          const activeArc = Math.max(0.01, arcLength * ratio);

          const gauge = document.getElementById("uiHueCircleGauge");
          const progress = document.getElementById("uiHueCircleProgress");
          const headerValue = document.getElementById("uiHueCircleHeaderValue");
          const currentValue = document.getElementById("uiHueCircleCurrentValue");
          const maxValue = document.getElementById("uiHueCircleMaxValue");
          const minMeta = document.getElementById("uiHueCircleMin");
          const maxMeta = document.getElementById("uiHueCircleMax");
          const stepMeta = document.getElementById("uiHueCircleStep");
          const scalingMeta = document.getElementById("uiHueCircleScaling");

          const formattedCurrent = Number.isInteger(safeCurrent)
            ? String(safeCurrent)
            : String(Number(safeCurrent.toFixed(2)));
          const formattedMax = Number.isInteger(max)
            ? String(max)
            : String(Number(max.toFixed(2)));

          if (gauge) {
            gauge.style.setProperty("--hue-circle-angle", `${needleAngle}deg`);
            gauge.setAttribute("aria-valuemin", String(min));
            gauge.setAttribute("aria-valuemax", String(max));
            gauge.setAttribute("aria-valuenow", String(safeCurrent));
          }
          if (progress) progress.style.strokeDasharray = `${activeArc} ${circumference}`;
          if (headerValue) headerValue.textContent = formattedCurrent;
          if (currentValue) currentValue.textContent = formattedCurrent;
          if (maxValue) maxValue.textContent = formattedMax;
          if (minMeta) minMeta.textContent = String(min);
          if (maxMeta) maxMeta.textContent = String(max);
          if (stepMeta) stepMeta.textContent = String(step);
          if (scalingMeta) scalingMeta.textContent = String(scalingInput?.value || "").trim() || "—";
          return;
        }

        const theme = applySliderPreviewTheme(uiType);
        const valueEl = document.getElementById("uiSliderPreviewValue");
        const minEl = document.getElementById("uiSliderPreviewMin");
        const maxEl = document.getElementById("uiSliderPreviewMax");
        const stepEl = document.getElementById("uiSliderPreviewStep");
        const scalingEl = document.getElementById("uiSliderPreviewScaling");
        const leftLabel = document.getElementById("uiSliderPreviewLeftLabel");
        const rightLabel = document.getElementById("uiSliderPreviewRightLabel");

        if (valueEl) valueEl.textContent = formatSliderPreviewValue(preview.value, theme);
        if (minEl) minEl.textContent = String(min);
        if (maxEl) maxEl.textContent = String(max);
        if (stepEl) stepEl.textContent = String(step);
        if (scalingEl) scalingEl.textContent = String(scalingInput?.value || "").trim() || "—";

        if (theme.fixedEdges) {
          if (leftLabel) leftLabel.textContent = "0°";
          if (rightLabel) rightLabel.textContent = "360°";
        }
      }

      function getButtonPreviewValue() {
        const rawValue = String(document.getElementById("fUiValues")?.value || "").trim();
        if (!rawValue) return "—";
        return rawValue.split(",")[0].trim() || rawValue;
      }

      function getPresetNamesReady(value) {
        return Boolean(
          getTogglePresetAsperUiValue(value) ||
          getToggleCustomAsperUiPair(value).ready
        );
      }

      function renderButtonUiLiveDemo(resetOutput = false) {
        const uiType = String(document.getElementById("fUiType")?.value || "")
          .trim()
          .toLowerCase();
        const demo = document.getElementById("buttonLiveDemo");
        if (!demo) return;

        const isButtonType = isButtonUiType(uiType);
        const toggleDemo = document.getElementById("toggleLiveDemo");
        demo.hidden = !isButtonType;

        // Button / Push Button configuration must not keep a stale Toggle preview.
        if (toggleDemo && isButtonType) toggleDemo.hidden = true;
        if (!isButtonType) return;

        const isPushButton = isPushButtonUiType(uiType);
        const isButton = isStandardButtonUiType(uiType);
        const previewControl = document.getElementById("buttonPreviewControl");
        const previewLabel = document.getElementById("buttonPreviewLabel");
        const previewState = document.getElementById("buttonPreviewState");
        const previewTitle = document.getElementById("buttonPreviewTitle");
        const previewBadge = document.getElementById("buttonPreviewTypeBadge");
        const previewIcon = document.getElementById("buttonPreviewIcon");
        const output = document.getElementById("buttonPreviewCurrentValue");
        const help = document.getElementById("buttonPreviewHelp");
        const asperUiValue = String(document.getElementById("fAsperUi")?.value || "").trim();
        const style = getToggleAsperUiStyle(asperUiValue || "false,true");
        const presetReady = getPresetNamesReady(asperUiValue);
        const pair = getToggleLiveValuePair(
          document.getElementById("fUiValues")?.value || ""
        );

        if (resetOutput) {
          buttonLiveDemoState = false;
        }

        if (previewControl) {
          previewControl.classList.toggle("push-button-preview", isPushButton);
          previewControl.classList.remove("is-pressed");
          previewControl.classList.toggle(
            "is-on",
            isButton && pair.ready && buttonLiveDemoState
          );
          previewControl.setAttribute(
            "aria-pressed",
            isButton && pair.ready && buttonLiveDemoState ? "true" : "false"
          );
          previewControl.disabled = isPushButton
            ? !presetReady
            : (!presetReady || !pair.ready);
        }

        if (previewTitle) {
          previewTitle.textContent = isPushButton ? "Preview Push Button" : "Preview Button";
        }

        if (previewBadge) {
          previewBadge.textContent = isPushButton ? "PUSH BUTTON" : "BUTTON";
        }

        if (previewLabel) {
          previewLabel.textContent = isPushButton ? "PUSH BUTTON" : "BUTTON";
        }

        if (previewIcon) {
          previewIcon.className = isPushButton ? "fas fa-hand-pointer" : "fas fa-power-off";
        }

        if (isPushButton) {
          if (previewState) previewState.textContent = presetReady ? "READY" : "SELECT PRESET";
          if (resetOutput && output) output.textContent = "—";
          if (help) {
            help.innerHTML = presetReady
              ? `<i class="fas fa-circle-check"></i><span>Press and release the Push Button preview. Push Button uses Preset Names only; no Functioning Names are required.</span>`
              : '<i class="fas fa-circle-info"></i><span>Select Preset Names above to enable the Push Button preview.</span>';
          }
          return;
        }

        // Normal Button is a two-state/latching control, not a momentary Push Button.
        // Each click changes to the other configured Functioning Name and keeps that state.
        if (!presetReady) {
          if (previewState) previewState.textContent = "SELECT PRESET";
          if (output) output.textContent = "—";
          if (help) {
            help.innerHTML = '<i class="fas fa-circle-info"></i><span>Select Preset Names above to enable the Button preview.</span>';
          }
          return;
        }

        if (!pair.ready) {
          if (previewState) previewState.textContent = "ENTER TWO VALUES";
          if (output) output.textContent = "—";
          if (help) {
            help.innerHTML = '<i class="fas fa-circle-info"></i><span>Enter exactly two Functioning Names, for example 01,02, to enable the Button preview.</span>';
          }
          return;
        }

        const activeValue = buttonLiveDemoState ? pair.trueValue : pair.falseValue;
        const activeLabel = buttonLiveDemoState ? style.trueLabel : style.falseLabel;
        if (previewState) previewState.textContent = activeLabel;
        if (output) output.textContent = activeValue;
        if (help) {
          help.innerHTML = `<i class="fas fa-circle-check"></i><span><strong>${pair.falseValue}</strong> = ${style.falseLabel} &nbsp;•&nbsp; <strong>${pair.trueValue}</strong> = ${style.trueLabel}. Click the Button once to change state; click again to change back.</span>`;
        }
      }

      function escapeDropdownHtml(value) {
        return String(value ?? "")
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#039;");
      }

      function parseDropdownCsv(value) {
        return String(value ?? "")
          .split(",")
          .map((item) => item.trim())
          .filter((item) => item !== "");
      }

      function getDropdownUiCount(value) {
        const raw = String(value ?? "").trim();
        if (!raw) return 0;

        // New format requested by the UI:
        //   As Per UI = 3  -> value numbers 1, 2, 3.
        if (/^\d+$/.test(raw)) {
          const count = Number.parseInt(raw, 10);
          return Number.isFinite(count) && count > 0 ? count : 0;
        }

        // Backward compatibility for old saved rows that may contain 1,2,3.
        return parseDropdownCsv(raw).length;
      }

      function getDropdownUiKeys() {
        const raw = String(document.getElementById("fAsperUi")?.value || "").trim();
        if (!raw) return [];

        if (/^\d+$/.test(raw)) {
          const count = getDropdownUiCount(raw);
          return Array.from({ length: count }, (_, index) => String(index + 1));
        }

        // Legacy saved values continue to render correctly while editing.
        return parseDropdownCsv(raw);
      }

      function getDropdownUiLabels() {
        const raw = String(document.getElementById("fUiValues")?.value || "");
        if (raw === "") return [];
        return raw.split(",").map((item) => String(item || "").trim());
      }

      function getDropdownUiMappings() {
        const keys = getDropdownUiKeys();
        const labels = getDropdownUiLabels();

        return keys.map((key, index) => ({
          key,
          label: String(labels[index] || "").trim(),
        }));
      }

      function normalizeDropdownAsperUi(value) {
        const raw = String(value ?? "").trim();
        if (!raw) return "";

        // New entries are a single positive integer count.
        if (/^\d+$/.test(raw)) {
          const count = Number.parseInt(raw, 10);
          return count > 0 ? String(count) : "";
        }

        // Convert an old comma-separated As Per UI value into its count when
        // the user edits it in the new UI.
        const legacyValues = parseDropdownCsv(raw);
        return legacyValues.length ? String(legacyValues.length) : "";
      }

      function setDropdownUiLabels(labels, dispatchInput = false) {
        const uiValuesInput = document.getElementById("fUiValues");
        if (!uiValuesInput) return;

        uiValuesInput.value = labels
          .map((label) => String(label ?? "").replace(/,/g, " ").trim())
          .join(",");

        if (dispatchInput) {
          uiValuesInput.dispatchEvent(new Event("input", { bubbles: true }));
        }
      }

      function ensureDropdownUiLabelSlots() {
        const keys = getDropdownUiKeys();
        if (!keys.length) return [];

        const labels = getDropdownUiLabels().slice(0, keys.length);
        while (labels.length < keys.length) labels.push("");
        setDropdownUiLabels(labels, false);
        return labels;
      }

      function renderDropdownUiValueSummary(activeKey = "") {
        const summary = document.getElementById("dropdownUiValueSummary");
        if (!summary) return;

        const mappings = getDropdownUiMappings();
        summary.innerHTML = mappings
          .map((item) => {
            const active = item.key === activeKey ? " active" : "";
            const empty = item.label ? "" : " empty-value";
            const label = item.label || "Not set";
            return `<button type="button" class="dropdown-ui-map-chip${active}${empty}" data-dropdown-key="${escapeDropdownHtml(item.key)}"><code>${escapeDropdownHtml(item.key)}</code><span>→</span><span>${escapeDropdownHtml(label)}</span></button>`;
          })
          .join("");
      }

      function selectDropdownUiValue(key, focusEditor = false) {
        const selector = document.getElementById("dropdownUiValueIndex");
        const editor = document.getElementById("dropdownUiValueEditor");
        const mappings = getDropdownUiMappings();
        if (!selector || !editor) return;

        const selected = mappings.find((item) => item.key === String(key || ""));
        if (!selected) {
          editor.value = "";
          editor.disabled = true;
          return;
        }

        selector.value = selected.key;
        editor.disabled = false;
        editor.value = selected.label;
        editor.placeholder = `Enter Content for ${selected.key}, e.g. Fan`;
        renderDropdownUiValueSummary(selected.key);
        if (focusEditor) editor.focus();
      }

      function updateSelectedDropdownUiValue() {
        const selector = document.getElementById("dropdownUiValueIndex");
        const editor = document.getElementById("dropdownUiValueEditor");
        if (!selector || !editor || !selector.value) return;

        const keys = getDropdownUiKeys();
        const index = keys.indexOf(selector.value);
        if (index < 0) return;

        const labels = ensureDropdownUiLabelSlots();
        labels[index] = String(editor.value || "").replace(/,/g, " ").trim();
        setDropdownUiLabels(labels, false);
        renderDropdownUiValueSummary(selector.value);
        renderDropdownUiLiveDemo();
      }

      function configureDropdownUiControls(uiType) {
        const isDropdown = isDropdownUiType(uiType);
        const asperUiInput = document.getElementById("fAsperUi");
        const uiValuesInput = document.getElementById("fUiValues");
        const dropdownHint = document.getElementById("dropdownUiValuesHint");
        const inlineEditor = document.getElementById("dropdownInlineUiValues");
        const selector = document.getElementById("dropdownUiValueIndex");
        const editor = document.getElementById("dropdownUiValueEditor");

        if (!asperUiInput || !uiValuesInput) return;

        if (!isDropdown) {
          uiValuesInput.hidden = false;
          uiValuesInput.removeAttribute("aria-hidden");
          if (inlineEditor) inlineEditor.hidden = true;
          if (dropdownHint) dropdownHint.hidden = true;
          asperUiInput.removeAttribute("inputmode");
          asperUiInput.removeAttribute("pattern");
          if (!isToggleUiType(uiType)) asperUiInput.readOnly = true;
          return;
        }

        asperUiInput.hidden = false;
        asperUiInput.readOnly = false;
        asperUiInput.placeholder = "Enter number of contents, e.g. 3";
        asperUiInput.setAttribute("inputmode", "numeric");
        asperUiInput.setAttribute("pattern", "[0-9]*");
        asperUiInput.removeAttribute("aria-busy");
        asperUiInput.classList.remove("backend-value-loading");

        // Keep the real backend field, but use the selector + editor as the
        // user-facing UI Values control for Dropdown.
        uiValuesInput.hidden = true;
        uiValuesInput.setAttribute("aria-hidden", "true");
        uiValuesInput.readOnly = false;
        if (inlineEditor) inlineEditor.hidden = false;

        const keys = getDropdownUiKeys();
        const currentKey = selector?.value || "";

        if (keys.length) {
          ensureDropdownUiLabelSlots();
        }

        if (selector) {
          selector.innerHTML = keys.length
            ? keys.map((key) => `<option value="${escapeDropdownHtml(key)}">${escapeDropdownHtml(key)}</option>`).join("")
            : '<option value="">Enter No. of Contents first</option>';
          selector.disabled = !keys.length;
        }

        if (!keys.length) {
          if (editor) {
            editor.value = "";
            editor.disabled = true;
            editor.placeholder = "Enter No. of Contents first";
          }
          renderDropdownUiValueSummary("");
        } else {
          const nextKey = keys.includes(currentKey) ? currentKey : keys[0];
          selectDropdownUiValue(nextKey, false);
        }

        const count = keys.length;
        if (dropdownHint) {
          dropdownHint.hidden = false;
          dropdownHint.innerHTML = count
            ? `<strong></strong><strong></strong> `
            : '<strong></strong>';
        }

        renderDropdownUiLiveDemo();
      }

      function renderDropdownUiLiveDemo() {
        const uiType = document.getElementById("fUiType")?.value || "";
        const demo = document.getElementById("dropdownLiveDemo");
        const preview = document.getElementById("dropdownPreviewSelect");
        const keyOutput = document.getElementById("dropdownPreviewKey");
        const labelOutput = document.getElementById("dropdownPreviewLabel");
        const help = document.getElementById("dropdownPreviewHelp");
        if (!demo || !preview) return;

        const isDropdown = isDropdownUiType(uiType);
        demo.hidden = !isDropdown;
        if (!isDropdown) return;

        const mappings = getDropdownUiMappings();
        const previousValue = preview.value;
        const ready = mappings.length > 0 && mappings.every((item) => item.label !== "");

        preview.innerHTML = mappings.length
          ? mappings
              .map((item) => `<option value="${escapeDropdownHtml(item.key)}">${escapeDropdownHtml(item.label || `Value ${item.key}`)}</option>`)
              .join("")
          : '<option value="">Configure dropdown values first</option>';
        preview.disabled = !mappings.length;

        if (mappings.some((item) => item.key === previousValue)) {
          preview.value = previousValue;
        } else if (mappings.length) {
          preview.value = mappings[0].key;
        }

        const selected = mappings.find((item) => item.key === preview.value);
        if (keyOutput) keyOutput.textContent = selected?.key || "—";
        if (labelOutput) labelOutput.textContent = selected?.label || "—";

        if (help) {
          help.innerHTML = ready
            ? '<i class="fas fa-circle-check"></i><span>Dropdown preview is ready. Change the selection to test Fan / AC / Phone or your configured values.</span>'
            : '<span></span>';
        }
      }


      function getTextMessageCount(value = null) {
        const raw = String(
          value === null
            ? (document.getElementById("fAsperUi")?.value || "")
            : value
        ).trim();

        if (/^\d+$/.test(raw)) {
          const count = Number.parseInt(raw, 10);
          return Number.isFinite(count) && count > 0 ? count : 0;
        }
        return 0;
      }

      function getTextMessageValues() {
        const raw = String(document.getElementById("fUiValues")?.value || "");
        if (raw === "") return [];

        /*
         * Text messages are stored in the existing fUiValues/backend field as
         * comma-separated values:
         *
         *   Message 1 = 22
         *   Message 2 = dd
         *   Message 3 = aa
         *
         *   Stored value = 22,dd,aa
         *
         * Backward compatibility:
         * older saved configurations that used newline-separated values are
         * still read correctly. As soon as they are edited/rendered they are
         * normalized back to the required comma-separated format.
         */
        const normalizedRaw = raw.replace(/\r\n?/g, "\n");

        if (normalizedRaw.includes("\n")) {
          return normalizedRaw.split("\n");
        }

        return normalizedRaw.split(",");
      }

      function setTextMessageValues(values, dispatchInput = false) {
        const uiValuesInput = document.getElementById("fUiValues");
        const messageInput = document.getElementById("fMessage");
        if (!uiValuesInput) return;

        const normalizedValues = values.map((item) => String(item ?? ""));

        // Required database/backend format:
        // 22,dd,aa
        const joined = normalizedValues.join(",");

        uiValuesInput.value = joined;
        if (messageInput && messageInput.value !== joined) {
          messageInput.value = joined;
        }

        if (dispatchInput) {
          uiValuesInput.dispatchEvent(new Event("input", { bubbles: true }));
        }
      }

      function ensureTextMessageSlots() {
        const count = getTextMessageCount();
        if (count < 1) return [];

        const values = getTextMessageValues().slice(0, count);
        while (values.length < count) values.push("");
        setTextMessageValues(values, false);
        return values;
      }

      function renderTextMessageEditor(focusIndex = -1) {
        const uiType = String(document.getElementById("fUiType")?.value || "")
          .trim()
          .toLowerCase();
        if (uiType !== "text") return;

        const rows = document.getElementById("textMessageRows");
        const hint = document.getElementById("textMessageCountHint");
        if (!rows) return;

        const count = getTextMessageCount();
        const values = count > 0 ? ensureTextMessageSlots() : [];

        rows.replaceChildren();

        if (count < 1) {
          if (hint) {
            hint.hidden = false;
            hint.innerHTML =
              '<i class="fas fa-circle-info"></i><span>Enter No. of Messages first. Example: <strong>3</strong> creates Message 1, Message 2 and Message 3.</span>';
          }
          renderMessageUiLiveDemo();
          return;
        }

        values.forEach((value, index) => {
          const row = document.createElement("div");
          row.className = "text-message-row";

          const label = document.createElement("label");
          label.className = "text-message-row-label";
          label.htmlFor = `textMessageInput_${index}`;
          label.textContent = `Message ${index + 1}`;

          const input = document.createElement("input");
          input.type = "text";
          input.id = `textMessageInput_${index}`;
          input.className = "text-message-input";
          input.dataset.textMessageIndex = String(index);
          input.value = value;
          input.placeholder = `Enter Message ${index + 1}`;
          input.autocomplete = "off";
          input.setAttribute("aria-label", `Message ${index + 1}`);

          row.append(label, input);
          rows.appendChild(row);
        });

        if (hint) {
          hint.hidden = false;
          hint.innerHTML =
            `<i class="fas fa-circle-check"></i><span>No. of Messages = <strong>${count}</strong>. Enter all ${count} message${count === 1 ? "" : "s"} below. They are stored as comma-separated values.</span>`;
        }

        if (focusIndex >= 0) {
          rows.querySelector(`[data-text-message-index="${focusIndex}"]`)?.focus();
        }

        renderMessageUiLiveDemo();
      }

      function configureTextMessageControls(uiType) {
        const normalizedType = String(uiType || "").trim().toLowerCase();
        const isText = normalizedType === "text";
        const asperUiInput = document.getElementById("fAsperUi");
        const uiValuesInput = document.getElementById("fUiValues");
        const editor = document.getElementById("textMessageInlineEditor");
        const hint = document.getElementById("textMessageCountHint");

        if (!asperUiInput || !uiValuesInput) return;

        // Text / Enter Text keep the existing preview, but Mix and Mix Values
        // are no longer visible inputs. Keep fAsperUi / fUiValues in the DOM so
        // older saved records can still restore their preview/backend payload.
        if (editor) editor.hidden = true;
        if (hint) hint.hidden = true;

        if (!isDropdownUiType(normalizedType)) {
          uiValuesInput.hidden = false;
          uiValuesInput.removeAttribute("aria-hidden");
          uiValuesInput.readOnly = false;
        }

        if (!isText) return;

        asperUiInput.hidden = false;
        asperUiInput.readOnly = false;
        asperUiInput.placeholder = "Enter Mix";
        asperUiInput.setAttribute("inputmode", "numeric");
        asperUiInput.setAttribute("pattern", "[0-9]*");
        asperUiInput.removeAttribute("aria-busy");
        asperUiInput.classList.remove("backend-value-loading");

        // Backward compatibility: keep the old numeric count behavior in Mix,
        // while Mix Values remains the single comma-separated backend value.
        if (!getTextMessageCount() && String(uiValuesInput.value || "").trim()) {
          const existingValues = getTextMessageValues();
          asperUiInput.value = String(Math.max(1, existingValues.length));
        }

        renderMessageUiLiveDemo();
      }

      function getMessagePreviewMeta(uiType) {
        const type = String(uiType || "").trim().toLowerCase();
        const map = {
          "text": {
            label: "TEXT",
            title: "Preview Text",
            badge: "TEXT",
            icon: "fa-gauge-high",
          },
          "enter text": {
            label: "ENTER TEXT",
            title: "Preview Enter Text",
            badge: "ENTER TEXT",
            icon: "fa-keyboard",
          },
          "console": {
            label: "CONSOLE",
            title: "Preview Console",
            badge: "CONSOLE",
            icon: "fa-terminal",
          },
          "notification": {
            label: "NOTIFICATION",
            title: "Preview Notification",
            badge: "NOTIFICATION",
            icon: "fa-bell",
          },
        };
        return map[type] || map.text;
      }

      function renderMessageUiLiveDemo() {
        const uiType = String(document.getElementById("fUiType")?.value || "")
          .trim()
          .toLowerCase();
        const demo = document.getElementById("messageLiveDemo");
        if (!demo) return;

        const isMessageUi = isMessagePreviewUiType(uiType);
        demo.hidden = !isMessageUi;
        if (!isMessageUi) return;

        const uiValuesInput = document.getElementById("fUiValues");
        const messageInput = document.getElementById("fMessage");
        const previewInput = document.getElementById("messagePreviewInput");
        const previewLabel = document.getElementById("messagePreviewLabel");
        const previewTitle = document.getElementById("messagePreviewTitle");
        const previewBadge = document.getElementById("messagePreviewBadge");
        const previewIcon = document.getElementById("messagePreviewIcon");
        const previewHelp = document.getElementById("messagePreviewHelp");
        const inputRow = document.getElementById("messagePreviewInputRow");
        const sendButton = document.getElementById("messageSendButton");
        const consolePreview = document.getElementById("messageConsolePreview");
        const textMultiplePreview = document.getElementById("messageTextMultiplePreview");
        const meta = getMessagePreviewMeta(uiType);
        const isConsole = uiType === "console";
        const isEnterText = uiType === "enter text";
        const isText = uiType === "text";
        const textMessageCount = isText ? getTextMessageCount() : 0;

        demo.classList.toggle("is-console", isConsole);

        // IMPORTANT:
        // Text may store multiple messages, but the preview must keep the
        // original single-message design. Never replace it with multiple
        // preview rows.
        if (inputRow) {
          inputRow.hidden = isConsole;
          inputRow.classList.toggle("has-send", isEnterText);
        }
        if (sendButton) sendButton.hidden = !isEnterText;
        if (consolePreview) consolePreview.hidden = !isConsole;
        if (textMultiplePreview) {
          textMultiplePreview.hidden = true;
          textMultiplePreview.replaceChildren();
        }

        // Existing configurations may already have Message saved but no UI Values.
        // Restore that backend value only ONCE when the message UI is first shown.
        // After the user starts editing, an empty UI Values field must stay empty;
        // otherwise the final remaining character (for example the leading "n" in
        // "niree") would be restored and could never be deleted.
        if (uiValuesInput && uiValuesInput.dataset.messageInitialRestoreDone !== "1") {
          if (!String(uiValuesInput.value || "")) {
            const savedMessage = String(messageInput?.value || "");
            if (savedMessage) uiValuesInput.value = savedMessage;
          }
          uiValuesInput.dataset.messageInitialRestoreDone = "1";
        }

        // Keep the exact value the user typed. Do not trim/rewrite it while the
        // user is editing because that can interfere with normal text editing.
        const value = String(uiValuesInput?.value || "");
        const hasValue = value.trim() !== "";
        const previewValue = hasValue ? value : "Command";

        if (previewLabel) previewLabel.textContent = meta.label;
        if (previewTitle) previewTitle.textContent = meta.title;
        if (previewBadge) previewBadge.textContent = meta.badge;
        if (previewIcon) previewIcon.className = `fas ${meta.icon}`;

        // For Text, fUiValues contains Message 1..N as comma-separated
        // values (for example 22,dd,aa). Store all of them, but keep the old
        // preview as ONE input and show only Message 1 in that preview.
        const textValues = isText ? getTextMessageValues() : [];
        const singlePreviewValue =
          isText
            ? (String(textValues[0] || "").trim() ? String(textValues[0]) : "Command")
            : previewValue;

        if (previewInput) {
          previewInput.value = isConsole ? "" : singlePreviewValue;
        }

        if (consolePreview) consolePreview.textContent = previewValue;

        // Keep the existing backend Message field synchronized with the UI Value,
        // INCLUDING an empty value. This lets the user delete/replace every
        // character, including the first/last remaining character.
        if (messageInput) {
          if (messageInput.value !== value) messageInput.value = value;
          messageInput.closest(".form-group")?.classList.remove("field-invalid");
          messageInput.setAttribute("aria-invalid", "false");
        }

        if (previewHelp) {
          if (isConsole) {
            previewHelp.innerHTML = hasValue
              ? '<i class="fas fa-circle-check"></i><span>Console preview is ready. Multiline data and line breaks are preserved while you edit Message or Command.</span>'
              : '<i class="fas fa-circle-info"></i><span>Paste or type console data in Message or Command. Press Enter to add new lines.</span>';
          } else if (isEnterText) {
            previewHelp.innerHTML = hasValue
              ? '<i class="fas fa-circle-check"></i><span>Enter Text preview is ready. The green Send icon is shown on the right.</span>'
              : '<i class="fas fa-circle-info"></i><span>Enter a Message or Command such as <strong>Command</strong> to preview it with the Send icon.</span>';
          } else if (isText) {
            const values = getTextMessageValues();
            const completeCount = values
              .slice(0, textMessageCount || values.length)
              .filter((item) => String(item || "").trim() !== "").length;
            previewHelp.innerHTML = textMessageCount > 0
              ? `<i class="fas fa-circle-check"></i><span>${completeCount} of ${textMessageCount} Text message${textMessageCount === 1 ? "" : "s"} configured. All messages are stored; the existing preview shows only Message 1.</span>`
              : '<i class="fas fa-circle-info"></i><span>Enter No. of Messages first, then enter each Text message.</span>';
          } else {
            previewHelp.innerHTML = hasValue
              ? '<i class="fas fa-circle-check"></i><span>Message preview is ready. Edit Message or Command to change the displayed value.</span>'
              : '<i class="fas fa-circle-info"></i><span>Enter a Message or Command such as <strong>Command</strong> to update this preview.</span>';
          }
        }
      }

      function renderDisplayToastUiLiveDemo() {
        const uiType = String(document.getElementById("fUiType")?.value || "")
          .trim()
          .toLowerCase();
        const demo = document.getElementById("displayToastLiveDemo");
        if (!demo) return;

        const isSupported = isDisplayToastUiType(uiType);
        demo.hidden = !isSupported;
        if (!isSupported) return;

        const isToast = isToastDisplayUiType(uiType);
        const uiValue = String(document.getElementById("fUiValues")?.value || "");
        const hasValue = uiValue.trim() !== "";

        const card = document.getElementById("displayToastReferenceCard");
        const title = document.getElementById("displayToastPreviewTitle");
        const badge = document.getElementById("displayToastPreviewBadge");
        const icon = document.getElementById("displayToastPreviewIcon");
        const label = document.getElementById("displayToastPreviewLabel");
        const value = document.getElementById("displayToastPreviewValue");
        const valueOutput = document.getElementById("displayToastPreviewOutputValue");
        const help = document.getElementById("displayToastPreviewHelp");

        if (card) {
          card.classList.toggle("is-display", !isToast);
          card.classList.toggle("is-toast", isToast);
        }
        if (title) title.textContent = isToast ? "Preview Toast Display" : "Preview Display";
        if (badge) badge.textContent = isToast ? "TOAST DISPLAY" : "DISPLAY";
        if (icon) icon.className = isToast ? "fas fa-comment-dots" : "fas fa-display";
        if (label) label.textContent = isToast ? "TOAST DISPLAY" : "DISPLAY";
        if (value) value.textContent = hasValue ? uiValue : (isToast ? "Toast message" : "Display value");
        if (valueOutput) valueOutput.textContent = hasValue ? uiValue : "—";

        if (help) {
          help.innerHTML = hasValue
            ? `<i class="fas fa-circle-check"></i><span>${isToast ? "Toast Display" : "Display"} preview is ready. Edit Message or Command to change the preview.</span>`
            : `<i class="fas fa-circle-info"></i><span>Enter a Message or Command to preview the ${isToast ? "toast message" : "display value"}.</span>`;
        }
      }

      function openUiConfigurationPopup(uiType) {
        const overlay = document.getElementById("uiConfigurationModal");
        if (!overlay) return;

        const normalizedType = String(uiType || "none").trim().toLowerCase();

        // None means that this field has no app UI. Do not open a separate
        // "None Configuration" popup. If another UI popup is already open,
        // close it immediately and keep the user in Field Configuration.
        if (!normalizedType || normalizedType === "none") {
          closeUiConfigurationPopup();
          return;
        }

        const option = getUiTypeOption(normalizedType);
        const toggleSection = document.getElementById("uiConfigToggleSection");
        const displayRangeSection = document.getElementById("uiConfigDisplayRangeSection");
        const sliderSection = document.getElementById("uiConfigSliderSection");
        const genericSection = document.getElementById("uiConfigGenericSection");
        const togglePreview = document.getElementById("toggleLiveDemo");
        const buttonPreview = document.getElementById("buttonLiveDemo");
        const dropdownPreview = document.getElementById("dropdownLiveDemo");
        const messagePreview = document.getElementById("messageLiveDemo");
        const displayToastPreview = document.getElementById("displayToastLiveDemo");

        clearUiConfigurationWarning();
        const usesValueSection =
          isToggleUiType(normalizedType) ||
          isButtonUiType(normalizedType) ||
          isDropdownUiType(normalizedType) ||
          isMessagePreviewUiType(normalizedType) ||
          isDisplayToastUiType(normalizedType);

        if (toggleSection) toggleSection.hidden = !usesValueSection;

        const usesDisplayRange =
          isSliderUiType(normalizedType) ||
          normalizedType === "text" ||
          normalizedType === "enter text";
        if (displayRangeSection) displayRangeSection.hidden = !usesDisplayRange;

        // Toggle and Button/Push Button share the value fields, but their previews
        // are mutually exclusive. Explicitly reset both every time this popup opens
        // so a previously opened Push Button preview can never remain visible when
        // the user switches to Toggle Switch.
        if (togglePreview) togglePreview.hidden = !isToggleUiType(normalizedType);
        if (buttonPreview) buttonPreview.hidden = !isButtonUiType(normalizedType);
        if (dropdownPreview) dropdownPreview.hidden = !isDropdownUiType(normalizedType);
        if (messagePreview) messagePreview.hidden = !isMessagePreviewUiType(normalizedType);
        if (displayToastPreview) displayToastPreview.hidden = !isDisplayToastUiType(normalizedType);

        if (sliderSection) sliderSection.hidden = !isSliderUiType(normalizedType);
        if (genericSection) {
          genericSection.hidden = usesValueSection || isSliderUiType(normalizedType);
        }

        const title = document.getElementById("uiConfigTitle");
        const subtitle = document.getElementById("uiConfigSubtitle");
        if (title) title.textContent = `${option.label} Configuration`;
        if (subtitle) {
          subtitle.textContent = isToggleUiType(normalizedType)
            ? "Choose Preset Names or use Custom for your own two state names, then enter exactly two Functioning Names and test the Toggle preview."
            : isStandardButtonUiType(normalizedType)
              ? "Choose Preset Names or use Custom, enter exactly two Functioning Names, then test the two-state Button preview."
              : isPushButtonUiType(normalizedType)
                ? "Choose Preset Names or use Custom. Push Button requires Preset Names only, then you can test the momentary preview."
              : isDropdownUiType(normalizedType)
                ? "Enter the No. of Contents (for example 3), then select 1, 2, 3 inside List of Contents and enter Fan, AC, Phone. Test the Dropdown preview."
                : normalizedType === "text"
                  ? "Enter Display Min and Display Max, then check the existing Text preview below."
                : normalizedType === "console"
                  ? "Paste or enter multiline data in Message or Command and check the live Console preview below."
                : normalizedType === "enter text"
                  ? "Enter Display Min and Display Max, then check the existing Enter Text preview with the Send icon."
                : isMessagePreviewUiType(normalizedType)
                  ? "Enter a Message or Command, then check the live message preview below."
                : isDisplayToastUiType(normalizedType)
                  ? `Enter a Message or Command, then check the live ${isToastDisplayUiType(normalizedType) ? "Toast Display" : "Display"} preview below.`
                : isHueCircleUiType(normalizedType)
                ? "Set Display Min, Display Max, Slider Step and Scaling, then test the Hue Circle preview."
                : isAutoTimerUiType(normalizedType)
                  ? "Set Display Min, Display Max, Slider Step and Scaling, then test the Auto Trigger With Timer preview."
                : isSliderUiType(normalizedType)
                  ? "Set Display Min, Display Max, Slider Step and Scaling, then test the Slider preview."
                  : "This UI type has no extra values in the UI Configuration popup.";
        }

        const editButton = document.getElementById("editUiConfigValues");
        if (editButton) {
          editButton.hidden = !(
            isToggleUiType(normalizedType) ||
            isButtonUiType(normalizedType) ||
            isDropdownUiType(normalizedType) ||
            isMessagePreviewUiType(normalizedType) ||
            isDisplayToastUiType(normalizedType) ||
            isSliderUiType(normalizedType)
          );
        }

        if (genericSection && !genericSection.hidden) {
          const preview = document.getElementById("uiConfigGenericPreview");
          const label = document.getElementById("uiConfigGenericLabel");
          if (preview) preview.innerHTML = option.preview || '<i class="fas fa-display"></i>';
          if (label) label.textContent = option.label;
        }

        configureToggleAsperUiControl(normalizedType);
        configureToggleUiValuesInput(normalizedType);
        configureDropdownUiControls(normalizedType);
        configureTextMessageControls(normalizedType);
        if (isToggleUiType(normalizedType)) renderToggleUiLiveDemo(true);
        if (isButtonUiType(normalizedType)) renderButtonUiLiveDemo(true);
        if (isDropdownUiType(normalizedType)) renderDropdownUiLiveDemo();
        if (isMessagePreviewUiType(normalizedType)) renderMessageUiLiveDemo();
        if (isDisplayToastUiType(normalizedType)) renderDisplayToastUiLiveDemo();
        if (isSliderUiType(normalizedType)) renderSliderUiLiveDemo();

        overlay.classList.add("open");
        overlay.style.display = "flex";
        overlay.setAttribute("aria-hidden", "false");
      }

      function closeUiConfigurationPopup() {
        const overlay = document.getElementById("uiConfigurationModal");
        if (!overlay) return;
        overlay.classList.remove("open");
        overlay.style.display = "none";
        overlay.setAttribute("aria-hidden", "true");
        clearUiConfigurationWarning();
      }

      function validateUiConfigurationPopup() {
        clearUiConfigurationWarning();
        const uiType = document.getElementById("fUiType")?.value || "";
        const invalid = [];
        let customMessage = "";

        if (usesPresetNamesUiType(uiType)) {
          const asPerUi = document.getElementById("fAsperUi");
          const toggleAsPerUi = document.getElementById("fToggleAsperUi");
          const customAsPerUiInput = document.getElementById("fToggleCustomAsperUiInput");
          const customMode = customAsPerUiInput && !customAsPerUiInput.hidden;
          const asPerUiValue = String(asPerUi?.value || "").trim();

          if (!asPerUiValue && !String(toggleAsPerUi?.value || "").trim()) {
            invalid.push(customMode ? customAsPerUiInput : (toggleAsPerUi || asPerUi));
          } else if (customMode && !getToggleCustomAsperUiPair(asPerUiValue).ready) {
            invalid.push(customAsPerUiInput || asPerUi);
            customMessage = "Custom Preset Names must contain exactly two names separated by a comma, for example CLOSE,OPEN.";
          }
        }

        if (isToggleUiType(uiType) || isStandardButtonUiType(uiType)) {
          const uiValues = document.getElementById("fUiValues");
          const pair = String(uiValues?.value || "").trim();

          if (!/^\d+,\d+$/.test(pair)) {
            invalid.push(uiValues);
            if (!customMessage) {
              customMessage = "Functioning Names must contain exactly two comma-separated numeric values, for example 01,02.";
            }
          }
        }

        if (isDropdownUiType(uiType)) {
          const asPerUi = document.getElementById("fAsperUi");
          const uiValues = document.getElementById("fUiValues");
          const uiValueEditor = document.getElementById("dropdownUiValueEditor");
          const count = getDropdownUiCount(asPerUi?.value || "");
          const mappings = getDropdownUiMappings();

          if (count < 1) {
            invalid.push(asPerUi);
            customMessage = "Enter the No. of Contents for the Dropdown, for example 3.";
          } else if (
            mappings.length !== count ||
            mappings.some((item) => !String(item.label || "").trim())
          ) {
            invalid.push(uiValueEditor || uiValues);
            customMessage = `No. of Contents is ${count}. Select each Content No. from 1 to ${count} and enter its Content. Example: 1 = Fan, 2 = AC, 3 = Phone.`;
          }
        }

        const normalizedMessageUiType = String(uiType || "").trim().toLowerCase();

        // Text and Enter Text intentionally have no Mix / Mix Values inputs.
        // Do not validate those hidden compatibility fields. Their existing
        // saved values, when present, are still left untouched for preview/edit
        // restoration. Display Min / Display Max are validated below.
        if (
          normalizedMessageUiType !== "text" &&
          normalizedMessageUiType !== "enter text" &&
          isMessagePreviewUiType(uiType)
        ) {
          const uiValues = document.getElementById("fUiValues");

          if (!String(uiValues?.value || "").trim()) {
            invalid.push(uiValues);
            customMessage = "Enter a Message or Command, for example Command.";
          }
        }

        if (isDisplayToastUiType(uiType)) {
          const uiValues = document.getElementById("fUiValues");

          if (!String(uiValues?.value || "").trim()) {
            invalid.push(uiValues);
            customMessage = "Enter a Message or Command.";
          }
        }

        const normalizedUiType = String(uiType || "").trim().toLowerCase();
        const requiresDisplayRange =
          isSliderUiType(uiType) ||
          normalizedUiType === "text" ||
          normalizedUiType === "enter text";

        if (requiresDisplayRange) {
          const minInput = document.getElementById("fDisplayMin");
          const maxInput = document.getElementById("fDisplayMax");
          const minValue = String(minInput?.value ?? "").trim();
          const maxValue = String(maxInput?.value ?? "").trim();

          if (!minValue) invalid.push(minInput);
          if (!maxValue) invalid.push(maxInput);

          if (
            minValue &&
            maxValue &&
            Number.isFinite(Number(minValue)) &&
            Number.isFinite(Number(maxValue)) &&
            Number(minValue) > Number(maxValue)
          ) {
            if (!invalid.includes(minInput)) invalid.push(minInput);
            if (!invalid.includes(maxInput)) invalid.push(maxInput);
            customMessage = "Display Min cannot be greater than Display Max.";
          }
        }

        if (isSliderUiType(uiType)) {
          const stepInput = document.getElementById("fSliderStep");
          const stepValue = String(stepInput?.value ?? "").trim();
          if (!stepValue || Number(stepValue) <= 0) invalid.push(stepInput);
        }

        const validControls = invalid.filter(Boolean);
        if (!validControls.length) return true;

        validControls.forEach((control) => {
          control.setAttribute("aria-invalid", "true");
          control.closest(".form-group")?.classList.add("field-invalid");
        });

        const warning = document.getElementById("uiConfigWarning");
        if (warning) {
          const labels = validControls.map((control) =>
            control.closest(".form-group")?.querySelector("label")?.textContent?.trim().replace(/\s+/g, " ") || control.id
          );
          warning.hidden = false;
          warning.innerHTML = `<i class="fas fa-triangle-exclamation"></i> ${customMessage || `Please complete: ${labels.join(", ")}.`}`;
        }

        validControls[0]?.focus();
        return false;
      }


      const NOTIFICATION_ENABLED_UI_TYPES = new Set([
        "text",
        "notification",
        "enter text",
        "console",
      ]);

      function getNotificationEnableForUiType(uiType) {
        const normalizedType = String(uiType || "")
          .trim()
          .toLowerCase();

        return NOTIFICATION_ENABLED_UI_TYPES.has(normalizedType)
          ? "Yes"
          : "No";
      }

      function updateNotificationEnableByUiType(uiType) {
        const notificationInput =
          document.getElementById("fNotificationEnable");
        const notificationHint =
          document.getElementById("notificationEnableHint");

        if (!notificationInput) return;

        const value = getNotificationEnableForUiType(uiType);
        notificationInput.value = value;

        if (notificationHint) {
          notificationHint.innerHTML =
            value === "Yes"
              ? '<i class="fas fa-circle-check"></i> Enabled for Text, Notification, Enter Text and Console UI types.'
              : '<i class="fas fa-circle-minus"></i> Disabled for this UI type.';
        }
      }

      function isToggleUiType(uiType) {
        return String(uiType || "")
          .trim()
          .toLowerCase() === "toggle switch";
      }

      const TOGGLE_ASPER_UI_STYLES = {
        "off,on": {
          falseLabel: "OFF",
          trueLabel: "ON",
          displayLabel: "ON / OFF",
        },
        "false,true": {
          falseLabel: "FALSE",
          trueLabel: "TRUE",
          displayLabel: "TRUE / FALSE",
        },
        "disable,enable": {
          falseLabel: "DISABLE",
          trueLabel: "ENABLE",
          displayLabel: "ENABLE / DISABLE",
        },
      };

      function getTogglePresetAsperUiValue(value) {
        const normalized = String(value || "")
          .trim()
          .toLowerCase()
          .replace(/\s+/g, "");

        // Accept both historical/logical order and the user-facing pair order.
        // Internally presets stay in false/off/disable first order so UI Value 1
        // maps to the first state and UI Value 2 maps to the second state.
        const aliases = {
          "on,off": "off,on",
          "off,on": "off,on",
          "true,false": "false,true",
          "false,true": "false,true",
          "enable,disable": "disable,enable",
          "disable,enable": "disable,enable",
        };

        return aliases[normalized] || "";
      }

      function normalizeToggleAsperUiValue(value) {
        const raw = String(value || "").trim();
        const preset = getTogglePresetAsperUiValue(raw);
        if (preset) return preset;

        // Custom mode intentionally keeps user text instead of forcing it back
        // to TRUE/FALSE. Only trim the two outer values for clean storage.
        const parts = raw.split(",");
        if (parts.length === 2) {
          return `${parts[0].trim()},${parts[1].trim()}`;
        }
        return raw;
      }

      function isTogglePresetAsperUiValue(value) {
        return Boolean(getTogglePresetAsperUiValue(value));
      }

      function getToggleCustomAsperUiPair(value) {
        const raw = String(value || "").trim();
        const parts = raw.split(",");
        return {
          first: String(parts[0] || "").trim(),
          second: String(parts[1] || "").trim(),
          ready:
            parts.length === 2 &&
            String(parts[0] || "").trim() !== "" &&
            String(parts[1] || "").trim() !== "",
        };
      }

      function getToggleAsperUiStyle(value) {
        const preset = getTogglePresetAsperUiValue(value);
        if (preset) {
          return TOGGLE_ASPER_UI_STYLES[preset] || TOGGLE_ASPER_UI_STYLES["false,true"];
        }

        const custom = getToggleCustomAsperUiPair(value);
        return {
          falseLabel: custom.first || "STATE 1",
          trueLabel: custom.second || "STATE 2",
          displayLabel: custom.ready
            ? `${custom.first} / ${custom.second}`
            : "CUSTOM",
        };
      }

      function setToggleAsperUiCustomMode(enabled, options = {}) {
        const asperUiInput = document.getElementById("fAsperUi");
        const toggleSelect = document.getElementById("fToggleAsperUi");
        const customInput = document.getElementById("fToggleCustomAsperUiInput");
        const customButton = document.getElementById("fToggleCustomAsperUiBtn");
        if (!asperUiInput || !toggleSelect || !customInput || !customButton) return;

        const useCustom = Boolean(enabled);
        toggleSelect.hidden = useCustom;
        customInput.hidden = !useCustom;
        customButton.classList.toggle("is-active", useCustom);
        customButton.setAttribute("aria-pressed", useCustom ? "true" : "false");

        const icon = customButton.querySelector("i");
        const label = customButton.querySelector("span");
        if (icon) icon.className = useCustom ? "fas fa-list" : "fas fa-pen";
        if (label) label.textContent = useCustom ? "Presets" : "Custom";
        customButton.title = useCustom
          ? "Return to Preset Names"
          : "Enter custom Preset Names";

        if (useCustom) {
          const backendValue = String(asperUiInput.value || "").trim();
          if (!options.keepCustomText && isTogglePresetAsperUiValue(backendValue)) {
            customInput.value = "";
          } else if (!customInput.value && backendValue && !isTogglePresetAsperUiValue(backendValue)) {
            customInput.value = backendValue;
          }

          asperUiInput.value = normalizeToggleAsperUiValue(customInput.value);
          asperUiInput.readOnly = true;
          if (options.focus !== false) customInput.focus();
        } else {
          const preset = getTogglePresetAsperUiValue(toggleSelect.value) || "false,true";
          toggleSelect.value = preset;
          asperUiInput.value = preset;
          asperUiInput.readOnly = true;
          if (options.focus) toggleSelect.focus();
        }
      }

      function configureToggleAsperUiControl(uiType) {
        const asperUiInput = document.getElementById("fAsperUi");
        const asperUiGroup = document.getElementById("asperUiFieldGroup");
        const toggleSelect = document.getElementById("fToggleAsperUi");
        const customInput = document.getElementById("fToggleCustomAsperUiInput");
        const customButton = document.getElementById("fToggleCustomAsperUiBtn");
        const controlRow = document.getElementById("toggleAsperUiControlRow");
        const hint = document.getElementById("toggleAsperUiHint");
        const label = document.getElementById("asperUiFieldLabel");
        if (!asperUiInput || !toggleSelect || !customInput || !customButton) return;

        const normalizedType = String(uiType || "").trim().toLowerCase();
        const isToggle = isToggleUiType(normalizedType);
        const isButton = isStandardButtonUiType(normalizedType);
        const isPushButton = isPushButtonUiType(normalizedType);
        const usesPresetNames = isToggle || isButton || isPushButton;
        const isDropdown = isDropdownUiType(normalizedType);
        const isText = normalizedType === "text";
        const isEnterText = normalizedType === "enter text";
        // Text and Enter Text no longer expose Mix in the UI Configuration popup.
        // Keep fAsperUi in the DOM/backend payload for compatibility, but hide
        // its visible field. Dropdown and preset-based controls still show it.
        const showAsperField = usesPresetNames || isDropdown;

        // Preserve the existing backend key fAsperUi, but give it a clear
        // UI-specific meaning:
        // Toggle Switch = Preset Names
        // Button = Preset Names
        // Push Button = Preset Names only
        // Dropdown = No. of Contents
        // Text = No. of Messages
        if (asperUiGroup) asperUiGroup.hidden = !showAsperField;

        if (label) {
          label.innerHTML = usesPresetNames
            ? '<i class="fas fa-wand-magic-sparkles"></i> Preset Names'
            : isDropdown
              ? '<i class="fas fa-hashtag"></i> No. of Contents'
              : (isText || isEnterText)
                ? '<i class="fas fa-layer-group"></i> Mix'
                : '<i class="fas fa-wand-magic-sparkles"></i> Configuration';
        }

        // Toggle Switch, Button and Push Button all use the same Preset Names
        // selector/custom editor. Push Button stops here and does not expose
        // Functioning Names.
        if (controlRow) controlRow.hidden = !usesPresetNames;

        if (usesPresetNames) {
          let currentValue = String(asperUiInput.value || toggleSelect.value || "").trim();

          // Older Button/Push Button rows used "1" because Preset Names were not
          // previously configurable. Treat that legacy placeholder as unconfigured
          // and start from the normal preset instead of showing an invalid custom pair.
          if ((isButton || isPushButton) && currentValue === "1") {
            currentValue = "";
          }

          const preset = getTogglePresetAsperUiValue(currentValue);

          asperUiInput.hidden = true;
          asperUiInput.readOnly = true;
          if (controlRow) controlRow.hidden = false;
          toggleSelect.disabled = false;
          toggleSelect.required = false;
          customInput.disabled = false;
          customButton.disabled = false;
          if (hint) {
            hint.hidden = false;
            hint.innerHTML = isPushButton
              ? '<i class="fas fa-hand-pointer"></i> Choose Preset Names or click Custom to enter your own preset names.'
              : '<i class="fas fa-tags"></i> Choose a preset or click Custom and enter any two names such as CLOSE,OPEN.';
          }
          if (label) label.htmlFor = preset ? "fToggleAsperUi" : "fToggleCustomAsperUiInput";

          if (preset || !currentValue) {
            const selectedPreset = preset || "false,true";
            toggleSelect.value = selectedPreset;
            asperUiInput.value = selectedPreset;
            setToggleAsperUiCustomMode(false, { focus: false });
          } else {
            customInput.value = normalizeToggleAsperUiValue(currentValue);
            asperUiInput.value = customInput.value;
            setToggleAsperUiCustomMode(true, { focus: false, keepCustomText: true });
          }
          return;
        }

        // Dropdown and Text keep the same backend field as a numeric count.
        // Other UI types hide this field and keep the compatibility default.
        asperUiInput.hidden = false;
        asperUiInput.readOnly = !(isDropdown || isText || isEnterText);
        if (!isDropdown && !isText && !isEnterText && !String(asperUiInput.value || "").trim()) {
          // Keep the legacy backend payload compatible without asking the user
          // to configure a field that is no longer visible.
          asperUiInput.value = "1";
        }

        if (isText) {
          asperUiInput.placeholder = "Enter Mix";
          asperUiInput.setAttribute("inputmode", "numeric");
          asperUiInput.setAttribute("pattern", "[0-9]*");
        } else if (isEnterText) {
          asperUiInput.placeholder = "Enter Mix";
          asperUiInput.removeAttribute("inputmode");
          asperUiInput.removeAttribute("pattern");
        }

        if (controlRow) controlRow.hidden = true;
        toggleSelect.hidden = false;
        toggleSelect.disabled = true;
        toggleSelect.required = false;
        customInput.hidden = true;
        customInput.disabled = true;
        customButton.disabled = true;
        customButton.classList.remove("is-active");
        customButton.setAttribute("aria-pressed", "false");

        const buttonIcon = customButton.querySelector("i");
        const buttonLabel = customButton.querySelector("span");
        if (buttonIcon) buttonIcon.className = "fas fa-pen";
        if (buttonLabel) buttonLabel.textContent = "Custom";
        if (hint) hint.hidden = true;
        if (label) label.htmlFor = "fAsperUi";
      }

      function sanitizeToggleUiValues(value) {
        const parts = String(value ?? "")
          .replace(/\s+/g, "")
          .split(",");

        const firstValue = (parts[0] || "").replace(/\D/g, "");
        const secondValue = (parts[1] || "").replace(/\D/g, "");

        // A Toggle Switch can have only two values. Any third (or later)
        // comma-separated value is ignored immediately.
        return parts.length > 1
          ? `${firstValue},${secondValue}`
          : firstValue;
      }

      function configureToggleUiValuesInput(uiType) {
        const uiValuesInput = document.getElementById("fUiValues");
        const uiValuesLabel = document.getElementById("uiValuesFieldLabel");
        const hint = document.getElementById("toggleUiValuesHint");
        if (!uiValuesInput) return;

        const normalizedUiType = String(uiType || "").trim().toLowerCase();
        const isToggle = isToggleUiType(normalizedUiType);
        const isButton = isStandardButtonUiType(normalizedUiType);
        const isPushButton = isPushButtonUiType(normalizedUiType);
        const needsFunctioningNames = isToggle || isButton;
        const isDropdown = isDropdownUiType(normalizedUiType);
        const isMessage = isMessagePreviewUiType(normalizedUiType);
        const isText = normalizedUiType === "text";
        const isEnterText = normalizedUiType === "enter text";
        const isDisplayToast = isDisplayToastUiType(normalizedUiType);
        const isConsole = normalizedUiType === "console";
        const uiValuesGroup = uiValuesInput.closest(".ui-values-field-column");
        const uiFieldsGrid = uiValuesInput.closest(".ui-config-fields");

        // Push Button configuration contains Preset Names only. Text and
        // Enter Text no longer expose Mix / Mix Values. Keep fUiValues and
        // fAsperUi in the DOM for backend/edit compatibility, but hide the
        // whole value-input row for Text and Enter Text.
        if (uiValuesGroup) {
          uiValuesGroup.hidden = isPushButton || isText || isEnterText;
        }
        if (uiFieldsGrid) {
          uiFieldsGrid.hidden = isText || isEnterText;
          uiFieldsGrid.classList.toggle("push-button-preset-only", isPushButton);
        }

        if (uiValuesLabel) {
          uiValuesLabel.innerHTML = needsFunctioningNames
            ? '<i class="fas fa-list"></i> Functioning Names'
            : isDropdown
              ? '<i class="fas fa-list"></i> List of Contents'
              : (isText || isEnterText)
                ? '<i class="fas fa-list"></i> Mix Values'
                : (isMessage || isDisplayToast)
                  ? '<i class="fas fa-message"></i> Message or Command'
                  : '<i class="fas fa-list"></i> UI Values';
        }

        if (hint) {
          hint.hidden = !needsFunctioningNames;
          if (needsFunctioningNames) {
            hint.innerHTML = `<i class="fas ${isButton ? "fa-square-check" : "fa-toggle-on"}"></i> Enter exactly two numeric Functioning Names, for example: 01,02.`;
          }
        }

        uiValuesInput.classList.toggle("console-ui-values", isConsole);
        if (uiValuesInput.tagName === "TEXTAREA") {
          uiValuesInput.rows = isConsole ? 8 : 1;
          uiValuesInput.setAttribute("aria-multiline", isConsole ? "true" : "false");
        }

        if (needsFunctioningNames) {
          uiValuesInput.placeholder = "Example: 01,02";
          uiValuesInput.setAttribute("data-toggle-two-values", "true");
          const sanitized = sanitizeToggleUiValues(uiValuesInput.value);
          if (uiValuesInput.value !== sanitized) {
            uiValuesInput.value = sanitized;
          }
        } else if (isPushButton) {
          // Hidden compatibility value only; Push Button has no Functioning Names field.
          if (!String(uiValuesInput.value || "").trim()) {
            uiValuesInput.value = "1";
          }
          uiValuesInput.removeAttribute("data-toggle-two-values");
        } else {
          uiValuesInput.placeholder = isDropdown
            ? "Contents are edited with the selector below"
            : isConsole
              ? "Paste or enter console data here. Press Enter for a new line."
              : (isText || isEnterText)
                ? "Enter Mix Values"
                : (isMessage || isDisplayToast)
                  ? "Enter message or command, e.g. Command"
                  : "Enter UI values";
          uiValuesInput.removeAttribute("data-toggle-two-values");
        }

        if (isToggle) renderToggleUiLiveDemo(true);
        if (isButton || isPushButton) renderButtonUiLiveDemo(true);
        if (isMessage) renderMessageUiLiveDemo();
        if (isDisplayToast) renderDisplayToastUiLiveDemo();
      }

      let toggleLiveDemoState = false;
      let buttonLiveDemoState = false;


      function getToggleLiveValuePair(value) {
        const sanitized = sanitizeToggleUiValues(value);
        const parts = sanitized.split(",");
        return {
          falseValue: String(parts[0] || "").trim(),
          trueValue: String(parts[1] || "").trim(),
          ready:
            parts.length === 2 &&
            String(parts[0] || "").trim() !== "" &&
            String(parts[1] || "").trim() !== "",
        };
      }

      function renderToggleUiLiveDemo(resetState = false) {
        const demo = document.getElementById("toggleLiveDemo");
        const buttonDemo = document.getElementById("buttonLiveDemo");
        const uiValuesLiveRow = document.getElementById("uiValuesLiveRow");
        const uiTypeInput = document.getElementById("fUiType");
        const asperUiInput = document.getElementById("fAsperUi");
        const uiValuesInput = document.getElementById("fUiValues");
        const currentValueEl = document.getElementById("toggleCurrentValue");
        const stateLabel = document.getElementById("toggleLiveStateLabel");
        const switchButton = document.getElementById("toggleLiveSwitch");
        const status = document.getElementById("toggleLiveDemoStatus");
        const help = document.getElementById("toggleLiveDemoHelp");

        if (!demo || !uiTypeInput || !uiValuesInput) return;

        const isToggle = isToggleUiType(uiTypeInput.value);
        demo.hidden = !isToggle;

        // A Toggle configuration must show only the Toggle preview.
        if (buttonDemo) buttonDemo.hidden = true;

        if (uiValuesLiveRow) {
          uiValuesLiveRow.classList.toggle("has-toggle-demo", isToggle);
        }
        if (!isToggle) return;

        if (resetState) {
          toggleLiveDemoState = false;
        }

        const pair = getToggleLiveValuePair(uiValuesInput.value);
        const style = getToggleAsperUiStyle(asperUiInput?.value || "false,true");

        // if (help) {
        //   help.textContent =
        //     `Selected labels: ${style.displayLabel}. ` +
        //     `First UI Value = ${style.falseLabel}; second UI Value = ${style.trueLabel}.`;
        // }

        if (switchButton) {
          switchButton.disabled = !pair.ready;
          switchButton.classList.toggle("is-on", pair.ready && toggleLiveDemoState);
          switchButton.setAttribute(
            "aria-pressed",
            pair.ready && toggleLiveDemoState ? "true" : "false",
          );
        }

        if (!pair.ready) {
          if (stateLabel) stateLabel.textContent = "Enter two values";
          if (currentValueEl) currentValueEl.textContent = "—";
          if (status) {
            status.classList.remove("ready");
            status.innerHTML = `
              <i class="fas fa-circle-info"></i>
              <span>Enter exactly two values above. Example: <strong>01,02</strong> means <strong>01 = ${style.falseLabel}</strong> and <strong>02 = ${style.trueLabel}</strong>.</span>
            `;
          }
          return;
        }

        const activeValue = toggleLiveDemoState
          ? pair.trueValue
          : pair.falseValue;

        if (stateLabel) {
          stateLabel.textContent = toggleLiveDemoState
            ? style.trueLabel
            : style.falseLabel;
        }
        if (currentValueEl) currentValueEl.textContent = activeValue;
        if (status) {
          status.classList.add("ready");
          status.innerHTML = `
            <i class="fas fa-circle-check"></i>
            <span><strong>${pair.falseValue}</strong> = ${style.falseLabel} &nbsp;•&nbsp; <strong>${pair.trueValue}</strong> = ${style.trueLabel}. Click the switch to test both values.</span>
          `;
        }
      }

      function updateUiTypeDependentFields(uiType) {
        const normalizedType = String(uiType || "").trim().toLowerCase();
        configureToggleAsperUiControl(normalizedType);
        configureToggleUiValuesInput(normalizedType);
        configureDropdownUiControls(normalizedType);
        configureTextMessageControls(normalizedType);

        /*
         * UI In/Output is independent from the selected UI component.
         * The user can always choose exactly one of:
         * Read, Write, Read/Write, or None.
         * Never auto-select or lock this field when UI Type changes.
         */
        const uiInOutInput = document.getElementById("fUiInOut");
        if (uiInOutInput) {
          uiInOutInput.disabled = false;
          uiInOutInput.removeAttribute("aria-disabled");
        }

        /*
         * Notification Enable is now selected explicitly by the user.
         * Do not auto-fill Yes or No from UI Type.
         */
        const messageGroup = document.getElementById("messageFieldGroup");
        const sliderStepGroup = document.getElementById("sliderStepFieldGroup");
        const scalingGroup = document.getElementById("scalingFieldGroup");

        const messageInput = document.getElementById("fMessage");
        const sliderStepInput = document.getElementById("fSliderStep");
        const scalingInput = document.getElementById("fScalling");

        const showMessage = MESSAGE_UI_TYPES.has(normalizedType);
        const hideMessageForText =
          normalizedType === "text" || normalizedType === "enter text";
        const showSliderFields = isSliderUiType(normalizedType);

        /*
         * Keep the original Message group in the DOM because the popup/open
         * and edit/restore code still references it. For Text and Enter Text,
         * hide only the visible Message control instead of removing its DOM.
         */
        if (messageGroup) {
          messageGroup.hidden = hideMessageForText || !showMessage;
        }

        if (sliderStepGroup) {
          sliderStepGroup.hidden = !showSliderFields;
        }

        if (scalingGroup) {
          scalingGroup.hidden = !showSliderFields;
        }

        if (messageInput) {
          messageInput.required = showMessage && !hideMessageForText;
        }

        if (sliderStepInput) {
          sliderStepInput.required = showSliderFields;
        }

        /*
         * Scaling remains optional unless your existing backend validation
         * requires it. We only control its visibility here.
         */
        if (scalingInput) {
          scalingInput.disabled = !showSliderFields;
        }

        if (!showMessage) {
          messageGroup?.classList.remove("field-invalid");
          messageInput?.setAttribute("aria-invalid", "false");
        }

        if (!showSliderFields) {
          sliderStepGroup?.classList.remove("field-invalid");
          sliderStepInput?.setAttribute("aria-invalid", "false");

          scalingGroup?.classList.remove("field-invalid");
          scalingInput?.setAttribute("aria-invalid", "false");
        }
      }

      function syncFieldReferenceControls() {
        const notificationSelect = document.getElementById("fNotificationEnable");
        document
          .querySelectorAll("[data-notification-value]")
          .forEach((button) => {
            button.classList.toggle(
              "active",
              String(button.dataset.notificationValue || "") === String(notificationSelect?.value || ""),
            );
          });

        const uiInOutSelect = document.getElementById("fUiInOut");
        const selectedUiInOut = String(uiInOutSelect?.value || "");
        document
          .querySelectorAll("[data-ui-inout-value]")
          .forEach((button) => {
            const isSelected =
              String(button.dataset.uiInoutValue || "") === selectedUiInOut;
            button.classList.toggle("active", isSelected);
            button.setAttribute("aria-pressed", isSelected ? "true" : "false");
          });

        const uiInOutStatus = document.getElementById("uiInOutSelectionStatus");
        if (uiInOutStatus) {
          const labelMap = {
            read: "Read",
            write: "Write",
            "read/write": "Read/Write",
            none: "None",
          };
          const selectedLabel = labelMap[selectedUiInOut] || "";
          uiInOutStatus.classList.toggle("selected", Boolean(selectedLabel));
          uiInOutStatus.innerHTML = selectedLabel
            ? `<i class="fas fa-circle-check"></i><span>Selected: <strong>${selectedLabel}</strong></span>`
            : '<i class="fas fa-circle-info"></i><span>Select one option: Read, Write, Read/Write, or None.</span>';
        }

        const notes = document.getElementById("fNotes");
        const notesCount = document.getElementById("fieldNotesCount");
        if (notesCount) {
          notesCount.textContent = `${String(notes?.value || "").length}/500`;
        }
      }

      function updateFieldComponentPreview(selectedValue) {
        const option = getUiTypeOption(selectedValue || "none");
        const preview = document.getElementById("fieldUiPreviewVisual");
        const title = document.getElementById("fieldUiPreviewTitle");
        const hint = document.getElementById("fieldUiPreviewHint");
        if (preview) {
          preview.dataset.uiType = option.value || "none";
          preview.innerHTML = option.preview || '<i class="fas fa-display"></i>';
        }
        if (title) title.textContent = option.label || "None";
        if (hint) hint.textContent = option.hint || "No UI control";
      }

      function applyUiComponentSearch() {
        const input = document.getElementById("uiComponentSearch");
        const query = String(input?.value || "").trim().toLowerCase();
        document.querySelectorAll("#uiTypePicker .ui-type-option[data-value]").forEach((button) => {
          const label = String(button.querySelector("strong")?.textContent || "").toLowerCase();
          const hint = String(button.querySelector("small")?.textContent || "").toLowerCase();
          const value = String(button.dataset.value || "").toLowerCase();
          button.hidden = Boolean(query) && !(`${label} ${hint} ${value}`.includes(query));
        });
      }

      function initializeFieldReferenceControls() {
        const search = document.getElementById("uiComponentSearch");
        if (search && search.dataset.bound !== "1") {
          search.dataset.bound = "1";
          search.addEventListener("input", applyUiComponentSearch);
        }

        document.querySelectorAll("[data-notification-value]").forEach((button) => {
          if (button.dataset.bound === "1") return;
          button.dataset.bound = "1";
          button.addEventListener("click", function () {
            const select = document.getElementById("fNotificationEnable");
            if (!select) return;
            select.value = this.dataset.notificationValue || "";
            select.dispatchEvent(new Event("change", { bubbles: true }));
            select.closest(".form-group")?.classList.remove("field-invalid");
            select.setAttribute("aria-invalid", "false");
            syncFieldReferenceControls();
          });
        });

        document.querySelectorAll("[data-ui-inout-value]").forEach((button) => {
          if (button.dataset.bound === "1") return;
          button.dataset.bound = "1";
          button.addEventListener("click", function () {
            const select = document.getElementById("fUiInOut");
            if (!select) return;
            const requestedValue = this.dataset.uiInoutValue || "";

            // UI In/Output is a true single-choice field. All four options
            // remain selectable regardless of the selected UI component.
            select.disabled = false;
            select.removeAttribute("aria-disabled");
            select.value = requestedValue;
            select.dispatchEvent(new Event("change", { bubbles: true }));
            select.closest(".form-group")?.classList.remove("field-invalid");
            select.setAttribute("aria-invalid", "false");
            syncFieldReferenceControls();
          });
        });

        const notes = document.getElementById("fNotes");
        if (notes && notes.dataset.referenceBound !== "1") {
          notes.dataset.referenceBound = "1";
          notes.addEventListener("input", syncFieldReferenceControls);
        }

        const backButton = document.getElementById("backFieldModal");
        if (backButton && backButton.dataset.bound !== "1") {
          backButton.dataset.bound = "1";
          backButton.addEventListener("click", closeByteFieldModal);
        }

        const notificationSelect = document.getElementById("fNotificationEnable");
        if (notificationSelect && notificationSelect.dataset.referenceBound !== "1") {
          notificationSelect.dataset.referenceBound = "1";
          notificationSelect.addEventListener("change", syncFieldReferenceControls);
        }

        const uiInOutSelect = document.getElementById("fUiInOut");
        if (uiInOutSelect && uiInOutSelect.dataset.referenceBound !== "1") {
          uiInOutSelect.dataset.referenceBound = "1";
          uiInOutSelect.addEventListener("change", syncFieldReferenceControls);
        }
      }

      function renderUiTypePicker(selectedValue) {
        const picker = document.getElementById("uiTypePicker");
        const select = document.getElementById("fUiType");
        if (!picker || !select) return;
        const value = selectedValue || select.value || "none";
        select.value = value;
        updateUiTypeDependentFields(value);
        picker.innerHTML = UI_TYPE_OPTIONS.map(
          (option) => `
              <button type="button" class="ui-type-option${option.value === value ? " active" : ""}" role="option" aria-selected="${option.value === value}" data-value="${option.value}">
                <span class="ui-preview">${option.preview}</span>
                <span class="ui-preview-label">
                  <strong>${option.label}</strong>
                  <small>${option.hint}</small>
                </span>
              </button>
            `,
        ).join("") + `
          <button type="button" class="ui-type-option ui-type-more-option" tabindex="-1" aria-disabled="true">
            <span class="ui-preview"><i class="fas fa-plus"></i></span>
            <span class="ui-preview-label">
              <strong>More Components</strong>
              <small>Coming soon...</small>
            </span>
          </button>
        `;

        updateFieldComponentPreview(value);
        initializeFieldReferenceControls();
        syncFieldReferenceControls();
        applyUiComponentSearch();

        picker.querySelectorAll(".ui-type-option[data-value]").forEach((button) => {
          button.addEventListener("click", function () {
            const nextValue = this.dataset.value;
            const previousValue = select.value || "none";
            const isSameUiType = previousValue === nextValue;

            // Preserve the field-definition selections while refreshing only
            // the UI-dependent automatic values (As Per UI / Serial / Values).
            const dataTypeInput = document.getElementById("fDataType");
            const valueDefInput = document.getElementById("fValueDef");
            const preservedDataType = dataTypeInput?.value || "";
            const preservedValueDef = valueDefInput?.value || "";

            select.value = nextValue;
            // Clicking the active UI option is also how the user reopens the
            // popup. Do not overwrite already edited values in that case.
            applyUiTypeAutoValues(nextValue, !isSameUiType);

            if (dataTypeInput && preservedDataType) {
              dataTypeInput.value = preservedDataType;
            }
            if (valueDefInput && preservedValueDef) {
              valueDefInput.value = preservedValueDef;
            }

            renderUiTypePicker(nextValue);
            select.dispatchEvent(new Event("change", { bubbles: true }));
            updateFieldComponentPreview(nextValue);
            syncFieldReferenceControls();

            // None is a complete "no UI" choice. Keep the user in the Field
            // Configuration modal and do not show a None Configuration popup.
            if (String(nextValue || "").trim().toLowerCase() === "none") {
              closeUiConfigurationPopup();
            } else {
              openUiConfigurationPopup(nextValue);
            }

            this.closest(".form-group")?.classList.remove("field-invalid");
            select.setAttribute("aria-invalid", "false");
          });
        });
      }

      const FIELD_DESC_OPTIONS = [
        "header",
        "data",
        "payload",
        "checksum",
        "terminator",
        "commandid",
        "function code",
        "terminator / crc",
        "status",
        "error code",
        "length",
        "version",
        "reserved",
        "timestamp",
        "device id",
      ];
      const API_PARTITION_OPTIONS = [
        /* Existing values retained so old saved configurations still restore. */
        { value: "commandId", label: "Command ID" },
        { value: "functionCode", label: "Function Code" },
        { value: "data", label: "Data" },
        { value: "terminatorCrc", label: "Terminator / CRC" },

        /* New Partition Name options requested for the UI. */
        { value: "header", label: "Header" },
        { value: "payload", label: "Payload" },
        { value: "checksum", label: "Checksum" },
        { value: "status", label: "Status" },
        { value: "errorCode", label: "Error Code" },
        { value: "length", label: "Length" },
        { value: "version", label: "Version" },
        { value: "reserved", label: "Reserved" },
        { value: "timestamp", label: "Timestamp" },
        { value: "deviceId", label: "Device ID" },
      ];
      /*
       * Keep partition colours independent from the page theme.
       * These distinct colours make adjacent byte partitions easy to identify.
       */
      const PARTITION_COLORS = [
        { color: "#2563EB", soft: "#EAF2FF", text: "#1746A2" },
        { color: "#7C3AED", soft: "#F2EBFF", text: "#5B21B6" },
        { color: "#0F8A75", soft: "#E5F8F4", text: "#0B6658" },
        { color: "#D97706", soft: "#FFF3DF", text: "#9A4C00" },
        { color: "#DB2777", soft: "#FDEAF3", text: "#9D174D" },
        { color: "#087EA4", soft: "#E6F7FB", text: "#075B75" },
        { color: "#6B8E23", soft: "#F1F8E4", text: "#496817" },
        { color: "#C2413B", soft: "#FDECEA", text: "#8D2925" },
      ];

      const apiPartitionSection = document.getElementById(
        "apiPartitionSection",
      );
      const commandFramesSection = document.getElementById(
        "commandFramesSection",
      );
      commandFramesSection.insertAdjacentElement(
        "afterend",
        apiPartitionSection,
      );
      apiPartitionSection.classList.remove("frame-partition-active");

      function clonePartitionObject(value) {
        return JSON.parse(JSON.stringify(value || {}));
      }

      function updateSaveBadge(state, message) {
        const badge = document.getElementById("saveStatusBadge");
        if (!badge) return;
        const icon =
          state === "saved"
            ? "fa-circle-check"
            : state === "error"
              ? "fa-circle-exclamation"
              : state === "unsaved"
                ? "fa-pen-to-square"
                : "fa-cloud-arrow-down";
        badge.className = `save-status-badge${state ? ` ${state}` : ""}`;
        badge.innerHTML = `<i class="fas ${icon}"></i><span>${message}</span>`;
        void badge.offsetWidth;
        badge.classList.add("status-change");
      }

      function markConfigurationUnsaved() {
        updateSaveBadge("unsaved", "Unsaved changes");
        updateFrameTypeUi();
      }

      function collectCurrentEntryData() {
        const entryData = {};
        document
          .querySelectorAll("input[id], select[id], textarea[id]")
          .forEach((control) => {
            if (
              control.type === "file" ||
              control.type === "button" ||
              control.type === "submit"
            ) {
              return;
            }

            if (control.type === "checkbox") {
              entryData[control.id] = control.checked;
              return;
            }

            if (control.type === "radio") {
              if (control.checked) {
                entryData[control.name || control.id] = control.value;
              }
              return;
            }

            entryData[control.id] = control.value;
          });
        return entryData;
      }

      function schemaDirectionLabel(value) {
        return value === "device_to_server"
          ? "Device to App/Server"
          : "App/Server to Device";
      }

      function normalizeDirectionValue(value) {
        const normalized = String(value || "").trim().toLowerCase();
        if (
          normalized === "device_to_server" ||
          normalized.includes("device to")
        ) {
          return "device_to_server";
        }
        if (
          normalized === "server_to_device" ||
          normalized.includes("server to") ||
          normalized.includes("app/server to")
        ) {
          return "server_to_device";
        }
        return "";
      }

      function addSchemaRowAliases(row, prefix) {
        const aliases = {};
        [
          "bitwiseMode",
          "startBytePosition",
          "endBytePosition",
          "numberOfBytes",
          "bitSize",
          "name",
          "fieldName",
          "fieldDescription",
          "dataType",
          "valueDefinition",
          "displayValueMin",
          "displayValueMax",
          "valueInHexMin",
          "valueInHexMax",
          "uiType",
          "uiId",
          "asperui",
          "sno_asperui",
          "asperuivalue",
          "uiPageNo",
          "uiDescriptionInOut",
          "sliderStepValue",
          "defaultvalue",
          "developerNotes",
          "notificationEnable",
          "notificationMessage",
          "scaling",
        ].forEach((key) => {
          aliases[`${prefix}_${key}`] = row[key];
        });
        return { ...row, ...aliases };
      }

      function buildEditorConfiguration() {
        captureActiveFramePartitionState();
        saveActiveFrameTypeStore();
        enforceCommandGetStatusCommandState(true);

        function buildFramesForType(frameType) {
          const store = frameTypeStores[frameType];
          return Array.from({ length: store.count || 0 }, (_, index) => ({
            frameNumber: index + 1,
            frameType,
            frameCode: store.frameCodes[index] || "",
            [`${frameType}Code`]: store.frameCodes[index] || "",
            dataFlowDirection:
              store.frameConfigurations[index]?.dataFlowDirection || "",
            multipleUi: store.frameConfigurations[index]?.multipleUi || "",
            voiceCommandEnabled: store.voiceCommandEnabled || "No",
            voiceCommands: clonePartitionObject(store.voiceCommands || []),
            valueGroups: clonePartitionObject(
              store.frameValueGroups[index] || [],
            ),
            partition: clonePartitionObject(
              store.framePartitionStates[index] || {},
            ),
            fieldDescriptions: clonePartitionObject(
              store.fieldDescriptions[index] || {},
            ),
            byteDescriptions: clonePartitionObject(
              store.byteDescriptions[index] || {},
            ),
            fieldViewModes: clonePartitionObject(
              store.fieldViewModes[index] || {},
            ),
          }));
        }

        const commandFrames = buildFramesForType("command");
        const responseFrames = buildFramesForType("response");
        const errorFrames = buildFramesForType("error");
        return {
          storageVersion: 3,
          savedAt: new Date().toISOString(),
          entryData: collectCurrentEntryData(),
          form: {
            parameterName: document.getElementById("paramNameInput").value,
            commandFrameCount: frameTypeStores.command.count || 0,
            responseFrameCount: frameTypeStores.response.count || 0,
            errorFrameCount: frameTypeStores.error.count || 0,
            triggerUi:
              document.getElementById("triggerUiSelect")?.value || "",
          },
          activeFrameType,
          commandFrames,
          responseFrames,
          errorFrames,
          bytes: clonePartitionObject(bytes),
          frameTypeStores: clonePartitionObject(frameTypeStores),
        };
      }

      function buildSchemaFrames(frameType, prefix, frameTypeName) {
        if (isCommandGetStatusCommandLocked(frameType)) {
          enforceCommandGetStatusCommandState(true);
        }
        const store = frameTypeStores[frameType];

        /*
         * EDIT DELETE FIX
         * ---------------
         * Row 2 inclusion is authoritative. If Command/Response/Error is not
         * selected, it must not be present in the payload even if an old Edit
         * record left stale arrays/counts in memory.
         */
        if (!store || !isFrameTypeIncluded(frameType)) {
          return [];
        }

        const parameterName =
          document.getElementById("paramNameInput").value.trim();
        const voiceEnabled = normalizeVoiceCommandEnabled(
          store.voiceCommandEnabled || "No",
          store.voiceCommands || [],
        );
        const voiceCommands =
          voiceEnabled === "Yes"
            ? normalizeVoiceCommandList(store.voiceCommands || [])
            : [];
        const voiceControlValue = voiceCommands.length
          ? JSON.stringify(voiceCommands)
          : "";

        return Array.from({ length: store.count || 0 }, (_, frameIndex) => {
          const partition = store.framePartitionStates[frameIndex] || {};
          const labels = partition.partitionLabels || {};
          const configurations =
            partition.partitionFieldConfigurations || {};
          const frameConfiguration =
            store.frameConfigurations[frameIndex] || {};
          const frameCode =
            store.frameCodes[frameIndex] ||
            partition.fullApiValue ||
            "";

          const rows = Object.keys(labels).map((key, rowIndex) => {
            const boundaries = key.split("-").map(Number);
            const start = Number.isFinite(boundaries[0])
              ? boundaries[0]
              : rowIndex;
            const end = Number.isFinite(boundaries[1])
              ? boundaries[1]
              : start + 1;
            const field = configurations[key]?.byte || {};
            const numberOfBytes = Math.max(1, end - start);
            const zeroHex = `0x${"00".repeat(numberOfBytes)}`;
            const maxHex = `0x${"FF".repeat(numberOfBytes)}`;
            const bitwise = Object.entries(configurations[key] || {})
              .filter(
                ([configurationKey, value]) =>
                  !configurationKey.startsWith("_") &&
                  configurationKey !== "byte" &&
                  value &&
                  typeof value === "object",
              )
              .map(([configurationKey, value]) => ({
                startBytePosition_1: configurationKey,
                endBytePosition_1: configurationKey,
                startBit: Array.isArray(value.bitPositions)
                  ? value.bitPositions[0]
                  : value.bitPosition,
                endBit: Array.isArray(value.bitPositions)
                  ? value.bitPositions[value.bitPositions.length - 1]
                  : value.bitPosition,
                numberOfBytes_1: Array.isArray(value.bitPositions)
                  ? value.bitPositions.length
                  : 1,
                name_1: value.name || value.fieldName || "",
                fieldName_1: value.name || value.fieldName || "",
                fieldDescription_1: labels[key] || "",
                dataType_1: value.dataType || "",
                valueDefinition_1: value.valueDef || "",
                uiType_1: value.uiType || "",
                uiDescriptionInOut_1: value.uiInOut || "",
                scaling_1: value.scalling || "",
                displayValueMin_1: value.displayValueMin || "",
                displayValueMax_1: value.displayValueMax || "",
                display_value_min_1: value.displayValueMin || "",
                display_value_max_1: value.displayValueMax || "",
                valueInHexMin_1: value.valueInHexMin || "",
                valueInHexMax_1: value.valueInHexMax || "",
                uiId_1: value.uiId || "",
                asperui_1: value.asperui || value.asperUi || "",
                sno_asperui_1: value.sno_asperui || value.uiSerialNo || "",
                asperuivalue_1: value.asperuivalue || value.uiValues || "",
                uiPageNo_1: value.uiPageNo || "",
                sliderStepValue_1: value.sliderStepValue || value.sliderStep || "",
                defaultvalue_1: value.defaultvalue || "",
                developerNotes_1: value.developerNotes || "",
                notificationEnable_1:
                  value.notificationEnable || "",
                notificationMessage_1: value.notificationMessage || value.message || "",
              }));

            const row = {
              bitwise: bitwise.length ? bitwise : null,
              startBytePosition: String(start),
              endBytePosition: String(Math.max(start, end - 1)),
              numberOfBytes: String(numberOfBytes),
              bitSize: String(numberOfBytes * 8),
              name: field.name || field.fieldName || "",
              fieldName: field.name || field.fieldName || "",
              fieldDescription: labels[key] || "",
              dataType: field.dataType || "",
              valueDefinition: field.valueDef || "",
              displayValueMin: field.displayValueMin || "0",
              displayValueMax: field.displayValueMax || "0",
              display_value_min: field.displayValueMin || "0",
              display_value_max: field.displayValueMax || "0",
              valueInHexMin: field.valueInHexMin || zeroHex,
              valueInHexMax: field.valueInHexMax || maxHex,
              uiType: field.uiType || "",
              uiId: field.uiId || "1",
              asperui: field.asperui || field.asperUi || "",
              sno_asperui: field.sno_asperui || field.uiSerialNo || "",
              asperuivalue: field.asperuivalue || field.uiValues || "",
              uiPageNo: field.uiPageNo || "",
              uiDescriptionInOut: field.uiInOut || "",
              sliderStepValue: field.sliderStepValue || field.sliderStep || "",
              defaultvalue: field.defaultvalue || "",
              developerNotes: field.developerNotes || "",
              notificationEnable:
                field.notificationEnable || "",
              notificationMessage: field.notificationMessage || field.message || "",
              scaling: field.scalling || "",
              bitwiseMode:
                partition.partitionViewModes?.[key] === "bitwise"
                  ? "Bitwise"
                  : "Bytewise",
            };
            return addSchemaRowAliases(row, prefix);
          });

          const direction = schemaDirectionLabel(
            frameConfiguration.dataFlowDirection,
          );
          const size = String(
            Math.max(1, Math.ceil(frameCode.length / 2)),
          );
          const codeProperty = `${frameType}Code`;

          return {
            parameterName,
            direction,
            size,
            triggerOptions: "None",
            frameType: frameTypeName,
            multipleui: frameConfiguration.multipleUi || "",
            triggerui:
              document.getElementById("triggerUiSelect")?.value || "false",
            voicecommand: voiceEnabled,
            voice_command: voiceEnabled,
            voicecontrol: voiceControlValue,
            voice_control: voiceControlValue,
            voiceCommands: clonePartitionObject(voiceCommands),
            voice_commands: clonePartitionObject(voiceCommands),
            frameCode,
            [codeProperty]: frameCode,
            valueGroups: clonePartitionObject(
              store.frameValueGroups[frameIndex] || [],
            ),
            partition: clonePartitionObject(partition),
            fieldDescriptions: clonePartitionObject(
              store.fieldDescriptions[frameIndex] || {},
            ),
            byteDescriptions: clonePartitionObject(
              store.byteDescriptions[frameIndex] || {},
            ),
            fieldViewModes: clonePartitionObject(
              store.fieldViewModes[frameIndex] || {},
            ),
            meta: {
              parametername: parameterName,
              noofrows: String(rows.length),
              dataflowdirection: direction,
              frametype: frameTypeName,
              framesize_bytes: size,
              frametrigger: "None",
              multipleui: frameConfiguration.multipleUi || "",
              triggerui:
                document.getElementById("triggerUiSelect")?.value || "",
              voicecommand: voiceEnabled,
              voice_command: voiceEnabled,
              voicecontrol: voiceControlValue,
              voice_control: voiceControlValue,
              voiceCommands: clonePartitionObject(voiceCommands),
              voice_commands: clonePartitionObject(voiceCommands),
            },
            rows,
          };
        });
      }

      function buildLocalConfiguration() {
        captureActiveFramePartitionState();
        saveActiveFrameTypeStore();

        const existing = serverApp.initialConfiguration || {};
        const commands = buildSchemaFrames("command", "cmd", "COMMAND");
        const responses = buildSchemaFrames("response", "resp", "RESPONSE");
        const errors = buildSchemaFrames("error", "error", "ERROR");
        const parameterName =
          document.getElementById("paramNameInput").value.trim();

        return {
          product: {
            itemid: String(serverApp.itemId),
            brandname: serverApp.product?.brandname || "",
            productname: serverApp.product?.productname || "",
            modelname: serverApp.product?.modelname || "",
            date:
              existing.product?.date ||
              new Date().toISOString().slice(0, 10),
            // UI-only compatibility: accept both NEW UI JSON keys and
            // the original OLD FORM/backend field names when restoring values.
            parameter_name:
              parameterName ||
              existing.product?.parameter_name ||
              existing.product?.parameterName ||
              existing.product?.parametername ||
              existing.product?.cmd_parametername ||
              "",
            page_number:
              existing.product?.page_number ||
              existing.product?.numberofpages ||
              existing.product?.pageNumber ||
              "",
            sequence_number:
              existing.product?.sequence_number ||
              existing.product?.Sequence ||
              existing.product?.sequenceNo ||
              "",
            command_frame_count: String(commands.length),
            response_frame_count: String(responses.length),
            error_frame_count: String(errors.length),
            page_names:
              existing.product?.page_names ||
              existing.product?.pagenames ||
              "",
            product_description:
              existing.product?.product_description ||
              existing.product?.productdescription ||
              "",
            editor_bytes: clonePartitionObject(bytes),
          },
          commands,
          responses,
          errors,
        };
      }

      let latestSavedJson = "";

      function downloadConfigurationJson(configurationOrJson) {
        const jsonText =
          typeof configurationOrJson === "string"
            ? configurationOrJson
            : JSON.stringify(configurationOrJson, null, 2);
        if (!jsonText) return;

        latestSavedJson = jsonText;
        const blob = new Blob([jsonText], {
          type: "application/json",
        });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        const parameterName =
          document.getElementById("paramNameInput")?.value?.trim() ||
          "configuration";
        link.href = url;
        link.download = `${parameterName.replace(
          /[^a-z0-9_-]+/gi,
          "_",
        )}_command-response-error.json`;
        document.body.appendChild(link);
        link.click();
        link.remove();
        window.setTimeout(() => URL.revokeObjectURL(url), 0);
      }

      function openJsonSavePopup(configuration) {
        const overlay = document.getElementById("jsonSaveOverlay");
        const output = document.getElementById("savedJsonOutput");
        const preview = document.getElementById("savedConfigurationPreview");
        const status = document.getElementById("jsonCopyStatus");
        const summary = document.getElementById("jsonSaveSummary");
        if (!overlay || !output || !preview || !status || !summary) {
          alert(JSON.stringify(configuration, null, 2));
          return;
        }
        latestSavedJson = JSON.stringify(configuration, null, 2);
        output.textContent = latestSavedJson;
        renderConfigurationPreview(configuration, preview);
        status.textContent = "";
        const entryCount = Object.keys(
          buildEditorConfiguration().entryData || {},
        ).length;
        const commandCount = configuration.commands?.length || 0;
        const responseCount = configuration.responses?.length || 0;
        const errorCount = configuration.errors?.length || 0;
        const frameCount = commandCount + responseCount + errorCount;
        summary.textContent = `${entryCount} entries and ${frameCount} frames (${commandCount} command, ${responseCount} response, ${errorCount} error) were stored in JSON format.`;
        overlay.classList.add("open");
        overlay.style.display = "flex";
        overlay.setAttribute("aria-hidden", "false");
        document.body.style.overflow = "hidden";
        document.getElementById("doneJsonSave")?.focus();
      }

      function renderConfigurationPreview(configuration, container) {
        container.replaceChildren();
        const product = configuration?.product || {};
        const commandFrames = Array.isArray(configuration?.commands)
          ? configuration.commands
          : [];
        const errorFrames = Array.isArray(configuration?.errors)
          ? configuration.errors
          : [];
        const responseFrames = Array.isArray(configuration?.responses)
          ? configuration.responses
          : [];

        const element = (tag, className, textValue) => {
          const node = document.createElement(tag);
          if (className) node.className = className;
          if (textValue !== undefined && textValue !== null) {
            node.textContent = String(textValue);
          }
          return node;
        };
        const value = (...candidates) => {
          const found = candidates.find(
            (candidate) =>
              candidate !== undefined &&
              candidate !== null &&
              String(candidate).trim() !== "",
          );
          return found === undefined ? "N/A" : String(found);
        };
        const isFilled = (candidate) =>
          candidate !== undefined &&
          candidate !== null &&
          String(candidate).trim() !== "" &&
          String(candidate).trim().toUpperCase() !== "N/A";

        const voiceCommandPhrasesForFrame = (frame) => {
          const candidates = [
            frame?.voiceCommands,
            frame?.voice_commands,
            frame?.voicecontrol,
            frame?.voice_control,
            frame?.meta?.voiceCommands,
            frame?.meta?.voice_commands,
            frame?.meta?.voicecontrol,
            frame?.meta?.voice_control,
          ];

          for (const candidate of candidates) {
            const commands = normalizeVoiceCommandList(candidate);
            if (commands.length) {
              return commands.join(" | ");
            }
          }

          return "N/A";
        };

        const summaryCard = element("section", "preview-summary-card");
        const summaryHead = element("div", "preview-summary-head");
        const headingCopy = element("div");
        headingCopy.append(
          element("h4", "", "Full Product Configuration Summary"),
          element(
            "p",
            "",
            "Organized by product, frame and field values.",
          ),
        );
        const badgeWrap = element("div", "preview-count-badges");
        [
          ["Command Frames", commandFrames.length],
          ["Response Frames", responseFrames.length],
          ["Error Frames", errorFrames.length],
        ].forEach(([label, count]) => {
          badgeWrap.append(
            element("span", "preview-count-badge", `${label}: ${count}`),
          );
        });
        summaryHead.append(headingCopy, badgeWrap);

        const productGrid = element("div", "preview-product-grid");
        const productFields = [
          ["Database Config ID", serverApp.id],
          ["Item ID", product.itemid],
          ["Brand Name", product.brandname, serverApp.product?.brandname],
          ["Product Name", product.productname, serverApp.product?.productname],
          ["Model Name", product.modelname, serverApp.product?.modelname],
          ["Version", product.version, serverApp.product?.version],
          ["Batch", product.batch, serverApp.product?.batch],
          ["Date", product.date],
          ["Parameter Name", product.parameter_name],
          ["Page Number", product.page_number],
          ["Sequence Number", product.sequence_number],
          ["Page Names", product.page_names],
          ["Description", product.product_description],
        ];
        productFields
          .filter((field) => isFilled(value(...field.slice(1))))
          .forEach((field, index, visibleFields) => {
          const fieldCard = element(
            "div",
            `preview-product-field${index === visibleFields.length - 1 ? " wide" : ""}`,
          );
          fieldCard.append(
            element("span", "preview-product-label", field[0]),
            element(
              "span",
              "preview-product-value",
              value(...field.slice(1)),
            ),
          );
          productGrid.append(fieldCard);
          });
        summaryCard.append(summaryHead, productGrid);
        container.append(summaryCard);

        const fieldRows = (frame, row, rowIndex) => {
          const bitwiseRows = Array.isArray(row?.bitwise)
            ? row.bitwise
            : [];
          const bitStart = value(
            row?.startBit,
            bitwiseRows[0]?.startBit,
          );
          const bitEnd = value(
            row?.endBit,
            bitwiseRows[0]?.endBit,
          );
          const range = (start, end) =>
            start === "N/A" && end === "N/A"
              ? "N/A"
              : `${start} : ${end}`;

          const bitwiseNames = bitwiseRows
            .map((bitRow) => {
              const candidates = [
                bitRow?.name_1,
                bitRow?.fieldName_1,
                bitRow?.field_name_1,
                bitRow?.name,
                bitRow?.fieldName,
                bitRow?.field_name,
              ];
              const found = candidates.find(
                (candidate) =>
                  candidate !== undefined &&
                  candidate !== null &&
                  String(candidate).trim() !== "",
              );
              return found === undefined ? "" : String(found).trim();
            })
            .filter(Boolean)
            .join(", ");

          return [
            ["Parameter Name", value(frame?.parameterName, frame?.meta?.parametername, product.parameter_name)],
            ["Data Flow Direction", value(frame?.direction, frame?.meta?.dataflowdirection)],
            ["Multiple UI", value(frame?.multipleui, frame?.multipleUi, frame?.meta?.multipleui)],
            ["Frame Type", value(frame?.frameType, frame?.meta?.frametype)],
            ["Frame Size Bytes", value(frame?.size, frame?.meta?.framesize_bytes)],
            ["Name", value(
              row?.name,
              row?.fieldName,
              row?.field_name,
              row?.cmd_name,
              row?.resp_name,
              row?.res_name,
              row?.error_name,
              row?.err_name,
              bitwiseNames,
            )],
            ["Description", value(row?.fieldDescription, row?.description)],
            ["Byte Range", range(value(row?.startBytePosition), value(row?.endBytePosition))],
            ["Bit Range", range(bitStart, bitEnd)],
            ["No. Bytes / Bits", value(row?.numberOfBytes, row?.numberOfBytes_1, row?.bitSize)],
            ["Bitwise Mode", value(row?.bitwiseMode)],
            ["Data Type", value(row?.dataType)],
            ["Value Definition", value(row?.valueDefinition)],
            ["Display Value Min", value(row?.displayValueMin)],
            ["Display Value Max", value(row?.displayValueMax)],
            ["Value In Hex Min", value(row?.valueInHexMin)],
            ["Value In Hex Max", value(row?.valueInHexMax)],
            ["UI Type", value(row?.uiType)],
            ["UI ID", value(row?.uiId)],
            ["As Per UI", value(row?.asperui)],
            ["UI Values", value(row?.asperuivalue)],
            ["UI Page No.", value(row?.uiPageNo)],
            ["UI In/Out", value(row?.uiDescriptionInOut)],
            ["Slider Step Value", value(row?.sliderStepValue)],
            ["Default Value", value(row?.defaultvalue)],
            ["Developer Notes", value(row?.developerNotes)],
            ["Notification Enable", value(row?.notificationEnable)],
            ["Notification Message", value(row?.notificationMessage)],
            ["Scaling", value(row?.scaling)],
          ].filter(([, fieldValue]) => isFilled(fieldValue));
        };

        const appendFrameSection = (title, frames) => {
          if (!frames.length) return;
          const section = element("section", "preview-frame-section");
          const titleBar = element("div", "preview-frame-section-title");
          titleBar.append(
            element("h4", "", title),
            element("span", "", `${frames.length} item(s)`),
          );
          section.append(titleBar);
          const frameList = element("div", "preview-frame-list");

          frames.forEach((frame, frameIndex) => {
            const frameCard = element("article", "preview-frame-card");
            const frameHead = element("div", "preview-frame-card-head");
            frameHead.append(
              element("span", "", `Frame ${String(frameIndex + 1).padStart(2, "0")}`),
              element(
                "span",
                "preview-frame-code",
                value(
                  frame?.frameCode,
                  frame?.commandCode,
                  frame?.responseCode,
                  frame?.errorCode,
                ),
              ),
            );
            frameCard.append(frameHead);

            const frameVoiceRows = [
              [
                "Voice Command",
                value(
                  frame?.voicecommand,
                  frame?.voice_command,
                  frame?.meta?.voicecommand,
                  frame?.meta?.voice_command,
                ),
              ],
              [
                "Voice Command Values",
                voiceCommandPhrasesForFrame(frame),
              ],
            ].filter(([, fieldValue]) => isFilled(fieldValue));

            if (frameVoiceRows.length) {
              const voiceTable = element("table", "preview-field-table");
              const voiceBody = document.createElement("tbody");

              frameVoiceRows.forEach(([label, fieldValue]) => {
                const tableRow = document.createElement("tr");
                tableRow.append(
                  element("th", "", label),
                  element("td", "", value(fieldValue)),
                );
                voiceBody.append(tableRow);
              });

              voiceTable.append(voiceBody);
              frameCard.append(voiceTable);
            }

            const rows =
              Array.isArray(frame?.rows) && frame.rows.length
                ? frame.rows
                : [{}];
            rows.forEach((row, rowIndex) => {
              const populatedFields = fieldRows(frame, row, rowIndex);
              if (!populatedFields.length) return;
              frameCard.append(
                element(
                  "div",
                  "preview-row-caption",
                  `Partition / Field ${rowIndex + 1}`,
                ),
              );
              const table = element("table", "preview-field-table");
              const body = document.createElement("tbody");
              populatedFields.forEach(([label, fieldValue]) => {
                const tableRow = document.createElement("tr");
                tableRow.append(
                  element("th", "", label),
                  element("td", "", value(fieldValue)),
                );
                body.append(tableRow);
              });
              table.append(body);
              frameCard.append(table);
            });
            frameList.append(frameCard);
          });
          section.append(frameList);
          container.append(section);
        };

        appendFrameSection("Command Frames", commandFrames);
        appendFrameSection("ErrorFrames", errorFrames);
        appendFrameSection("ResponseFrames", responseFrames);
      }

      function closeJsonSavePopup() {
        const overlay = document.getElementById("jsonSaveOverlay");
        if (!overlay) return;
        overlay.classList.remove("open");
        overlay.style.display = "";
        overlay.setAttribute("aria-hidden", "true");
        document.body.style.overflow = "";
        moveToCommandResponseErrorFlow(true);
      }

      function moveToCommandResponseErrorFlow(focusActiveStage = false) {
        const flow = document.getElementById("commandResponseErrorFlow");
        if (!flow) return;
        flow.classList.add("section-highlight");
        flow?.scrollIntoView({ behavior: "smooth", block: "center" });
        if (focusActiveStage) {
          flow
            .querySelector(".flow-stage.active")
            ?.focus({ preventScroll: true });
        }
        window.setTimeout(
          () => flow.classList.remove("section-highlight"),
          1200,
        );
      }

      function csrfRequestHeaders() {
        const headers = {
          "Content-Type": "application/json",
          Accept: "application/json",
          "X-Requested-With": "XMLHttpRequest",
        };
        const csrfHash =
          document.querySelector('meta[name="csrf-token-hash"]')?.content ||
          "";
        if (csrfHash && serverApp.csrfHeader) {
          headers[serverApp.csrfHeader] = csrfHash;
        }
        return headers;
      }

      function updateCsrfToken(result) {
        const nextHash =
          result?.csrfHash ||
          result?.csrf_hash ||
          result?.csrf?.hash ||
          "";
        const meta = document.querySelector('meta[name="csrf-token-hash"]');
        if (nextHash && meta) meta.content = nextHash;
      }

      async function persistConfiguration(message) {
        let configuration = buildLocalConfiguration();
        configuration = enforceLockedCommandOnConfiguration(configuration);
        const headers = csrfRequestHeaders();
        delete headers["Content-Type"];
        if (serverApp.id) {
          headers["X-Configuration-Id"] = String(serverApp.id);
        }

        const product = configuration.product || {};
        const formData = new FormData();
        formData.append("full_config_json", JSON.stringify(configuration));
        formData.append("config_id", serverApp.id ? String(serverApp.id) : "0");
        formData.append("itemid", product.itemid || String(serverApp.itemId || ""));
        formData.append("brandname", product.brandname || "");
        formData.append("productname", product.productname || "");
        formData.append("modelname", product.modelname || "");
        formData.append("date", product.date || "");
        formData.append("parameter_name", product.parameter_name || "");
        formData.append("page_number", product.page_number || "");
        formData.append("sequence_number", product.sequence_number || "");
        formData.append(
          "command_frame_count",
          product.command_frame_count || String(configuration.commands?.length || 0),
        );
        formData.append(
          "response_frame_count",
          product.response_frame_count || String(configuration.responses?.length || 0),
        );
        formData.append(
          "error_frame_count",
          product.error_frame_count || String(configuration.errors?.length || 0),
        );
        formData.append("page_names", product.page_names || "");
        formData.append(
          "product_description",
          product.product_description || "",
        );

        // ---------------------------------------------------------------
        // UI-ONLY OLD FORM BACKEND COMPATIBILITY
        // Keep the NEW UI/payload, but also submit every original product
        // field name expected by the working legacy form/controller.
        // ---------------------------------------------------------------
        formData.append("id", product.itemid || String(serverApp.itemId || ""));
        formData.append("parametername", product.parameter_name || "");
        formData.append("cmd_parametername", product.parameter_name || "");
        formData.append("numberofpages", product.page_number || "");
        formData.append("Sequence", product.sequence_number || "");
        formData.append("pagenames", product.page_names || "");
        formData.append("productdescription", product.product_description || "");

        const appendLegacyFrameMeta = (prefix, frames) => {
          const first = Array.isArray(frames) && frames.length ? frames[0] : {};
          const meta = first?.meta || {};
          formData.append(`${prefix}_parametername`, first?.parameterName || meta?.parametername || product.parameter_name || "");
          formData.append(`${prefix}_data_flow_direction`, first?.direction || meta?.dataflowdirection || "");
          formData.append(`${prefix}_frametype`, first?.frameType || meta?.frametype || "");
          formData.append(`${prefix}_framesizeinbytes`, first?.size || meta?.framesize_bytes || "");
          formData.append(`${prefix}_noofrows`, meta?.noofrows || String(first?.rows?.length || 0));
          formData.append(`${prefix}_frametrigger`, first?.triggerOptions || meta?.frametrigger || "None");
          formData.append(`${prefix}_multipleui`, first?.multipleui || meta?.multipleui || "false");
          formData.append(`${prefix}_triggerui`, first?.triggerui || meta?.triggerui || "false");
          const voiceEnabled = first?.voicecommand || first?.voice_command || meta?.voicecommand || meta?.voice_command || "No";
          const voiceControl = first?.voicecontrol || first?.voice_control || meta?.voicecontrol || meta?.voice_control || "";
          formData.append(`${prefix}_voice_command`, voiceEnabled);
          formData.append(`${prefix}_voicecommand`, voiceEnabled);
          formData.append(`${prefix}_voice_control_instruction`, voiceControl);
          formData.append(`${prefix}_voice_instruction`, voiceControl);
          formData.append(`${prefix}_voicecontrol`, voiceControl);
          formData.append(`${prefix}_remarks`, meta?.remarks || "");
        };

        appendLegacyFrameMeta("cmd", configuration.commands);
        appendLegacyFrameMeta("resp", configuration.responses);
        appendLegacyFrameMeta("error", configuration.errors);

        const response = await fetch(serverApp.saveUrl, {
          method: "POST",
          headers,
          body: formData,
          credentials: "same-origin",
        });
        const result = await response.json().catch(() => null);
        if (!response.ok || !result?.success) {
          throw new Error(
            result?.message ||
              `Database save failed (HTTP ${response.status}).`,
          );
        }

        updateCsrfToken(result);
        serverApp.id = Number(
          result.data?.configId ||
          result.data?.config_id ||
          result.config_id ||
          result.id ||
          serverApp.id,
        );

        if (serverApp.id) {
          serverApp.isEditMode = true;
        }

        const savedParameterSource =
          document.getElementById("parameterNameSourceSelect")?.value || "";
        const savedParameterName =
          document.getElementById("paramNameInput")?.value?.trim() || "";

        if (
          savedParameterSource === "existing" &&
          savedParameterName
        ) {
          USED_EXISTING_PARAMETER_NAMES.add(
            normalizeParameterLookup(savedParameterName),
          );
        }

        serverApp.initialConfiguration = configuration;
        if (serverApp.id) {
          serverApp.deleteUrl =
            `${<?= json_encode(site_url('items/delete_api_config')) ?>}/${serverApp.id}`;
          const deleteButton = document.getElementById(
            "deleteConfigurationBtn",
          );
          if (deleteButton) deleteButton.style.display = "";
        }

        const time = new Date().toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        });
        updateSaveBadge(
          "saved",
          `${result.message || message || "Configuration saved"}Â· ${time}`,
        );
        return configuration;
      }

      async function handleSaveConfiguration(event) {
        event?.preventDefault();
        event?.stopPropagation();

        /*
         * FINAL DUPLICATE CHECK
         * ---------------------
         * Re-read the saved API list immediately before Save so a parameter
         * selected in an older/open browser tab cannot be reused.
         */
        if (
          !COMMAND_GET_STATUS_EDIT_LOCKED &&
          document.getElementById("parameterNameSourceSelect")?.value ===
            "existing"
        ) {
          const selectedExistingParameter =
            document.getElementById("existingParameterNameSelect")?.value?.trim() ||
            "";

          await loadUsedExistingParameterNames();

          if (
            selectedExistingParameter &&
            isExistingParameterAlreadyUsed(selectedExistingParameter)
          ) {
            const existingSelect = document.getElementById(
              "existingParameterNameSelect",
            );

            if (existingSelect) {
              existingSelect.value = "";
              existingSelect.focus();
            }

            setCanonicalParameterName("", true);
            updateRequiredDropdownWarnings(true);
            updateSaveBadge(
              "error",
              "Existing Parameter is already used",
            );

            alert(
              `"${selectedExistingParameter}" is already selected by another API. Select another Existing Parameter.`,
            );

            return;
          }
        }

        captureActiveFramePartitionState();
        saveActiveFrameTypeStore();

        /*
         * SELECTED FRAME TYPE VALIDATION
         * ------------------------------
         * A frame type selected in row 2 is a promise that this API includes
         * that type. Therefore it must have at least one frame before Save.
         * This prevents selected Response/Error types with count = 0 from
         * silently bypassing all later validation loops.
         */
        const selectedFrameTypes = getIncludedFrameTypes();
        let firstSelectedTypeWithoutFrames = null;

        for (const frameType of selectedFrameTypes) {
          const store = frameTypeStores[frameType];
          const count = Math.max(0, Number(store?.count) || 0);

          if (count < 1) {
            firstSelectedTypeWithoutFrames = frameType;
            break;
          }
        }

        if (firstSelectedTypeWithoutFrames) {
          const frameType = firstSelectedTypeWithoutFrames;
          const frameLabel = FRAME_TYPE_LABELS[frameType];

          if (activeFrameType !== frameType) {
            switchFrameType(frameType, true);
          }

          const countInput = document.getElementById("cmdFrameCountInput");
          const countWrap = countInput?.closest(".input-with-icon");
          const selectedCard = document.querySelector(
            `.frame-choice-card[data-frame-choice="${frameType}"]`,
          );

          countWrap?.classList.add("input-error");
          countInput?.setAttribute("aria-invalid", "true");
          selectedCard?.classList.add("selected-frame-incomplete");

          const warningMessage =
            `${frameLabel} is selected. Enter the No. of Frames and complete at least one ${frameLabel.toLowerCase()} before saving the configuration.`;

          updateSaveBadge(
            "error",
            `${frameLabel} is incomplete`,
          );

          alert(warningMessage);

          const setupSection =
            document.getElementById("commandFramesSection") ||
            countInput?.closest(".section") ||
            countInput;

          setupSection?.scrollIntoView({
            behavior: "smooth",
            block: "center",
          });

          window.setTimeout(() => {
            countInput?.focus();
            countInput?.select?.();
          }, 350);

          return;
        }

        /*
         * FRAME SETTINGS VALIDATION COMES FIRST
         * ------------------------------------
         * After frames are generated, Data Flow Direction and Multiple UI
         * are the first required configuration choices. Show these missing
         * settings before asking for the frame Command Value.
         */
        let firstIncomplete = null;

        selectedFrameTypes.some((frameType) => {
          const store = frameTypeStores[frameType];
          const count = Math.max(0, Number(store?.count) || 0);

          for (let index = 0; index < count; index += 1) {
            const configuration =
              store?.frameConfigurations?.[index] || {};

            const commandDirectionOnly =
              COMMAND_GET_STATUS_EDIT_LOCKED && frameType === "command";
            if (
              !configuration.dataFlowDirection ||
              (!commandDirectionOnly && !configuration.multipleUi)
            ) {
              firstIncomplete = {
                frameType,
                index,
                configuration,
              };
              return true;
            }
          }

          return false;
        });

        if (firstIncomplete) {
          const { frameType, index } = firstIncomplete;

          if (activeFrameType !== frameType) {
            switchFrameType(frameType, true);
          }

          /*
           * switchFrameType() loads the selected store into the active
           * frameConfigurations array. Use the active values after switching.
           */
          const configuration =
            frameConfigurations?.[index] || {};

          const missingFrameSettings = [];

          if (!configuration.dataFlowDirection) {
            const directionSelect =
              document.getElementById(`frameDirection${index}`);

            directionSelect?.classList.add("frame-field-error");
            directionSelect?.setAttribute("aria-invalid", "true");

            missingFrameSettings.push({
              id: `frameDirection${index}`,
              label: "Data Flow Direction",
              icon: "fa-right-left",
            });
          }

          if (!(COMMAND_GET_STATUS_EDIT_LOCKED && frameType === "command") && !configuration.multipleUi) {
            const multipleUiControl =
              document.getElementById(`frameMultipleUi${index}`);

            multipleUiControl?.classList.add("frame-field-error");
            multipleUiControl?.setAttribute("aria-invalid", "true");

            missingFrameSettings.push({
              id: `frameMultipleUi${index}`,
              label: "Multiple UI",
              icon: "fa-window-restore",
            });
          }

          const frameLabel =
            `${FRAME_TYPE_LABELS[frameType]} Frame ${index + 1}`;

          updateSaveBadge(
            "error",
            `${frameLabel} settings are incomplete`,
          );

          showFrameSettingsValidationPopup(
            index,
            missingFrameSettings,
          );

          return;
        }

        /*
         * COMMAND VALUE VALIDATION COMES SECOND
         * ------------------------------------
         * Only after the required frame settings above are complete do we
         * validate the full Command/Response/Error frame value.
         */
        let firstInvalidCommandValue = null;
        Object.keys(FRAME_TYPE_LABELS).some((frameType) => {
          const store = frameTypeStores[frameType];
          let count = Math.max(0, Number(store?.count) || 0);

          /*
           * Defensive cleanup for old Edit records created before the frame
           * count fix. If Response/Error says count=1 but contains absolutely
           * no real frame data, treat it as zero instead of validating a
           * phantom frame.
           */
          if (
            frameType !== "command" &&
            count > 0 &&
            !isFrameTypeIncluded(frameType)
          ) {
            const hasRealFrame = Array.from(
              { length: count },
              (_, index) => {
                const code = cleanFullApi(
                  String(
                    store?.frameCodes?.[index] ||
                      store?.framePartitionStates?.[index]?.fullApiValue ||
                      "",
                  ),
                );

                const partition =
                  store?.framePartitionStates?.[index] || {};
                const configuration =
                  store?.frameConfigurations?.[index] || {};

                return Boolean(
                  code ||
                    partition?.partitionCuts?.length ||
                    Object.keys(partition?.partitionLabels || {}).length ||
                    Object.keys(
                      partition?.partitionFieldConfigurations || {},
                    ).length ||
                    configuration?.dataFlowDirection ||
                    configuration?.multipleUi
                );
              },
            ).some(Boolean);

            if (!hasRealFrame) {
              store.count = 0;
              count = 0;
            }
          }

          for (let index = 0; index < count; index += 1) {
            const commandValue = cleanFullApi(
              String(
                store?.frameCodes?.[index] ||
                  store?.framePartitionStates?.[index]?.fullApiValue ||
                  "",
              ),
            );

            if (!commandValue || commandValue.length % 2 !== 0) {
              firstInvalidCommandValue = {
                frameType,
                index,
                isEmpty: !commandValue,
              };
              return true;
            }
          }

          return false;
        });

        if (firstInvalidCommandValue) {
          const { frameType, index, isEmpty } = firstInvalidCommandValue;
          if (activeFrameType !== frameType) switchFrameType(frameType);

          activePartitionFrameIndex = index;
          selectedFrameIndex = index;
          awaitingFrameClick = false;
          loadFramePartitionState(index);

          const section = document.getElementById("apiPartitionSection");
          const commandInput = document.getElementById("fullApiInput");
          const commandInputWrap = commandInput?.closest(".input-with-icon");
          const apiError = document.getElementById("apiError");
          const frameLabel = `${FRAME_TYPE_LABELS[frameType]} Frame ${index + 1}`;
          const warningMessage = isEmpty
            ? `Enter the Command Value for ${frameLabel} before saving the configuration.`
            : `Complete the Command Value for ${frameLabel}. Every byte must contain exactly 2 hexadecimal characters.`;

          document
            .querySelectorAll(".command-frame-card")
            .forEach((card, cardIndex) => {
              card.classList.toggle("selected", cardIndex === index);
              card.classList.remove("awaiting-click");
            });
          section?.classList.add("frame-partition-active", "section-highlight");
          commandInputWrap?.classList.add("input-error");
          commandInput?.setAttribute("aria-invalid", "true");
          if (apiError) {
            apiError.innerHTML = `<i class="fas fa-triangle-exclamation" aria-hidden="true"></i><span>${warningMessage}</span>`;
          }
          updateSaveBadge("error", "Command Value is required");
          alert(warningMessage);
          section?.scrollIntoView({ behavior: "smooth", block: "start" });
          window.setTimeout(() => {
            section?.classList.remove("section-highlight");
            commandInput?.focus();
          }, 350);
          return;
        }

        // Validate every partition and its Field Configuration before saving.
        // This uses the stored state directly so all Command, Response and
        // Error frames are checked, not only the frame currently on screen.
        let firstIncompletePartition = null;
        Object.keys(FRAME_TYPE_LABELS).some((frameType) => {
          const store = frameTypeStores[frameType];
          const count = Math.max(0, Number(store?.count) || 0);

          // Command Get Status command configuration is protocol-owned.
          // Only Direction is editable, so its saved partitions/field values
          // must not be reopened or revalidated by the browser.
          if (COMMAND_GET_STATUS_EDIT_LOCKED && frameType === "command") {
            return false;
          }

          for (let frameIndex = 0; frameIndex < count; frameIndex += 1) {
            const state = store?.framePartitionStates?.[frameIndex] || {};
            const commandValue = cleanFullApi(
              String(
                store?.frameCodes?.[frameIndex] ||
                  state.fullApiValue ||
                  "",
              ),
            );
            const byteCount = commandValue.length / 2;
            const cuts = Array.isArray(state.partitionCuts)
              ? state.partitionCuts
                  .map(Number)
                  .filter(
                    (cut) =>
                      Number.isInteger(cut) &&
                      cut > 0 &&
                      cut < byteCount,
                  )
              : [];
            const boundaries = [
              0,
              ...new Set(cuts),
              byteCount,
            ].sort((a, b) => a - b);
            const labels = state.partitionLabels || {};
            const viewModes = state.partitionViewModes || {};
            const configurations =
              state.partitionFieldConfigurations || {};

            for (
              let partitionIndex = 0;
              partitionIndex < boundaries.length - 1;
              partitionIndex += 1
            ) {
              const start = boundaries[partitionIndex];
              const end = boundaries[partitionIndex + 1];
              const key = `${start}-${end}`;
              const partitionName = labels[key] || "";

              if (!partitionName) {
                firstIncompletePartition = {
                  frameType,
                  frameIndex,
                  partitionIndex,
                  message: `Select a name for Partition ${partitionIndex + 1}.`,
                };
                return true;
              }

              const currentView =
                partitionName === "data"
                  ? viewModes[key] || "bytewise"
                  : "bytewise";
              const partitionConfiguration = configurations[key] || {};

              if (currentView === "bytewise") {
                if (
                  !isFieldConfigurationComplete(
                    partitionConfiguration.byte,
                  )
                ) {
                  firstIncompletePartition = {
                    frameType,
                    frameIndex,
                    partitionIndex,
                    message:
                      "Open Configure Complete Partition, select Data Type, Value Definition, UI Type and UI In/Output, then click Save Field.",
                  };
                  return true;
                }
                continue;
              }

              const bitCount = (end - start) * 8;
              const bitCuts = Array.isArray(partitionConfiguration._bitCuts)
                ? partitionConfiguration._bitCuts
                    .map(Number)
                    .filter(
                      (cut) =>
                        Number.isInteger(cut) &&
                        cut > 0 &&
                        cut < bitCount,
                    )
                : [];
              const missingBitGroup = bitGroupsFromCuts(
                [...new Set(bitCuts)].sort((a, b) => a - b),
                bitCount,
              ).find(
                (group) =>
                  !isFieldConfigurationComplete(
                    partitionConfiguration[bitGroupConfigKey(group)],
                  ),
              );

              if (missingBitGroup) {
                firstIncompletePartition = {
                  frameType,
                  frameIndex,
                  partitionIndex,
                  message: `Configure ${bitGroupLabel(missingBitGroup)} and select all required Field Configuration values.`,
                };
                return true;
              }
            }
          }
          return false;
        });

        if (firstIncompletePartition) {
          const { frameType, frameIndex, partitionIndex, message } =
            firstIncompletePartition;
          if (activeFrameType !== frameType) switchFrameType(frameType);
          activePartitionFrameIndex = frameIndex;
          selectedFrameIndex = frameIndex;
          awaitingFrameClick = false;
          showPartitionWarnings = true;
          loadFramePartitionState(frameIndex);
          updateSaveBadge("error", "Field Configuration is incomplete");
          alert(
            `${FRAME_TYPE_LABELS[frameType]} Frame ${frameIndex + 1}, Partition ${partitionIndex + 1}: ${message}`,
          );
          document
            .getElementById("apiPartitionSection")
            ?.scrollIntoView({ behavior: "smooth", block: "start" });
          return;
        }

        const saveButton = document.getElementById("saveBtn");
        if (saveButton) {
          saveButton.disabled = true;
          saveButton.setAttribute("aria-busy", "true");
        }

        try {
          const savedConfiguration = await persistConfiguration(
            "Configuration saved",
          );
          moveToCommandResponseErrorFlow(true);

          // Let the user see the page move to the Command/Response/Error flow
          // before the existing saved-JSON confirmation popup is displayed.
          const popupDelay = window.matchMedia(
            "(prefers-reduced-motion: reduce)",
          ).matches
            ? 0
            : 550;
          window.setTimeout(
            () => openJsonSavePopup(savedConfiguration),
            popupDelay,
          );
        } catch (error) {
          console.error("Unable to save the API configuration.", error);
          updateSaveBadge("error", "Database save failed");
          alert(error.message || "The configuration could not be saved.");
        } finally {
          if (saveButton) {
            saveButton.disabled = false;
            saveButton.removeAttribute("aria-busy");
          }
        }
      }

      const saveConfigurationButton = document.getElementById("saveBtn");
      if (saveConfigurationButton) {
        saveConfigurationButton.addEventListener(
          "click",
          handleSaveConfiguration,
        );
      }

      document.getElementById("backBtn")?.addEventListener("click", function () {
        window.history.back();
      });

      document
        .getElementById("closeJsonSave")
        .addEventListener("click", closeJsonSavePopup);
      document
        .getElementById("doneJsonSave")
        .addEventListener("click", closeJsonSavePopup);
      document
        .getElementById("jsonSaveOverlay")
        .addEventListener("click", function (event) {
          if (event.target === this) closeJsonSavePopup();
        });
      document
        .getElementById("copySavedJson")
        .addEventListener("click", async function () {
          const status = document.getElementById("jsonCopyStatus");
          try {
            await navigator.clipboard.writeText(latestSavedJson);
            status.textContent = "JSON copied successfully.";
          } catch (error) {
            const selection = window.getSelection();
            const range = document.createRange();
            range.selectNodeContents(
              document.getElementById("savedJsonOutput"),
            );
            selection.removeAllRanges();
            selection.addRange(range);
            status.textContent = "JSON selected. Press Ctrl+C to copy.";
          }
        });
      document
        .getElementById("downloadSavedJson")
        .addEventListener("click", function () {
          downloadConfigurationJson(latestSavedJson);
        });
      document
        .getElementById("viewSavedApi")
        ?.addEventListener("click", function () {
          window.location.assign(serverApp.listUrl || serverApp.createUrl);
        });

      function normalizeConfigurationPayload(configuration) {
        const parseStoredJson = (value) => {
          if (value && typeof value === "object") return value;
          if (typeof value !== "string" || !value.trim()) return null;
          let candidate = value.trim();
          for (let attempt = 0; attempt < 4; attempt += 1) {
            try {
              const parsed = JSON.parse(candidate);
              if (parsed && typeof parsed === "object") return parsed;
              if (typeof parsed !== "string" || !parsed.trim()) return null;
              candidate = parsed.trim();
            } catch (error) {
              return null;
            }
          }
          return null;
        };
        const source = parseStoredJson(configuration);
        if (!source) return null;
        let normalized = source;
        for (let depth = 0; depth < 5; depth += 1) {
          const next =
            parseStoredJson(normalized.payload) ||
            parseStoredJson(normalized.configuration) ||
            parseStoredJson(normalized.full_config_json) ||
            parseStoredJson(normalized.configuration_json) ||
            parseStoredJson(normalized.config_json) ||
            parseStoredJson(normalized.data?.payload) ||
            parseStoredJson(normalized.data?.configuration) ||
            parseStoredJson(normalized.data?.full_config_json) ||
            parseStoredJson(normalized.data);
          if (!next || next === normalized) break;
          normalized = next;
        }
        if (!normalized || typeof normalized !== "object") {
          return null;
        }

        const product =
          parseStoredJson(normalized.product) ||
          parseStoredJson(source.product) ||
          {};
        const normalizeFrameList = (...candidates) => {
          for (const candidate of candidates) {
            const parsed = parseStoredJson(candidate);
            if (Array.isArray(parsed)) return parsed;
            if (parsed && typeof parsed === "object") {
              const numericEntries = Object.keys(parsed)
                .filter((key) => /^\d+$/.test(key))
                .sort((left, right) => Number(left) - Number(right))
                .map((key) => parsed[key]);
              if (numericEntries.length) return numericEntries;
              for (const containerKey of [
                "frames",
                "items",
                "records",
                "data",
                "rows",
                "details",
              ]) {
                const nested = parseStoredJson(parsed[containerKey]);
                if (Array.isArray(nested)) return nested;
              }
            }
          }
          return [];
        };
        let commands = normalizeFrameList(
          normalized.commands,
          normalized.commandFrames,
          normalized.command_frames,
          source.commands,
        );
        let responses = normalizeFrameList(
          normalized.responses,
          normalized.responseFrames,
          normalized.response_frames,
          source.responses,
        );
        let errors = normalizeFrameList(
          normalized.errors,
          normalized.errorFrames,
          normalized.error_frames,
          source.errors,
        );

        /*
         * EDIT FRAME RESTORE FIX
         * ----------------------
         * Command may use the legacy saved count because some old records keep
         * the command value in flat product fields and need one placeholder
         * frame for restoration.
         *
         * Response and Error are OPTIONAL. Their real arrays are authoritative.
         * Do NOT create empty frames from response_frame_count/error_frame_count
         * when there are no saved Response/Error frames.
         */
        const padCommandFramesToSavedCount = (
          frames,
          ...countCandidates
        ) => {
          const requestedCount = Math.min(
            20,
            Math.max(
              frames.length,
              0,
              ...countCandidates.map(
                (value) => Number.parseInt(value, 10) || 0,
              ),
            ),
          );

          const result = [...frames];

          while (result.length < requestedCount) {
            result.push({});
          }

          return result;
        };

        commands = padCommandFramesToSavedCount(
          commands,
          product.command_frame_count,
          product.commandFrameCount,
        );

        /*
         * IMPORTANT:
         * No padding for optional frame types.
         * [] must remain [] when the user never created those frames.
         */
        responses = Array.isArray(responses) ? responses : [];
        errors = Array.isArray(errors) ? errors : [];
        const flatCommandValue =
          product.command_value ||
          product.commandValue ||
          product.command_code ||
          product.commandCode ||
          product.full_api_value ||
          product.fullApiValue ||
          "";
        if (flatCommandValue && commands.length) {
          const firstCommand =
            commands[0] && typeof commands[0] === "object"
              ? commands[0]
              : {};
          if (
            !firstCommand.commandCode &&
            !firstCommand.frameCode &&
            !firstCommand.commandValue
          ) {
            commands[0] = {
              ...firstCommand,
              commandValue: flatCommandValue,
            };
          }
        }

        if (!Object.keys(product).length && !commands.length && !responses.length && !errors.length) {
          return null;
        }
        return {
          product: clonePartitionObject(product),
          commands: clonePartitionObject(commands),
          responses: clonePartitionObject(responses),
          errors: clonePartitionObject(errors),
        };
      }

      function schemaFramesToStore(frames, frameType) {
        const list = Array.isArray(frames)
          ? frames
          : frames && typeof frames === "object"
            ? Object.keys(frames)
              .filter((key) => /^\d+$/.test(key))
              .sort((left, right) => Number(left) - Number(right))
              .map((key) => frames[key])
            : [];
        const codeProperty = `${frameType}Code`;
        const parseFrameObject = (value) => {
          if (value && typeof value === "object") {
            return clonePartitionObject(value);
          }
          if (typeof value === "string" && value.trim()) {
            try {
              const parsed = JSON.parse(value);
              return parsed && typeof parsed === "object" ? parsed : {};
            } catch (error) {
              return {};
            }
          }
          return {};
        };
        const normalizedFrames = list.map((frame) => parseFrameObject(frame));
        const compactKey = (value) =>
          String(value || "")
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9]/g, "");
        const readAliasedValue = (
          source,
          aliases,
          maxDepth = 3,
          depth = 0,
          visited = new Set(),
        ) => {
          if (
            !source ||
            typeof source !== "object" ||
            depth > maxDepth ||
            visited.has(source)
          ) {
            return undefined;
          }
          visited.add(source);
          const aliasKeys = new Set(aliases.map(compactKey));
          for (const [key, value] of Object.entries(source)) {
            if (aliasKeys.has(compactKey(key)) && value !== null && value !== "") {
              return value;
            }
          }
          for (const [key, value] of Object.entries(source)) {
            if (
              ["rows", "bitwise", "fields"].includes(compactKey(key)) ||
              !value ||
              typeof value !== "object"
            ) {
              continue;
            }
            const found = readAliasedValue(
              value,
              aliases,
              maxDepth,
              depth + 1,
              visited,
            );
            if (found !== undefined) return found;
          }
          return undefined;
        };
        const readRowValue = (row, key) => {
          const prefixes = {
            command: "cmd",
            response: "resp",
            error: "error",
          };
          const value = readAliasedValue(
            row,
            [
              key,
              `${prefixes[frameType]}_${key}`,
              `${prefixes[frameType]}${key}`,
            ],
            1,
          );
          return value ?? "";
        };
        const normalizePartitionName = (value) => {
          const compact = String(value || "")
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9]/g, "");
          const match = API_PARTITION_OPTIONS.find(
            (option) =>
              option.value.toLowerCase().replace(/[^a-z0-9]/g, "") === compact ||
              option.label.toLowerCase().replace(/[^a-z0-9]/g, "") === compact,
          );
          if (match) return match.value;
          if (compact === "commandid") return "commandId";
          if (compact === "functioncode") return "functionCode";

          /*
           * Preserve old "Data" while allowing the new explicit "Payload".
           * Existing saved Data remains Data; saved Payload remains Payload.
           */
          if (compact === "data") return "data";
          if (compact === "payload") return "payload";

          if (compact === "errorcode") return "errorCode";
          if (compact === "deviceid") return "deviceId";

          if (
            compact === "terminator" ||
            compact === "crc" ||
            compact === "terminatorcrc"
          ) {
            return "terminatorCrc";
          }
          return "";
        };
        const rowToConfiguration = (row, suffix = "") => ({
          dataType:
            readRowValue(row, `dataType${suffix}`) ||
            row?.[`dataType${suffix}`] ||
            "",
          valueDef:
            readRowValue(row, `valueDefinition${suffix}`) ||
            row?.[`valueDefinition${suffix}`] ||
            "",
          uiType:
            readRowValue(row, `uiType${suffix}`) ||
            row?.[`uiType${suffix}`] ||
            "",
          uiInOut:
            readRowValue(row, `uiDescriptionInOut${suffix}`) ||
            row?.[`uiDescriptionInOut${suffix}`] ||
            "",
          scalling:
            readRowValue(row, `scaling${suffix}`) ||
            row?.[`scaling${suffix}`] ||
            "",
          displayValueMin:
            readRowValue(row, `displayValueMin${suffix}`) ||
            row?.[`displayValueMin${suffix}`] ||
            "",
          displayValueMax:
            readRowValue(row, `displayValueMax${suffix}`) ||
            row?.[`displayValueMax${suffix}`] ||
            "",
          valueInHexMin:
            readRowValue(row, `valueInHexMin${suffix}`) ||
            row?.[`valueInHexMin${suffix}`] ||
            "",
          valueInHexMax:
            readRowValue(row, `valueInHexMax${suffix}`) ||
            row?.[`valueInHexMax${suffix}`] ||
            "",
          uiId:
            readRowValue(row, `uiId${suffix}`) ||
            row?.[`uiId${suffix}`] ||
            "",
          asperui:
            readRowValue(row, `asperui${suffix}`) ||
            row?.[`asperui${suffix}`] ||
            "",
          sno_asperui:
            readRowValue(row, `sno_asperui${suffix}`) ||
            row?.[`sno_asperui${suffix}`] ||
            "",
          asperuivalue:
            readRowValue(row, `asperuivalue${suffix}`) ||
            row?.[`asperuivalue${suffix}`] ||
            "",
          uiPageNo:
            readRowValue(row, `uiPageNo${suffix}`) ||
            row?.[`uiPageNo${suffix}`] ||
            "",
          sliderStepValue:
            readRowValue(row, `sliderStepValue${suffix}`) ||
            row?.[`sliderStepValue${suffix}`] ||
            "",
          defaultvalue:
            readRowValue(row, `defaultvalue${suffix}`) ||
            row?.[`defaultvalue${suffix}`] ||
            "",
          developerNotes:
            readRowValue(row, `developerNotes${suffix}`) ||
            row?.[`developerNotes${suffix}`] ||
            "",
          name:
            readRowValue(row, `name${suffix}`) ||
            readRowValue(row, `fieldName${suffix}`) ||
            row?.[`name${suffix}`] ||
            row?.[`fieldName${suffix}`] ||
            "",
          fieldName:
            readRowValue(row, `fieldName${suffix}`) ||
            readRowValue(row, `name${suffix}`) ||
            row?.[`fieldName${suffix}`] ||
            row?.[`name${suffix}`] ||
            "",
          notificationEnable:
            readRowValue(row, `notificationEnable${suffix}`) ||
            readRowValue(row, `notifEnable${suffix}`) ||
            row?.[`notificationEnable${suffix}`] ||
            row?.[`notifEnable${suffix}`] ||
            "No",
          notificationMessage:
            readRowValue(row, `notificationMessage${suffix}`) ||
            readRowValue(row, `notifMsg${suffix}`) ||
            row?.[`notificationMessage${suffix}`] ||
            row?.[`notifMsg${suffix}`] ||
            "",
        });
        const rebuildPartitionFromRows = (frame, frameCode) => {
          const rawRows = readAliasedValue(
            frame,
            [
              "rows",
              "frameRows",
              "rowData",
              "partitionRows",
              `${frameType}Rows`,
              `${frameType}_rows`,
            ],
            2,
          );
          const parsedRows = parseFrameObject(rawRows || []);
          const rows = Array.isArray(parsedRows)
            ? parsedRows.map(parseFrameObject)
            : [];
          if (!rows.length) return {};

          const partitionLabels = {};
          const partitionViewModes = {};
          const partitionFieldConfigurations = {};
          const partitionCuts = [];
          let inferredByteCount = Math.ceil(frameCode.length / 2);

          rows.forEach((row, rowIndex) => {
            const rawStart = Number.parseInt(
              readRowValue(row, "startBytePosition"),
              10,
            );
            const rawEnd = Number.parseInt(
              readRowValue(row, "endBytePosition"),
              10,
            );
            const byteCount = Math.max(
              1,
              Number.parseInt(readRowValue(row, "numberOfBytes"), 10) || 1,
            );
            const start = Number.isFinite(rawStart) ? rawStart : rowIndex;
            const endExclusive = Number.isFinite(rawEnd)
              ? Math.max(start + 1, rawEnd + 1)
              : start + byteCount;
            const key = `${start}-${endExclusive}`;
            inferredByteCount = Math.max(inferredByteCount, endExclusive);
            if (start > 0) partitionCuts.push(start);

            partitionLabels[key] = normalizePartitionName(
              readRowValue(row, "fieldDescription"),
            );
            const parsedBitwise = parseFrameObject(
              readAliasedValue(
                row,
                ["bitwise", "bitwiseRows", "bitRows", "bits"],
                2,
              ) || [],
            );
            const bitwiseRows = Array.isArray(parsedBitwise)
              ? parsedBitwise
              : [];
            const isBitwise =
              String(readRowValue(row, "bitwiseMode"))
                .trim()
                .toLowerCase() === "bitwise" ||
              bitwiseRows.length > 0;
            partitionViewModes[key] = isBitwise ? "bitwise" : "bytewise";
            partitionFieldConfigurations[key] = {
              byte: rowToConfiguration(row),
            };

            if (isBitwise && bitwiseRows.length) {
              const bitCuts = new Set();
              const bitCount = Math.max(8, (endExclusive - start) * 8);
              bitwiseRows.forEach((rawBitRow) => {
                const bitRow = parseFrameObject(rawBitRow);
                const startValue = String(
                  bitRow.startBytePosition_1 ??
                    bitRow.startBit ??
                    bitRow.start_bit ??
                    "0",
                );
                const endValue = String(
                  bitRow.endBytePosition_1 ??
                    bitRow.endBit ??
                    bitRow.end_bit ??
                    startValue,
                );
                const startMatch = startValue.match(/\d+/g);
                const endMatch = endValue.match(/\d+/g);
                const isEncodedGroup =
                  /bit[\s_-]*group/i.test(startValue) &&
                  startMatch?.length >= 2;
                const startBit = isEncodedGroup
                  ? Number(startMatch[0])
                  : startMatch
                    ? Number(startMatch[startMatch.length - 1])
                    : 0;
                const endBit = isEncodedGroup
                  ? Number(startMatch[startMatch.length - 1])
                  : endMatch
                    ? Number(endMatch[endMatch.length - 1])
                    : startBit;
                const lowBit = Math.max(0, Math.min(startBit, endBit));
                const highBit = Math.min(
                  bitCount - 1,
                  Math.max(startBit, endBit),
                );
                const positions = Array.from(
                  { length: highBit - lowBit + 1 },
                  (_, index) => lowBit + index,
                );
                const configKey =
                  positions.length === 1
                    ? `bit:${positions[0]}`
                    : `bit-group:${positions[0]}-${positions[positions.length - 1]}`;
                partitionFieldConfigurations[key][configKey] = {
                  ...rowToConfiguration(bitRow, "_1"),
                  bitPosition:
                    positions.length === 1 ? positions[0] : null,
                  bitPositions: positions,
                };
                if (lowBit > 0) bitCuts.add(lowBit);
                if (highBit + 1 < bitCount) bitCuts.add(highBit + 1);
              });
              partitionFieldConfigurations[key]._bitCuts = [...bitCuts].sort(
                (a, b) => a - b,
              );
            }
          });

          const normalizedCode = frameCode || "";
          const valueGroups = Object.keys(partitionLabels).map((key) => {
            const [start, end] = key.split("-").map(Number);
            return normalizedCode.slice(start * 2, end * 2);
          });
          return {
            fullApiValue: normalizedCode,
            partitionCuts: [...new Set(partitionCuts)].sort((a, b) => a - b),
            partitionLabels,
            partitionViewModes,
            partitionFieldConfigurations,
            selectedBitGroups: {},
            partitionsConfirmed: Object.values(partitionLabels).every(Boolean),
            valueGroups,
            inferredByteCount,
          };
        };
        const resolvedFrameCodes = normalizedFrames.map((frame) => {
          const rawGroups = readAliasedValue(
            frame,
            ["valueGroups", "value_groups", "hexGroups", "byteValues"],
            2,
          );
          const parsedGroups = parseFrameObject(rawGroups || []);
          const groups = Array.isArray(parsedGroups)
            ? parsedGroups
            : [];
          const codeValue = readAliasedValue(
            frame,
            [
              codeProperty,
              `${frameType}_code`,
              `${frameType}Value`,
              `${frameType}_value`,
              "frameCode",
              "frame_code",
              "commandValue",
              "command_value",
              "apiValue",
              "api_value",
              "fullApiValue",
              "full_api_value",
              "fullApi",
              "hexValue",
              "hex_value",
            ],
            4,
          );
          return String(codeValue ?? groups.join("") ?? "")
            .replace(/[^0-9a-f]/gi, "")
            .toUpperCase();
        });
        const resolvedPartitions = normalizedFrames.map((frame, index) => {
          const savedPartition = parseFrameObject(
            frame?.partition ||
              frame?.partitionState ||
              frame?.partition_state ||
              frame?.editorPartition ||
              {},
          );
          return Object.keys(savedPartition).length
            ? savedPartition
            : rebuildPartitionFromRows(frame, resolvedFrameCodes[index]);
        });
        const firstFrame = normalizedFrames[0] || {};
        const firstMeta = firstFrame?.meta || {};
        const restoredVoiceCommands = normalizeVoiceCommandList(
          firstFrame?.voiceCommands ??
          firstFrame?.voice_commands ??
          firstFrame?.voicecontrol ??
          firstFrame?.voice_control ??
          firstMeta?.voiceCommands ??
          firstMeta?.voice_commands ??
          firstMeta?.voicecontrol ??
          firstMeta?.voice_control ??
          "",
        );
        const restoredVoiceEnabled = normalizeVoiceCommandEnabled(
          firstFrame?.voicecommand ??
          firstFrame?.voice_command ??
          firstMeta?.voicecommand ??
          firstMeta?.voice_command ??
          "",
          restoredVoiceCommands,
        );

        return {
          count: normalizedFrames.length,
          voiceCommandEnabled: restoredVoiceEnabled,
          voiceCommands: restoredVoiceCommands,
          frameCodes: resolvedFrameCodes,
          frameValueGroups: normalizedFrames.map((frame, index) => {
            const groups = parseFrameObject(frame?.valueGroups || []);
            return Array.isArray(groups) && groups.length
              ? groups
              : resolvedPartitions[index]?.valueGroups || [];
          }),
          fieldDescriptions: Object.fromEntries(
            normalizedFrames.map((frame, index) => [
              index,
              parseFrameObject(frame?.fieldDescriptions || {}),
            ]),
          ),
          byteDescriptions: Object.fromEntries(
            normalizedFrames.map((frame, index) => [
              index,
              parseFrameObject(frame?.byteDescriptions || {}),
            ]),
          ),
          fieldViewModes: Object.fromEntries(
            normalizedFrames.map((frame, index) => [
              index,
              parseFrameObject(frame?.fieldViewModes || {}),
            ]),
          ),
          framePartitionStates: resolvedPartitions,
          frameConfigurations: normalizedFrames.map((frame) => ({
            dataFlowDirection: normalizeDirectionValue(
              frame?.direction ||
              frame?.dataFlowDirection ||
              frame?.dataflowdirection ||
              frame?.meta?.dataflowdirection ||
              "",
            ),
            multipleUi: String(
              frame?.multipleui ??
              frame?.multipleUi ??
              frame?.meta?.multipleui ??
              "",
            ).toLowerCase(),
          })),
        };
      }

      function schemaToEditorSaved(configuration) {
        const schema = normalizeConfigurationPayload(configuration);
        if (!schema) return null;
        return {
          storageVersion: 3,
          savedAt: schema.product.date || "",
          form: {
            parameterName:
              schema.product.parameter_name ||
              schema.product.parameterName ||
              schema.commands[0]?.parameterName ||
              schema.commands[0]?.parametername ||
              schema.commands[0]?.meta?.parametername ||
              "",
            commandFrameCount: schema.commands.length,
            responseFrameCount: schema.responses.length,
            errorFrameCount: schema.errors.length,
            triggerUi:
              schema.commands[0]?.triggerui ||
              schema.responses[0]?.triggerui ||
              schema.errors[0]?.triggerui ||
              "",
          },
          activeFrameType:
            schema.commands.length > 0
              ? "command"
              : schema.responses.length > 0
                ? "response"
                : schema.errors.length > 0
                  ? "error"
                  : "command",
          bytes: clonePartitionObject(schema.product.editor_bytes || []),
          frameTypeStores: {
            command: schemaFramesToStore(schema.commands, "command"),
            response: schemaFramesToStore(schema.responses, "response"),
            error: schemaFramesToStore(schema.errors, "error"),
          },
        };
      }

      function restoreSavedConfiguration(
        configuration = serverApp.initialConfiguration,
      ) {
        const saved = schemaToEditorSaved(configuration);
        if (!saved || !saved.form) return false;

        document.getElementById("paramNameInput").value =
          saved.form.parameterName || "";
        syncParameterNameChooserFromCanonical({ dispatchInput: false });
        if (document.getElementById("triggerUiSelect")) {
          document.getElementById("triggerUiSelect").value =
            saved.form.triggerUi || "";
        }
        bytes =
          Array.isArray(saved.bytes) && saved.bytes.length
            ? clonePartitionObject(saved.bytes)
            : bytes;
        if (!bytes.length) {
          const allCodes = Object.values(saved.frameTypeStores || {})
            .flatMap((store) => store?.frameCodes || []);
          const inferredByteCount = Math.max(
            8,
            ...allCodes.map((code) =>
              Math.ceil(String(code || "").replace(/[^0-9a-f]/gi, "").length / 2),
            ),
          );
          bytes = Array.from({ length: inferredByteCount }, (_, index) => ({
            id: index,
            value: generateByteValue(index),
            active: false,
          }));
        }
        if (saved.storageVersion === 3 && saved.frameTypeStores) {
          Object.keys(FRAME_TYPE_LABELS).forEach((frameType) => {
            const restoredStore =
              saved.frameTypeStores[frameType] || createEmptyFrameTypeStore();
            frameTypeStores[frameType] = {
              count: parseInt(restoredStore.count, 10) || 0,
              frameCodes: clonePartitionObject(
                restoredStore.frameCodes || [],
              ),
              frameValueGroups: clonePartitionObject(
                restoredStore.frameValueGroups || [],
              ),
              fieldDescriptions: clonePartitionObject(
                restoredStore.fieldDescriptions || {},
              ),
              byteDescriptions: clonePartitionObject(
                restoredStore.byteDescriptions || {},
              ),
              fieldViewModes: clonePartitionObject(
                restoredStore.fieldViewModes || {},
              ),
              framePartitionStates: clonePartitionObject(
                restoredStore.framePartitionStates || [],
              ),
              frameConfigurations: clonePartitionObject(
                restoredStore.frameConfigurations || [],
              ),
              voiceCommandEnabled: normalizeVoiceCommandEnabled(
                restoredStore.voiceCommandEnabled || "No",
                restoredStore.voiceCommands || [],
              ),
              voiceCommands: normalizeVoiceCommandList(
                restoredStore.voiceCommands || [],
              ),
            };
          });
          activeFrameType = FRAME_TYPE_LABELS[saved.activeFrameType]
            ? saved.activeFrameType
            : "command";
        } else {
          frameTypeStores.command = {
            count:
              parseInt(saved.form.commandFrameCount, 10) ||
              saved.frameCodes?.length ||
              saved.commandFrames?.length ||
              0,
            frameCodes: clonePartitionObject(saved.frameCodes || []),
            frameValueGroups: clonePartitionObject(
              saved.frameValueGroups || [],
            ),
            fieldDescriptions: clonePartitionObject(
              saved.fieldDescriptions || {},
            ),
            byteDescriptions: clonePartitionObject(
              saved.byteDescriptions || {},
            ),
            fieldViewModes: clonePartitionObject(saved.fieldViewModes || {}),
            framePartitionStates: clonePartitionObject(
              saved.framePartitionStates || [],
            ),
            frameConfigurations: Array.isArray(saved.frameConfigurations)
              ? clonePartitionObject(saved.frameConfigurations)
              : Array.isArray(saved.commandFrames)
                ? saved.commandFrames.map((frame) => ({
                    dataFlowDirection:
                      frame.dataFlowDirection ||
                      saved.form.dataFlowDirection ||
                      "",
                    multipleUi:
                      frame.multipleUi || saved.form.multipleUi || "",
                  }))
                : [],
            voiceCommandEnabled: normalizeVoiceCommandEnabled(
              saved.form.voiceCommandEnabled ||
                saved.form.voicecommand ||
                saved.form.voice_command ||
                "No",
              saved.form.voiceCommands || [],
            ),
            voiceCommands: normalizeVoiceCommandList(
              saved.form.voiceCommands ||
                saved.form.voicecontrol ||
                saved.form.voice_control ||
                [],
            ),
          };
          activeFrameType = "command";
        }
        enforceCommandGetStatusCommandState(false);
        initializeFrameInclusionFromStores();
        loadFrameTypeStore(activeFrameType);
        updateFrameTypeUi();
        syncCommandGetStatusLockUi();

        selectedFrameIndex = null;
        activePartitionFrameIndex = null;
        fullApiValue = "";
        hexEditorDraftBytes = [""];
        hexEditorDraftIsIncomplete = false;
        restoredByteCount = 0;
        partitionCuts = [];
        partitionLabels = {};
        partitionViewModes = {};
        partitionFieldConfigurations = {};
        selectedBitGroups = {};
        partitionsConfirmed = false;

        const savedCount = Math.min(
          20,
          Math.max(
            0,
            frameTypeStores[activeFrameType].count || frameCodes.length || 0,
          ),
        );
        document.getElementById("cmdFrameCountInput").value = savedCount;
        // Edit restoration must not depend on the Add-form Generate
        // validation. Saved cards are rendered directly from the database
        // payload even when a legacy row has a missing optional value.
        if (savedCount > 0 && bytes.length > 0) {
          generateCommandFrames(savedCount, true);
        } else {
          document.getElementById("commandFramesContainer").innerHTML = "";
          updateCommandFrameCount();
        }
        renderApiPartitionEditor();
        updateFramePartitionStates();
        updateFieldDescFrameSelect();
        renderFieldDescription();

        // In Edit mode, reveal the first saved frame automatically. This
        // makes its partitions and field/bit settings visible without
        // requiring the user to click the frame card first.
        if (savedCount > 0) {
          const firstSavedFrameIndex = framePartitionStates.findIndex(
            (state, index) =>
              Boolean(
                frameCodes[index] ||
                state?.fullApiValue ||
                state?.partitionCuts?.length ||
                Object.keys(state?.partitionLabels || {}).length ||
                Object.keys(state?.partitionFieldConfigurations || {}).length,
              ),
          );
          const frameIndex =
            firstSavedFrameIndex >= 0 ? firstSavedFrameIndex : 0;
          activePartitionFrameIndex = frameIndex;
          selectedFrameIndex = frameIndex;
          loadFramePartitionState(frameIndex);
          document
            .getElementById("apiPartitionSection")
            ?.classList.add("frame-partition-active");
          document
            .querySelectorAll("#commandFramesContainer .command-frame-card")
            .forEach((card, index) => {
              card.classList.toggle("selected", index === frameIndex);
            });
          const fieldFrameSelect =
            document.getElementById("fieldDescFrameSelect");
          if (fieldFrameSelect?.querySelector(`option[value="${frameIndex}"]`)) {
            fieldFrameSelect.value = String(frameIndex);
          }
          renderFieldDescription();
        }

        const savedDate = saved.savedAt ? new Date(saved.savedAt) : null;
        const time =
          savedDate && !Number.isNaN(savedDate.getTime())
            ? savedDate.toLocaleTimeString([], {
              hour: "2-digit",
              minute: "2-digit",
            })
            : "";
        updateSaveBadge(
          "saved",
          time
            ? `Loaded database configuration  ${time}`
            : "Loaded database configuration", 
        );
        return true;
      }

      async function loadEditConfiguration() {
        if (!serverApp.id || !serverApp.readUrl) return false;
        updateSaveBadge("saving", "Loading saved configuration...");
        try {
          const response = await fetch(serverApp.readUrl, {
            method: "GET",
            headers: {
              Accept: "application/json",
              "X-Requested-With": "XMLHttpRequest",
            },
            credentials: "same-origin",
          });
          const result = await response.json().catch(() => null);
          if (!response.ok || !result?.success) {
            throw new Error(
              result?.message || "The saved API configuration could not be loaded.",
            );
          }
          updateCsrfToken(result);
          serverApp.initialConfiguration = normalizeConfigurationPayload(
            result.data?.configuration ||
            result.configuration ||
            result.data ||
            result,
          );
          return restoreSavedConfiguration(serverApp.initialConfiguration);
        } catch (error) {
          console.error("Unable to load the API configuration.", error);
          updateSaveBadge("error", "Could not load saved configuration");
          alert(error.message || "The saved API configuration could not be loaded.");
          return false;
        }
      }

      function captureActiveFramePartitionState() {
        if (!Number.isInteger(activePartitionFrameIndex)) return;
        framePartitionStates[activePartitionFrameIndex] = {
          fullApiValue,
          inferredByteCount:
            fullApiValue.length > 0
              ? Math.ceil(fullApiValue.length / 2)
              : restoredByteCount,
          partitionCuts: [...partitionCuts],
          partitionLabels: clonePartitionObject(partitionLabels),
          partitionViewModes: clonePartitionObject(partitionViewModes),
          partitionFieldConfigurations: clonePartitionObject(
            partitionFieldConfigurations,
          ),
          selectedBitGroups: clonePartitionObject(selectedBitGroups),
          partitionsConfirmed: Boolean(partitionsConfirmed),
        };
      }

      function resetHexEditorDraftFromApiValue() {
        const savedBytes = normalizeHex(String(fullApiValue || ""))
          .match(/[0-9A-F]{2}/g) || [];
        if (savedBytes.length) {
          hexEditorDraftBytes = savedBytes;
        } else {
          fullApiValue = "00";
          hexEditorDraftBytes = ["00"];
        }
        hexEditorDraftIsIncomplete = false;
      }

      function loadFramePartitionState(frameIndex) {
        const saved = framePartitionStates[frameIndex] || {};
        fullApiValue = saved.fullApiValue || frameCodes[frameIndex] || "";
        resetHexEditorDraftFromApiValue();


        restoredByteCount = fullApiValue
          ? Math.ceil(fullApiValue.length / 2)
          : Math.max(
              0,
              Number.parseInt(
                saved.inferredByteCount ??
                  saved.byteCount ??
                  saved.frameSizeBytes ??
                  0,
                10,
              ) || 0,
            );
        partitionCuts = Array.isArray(saved.partitionCuts)
          ? [...saved.partitionCuts]
          : [];
        partitionLabels = clonePartitionObject(saved.partitionLabels);
        partitionViewModes = clonePartitionObject(saved.partitionViewModes);
        partitionFieldConfigurations = clonePartitionObject(
          saved.partitionFieldConfigurations,
        );
        selectedBitGroups = clonePartitionObject(saved.selectedBitGroups);
        partitionsConfirmed = Boolean(saved.partitionsConfirmed);
        if (isCommandGetStatusCommandLocked()) {
          fullApiValue = COMMAND_GET_STATUS_FIXED_VALUE;
          hexEditorDraftBytes = COMMAND_GET_STATUS_FIXED_BYTES.slice();
          hexEditorDraftIsIncomplete = false;
          restoredByteCount = 3;
        } else if (isCommandGetStatusResponseFrame()) {
          const responseBytes = getCommandGetStatusResponseDraftBytes();
          syncCommandGetStatusResponseValue(responseBytes, false);
        }
        enforceCommandGetStatusPartitionRules();
        document.getElementById("fullApiInput").value = fullApiValue;
        document.getElementById("partitionStepFrameName").textContent =
          `${getActiveFrameLabel()} Frame ${frameIndex + 1}`;
        renderApiPartitionEditor();
      }

      function getFrameFillStatus(frameIndex) {
        const confirmed = Boolean(
          framePartitionStates[frameIndex]?.partitionsConfirmed,
        );
        if (confirmed) return "filled";
        const hasApi = Boolean(
          (frameCodes[frameIndex] || "").trim() ||
          framePartitionStates[frameIndex]?.fullApiValue,
        );
        if (hasApi) return "in-progress";
        return "pending";
      }

      function updateFramePartitionStates() {
        document
          .querySelectorAll("#commandFramesContainer .command-frame-card")
          .forEach((card, index) => {
            const status = getFrameFillStatus(index);
            card.classList.toggle("partition-complete", status === "filled");
            card.classList.toggle("needs-partition", status === "pending");
            card.classList.toggle("frame-in-progress", status === "in-progress");
            const badge = card.querySelector(".frame-status-badge");
            const state = card.querySelector(".frame-partition-state");
            if (badge) {
              if (status === "filled") {
                badge.className = "frame-status-badge filled";
                badge.innerHTML =
                  '<i class="fas fa-circle-check"></i> Filled';
              } else if (status === "in-progress") {
                badge.className = "frame-status-badge in-progress";
                badge.innerHTML =
                  '<i class="fas fa-spinner"></i> In progress';
              } else {
                badge.className = "frame-status-badge pending";
                badge.innerHTML =
                  '<i class="fas fa-hourglass-half"></i> Pending';
              }
            }
            if (state) {
              if (status === "filled") {
                state.hidden = false;
                state.className = "frame-partition-state complete";
                state.innerHTML =
                  '<i class="fas fa-circle-check"></i> API partitioned';
              } else if (status === "in-progress") {
                state.hidden = false;
                state.className = "frame-partition-state in-progress";
                state.innerHTML =
                  '<i class="fas fa-pen-to-square"></i> Finish partitioning';
              } else {
                // Keep the state element for later dynamic updates, but do not
                // show a separate pending-state action box.
                state.hidden = true;
                state.className = "frame-partition-state";
                state.innerHTML = "";
              }
            }
          });
      }

      function deleteCommandFrame(frameIndex) {
        if (isCommandGetStatusCommandLocked()) {
          enforceCommandGetStatusCommandState(true);
          return;
        }
        const frameName = `${getActiveFrameLabel()} Frame ${frameIndex + 1}`;
        const status = getFrameFillStatus(frameIndex);
        const confirmMessage =
          status === "filled"
            ? `Delete ${frameName}? Its saved API partition will also be removed.`
            : `Delete ${frameName}?`;
        if (!window.confirm(confirmMessage)) return;

        const currentCount = document.querySelectorAll(
          "#commandFramesContainer .command-frame-card",
        ).length;
        frameCodes.splice(frameIndex, 1);
        frameValueGroups.splice(frameIndex, 1);
        framePartitionStates.splice(frameIndex, 1);
        frameConfigurations.splice(frameIndex, 1);
        const newFieldDesc = {};
        const newByteDesc = {};
        const newViewModes = {};
        for (let key in fieldDescriptions) {
          let idx = parseInt(key);
          if (idx === frameIndex) continue;
          if (idx > frameIndex)
            newFieldDesc[idx - 1] = fieldDescriptions[idx];
          else newFieldDesc[idx] = fieldDescriptions[idx];
        }
        for (let key in byteDescriptions) {
          let idx = parseInt(key);
          if (idx === frameIndex) continue;
          if (idx > frameIndex) newByteDesc[idx - 1] = byteDescriptions[idx];
          else newByteDesc[idx] = byteDescriptions[idx];
        }
        for (let key in fieldViewModes) {
          let idx = parseInt(key);
          if (idx === frameIndex) continue;
          if (idx > frameIndex) newViewModes[idx - 1] = fieldViewModes[idx];
          else newViewModes[idx] = fieldViewModes[idx];
        }
        fieldDescriptions = newFieldDesc;
        byteDescriptions = newByteDesc;
        fieldViewModes = newViewModes;

        if (selectedFrameIndex === frameIndex) {
          document.getElementById("byteDetailPopup").style.display = "none";
          selectedFrameIndex = null;
          activePartitionFrameIndex = null;
          document
            .getElementById("apiPartitionSection")
            .classList.remove("frame-partition-active");
        } else if (
          selectedFrameIndex !== null &&
          selectedFrameIndex > frameIndex
        ) {
          selectedFrameIndex--;
          if (
            activePartitionFrameIndex !== null &&
            activePartitionFrameIndex > frameIndex
          ) {
            activePartitionFrameIndex--;
          }
        }

        const newCount = Math.max(0, currentCount - 1);
        document.getElementById("cmdFrameCountInput").value = newCount;
        if (newCount === 0) {
          awaitingFrameClick = false;
          document.getElementById("commandFramesContainer").innerHTML = "";
          updateCommandFrameCount();
          document.getElementById("byteDetailPopup").style.display = "none";
          selectedFrameIndex = null;
          frameCodes = [];
          frameValueGroups = [];
          framePartitionStates = [];
          frameConfigurations = [];
          activePartitionFrameIndex = null;
          document
            .getElementById("apiPartitionSection")
            .classList.remove("frame-partition-active");
          fieldDescriptions = {};
          byteDescriptions = {};
          fieldViewModes = {};
          updateFieldDescFrameSelect();
          renderFieldDescription();
          document
            .getElementById("framesNextBanner")
            ?.classList.remove("show");

          /*
           * If the user deleted the last Response/Error/Command frame and
           * another frame type still exists, remove this type completely.
           * Save will therefore contain count 0 and an empty array.
           */
          const deletedFrameType = activeFrameType;
          const remainingIncludedTypes = getIncludedFrameTypes().filter(
            (type) => type !== deletedFrameType,
          );

          if (remainingIncludedTypes.length) {
            setFrameTypeIncluded(deletedFrameType, false);
          }

          markConfigurationUnsaved();
          return;
        }
        generateCommandFrames(newCount, true);
        markConfigurationUnsaved();
      }

      function addCommandFrame() {
        if (isCommandGetStatusCommandLocked()) {
          enforceCommandGetStatusCommandState(true);
          return;
        }
        if (!checkRequirements()) {
          showRequirementPopup();
          return;
        }
        if (bytes.length === 0) {
          generate8Bytes();
        }
        const currentCount = document.querySelectorAll(
          "#commandFramesContainer .command-frame-card",
        ).length;
        if (currentCount >= 20) {
          alert(`Maximum of 20 ${getActiveFrameLabel().toLowerCase()} frames allowed.`);
          return;
        }
        const newCount = currentCount + 1;
        document.getElementById("cmdFrameCountInput").value = newCount;
        awaitingFrameClick = true;
        generateCommandFrames(newCount, true);
        document
          .getElementById("commandFramesSection")
          ?.scrollIntoView({ behavior: "smooth", block: "nearest" });
      }


      let activeMultipleUiFrameIndex = null;
      let activeMultipleUiTrigger = null;

      function updateMultipleUiButtonState(button, value) {
        if (!button) return;

        const isMultiple = value === "true";
        const isSingle = value === "false";

        button.dataset.value = value || "";
        button.classList.toggle("has-value", isMultiple || isSingle);
        button.classList.remove("frame-field-error");
        button.setAttribute("aria-invalid", "false");

        button.innerHTML = `
          <span class="multiple-ui-button-main">
            <i class="fas ${
              isMultiple
                ? "fa-layer-group"
                : isSingle
                  ? "fa-square"
                  : "fa-window-restore"
            }"></i>
            <span class="multiple-ui-button-copy">
              <strong>${
                isMultiple
                  ? "True — Multiple UI"
                  : isSingle
                    ? "False — Single UI"
                    : "Choose True or False"
              }</strong>
              <small>${
                isMultiple
                  ? "This frame can represent more than one UI control."
                  : isSingle
                    ? "This frame represents one UI control."
                    : "Click to choose the UI representation."
              }</small>
            </span>
          </span>
          <i class="fas fa-chevron-right multiple-ui-chevron" aria-hidden="true"></i>
        `;
      }


      function getMultipleUiCommandValue(frameIndex) {
        const partitionState = framePartitionStates?.[frameIndex] || {};

        return cleanFullApi(
          String(
            frameCodes?.[frameIndex] ||
            partitionState.fullApiValue ||
            "",
          ),
        );
      }

      function renderMultipleUiCommandVisual(frameIndex) {
        const trueBox =
          document.getElementById("multipleUiTrueRepresentation");
        const falseBox =
          document.getElementById("multipleUiFalseRepresentation");

        if (!trueBox || !falseBox) return;

        /*
         * VISUAL EXAMPLE ONLY
         * -------------------
         * This popup is only to help the user understand the difference
         * between Multiple UI = True and Multiple UI = False.
         *
         * It does NOT read, modify or save the actual frame Command Value.
         */
        const demoCommandValue = "A3BCC1";

        /*
         * TRUE / Multiple UI
         *
         * A3 -> Display
         * BC -> Button
         * C1 -> Toggle
         */
        trueBox.innerHTML = `
          <span class="multiple-ui-command-map">
            <span class="multiple-ui-command-source">
              Example Command Value: ${demoCommandValue}
            </span>

            <span class="multiple-ui-command-row">
              <span class="multiple-ui-command-code">A3</span>

              <span class="multiple-ui-command-arrow">
                <i class="fas fa-arrow-right"></i>
              </span>

              <span class="multiple-ui-command-control">
                <span class="multiple-ui-command-control-name">
                  <i class="fas fa-display"></i>
                  Display
                </span>

                <span class="multiple-ui-demo-display">123</span>
              </span>
            </span>

            <span class="multiple-ui-command-row">
              <span class="multiple-ui-command-code">BC</span>

              <span class="multiple-ui-command-arrow">
                <i class="fas fa-arrow-right"></i>
              </span>

              <span class="multiple-ui-command-control">
                <span class="multiple-ui-command-control-name">
                  <i class="fas fa-hand-pointer"></i>
                  Button
                </span>

                <span class="multiple-ui-demo-button">ON</span>
              </span>
            </span>

            <span class="multiple-ui-command-row">
              <span class="multiple-ui-command-code">C1</span>

              <span class="multiple-ui-command-arrow">
                <i class="fas fa-arrow-right"></i>
              </span>

              <span class="multiple-ui-command-control">
                <span class="multiple-ui-command-control-name">
                  <i class="fas fa-toggle-on"></i>
                  Toggle
                </span>

                <span class="multiple-ui-demo-toggle">
                  <span></span>
                </span>
              </span>
            </span>
          </span>
        `;

        /*
         * FALSE / Single UI
         *
         * A3BCC1 -> Toggle
         */
        falseBox.innerHTML = `
          <span class="multiple-ui-command-map">
            <span class="multiple-ui-command-source">
              Example Command Value: ${demoCommandValue}
            </span>

            <span class="multiple-ui-command-row">
              <span class="multiple-ui-command-code full-command">
                ${demoCommandValue}
              </span>

              <span class="multiple-ui-command-arrow">
                <i class="fas fa-arrow-right"></i>
              </span>

              <span class="multiple-ui-command-control">
                <span class="multiple-ui-command-control-name">
                  <i class="fas fa-toggle-on"></i>
                  Toggle
                </span>

                <span class="multiple-ui-demo-toggle">
                  <span></span>
                </span>
              </span>
            </span>
          </span>
        `;
      }

      function syncMultipleUiPopupSelection() {
        const currentValue =
          activeMultipleUiFrameIndex === null
            ? ""
            : frameConfigurations[activeMultipleUiFrameIndex]?.multipleUi || "";

        document
          .querySelectorAll(".multiple-ui-option-card")
          .forEach((option) => {
            const selected =
              option.dataset.multipleUiValue === currentValue;

            option.classList.toggle("selected", selected);
            option.setAttribute(
              "aria-pressed",
              selected ? "true" : "false",
            );
          });
      }

      function openMultipleUiPopup(frameIndex, triggerButton = null) {
        if (isCommandGetStatusCommandLocked()) return;
        const overlay = document.getElementById("multipleUiOverlay");
        if (!overlay) return;

        activeMultipleUiFrameIndex = frameIndex;
        activeMultipleUiTrigger =
          triggerButton ||
          document.getElementById(`frameMultipleUi${frameIndex}`);

        activeMultipleUiTrigger?.setAttribute("aria-expanded", "true");

        renderMultipleUiCommandVisual(frameIndex);
        syncMultipleUiPopupSelection();

        overlay.classList.add("open");
        overlay.setAttribute("aria-hidden", "false");

        const selectedOption =
          overlay.querySelector(".multiple-ui-option-card.selected") ||
          overlay.querySelector(".multiple-ui-option-card");

        selectedOption?.focus();
      }

      function closeMultipleUiPopup(returnFocus = true) {
        const overlay = document.getElementById("multipleUiOverlay");
        if (!overlay) return;

        overlay.classList.remove("open");
        overlay.setAttribute("aria-hidden", "true");

        activeMultipleUiTrigger?.setAttribute("aria-expanded", "false");

        if (returnFocus) {
          activeMultipleUiTrigger?.focus();
        }

        activeMultipleUiFrameIndex = null;
        activeMultipleUiTrigger = null;
      }

      function selectMultipleUiValue(value) {
        if (isCommandGetStatusCommandLocked()) return;
        if (
          activeMultipleUiFrameIndex === null ||
          !["true", "false"].includes(value)
        ) {
          return;
        }

        if (!frameConfigurations[activeMultipleUiFrameIndex]) {
          frameConfigurations[activeMultipleUiFrameIndex] = {
            dataFlowDirection: "",
            multipleUi: "",
          };
        }

        frameConfigurations[activeMultipleUiFrameIndex].multipleUi = value;

        const button =
          document.getElementById(
            `frameMultipleUi${activeMultipleUiFrameIndex}`,
          );

        updateMultipleUiButtonState(button, value);
        syncMultipleUiPopupSelection();
        markConfigurationUnsaved();

        closeMultipleUiPopup(true);
      }

      document
        .querySelectorAll(".multiple-ui-option-card")
        .forEach((option) => {
          option.addEventListener("click", function () {
            selectMultipleUiValue(this.dataset.multipleUiValue);
          });
        });

      document
        .getElementById("multipleUiCloseBtn")
        ?.addEventListener("click", function () {
          closeMultipleUiPopup(true);
        });

      document
        .getElementById("multipleUiOverlay")
        ?.addEventListener("click", function (event) {
          if (event.target === this) {
            closeMultipleUiPopup(true);
          }
        });

      document.addEventListener("keydown", function (event) {
        if (
          event.key === "Escape" &&
          document
            .getElementById("multipleUiOverlay")
            ?.classList.contains("open")
        ) {
          closeMultipleUiPopup(true);
        }
      });

      function openFramePartitionEditor(frameIndex) {
        if (isCommandGetStatusCommandLocked()) {
          return;
        }
        const frameConfiguration = frameConfigurations[frameIndex] || {};
        const directionSelect = document.getElementById(
          `frameDirection${frameIndex}`,
        );
        const multipleUiControl = document.getElementById(
          `frameMultipleUi${frameIndex}`,
        );
        const missing = [];
        if (!frameConfiguration.dataFlowDirection) {
          missing.push({
            id: `frameDirection${frameIndex}`,
            label: "Data Flow Direction",
            icon: "fa-right-left",
          });
          directionSelect?.classList.add("frame-field-error");
          directionSelect?.setAttribute("aria-invalid", "true");
        }
        if (!frameConfiguration.multipleUi) {
          missing.push({
            id: `frameMultipleUi${frameIndex}`,
            label: "Multiple UI",
            icon: "fa-window-restore",
          });
          multipleUiControl?.classList.add("frame-field-error");
          multipleUiControl?.setAttribute("aria-invalid", "true");
        }
        if (missing.length) {
          showFrameSettingsValidationPopup(frameIndex, missing);
          return;
        }
        captureActiveFramePartitionState();
        activePartitionFrameIndex = frameIndex;
        selectedFrameIndex = frameIndex;
        awaitingFrameClick = false;
        showPartitionWarnings = false;
        document.getElementById("framesNextBanner")?.classList.remove("show");
        loadFramePartitionState(frameIndex);
        const section = document.getElementById("apiPartitionSection");
        section.classList.add("frame-partition-active", "section-highlight");
        document
          .querySelectorAll(".command-frame-card")
          .forEach((card, index) => {
            card.classList.toggle("selected", index === frameIndex);
            card.classList.remove("awaiting-click");
          });
        section.scrollIntoView({ behavior: "smooth", block: "start" });
        setTimeout(() => section.classList.remove("section-highlight"), 1200);
        setTimeout(() => {
          document.getElementById("fullApiInput")?.focus();
        }, 350);
      }

      function applyPartitionColor(element, partitionIndex) {
        const palette =
          PARTITION_COLORS[partitionIndex % PARTITION_COLORS.length];
        element.classList.add("partition-colored");
        element.style.setProperty("--partition-color", palette.color);
        element.style.setProperty("--partition-soft", palette.soft);
        element.style.setProperty("--partition-text", palette.text);
        element.dataset.partitionColorIndex = String(partitionIndex);
      }

      function cleanFullApi(value) {
        return value
          .replace(/0x/gi, "")
          .replace(/[^0-9a-f]/gi, "")
          .toUpperCase();
      }

      function getApiBytes() {
        if (
          hexEditorDraftIsIncomplete &&
          Array.isArray(hexEditorDraftBytes) &&
          hexEditorDraftBytes.length
        ) {
          return hexEditorDraftBytes.map((value) => {
            const cleaned = normalizeHex(String(value || ""))
              .replace(/[^0-9A-F]/g, "")
              .slice(0, 2);
            if (/^[0-9A-F]{2}$/.test(cleaned)) return cleaned;
            return cleaned ? cleaned.padEnd(2, "-") : "--";
          });
        }

        const actualBytes = fullApiValue.match(/.{1,2}/g) || [];
        if (actualBytes.length || restoredByteCount < 1) return actualBytes;
        return Array.from(
          { length: restoredByteCount },
          (_, index) => `B${index + 1}`,
        );
      }

      function getPartitionRanges() {
        const byteCount = getApiBytes().length;
        const hasCompleteActualApi =
          Boolean(fullApiValue) && fullApiValue.length % 2 === 0;
        const hasRestoredLayout = !fullApiValue && restoredByteCount > 0;
        if (!byteCount || (!hasCompleteActualApi && !hasRestoredLayout))
          return [];
        const boundaries = [
          0,
          ...partitionCuts.filter((cut) => cut > 0 && cut < byteCount),
          byteCount,
        ]
          .filter((value, index, array) => array.indexOf(value) === index)
          .sort((a, b) => a - b);
        const ranges = [];
        for (let index = 0; index < boundaries.length - 1; index++) {
          ranges.push({
            start: boundaries[index],
            end: boundaries[index + 1],
          });
        }
        return ranges;
      }

      function partitionKey(range) {
        return `${range.start}-${range.end}`;
      }

      function getPartitionValidation() {
        if (!fullApiValue)
          return {
            valid: false,
            message: "Enter the complete hexadecimal API.",
          };
        if (fullApiValue.length % 2 !== 0)
          return {
            valid: false,
            message:
              "The API has an incomplete byte. Add one more hexadecimal character.",
          };
        const ranges = getPartitionRanges();
        if (!ranges.length)
          return {
            valid: false,
            message: "The API must contain at least one complete byte.",
          };
        const unnamed = ranges.findIndex(
          (range) => !partitionLabels[partitionKey(range)],
        );
        if (unnamed !== -1)
          return {
            valid: false,
            message: `Select a name for Partition ${unnamed + 1}.`,
          };
        for (let index = 0; index < ranges.length; index++) {
          const configurationValidation = getPartitionConfigurationValidation(
            partitionKey(ranges[index]),
          );
          if (!configurationValidation.valid) {
            return {
              valid: false,
              message: `Partition ${index + 1}: ${configurationValidation.message}`,
            };
          }
        }
        return {
          valid: true,
          message: `${ranges.length} partition${ranges.length === 1 ? "" : "s"} ready.`,
        };
      }

      function getStepOneTemplate() {
        const apiBytes = getApiBytes();
        return getPartitionRanges().map((range, index) => {
          const nameValue = partitionLabels[partitionKey(range)] || "";
          return {
            index,
            start: range.start,
            end: range.end,
            code: apiBytes.slice(range.start, range.end).join(""),
            nameValue,
            nameLabel:
              API_PARTITION_OPTIONS.find(
                (option) => option.value === nameValue,
              )?.label || "Unnamed",
          };
        });
      }

      function mapPartitionNameToFieldDescription(nameValue) {
        const mapping = {
          commandId: "commandid",
          functionCode: "function code",
          data: "data",
          terminatorCrc: "terminator / crc",
        };
        return mapping[nameValue] || "";
      }

      function updateLinkedApiPanel() {
        const code = document.getElementById("linkedApiCode");
        const chips = document.getElementById("linkedPartitionChips");
        const state = document.getElementById("linkedApiState");
        if (!code || !chips || !state) return;

        code.textContent =
          fullApiValue || "Complete Step 2 for a frame to import its API.";
        chips.innerHTML = "";
        getStepOneTemplate().forEach((partition) => {
          const chip = document.createElement("span");
          chip.className = "linked-partition-chip";
          applyPartitionColor(chip, partition.index);
          chip.innerHTML = `<strong>${partition.nameLabel}</strong><code>${partition.code}</code>`;
          chips.appendChild(chip);
        });

        if (partitionsConfirmed && getPartitionValidation().valid) {
          state.className = "linked-api-state";
          state.innerHTML =
            '<i class="fas fa-circle-check"></i> Linked from Step 2';
        } else {
          state.className = "linked-api-state pending";
          state.innerHTML = fullApiValue
            ? '<i class="fas fa-rotate"></i> Reconfirm Step 2'
            : '<i class="fas fa-clock"></i> Waiting for Step 2';
        }
      }

      function applyStepOneTemplateToFrames(
        count,
        overwrite,
        targetFrameIndex = null,
      ) {
        const template = getStepOneTemplate();
        if (!template.length || !partitionsConfirmed) return;
        const templateCodes = template.map((partition) => partition.code);
        const frameIndexes = Number.isInteger(targetFrameIndex)
          ? [targetFrameIndex]
          : Array.from({ length: count }, (_, index) => index);

        for (const frameIndex of frameIndexes) {
          if (frameIndex < 0 || frameIndex >= count) continue;
          if (overwrite || !frameCodes[frameIndex]) {
            frameCodes[frameIndex] = fullApiValue;
          }
          if (overwrite || !frameValueGroups[frameIndex]?.length) {
            frameValueGroups[frameIndex] = templateCodes.slice();
          }
          if (overwrite || !byteDescriptions[frameIndex]) {
            byteDescriptions[frameIndex] = {};
            fieldViewModes[frameIndex] = {};
            template.forEach((partition, partitionIndex) => {
              const fieldDescription = mapPartitionNameToFieldDescription(
                partition.nameValue,
              );
              byteDescriptions[frameIndex][partitionIndex] = fieldDescription;
              if (fieldDescription === "data") {
                const key = `${partition.start}-${partition.end}`;
                fieldViewModes[frameIndex][partitionIndex] =
                  partitionViewModes[key] || "bytewise";
              }
            });
          }
          if (overwrite || !fieldDescriptions[frameIndex]) {
            fieldDescriptions[frameIndex] = {};
            template.forEach((partition, partitionIndex) => {
              const key = `${partition.start}-${partition.end}`;
              const configurations = partitionFieldConfigurations[key] || {};
              const selectedConfigurationMode =
                partition.nameValue === "data"
                  ? partitionViewModes[key] || "bytewise"
                  : "bytewise";
              Object.entries(configurations).forEach(
                ([configurationKey, configuration]) => {
                  if (
                    configurationKey === "_bitGroups" ||
                    configurationKey === "_bitCuts"
                  )
                    return;
                  if (
                    selectedConfigurationMode === "bytewise" &&
                    configurationKey !== "byte"
                  )
                    return;
                  if (
                    selectedConfigurationMode === "bitwise" &&
                    configurationKey === "byte"
                  )
                    return;
                  let frameConfigurationKey;
                  if (configurationKey === "byte") {
                    frameConfigurationKey = `byte:${partitionIndex}`;
                  } else if (configurationKey.startsWith("bit-group:")) {
                    frameConfigurationKey = `bit-group:${partitionIndex}:${configurationKey.slice("bit-group:".length)}`;
                  } else {
                    frameConfigurationKey = `bit:${partitionIndex}:${configurationKey.split(":")[1]}`;
                  }
                  fieldDescriptions[frameIndex][frameConfigurationKey] = {
                    ...configuration,
                    byteIndex: partitionIndex,
                  };
                },
              );
            });
          }
        }
      }

      function syncFrameStructureFromStepOne() {
        bytes = getApiBytes().map((byteValue, index) => ({
          id: index,
          value: `0x${byteValue}`,
          active: true,
        }));
        renderByteRow("byteRowContainer", bytes);
        updateSelectedInfo();
        updateFrameSizeLabel();
      }

      function setPartitionChanged() {
        partitionsConfirmed = false;
        captureActiveFramePartitionState();
        updateLinkedApiPanel();
        updateFrameTypeUi();
      }

      function getApiTimelineScrollLeft() {
        return (
          document.getElementById("apiTimelineScroll")?.scrollLeft || 0
        );
      }

      function restoreApiTimelineScroll(scrollLeft) {
        requestAnimationFrame(function () {
          const timelineScroll =
            document.getElementById("apiTimelineScroll");
          if (timelineScroll) {
            timelineScroll.scrollLeft = scrollLeft;
            updatePartitionNavigation();
          }
        });
      }

      function getPartitionScrollTargets() {
        const timelineScroll =
          document.getElementById("apiTimelineScroll");
        const timeline = document.getElementById("apiTimeline");
        if (!timelineScroll || !timeline || timeline.style.display === "none") {
          return [];
        }

        const maxScroll = Math.max(
          0,
          timelineScroll.scrollWidth - timelineScroll.clientWidth,
        );
        const targets = Array.from(
          timeline.querySelectorAll(".partition-name-band"),
        ).map((band) => Math.max(0, Math.min(maxScroll, band.offsetLeft)));
        targets.push(maxScroll);
        return [...new Set(targets.map((value) => Math.round(value)))].sort(
          (a, b) => a - b,
        );
      }

      function updatePartitionNavigation() {
        const timelineScroll =
          document.getElementById("apiTimelineScroll");
        const previousButton =
          document.getElementById("previousPartitionBtn");
        const nextButton = document.getElementById("nextPartitionBtn");
        if (!timelineScroll || !previousButton || !nextButton) return;

        const targets = getPartitionScrollTargets();
        const current = timelineScroll.scrollLeft;
        const tolerance = 3;
        const canMoveLeft = targets.some(
          (target) => target < current - tolerance,
        );
        const canMoveRight = targets.some(
          (target) => target > current + tolerance,
        );
        previousButton.disabled = !canMoveLeft;
        nextButton.disabled = !canMoveRight;
        previousButton.setAttribute("aria-disabled", String(!canMoveLeft));
        nextButton.setAttribute("aria-disabled", String(!canMoveRight));
      }

      function scrollToAdjacentPartition(direction) {
        const timelineScroll =
          document.getElementById("apiTimelineScroll");
        if (!timelineScroll) return;
        const targets = getPartitionScrollTargets();
        const current = timelineScroll.scrollLeft;
        const tolerance = 3;
        const target =
          direction < 0
            ? [...targets]
                .reverse()
                .find((position) => position < current - tolerance)
            : targets.find((position) => position > current + tolerance);
        if (target === undefined) return;
        timelineScroll.scrollTo({ left: target, behavior: "smooth" });
      }

      function addCut(cutPosition) {
        if (isCommandGetStatusCommandLocked()) return;
        const previousScrollLeft = getApiTimelineScrollLeft();
        const byteCount = getApiBytes().length;
        if (
          cutPosition <= 0 ||
          cutPosition >= byteCount ||
          partitionCuts.includes(cutPosition)
        )
          return;
        partitionCuts.push(cutPosition);
        partitionCuts.sort((a, b) => a - b);
        setPartitionChanged();
        renderApiPartitionEditor();
        restoreApiTimelineScroll(previousScrollLeft);
      }

      function removeCut(cutPosition) {
        if (isCommandGetStatusProtectedCut(cutPosition)) return;
        const previousScrollLeft = getApiTimelineScrollLeft();
        partitionCuts = partitionCuts.filter((cut) => cut !== cutPosition);
        setPartitionChanged();
        renderApiPartitionEditor();
        restoreApiTimelineScroll(previousScrollLeft);
      }

      function moveCutByOne(cutPosition, direction) {
        if (isCommandGetStatusProtectedCut(cutPosition)) return;
        const byteCount = getApiBytes().length;
        const nextCut = cutPosition + direction;
        if (
          !partitionCuts.includes(cutPosition) ||
          nextCut < 1 ||
          nextCut >= byteCount ||
          partitionCuts.includes(nextCut)
        ) {
          return;
        }
        const previousScrollLeft = getApiTimelineScrollLeft();
        partitionCuts = partitionCuts
          .map((cut) => (cut === cutPosition ? nextCut : cut))
          .sort((a, b) => a - b);
        setPartitionChanged();
        renderApiPartitionEditor();
        restoreApiTimelineScroll(previousScrollLeft);
      }

      function startCutDrag(event, originalCut, marker) {
        if (isCommandGetStatusProtectedCut(originalCut)) return;
        if (event.button !== undefined && event.button !== 0) return;
        event.preventDefault();
        const timeline = document.getElementById("apiTimeline");
        const byteCount = getApiBytes().length;
        const rect = timeline.getBoundingClientRect();
        let targetCut = originalCut;
        let moved = false;
        marker.classList.add("dragging");

        function onMove(moveEvent) {
          const clientX =
            moveEvent.clientX ?? moveEvent.touches?.[0]?.clientX;
          if (clientX === undefined || rect.width === 0) return;
          const rawCut = Math.round(
            ((clientX - rect.left) / rect.width) * byteCount,
          );
          const candidate = Math.max(1, Math.min(byteCount - 1, rawCut));
          if (candidate !== originalCut) moved = true;
          if (
            !partitionCuts.includes(candidate) ||
            candidate === originalCut
          ) {
            targetCut = candidate;
            marker.style.left = `${(candidate / byteCount) * 100}%`;
          }
        }

        function onEnd() {
          const previousScrollLeft = getApiTimelineScrollLeft();
          window.removeEventListener("pointermove", onMove);
          window.removeEventListener("pointerup", onEnd);
          marker.classList.remove("dragging");
          if (moved && targetCut !== originalCut) {
            partitionCuts = partitionCuts.filter(
              (cut) => cut !== originalCut,
            );
            partitionCuts.push(targetCut);
            partitionCuts.sort((a, b) => a - b);
            setPartitionChanged();
            suppressCutClick = true;
            setTimeout(() => {
              suppressCutClick = false;
            }, 0);
            renderApiPartitionEditor();
            restoreApiTimelineScroll(previousScrollLeft);
          }
        }

        window.addEventListener("pointermove", onMove);
        window.addEventListener("pointerup", onEnd);
      }

      function renderApiTimeline() {
        const bytesForApi = getApiBytes();
        const ranges = getPartitionRanges();
        const timeline = document.getElementById("apiTimeline");
        const empty = document.getElementById("apiTimelineEmpty");
        const isComplete =
          (Boolean(fullApiValue) && fullApiValue.length % 2 === 0) ||
          (!fullApiValue && restoredByteCount > 0);

        if (!isComplete) {
          timeline.style.display = "none";
          timeline.innerHTML = "";
          empty.style.display = "grid";
          empty.textContent = fullApiValue
            ? "Complete the last byte to enable partition controls."
            : "Enter the full API above to display its bytes and partition controls.";
          updatePartitionNavigation();
          return;
        }

        empty.style.display = "none";
        timeline.style.display = "grid";
        timeline.innerHTML = "";
        timeline.style.gridTemplateColumns = `repeat(${bytesForApi.length}, minmax(54px, 1fr))`;

        bytesForApi.forEach((byteValue, index) => {
          const cell = document.createElement("div");
          cell.className = "api-byte-cell";
          cell.style.gridColumn = String(index + 1);
          const partitionIndex = ranges.findIndex(
            (range) => index >= range.start && index < range.end,
          );
          if (partitionIndex !== -1)
            applyPartitionColor(cell, partitionIndex);
          cell.innerHTML = `<span class="api-byte-index">Byte ${index + 1}</span><span class="api-byte-value">${byteValue}</span>`;
          timeline.appendChild(cell);
        });

        renderPartitionNameBands(timeline, ranges);

        for (let cut = 1; cut < bytesForApi.length; cut++) {
          const marker = document.createElement("button");
          marker.type = "button";
          const isActive = partitionCuts.includes(cut);
          const protectedCut = isCommandGetStatusProtectedCut(cut);
          marker.className = "cut-target" + (isActive ? " active" : "") + (protectedCut ? " protocol-cut-locked" : "");
          if (protectedCut) {
            marker.disabled = true;
            marker.setAttribute("aria-disabled", "true");
          }
          marker.style.left = `${(cut / bytesForApi.length) * 100}%`;
          marker.setAttribute(
            "aria-label",
            isActive
              ? `Move or remove cut after byte ${cut}`
              : `Add cut after byte ${cut}`,
          );
          marker.title = isActive
            ? "Drag this scissors cut to move it, or click to remove it"
            : "click agin to deselect the partitons";
          const leftDisabled =
            cut <= 1 || partitionCuts.includes(cut - 1);
          const rightDisabled =
            cut >= bytesForApi.length - 1 ||
            partitionCuts.includes(cut + 1);
          marker.innerHTML = isActive
            ? `<span class="cut-nudges" aria-hidden="true">
                 <span class="cut-nudge${leftDisabled ? " disabled" : ""}" data-direction="-1" title="Move partition cut left"><i class="fas fa-chevron-left"></i></span>
                 <span class="cut-nudge${rightDisabled ? " disabled" : ""}" data-direction="1" title="Move partition cut right"><i class="fas fa-chevron-right"></i></span>
               </span>
               <span class="cut-chip"><i class="fas fa-scissors"></i></span>
               <span class="cut-hover-tip">click agin to deselect the partitons</span>`
            : `<span class="cut-chip"><i class="fas fa-plus"></i></span>
               <span class="cut-hover-tip">click agin to deselect the partitons</span>`;
          if (isActive) {
            const rightPartitionIndex = ranges.findIndex(
              (range) => range.start === cut,
            );
            applyPartitionColor(
              marker,
              rightPartitionIndex === -1 ? 0 : rightPartitionIndex,
            );
            marker.addEventListener("pointerdown", function (event) {
              if (event.target.closest(".cut-nudge")) return;
              startCutDrag(event, cut, marker);
            });
          }
          marker.addEventListener("click", function (event) {
            event.preventDefault();
            event.stopPropagation();
            if (suppressCutClick) return;
            const nudge = event.target.closest(".cut-nudge");
            if (nudge) {
              if (!nudge.classList.contains("disabled")) {
                moveCutByOne(cut, Number(nudge.dataset.direction));
              }
              return;
            }
            if (partitionCuts.includes(cut)) removeCut(cut);
            else addCut(cut);
          });
          timeline.appendChild(marker);
        }
        requestAnimationFrame(updatePartitionNavigation);
      }

      function getPartitionConfiguredFieldNames(key) {
        const configurations = partitionFieldConfigurations[key] || {};
        const partitionName = partitionLabels[key] || "";
        const currentView =
          partitionName === "data"
            ? partitionViewModes[key] || "bytewise"
            : "bytewise";
        const names = [];

        const addName = (configuration) => {
          const fieldName = String(
            configuration?.name ||
            configuration?.fieldName ||
            configuration?.field_name ||
            ""
          ).trim();
          if (fieldName && !names.includes(fieldName)) names.push(fieldName);
        };

        if (currentView === "bytewise") {
          addName(configurations.byte);
        } else {
          Object.entries(configurations).forEach(([configurationKey, configuration]) => {
            if (configurationKey === "byte" || configurationKey.startsWith("_")) return;
            addName(configuration);
          });
        }

        return names;
      }

      function getPartitionConfiguredFieldName(key) {
        return getPartitionConfiguredFieldNames(key).join(" / ");
      }

      function renderPartitionNameBands(timeline, ranges) {
        ranges.forEach((range, index) => {
          const key = partitionKey(range);
          const band = document.createElement("div");
          band.className = "partition-name-band";
          band.style.gridColumn = `${range.start + 1} / ${range.end + 1}`;
          applyPartitionColor(band, index);

          const fixedPartitionName = getCommandGetStatusFixedPartitionName(range);
          if (fixedPartitionName) {
            partitionLabels[key] = fixedPartitionName;
          }

          const selectedValue = partitionLabels[key] || "";
          const configuredFieldName = getPartitionConfiguredFieldName(key);
          const responseWrapperConfigLocked =
            isCommandGetStatusLockedResponsePartitionRange(range);
          const commandConfigLocked = isCommandGetStatusCommandLocked();
          const fieldConfigurationLocked =
            commandConfigLocked || responseWrapperConfigLocked;
          const hasName = Boolean(selectedValue);
          const configValidation = hasName
            ? getPartitionConfigurationValidation(key)
            : { valid: false, message: "Select a partition name first." };

          const statusTone = fieldConfigurationLocked
            ? "locked"
            : hasName && configValidation.valid
              ? "ready"
              : "setup";
          const statusLabel = fieldConfigurationLocked
            ? "Locked"
            : hasName && configValidation.valid
              ? "Configured"
              : "Needs setup";

          const header = document.createElement("div");
          header.className = "partition-card-head";
          header.innerHTML = `
            <div class="partition-card-title">
              <span class="partition-name-dot"></span>
              <span class="partition-card-title-copy">
                <span>Partition ${index + 1}</span>
                <small class="partition-card-field-name"></small>
              </span>
            </div>
            <span class="partition-setup-badge ${statusTone}"><i class="fas ${statusTone === "ready" ? "fa-circle-check" : statusTone === "locked" ? "fa-lock" : "fa-circle"}"></i> ${statusLabel}</span>
          `;
          const configuredFieldNameEl = header.querySelector(".partition-card-field-name");
          if (configuredFieldNameEl) configuredFieldNameEl.textContent = configuredFieldName;

          const fieldLabel = document.createElement("label");
          fieldLabel.className = "partition-field-label";
          fieldLabel.textContent = "Partition Name";

          const select = document.createElement("select");
          select.setAttribute(
            "aria-label",
            `Name for partition ${index + 1}`,
          );
          select.innerHTML =
            '<option value="">Select partition name</option>';
          API_PARTITION_OPTIONS.forEach((optionData) => {
            const option = document.createElement("option");
            option.value = optionData.value;
            option.textContent = optionData.label;
            if (selectedValue === optionData.value) option.selected = true;
            select.appendChild(option);
          });
          if (fixedPartitionName) {
            select.value = fixedPartitionName;
            select.disabled = true;
            select.setAttribute("aria-disabled", "true");
            select.title = "Protocol-owned partition name";
          }

          select.addEventListener("change", function () {
            const lockedPartitionName = getCommandGetStatusFixedPartitionName(range);
            if (lockedPartitionName) {
              partitionLabels[key] = lockedPartitionName;
              this.value = lockedPartitionName;
              return;
            }
            const selectedPartitionName = this.value || "";
            partitionLabels[key] = selectedPartitionName;

            if (selectedPartitionName !== "data") {
              delete partitionFieldConfigurations[key]?.bit;
            }

            renderApiPartitionEditor();
            markConfigurationUnsaved();

            if (!selectedPartitionName) {
              return;
            }

            requestAnimationFrame(function () {
              const currentRange = getPartitionRanges().find(
                (item) => partitionKey(item) === key,
              );

              if (!currentRange || !partitionLabels[key]) {
                return;
              }

              if (selectedPartitionName === "data") {
                openPartitionModePopup(key, index);
                return;
              }

              const partitionCode = getApiBytes()
                .slice(currentRange.start, currentRange.end)
                .join("");

              openPartitionFieldModal(
                key,
                partitionCode,
                index,
              );
            });
          });

          const configBtn = document.createElement("button");
          configBtn.type = "button";
          configBtn.className = "partition-config-open-btn";

          if (fieldConfigurationLocked) {
            configBtn.disabled = true;
            configBtn.classList.add("config-ready");
            configBtn.innerHTML =
              '<i class="fas fa-lock"></i> Configuration Locked';
            configBtn.title = responseWrapperConfigLocked
              ? "DE, E7 and final 0A field configuration is protocol-owned and cannot be edited"
              : "Command Get Status field configuration is locked";
          } else if (!hasName) {
            configBtn.disabled = true;
            configBtn.classList.add("config-disabled");
            configBtn.innerHTML =
              '<i class="fas fa-sliders"></i> Configure Partition';
            configBtn.title = "Select a partition name first";
          } else {
            if (configValidation.valid) {
              configBtn.classList.add("config-ready");
            } else {
              configBtn.classList.add("config-missing");
            }
            configBtn.innerHTML =
              '<i class="fas fa-sliders"></i> Configure Partition';
            configBtn.title = `Open configuration for Partition ${index + 1}`;
          }

          configBtn.addEventListener("click", function (event) {
            event.preventDefault();
            event.stopPropagation();
            if (fieldConfigurationLocked) return;
            if (!partitionLabels[key]) return;
            openPartitionModePopup(key, index);
          });

          const helper = document.createElement("span");
          if (!hasName && showPartitionWarnings) {
            band.classList.add("missing-selection", "show-warning");
            select.classList.add("dropdown-error");
            select.setAttribute("aria-invalid", "true");
            helper.className = "partition-dropdown-warning";
            helper.innerHTML =
              '<i class="fas fa-triangle-exclamation"></i> Select this partition name';
          } else {
            select.setAttribute("aria-invalid", "false");
            helper.className = "partition-dropdown-hint";
            if (fieldConfigurationLocked) {
              helper.innerHTML =
                '<i class="fas fa-circle-info"></i> This partition is locked by the protocol';
            } else if (!hasName) {
              helper.innerHTML =
                '<i class="fas fa-circle-info"></i> Choose a name to continue';
            } else if (configValidation.valid) {
              helper.innerHTML =
                '<i class="fas fa-circle-check"></i> Configuration is ready for this partition';
            } else if (selectedValue === "data") {
              helper.innerHTML =
                '<i class="fas fa-circle-info"></i> Choose byte-wise or bit-wise configuration';
            } else {
              helper.innerHTML =
                '<i class="fas fa-circle-info"></i> Click Configure Partition to continue';
            }
          }

          band.append(header, fieldLabel, select, helper, configBtn);
          timeline.appendChild(band);
        });
      }

      function renderPartitionVisualBlocks() {
        const container = document.getElementById("partitionVisualBlocks");
        if (!container) return;
        const apiBytes = getApiBytes();
        const ranges = getPartitionRanges();
        container.innerHTML = "";

        const hasCompleteActualApi =
          Boolean(fullApiValue) && fullApiValue.length % 2 === 0;
        const hasRestoredLayout = !fullApiValue && restoredByteCount > 0;
        if ((!hasCompleteActualApi && !hasRestoredLayout) || !ranges.length) {
          container.innerHTML =
            '<div class="partition-visual-empty"><i class="fas fa-circle-info"></i> Enter a complete API to see each partition as byte boxes.</div>';
          return;
        }

        ranges.forEach((range, index) => {
          const key = partitionKey(range);
          const selectedValue = partitionLabels[key] || "";
          const selectedLabel =
            API_PARTITION_OPTIONS.find(
              (option) => option.value === selectedValue,
            )?.label || "Name not selected";
          const configuredFieldName = getPartitionConfiguredFieldName(key);
          const block = document.createElement("div");
          block.className = `partition-visual-block${selectedValue ? "" : " missing"}`;
          applyPartitionColor(block, index);
          if (!selectedValue) block.classList.add("missing");
          const byteStart = range.start + 1;
          const byteEnd = range.end;
          const byteBoxes = apiBytes
            .slice(range.start, range.end)
            .map(
              (byteValue, byteOffset) => `
                  <div class="partition-byte-box">
                    <span class="byte-box-index">B${range.start + byteOffset + 1}</span>
                    <span class="byte-box-value">${byteValue}</span>
                  </div>
                `,
            )
            .join("");

          const responseWrapperConfigLocked =
            isCommandGetStatusLockedResponsePartitionRange(range);
          const commandConfigLocked = isCommandGetStatusCommandLocked();
          const fieldConfigurationLocked =
            commandConfigLocked || responseWrapperConfigLocked;
          const configValidation = selectedValue
            ? getPartitionConfigurationValidation(key)
            : { valid: false };
          const configBtnClass = fieldConfigurationLocked
            ? " config-ready"
            : !selectedValue
              ? ""
              : configValidation.valid
                ? " config-ready"
                : " config-missing";
          const configBtnLabel = fieldConfigurationLocked
            ? "Configuration Locked"
            : !selectedValue
              ? "Select name first"
              : configValidation.valid
                ? "Open Configuration"
                : "Configure Partition";

          block.innerHTML = `
                    <span class="partition-visual-index"><i class="fas fa-puzzle-piece"></i> Partition ${index + 1}</span>
                    <div class="partition-byte-boxes">${byteBoxes}</div>
                    <span class="partition-visual-name">
                        <i class="fas ${selectedValue ? "fa-tag" : "fa-circle-info"}"></i>
                        ${selectedLabel}
                    </span>
                    <span class="partition-visual-field-name"></span>
                    <span class="partition-visual-range"><i class="fas fa-ruler-horizontal"></i> Byte ${byteStart}${byteEnd === byteStart ? "" : ` to Byte ${byteEnd}`}</span>
                    <button type="button" class="partition-config-open-btn${configBtnClass}" ${fieldConfigurationLocked || !selectedValue ? "disabled" : ""}>
                      <i class="fas ${fieldConfigurationLocked ? "fa-lock" : "fa-sliders"}"></i> ${configBtnLabel}
                    </button>
                `;
          const visualFieldNameEl = block.querySelector(".partition-visual-field-name");
          if (visualFieldNameEl) {
            visualFieldNameEl.textContent = configuredFieldName;
            visualFieldNameEl.hidden = !configuredFieldName;
          }

          const previewConfigBtn = block.querySelector(
            ".partition-config-open-btn",
          );
          previewConfigBtn?.addEventListener("click", function (event) {
            event.preventDefault();
            event.stopPropagation();
            if (fieldConfigurationLocked) return;
            if (!partitionLabels[key]) return;
            openPartitionModePopup(key, index);
          });
          container.appendChild(block);
        });
      }

      let activePartitionModeKey = null;
      let activePartitionModeIndex = null;

      function openPartitionModePopup(key, partitionIndex) {
        if (isCommandGetStatusCommandLocked()) return;
        if (isCommandGetStatusLockedResponsePartitionKey(key)) return;
        const range = getPartitionRanges().find(
          (item) => partitionKey(item) === key,
        );
        if (!range || !partitionLabels[key]) return;

        activePartitionModeKey = key;
        activePartitionModeIndex = partitionIndex;
        const overlay = document.getElementById("partitionModeOverlay");
        const modal = document.getElementById("partitionModeModal");
        const body = document.getElementById("partitionModeBody");
        const partitionCode = getApiBytes()
          .slice(range.start, range.end)
          .join("");
        const nameLabel =
          API_PARTITION_OPTIONS.find(
            (option) => option.value === partitionLabels[key],
          )?.label || "Partition";

        applyPartitionColor(modal, partitionIndex);
        document.getElementById("partitionModeTitle").textContent =
          `Partition ${partitionIndex + 1} ${nameLabel}`;
        document.getElementById("partitionModeCode").textContent =
          partitionCode;
        body.innerHTML = "";
        const warning = document.createElement("div");
        warning.id = "partitionConfigWarning";
        warning.className = "partition-config-warning";
        warning.setAttribute("role", "alert");
        warning.innerHTML =
          '<i class="fas fa-triangle-exclamation"></i><span>Complete and save the required configuration before clicking Done.</span>';
        body.appendChild(warning);
        modal.classList.remove("config-invalid");
        renderPartitionConfigurationControls(body, range, partitionIndex);
        overlay.style.display = "flex";
      }

      function closePartitionModePopup() {
        document.getElementById("partitionModeOverlay").style.display =
          "none";
        activePartitionModeKey = null;
        activePartitionModeIndex = null;
      }

      document
        .getElementById("closePartitionMode")
        .addEventListener("click", closePartitionModePopup);
      document
        .getElementById("donePartitionMode")
        .addEventListener("click", function () {
          if (!activePartitionModeKey) return;
          const validation = getPartitionConfigurationValidation(
            activePartitionModeKey,
          );
          const modal = document.getElementById("partitionModeModal");
          const warning = document.getElementById("partitionConfigWarning");

          if (!validation.valid) {
            modal.classList.add("config-invalid");
            if (warning) {
              warning.classList.add("show");
              warning.querySelector("span").textContent = validation.message;
            }
            renderActivePartitionMode();
            const refreshedWarning = document.getElementById(
              "partitionConfigWarning",
            );
            const refreshedModal =
              document.getElementById("partitionModeModal");
            refreshedModal.classList.add("config-invalid");
            if (refreshedWarning) {
              refreshedWarning.classList.add("show");
              refreshedWarning.querySelector("span").textContent =
                validation.message;
              refreshedWarning.scrollIntoView({
                behavior: "smooth",
                block: "nearest",
              });
            }
            return;
          }

          closePartitionModePopup();
        });
      document
        .getElementById("partitionModeOverlay")
        .addEventListener("click", function (event) {
          if (event.target === this) closePartitionModePopup();
        });

      function isFieldConfigurationComplete(configuration) {
        if (!configuration || typeof configuration !== "object") return false;
        return (
          Boolean(configuration.dataType) &&
          Boolean(configuration.valueDef) &&
          Boolean(configuration.uiType) &&
          Boolean(configuration.uiInOut)
        );
      }

      function bitGroupConfigKey(group) {
        const sorted = [...group].sort((a, b) => a - b);
        return sorted.length === 1
          ? `bit:${sorted[0]}`
          : `bit-group:${sorted[0]}-${sorted[sorted.length - 1]}`;
      }

      function bitGroupLabel(group) {
        return [...group]
          .sort((a, b) => a - b)
          .map((bit) => `b${bit}`)
          .join(" + ");
      }

      function getBitCuts(key, bitCount) {
        const configurations = partitionFieldConfigurations[key] || {};
        if (Array.isArray(configurations._bitCuts)) {
          return [...new Set(configurations._bitCuts.map(Number))]
            .filter(
              (cut) =>
                Number.isInteger(cut) && cut > 0 && cut < bitCount,
            )
            .sort((a, b) => a - b);
        }

        /* Migrate groups saved by the previous Combine Selected version. */
        if (Array.isArray(configurations._bitGroups)) {
          const cuts = new Set();
          configurations._bitGroups.forEach((group) => {
            if (!Array.isArray(group) || !group.length) return;
            const clean = [...new Set(group.map(Number))]
              .filter(
                (bit) =>
                  Number.isInteger(bit) && bit >= 0 && bit < bitCount,
              )
              .sort((a, b) => a - b);
            if (!clean.length) return;
            if (clean[0] > 0) cuts.add(clean[0]);
            if (clean[clean.length - 1] + 1 < bitCount)
              cuts.add(clean[clean.length - 1] + 1);
          });
          return [...cuts].sort((a, b) => a - b);
        }
        return [];
      }

      function bitGroupsFromCuts(cuts, bitCount) {
        const boundaries = [0, ...cuts, bitCount];
        const groups = [];
        for (let index = 0; index < boundaries.length - 1; index++) {
          const group = [];
          for (
            let bit = boundaries[index];
            bit < boundaries[index + 1];
            bit++
          )
            group.push(bit);
          if (group.length) groups.push(group);
        }
        return groups.reverse();
      }

      function getBitGroups(key, bitCount) {
        return bitGroupsFromCuts(getBitCuts(key, bitCount), bitCount);
      }

      function saveBitCuts(key, bitCount, nextCuts) {
        if (!partitionFieldConfigurations[key])
          partitionFieldConfigurations[key] = {};
        const configurations = partitionFieldConfigurations[key];
        const cleanCuts = [...new Set(nextCuts.map(Number))]
          .filter(
            (cut) =>
              Number.isInteger(cut) && cut > 0 && cut < bitCount,
          )
          .sort((a, b) => a - b);
        const validConfigurationKeys = new Set(
          bitGroupsFromCuts(cleanCuts, bitCount).map(bitGroupConfigKey),
        );

        Object.keys(configurations).forEach((configKey) => {
          if (
            (configKey.startsWith("bit:") ||
              configKey.startsWith("bit-group:")) &&
            !validConfigurationKeys.has(configKey)
          )
            delete configurations[configKey];
        });
        configurations._bitCuts = cleanCuts;
        delete configurations._bitGroups;
        selectedBitGroups[key] = [];
      }

      function toggleBitCut(key, bitCount, cut) {
        const previousScrollLeft =
          document.querySelector(
            "#partitionModeBody .bit-cut-scroll",
          )?.scrollLeft || 0;
        const cuts = getBitCuts(key, bitCount);
        const nextCuts = cuts.includes(cut)
          ? cuts.filter((item) => item !== cut)
          : [...cuts, cut];
        saveBitCuts(key, bitCount, nextCuts);
        setPartitionChanged();
        renderApiPartitionEditor();
        renderActivePartitionMode();
        restoreBitTimelineScroll(previousScrollLeft);
      }

      function clearBitCuts(key, bitCount) {
        const previousScrollLeft =
          document.querySelector(
            "#partitionModeBody .bit-cut-scroll",
          )?.scrollLeft || 0;
        saveBitCuts(key, bitCount, []);
        setPartitionChanged();
        renderApiPartitionEditor();
        renderActivePartitionMode();
        restoreBitTimelineScroll(previousScrollLeft);
      }

      function restoreBitTimelineScroll(scrollLeft) {
        requestAnimationFrame(function () {
          const timelineScroll = document.querySelector(
            "#partitionModeBody .bit-cut-scroll",
          );
          if (timelineScroll) timelineScroll.scrollLeft = scrollLeft;
        });
      }

      function getPartitionConfigurationValidation(key) {
        const range = getPartitionRanges().find(
          (item) => partitionKey(item) === key,
        );
        if (!range)
          return {
            valid: false,
            message:
              "This partition is no longer available. Recreate the partition and try again.",
          };

        const partitionName = partitionLabels[key] || "";
        if (!partitionName)
          return {
            valid: false,
            message:
              "Select a partition name before completing its configuration.",
          };

        const currentView =
          partitionName === "data"
            ? partitionViewModes[key] || "bytewise"
            : "bytewise";
        const configurations = partitionFieldConfigurations[key] || {};

        if (currentView === "bytewise") {
          return isFieldConfigurationComplete(configurations.byte)
            ? { valid: true, message: "Byte-wise configuration is complete." }
            : {
              valid: false,
              message:
                "Byte-wise configuration is incomplete. Open Configure Complete Partition, fill the form, and click Save Field.",
            };
        }

        const bitCount = (range.end - range.start) * 8;
        const bitGroups = getBitGroups(key, bitCount);
        const missingGroups = bitGroups.filter(
          (group) =>
            !isFieldConfigurationComplete(
              configurations[bitGroupConfigKey(group)],
            ),
        );
        return missingGroups.length === 0
          ? { valid: true, message: "Bit-wise configuration is complete." }
          : {
            valid: false,
            message: `Configure and save these bit partitions: ${missingGroups
              .slice(0, 8)
              .map(bitGroupLabel)
              .join(", ")}${missingGroups.length > 8 ? ` and ${missingGroups.length - 8} more` : ""}.`,
          };
      }

      function renderActivePartitionMode() {
        if (
          !activePartitionModeKey ||
          !Number.isInteger(activePartitionModeIndex)
        )
          return;
        openPartitionModePopup(
          activePartitionModeKey,
          activePartitionModeIndex,
        );
      }

      function renderPartitionConfigurationControls(
        band,
        range,
        partitionIndex,
      ) {
        const key = partitionKey(range);
        const partitionName = partitionLabels[key] || "";
        if (!partitionName) return;

        const apiBytes = getApiBytes();
        const partitionCode = apiBytes.slice(range.start, range.end).join("");
        const currentView =
          partitionName === "data"
            ? partitionViewModes[key] || "bytewise"
            : "bytewise";
        const controls = document.createElement("div");
        controls.className = "partition-config-controls";

        if (partitionName === "data") {
          const toggles = document.createElement("div");
          toggles.className = "view-toggle-buttons";
          const byteButton = document.createElement("button");
          byteButton.type = "button";
          byteButton.className =
            "view-toggle-btn" +
            (currentView === "bytewise" ? " active" : "");
          byteButton.innerHTML =
            '<i class="fas fa-cube"></i> Byte Wise';
          byteButton.addEventListener("click", function () {
            partitionViewModes[key] = "bytewise";
            setPartitionChanged();
            renderApiPartitionEditor();
            renderActivePartitionMode();
          });
          const bitButton = document.createElement("button");
          bitButton.type = "button";
          bitButton.className =
            "view-toggle-btn" +
            (currentView === "bitwise" ? " active" : "");
          bitButton.innerHTML = '<i class="fas fa-grip"></i> Bit Wise';
          bitButton.addEventListener("click", function () {
            partitionViewModes[key] = "bitwise";
            setPartitionChanged();
            renderApiPartitionEditor();
            renderActivePartitionMode();
          });
          toggles.append(byteButton, bitButton);
          controls.appendChild(toggles);
        } else {
          const byteOnly = document.createElement("div");
          byteOnly.className = "view-toggle-buttons single-view";
          const byteOnlyButton = document.createElement("button");
          byteOnlyButton.type = "button";
          byteOnlyButton.className = "view-toggle-btn active";
          byteOnlyButton.innerHTML = '<i class="fas fa-cube"></i> Byte Wise';
          byteOnlyButton.addEventListener("click", function () {
            openPartitionFieldModal(key, partitionCode, partitionIndex);
          });
          byteOnly.appendChild(byteOnlyButton);
          controls.appendChild(byteOnly);
        }

        if (partitionName !== "data" || currentView === "bytewise") {
          const field = partitionFieldConfigurations[key]?.byte || {};
          const fieldComplete = isFieldConfigurationComplete(field);
          const action = document.createElement("button");
          action.type = "button";
          action.className = `byte-wise-action${fieldComplete ? "" : " config-missing"}`;
          action.setAttribute(
            "aria-invalid",
            fieldComplete ? "false" : "true",
          );
          action.innerHTML = `<span><strong>${fieldComplete ? "Configuration Saved" : '<span class="click-here-highlight">Click Here</span> <span class="configure-complete-text">Configure Complete Partition</span>'}</strong>${fieldComplete ? `<small>${field.dataType} ${field.uiType}</small>` : ""}</span><i class="fas ${fieldComplete ? "fa-circle-check" : "fa-hand-pointer"}"></i>`;
          action.addEventListener("click", function () {
            openPartitionFieldModal(key, partitionCode, partitionIndex);
          });
          controls.appendChild(action);
          if (!fieldComplete) {
            const inlineWarning = document.createElement("div");
            inlineWarning.className = "inline-config-warning";
            inlineWarning.innerHTML =
              '<i class="fas fa-triangle-exclamation"></i> Byte-wise form must be completed and saved.';
            controls.appendChild(inlineWarning);
          }
        } else {
          const binary = hexToBinary(partitionCode);
          const bitCount = binary.length;
          const bitCuts = getBitCuts(key, bitCount);
          const bitGroups = getBitGroups(key, bitCount);
          const bitGroupByPosition = {};
          bitGroups.forEach((group, groupIndex) => {
            group.forEach((bitPosition) => {
              bitGroupByPosition[bitPosition] = { group, groupIndex };
            });
          });

          const help = document.createElement("div");
          help.className = "bit-partition-help";
          help.innerHTML =
            '<i class="fas fa-scissors"></i> Click + between bits to create partitions. Click a colored bit partition below to open its Field Configuration.';
          controls.appendChild(help);

          const timelineScroll = document.createElement("div");
          timelineScroll.className = "bit-cut-scroll";
          const timeline = document.createElement("div");
          timeline.className = "bit-cut-timeline";
          timeline.style.gridTemplateColumns = `repeat(${bitCount}, minmax(68px, 1fr))`;
          timeline.style.minWidth = `${Math.max(560, bitCount * 68)}px`;

          for (
            let bitPosition = bitCount - 1;
            bitPosition >= 0;
            bitPosition--
          ) {
            const bitValue = binary[bitCount - 1 - bitPosition];
            const groupInfo = bitGroupByPosition[bitPosition];
            const group = groupInfo.group;
            const groupColor =
              PARTITION_COLORS[groupInfo.groupIndex % PARTITION_COLORS.length];
            const bit = document.createElement("div");
            bit.className = "bit-cut-cell";
            bit.style.gridColumn = String(bitCount - bitPosition);
            bit.style.setProperty("--bit-group-color", groupColor.color);
            bit.style.setProperty("--bit-group-soft", groupColor.soft);
            bit.style.setProperty("--bit-group-text", groupColor.text);
            bit.innerHTML = `<span class="bit-cut-index">b${bitPosition}</span><span class="bit-cut-value">${bitValue}</span>`;
            timeline.appendChild(bit);
          }

          bitGroups.forEach((group, groupIndex) => {
            const groupColor =
              PARTITION_COLORS[groupIndex % PARTITION_COLORS.length];
            const configKey = bitGroupConfigKey(group);
            const groupComplete = isFieldConfigurationComplete(
              partitionFieldConfigurations[key]?.[configKey],
            );
            const rangeBlock = document.createElement("div");
            const isSingleBitGroup = group.length === 1;
            rangeBlock.className = `bit-range-block${isSingleBitGroup ? " single-bit-range" : ""}${groupComplete ? "" : " missing"}`;
            const groupStart = group[0];
            const groupEnd = group[group.length - 1];
            rangeBlock.style.gridColumn = `${bitCount - groupEnd} / ${bitCount - groupStart + 1}`;
            rangeBlock.style.setProperty(
              "--bit-group-color",
              groupColor.color,
            );
            rangeBlock.style.setProperty("--bit-group-soft", groupColor.soft);
            rangeBlock.style.setProperty("--bit-group-text", groupColor.text);
            const configureButtonText = groupComplete
              ? "Edit"
              : isSingleBitGroup
                ? "Configure"
                : "Configure Partition";
            rangeBlock.innerHTML = `<span><i class="fas ${groupComplete ? "fa-circle-check" : "fa-sliders"}"></i> ${bitGroupLabel(group)}</span><small>${groupComplete ? "Configuration saved" : "Configuration required"}</small><button type="button" class="bit-configure-btn" title="${groupComplete ? "Edit field configuration" : "Configure this bit partition"}"><i class="fas ${groupComplete ? "fa-pen" : "fa-sliders"}"></i><span>${configureButtonText}</span></button>`;
            rangeBlock.setAttribute(
              "aria-label",
              `${bitGroupLabel(group)}: ${groupComplete ? "configuration saved" : "open field configuration"}`,
            );
            const openBitGroupConfiguration = function (event) {
              event?.preventDefault();
              event?.stopPropagation();
              openPartitionFieldModal(
                key,
                partitionCode,
                partitionIndex,
                undefined,
                group,
              );
            };
            rangeBlock.addEventListener(
              "click",
              openBitGroupConfiguration,
            );
            rangeBlock
              .querySelector(".bit-configure-btn")
              .addEventListener("click", openBitGroupConfiguration);
            timeline.appendChild(rangeBlock);
          });

          for (let cut = 1; cut < bitCount; cut++) {
            const marker = document.createElement("button");
            marker.type = "button";
            const isActive = bitCuts.includes(cut);
            marker.className = `bit-cut-target${isActive ? " active" : ""}`;
            marker.style.left = `${((bitCount - cut) / bitCount) * 100}%`;
            if (isActive) {
              const rightGroupIndex = bitGroups.findIndex(
                (group) => group[0] === cut,
              );
              const markerColor =
                PARTITION_COLORS[
                (rightGroupIndex === -1 ? 0 : rightGroupIndex) %
                PARTITION_COLORS.length
                ];
              marker.style.setProperty("--bit-cut-color", markerColor.color);
            }
            marker.title = isActive
              ? `Remove cut between b${cut} and b${cut - 1}`
              : `Add cut between b${cut} and b${cut - 1}`;
            marker.setAttribute("aria-label", marker.title);
            marker.addEventListener("click", function (event) {
              event.preventDefault();
              event.stopPropagation();
              toggleBitCut(key, bitCount, cut);
            });
            timeline.appendChild(marker);
          }
          timelineScroll.appendChild(timeline);
          controls.appendChild(timelineScroll);

          const actions = document.createElement("div");
          actions.className = "bit-cut-actions";
          const clearButton = document.createElement("button");
          clearButton.type = "button";
          clearButton.className = "bit-partition-action secondary";
          clearButton.disabled = bitCuts.length === 0;
          clearButton.innerHTML =
            '<i class="fas fa-eraser"></i> Clear Bit Cuts';
          clearButton.addEventListener("click", function () {
            clearBitCuts(key, bitCount);
          });
          const count = document.createElement("span");
          count.className = "partition-limit";
          count.textContent = `${bitGroups.length} bit partition${bitGroups.length === 1 ? "" : "s"}`;
          actions.append(clearButton, count);
          controls.appendChild(actions);

          const binaryValue = document.createElement("div");
          binaryValue.className = "binary-value";
          binaryValue.textContent = `${partitionCode} = ${binary}`;
          controls.appendChild(binaryValue);

          const bitValidation = getPartitionConfigurationValidation(key);
          if (!bitValidation.valid) {
            const inlineWarning = document.createElement("div");
            inlineWarning.className = "inline-config-warning";
            inlineWarning.innerHTML = `<i class="fas fa-triangle-exclamation"></i> ${bitValidation.message}`;
            controls.appendChild(inlineWarning);
          }
        }

        band.appendChild(controls);
      }

      function updatePartitionStatus() {
        const validation = getPartitionValidation();
        const status = document.getElementById("partitionStatus");
        const confirmButton = document.getElementById("confirmPartitionsBtn");
        const hasCompleteApi =
          Boolean(fullApiValue) && fullApiValue.length % 2 === 0;
        status.className = "partition-status";

        if (partitionsConfirmed && validation.valid) {
          status.classList.add("complete");
          status.innerHTML = `<i class="fas fa-circle-check"></i><span>Step 2 complete for ${getActiveFrameLabel()} Frame ${(activePartitionFrameIndex ?? 0) + 1}: ${validation.message}</span>`;
          confirmButton.innerHTML =
            'Frame Partitions Saved <i class="fas fa-check"></i>';
        } else {
          if (showPartitionWarnings && hasCompleteApi && !validation.valid) {
            status.classList.add("error");
            status.innerHTML = `<i class="fas fa-triangle-exclamation"></i><span>${validation.message}</span>`;
          } else {
            status.innerHTML = `<i class="fas fa-circle-info"></i><span>${hasCompleteApi
                ? "Tip: click + between bytes to cut, then name each partition below."
                : "Enter the API, create partitions, and name every block."
              }</span>`;
          }
          confirmButton.innerHTML =
            'Save Frame Partitions <i class="fas fa-check"></i>';
        }
        confirmButton.disabled = !hasCompleteApi;
      }

      function renderApiPartitionEditor(skipHexByteEditor = false) {
        if (!skipHexByteEditor) renderHexByteEditor();
        enforceCommandGetStatusPartitionRules();
        const byteCount = getApiBytes().length;
        const hasRestoredLayout = !fullApiValue && restoredByteCount > 0;
        const isComplete =
          (Boolean(fullApiValue) && fullApiValue.length % 2 === 0) ||
          hasRestoredLayout;
        partitionCuts = partitionCuts.filter(
          (cut) => cut > 0 && cut < byteCount,
        );
        document.getElementById("apiByteCount").innerHTML =
          hasRestoredLayout
            ? `<i class="fas fa-database"></i> ${byteCount} saved byte positions restored`
            : `<i class="fas fa-ruler-horizontal"></i> ${isComplete ? byteCount : Math.floor(fullApiValue.length / 2)} bytes, ${fullApiValue.length} hex characters`;
        document.getElementById("apiError").textContent =
          fullApiValue && !isComplete
            ? "Incomplete byte: every byte needs exactly 2 hexadecimal characters."
            : hasRestoredLayout
              ? "Saved partitions and configurations were restored. Enter the original full API only if you need to change its byte values."
            : "";
        document
          .getElementById("partitionReadyHint")
          .classList.toggle(
            "show",
            Boolean(fullApiValue) && isComplete && byteCount >= 2,
          );
        document.getElementById("partitionLimitText").textContent =
          byteCount < 2
            ? "Enter at least 2 bytes to add a cut."
            : `${getPartitionRanges().length} of ${byteCount} possible partitions`;
        document.getElementById("clearPartitionsBtn").disabled =
          isCommandGetStatusCommandLocked() || partitionCuts.length === 0;
        document.getElementById("addPartitionBtn").disabled =
          isCommandGetStatusCommandLocked() || byteCount < 2 || partitionCuts.length >= byteCount - 1;
        renderApiTimeline();
        renderPartitionVisualBlocks();
        updatePartitionStatus();
        updateLinkedApiPanel();
      }

      document
        .getElementById("fullApiInput")
        .addEventListener("input", function () {
          if (isCommandGetStatusCommandLocked()) {
            this.value = COMMAND_GET_STATUS_FIXED_VALUE;
            enforceCommandGetStatusCommandState(true);
            return;
          }
          if (isCommandGetStatusResponseFrame()) {
            const cleanedResponse = cleanFullApi(this.value);
            const responseBytes = cleanedResponse.match(/[0-9A-F]{2}/g) || [];
            if (responseBytes.length >= 3 && responseBytes[0] === "DE" && responseBytes[1] === "E7" && responseBytes[responseBytes.length - 1] === "0A") {
              syncCommandGetStatusResponseValue(responseBytes, true);
            } else {
              syncCommandGetStatusResponseValue(["DE", "E7", "0A"], true);
            }
            renderApiPartitionEditor();
            return;
          }
          const cleaned = cleanFullApi(this.value);
          if (this.value !== cleaned) this.value = cleaned;
          this.closest(".input-with-icon")?.classList.remove("input-error");
          this.removeAttribute("aria-invalid");
          fullApiValue = cleaned;
          resetHexEditorDraftFromApiValue();
          restoredByteCount = cleaned
            ? Math.ceil(cleaned.length / 2)
            : 0;
          partitionCuts = partitionCuts.filter(
            (cut) => cut < getApiBytes().length,
          );
          setPartitionChanged();
          renderApiPartitionEditor();
        });

      document
        .getElementById("addPartitionBtn")
        .addEventListener("click", function () {
          if (isCommandGetStatusCommandLocked()) return;
          const byteCount = getApiBytes().length;
          if (byteCount < 2) return;

          const previousScrollLeft = getApiTimelineScrollLeft();
          const candidateCuts = Array.from(
            { length: byteCount - 1 },
            (_, index) => index + 1,
          ).filter((cut) => !isCommandGetStatusProtectedCut(cut));
          const nextCut = candidateCuts.find((cut) => !partitionCuts.includes(cut));

          if (!nextCut) return;

          partitionCuts = [...partitionCuts, nextCut].sort((a, b) => a - b);
          setPartitionChanged();
          renderApiPartitionEditor();
          restoreApiTimelineScroll(previousScrollLeft);
        });

      document
        .getElementById("clearPartitionsBtn")
        .addEventListener("click", function () {
          if (isCommandGetStatusCommandLocked()) return;
          const previousScrollLeft = getApiTimelineScrollLeft();
          partitionCuts = [];
          enforceCommandGetStatusPartitionRules();
          setPartitionChanged();
          renderApiPartitionEditor();
          restoreApiTimelineScroll(previousScrollLeft);
        });

      document
        .getElementById("confirmPartitionsBtn")
        .addEventListener("click", async function () {
          const validation = getPartitionValidation();
          if (

            !validation.valid ||
            !Number.isInteger(activePartitionFrameIndex)
          ) {
            showPartitionWarnings = true;
            renderApiPartitionEditor();
            const firstMissing = document.querySelector(
              ".partition-name-band.show-warning, .byte-wise-action.config-missing, .bit.config-missing",
            );
            firstMissing?.scrollIntoView({
              behavior: "smooth",
              block: "center",
            });
            return;
          }
          showPartitionWarnings = false;
          partitionsConfirmed = true;
          captureActiveFramePartitionState();
          syncFrameStructureFromStepOne();
          const generatedCount = document.querySelectorAll(
            "#commandFramesContainer .command-frame-card",
          ).length;
          applyStepOneTemplateToFrames(
            generatedCount,
            true,
            activePartitionFrameIndex,
          );
          captureActiveFramePartitionState();
          updatePartitionStatus();
          updateLinkedApiPanel();
          if (generatedCount > 0 && checkRequirements()) {
            generateCommandFrames(generatedCount, true);
            updateFieldDescFrameSelect();
            renderFieldDescription();
          }
          updateFramePartitionStates();
          const confirmButton = document.getElementById(
            "confirmPartitionsBtn",
          );
          if (confirmButton) {
            confirmButton.disabled = true;
            confirmButton.setAttribute("aria-busy", "true");
          }
          try {
            await persistConfiguration(
              `Frame ${activePartitionFrameIndex + 1} saved`,
            );
            moveToCommandResponseErrorFlow(true);
          } catch (error) {
            console.error("Unable to save the frame partitions.", error);
            updateSaveBadge("error", "Frame partition save failed");
            alert(error.message || "The frame partitions could not be saved.");
          } finally {
            if (confirmButton) {
              confirmButton.removeAttribute("aria-busy");
            }
            updatePartitionStatus();
          }
        });

      function generateByteValue(index) {
        return "0x" + String(index + 1).padStart(2, "0");
      }

      function initBytes(count) {
        bytes = [];
        for (let i = 0; i < count; i++) {
          bytes.push({ id: i, value: generateByteValue(i), active: false });
        }
      }
      initBytes(8);
      if (bytes.length >= 7) {
        bytes[0].active = true;
        bytes[2].active = true;
        bytes[6].active = true;
      }
      function getVoiceCommandRequirementState() {
        const select = document.getElementById("voiceCommandEnableSelect");
        const selected = String(select?.value || "").trim();
        const inputs = Array.from(
          document.querySelectorAll("#voiceCommandList .voice-command-input"),
        );

        if (!["Yes", "No"].includes(selected)) {
          return {
            valid: false,
            message: "Select Voice Command as Yes or No.",
            selected,
            inputs,
          };
        }

        if (selected === "Yes") {
          if (!inputs.length) {
            return {
              valid: false,
              message: "Add and fill at least one Voice Command Phrase.",
              selected,
              inputs,
            };
          }

          const emptyInputs = inputs.filter((input) => !input.value.trim());
          if (emptyInputs.length) {
            return {
              valid: false,
              message: "Fill every Voice Command Phrase before generating frames.",
              selected,
              inputs,
            };
          }
        }

        return {
          valid: true,
          message: "",
          selected,
          inputs,
        };
      }

      function updateVoiceCommandRequiredState(showWarnings = false) {
        const state = getVoiceCommandRequirementState();
        const editor = document.getElementById("voiceCommandEditor");
        const phraseInvalid =
          showWarnings && state.selected === "Yes" && !state.valid;

        editor?.classList.toggle("voice-command-invalid", phraseInvalid);

        state.inputs.forEach((input) => {
          const invalid =
            phraseInvalid && !String(input.value || "").trim();
          input.classList.toggle("voice-command-invalid", invalid);
          input.setAttribute("aria-invalid", String(invalid));
        });
      }

      function checkRequirements() {
        const paramName = document
          .getElementById("paramNameInput")
          ?.value?.trim();
        const frameCount = Number.parseInt(
          document.getElementById("cmdFrameCountInput")?.value,
          10,
        );
        const voiceRequirement = getVoiceCommandRequirementState();

        return (
          Boolean(paramName) &&
          Number.isInteger(frameCount) &&
          frameCount >= 1 &&
          voiceRequirement.valid
        );
      }


      const requiredDropdowns = [
        {
          id: "parameterNameSourceSelect",
          label: "Parameter Name",
          icon: "fa-signature",
          message: () => {
            const source = document.getElementById("parameterNameSourceSelect")?.value || "";
            if (!source) return "Select Existing Parameter or Custom Parameter Name.";
            if (source === "existing") return "Select a parameter from Command Get Status Response.";
            return "Enter a custom parameter name.";
          },
          isInput: false,
          validate: () => Boolean(document.getElementById("paramNameInput")?.value?.trim()),
        },
        {
          id: "cmdFrameCountInput",
          label: "No. of Frames",
          icon: "fa-layer-group",
          message: () =>
            `Enter at least 1 ${getActiveFrameLabel().toLowerCase()} frame.`,
          isInput: true,
          validate: (el) => {
            const count = Number.parseInt(el.value, 10);
            return Number.isInteger(count) && count >= 1;
          },
        },
        {
          id: "voiceCommandEnableSelect",
          label: "Voice Command / Voice Command Phrases",
          icon: "fa-microphone",
          message: () => getVoiceCommandRequirementState().message,
          isInput: false,
          validate: () => getVoiceCommandRequirementState().valid,
        },
      ];
      function isRequiredFieldValid(field) {
        const el = document.getElementById(field.id);
        if (!el) return false;
        if (typeof field.validate === "function") return field.validate(el);
        if (field.isInput) return Boolean(el.value?.trim());
        return Boolean(el.value);
      }

      function updateSetupFieldHints() {
        requiredDropdowns.forEach((field) => {
          const hint = document.querySelector(
            `.field-setup-hint[data-for="${field.id}"]`,
          );
          const item = document
            .getElementById(field.id)
            ?.closest(".param-item");
          const valid = isRequiredFieldValid(field);
          if (hint) hint.hidden = valid || showSetupWarnings;
          item?.classList.toggle("has-error", showSetupWarnings && !valid);
        });
      }

      function updateRequiredDropdownWarnings(showWarnings = true) {
        showSetupWarnings = showWarnings;
        requiredDropdowns.forEach((field) => {
          const { id, message, isInput } = field;
          const control = document.getElementById(id);
          if (!control) return;
          const wrapper = isInput
            ? control.closest(".input-with-icon")
            : control.closest(".select-with-icon");
          if (!wrapper) return;
          let warning = wrapper.parentElement.querySelector(
            `.dropdown-warning[data-for="${id}"]`,
          );
          if (!warning) {
            warning = document.createElement("span");
            warning.className = "dropdown-warning";
            warning.dataset.for = id;
            warning.setAttribute("role", "alert");
            warning.innerHTML =
              '<i class="fas fa-triangle-exclamation"></i><span></span>';
            wrapper.insertAdjacentElement("afterend", warning);
          }
          const warningMessage =
            typeof message === "function" ? message() : message;
          warning.querySelector("span").textContent = warningMessage;
          const invalid = !isRequiredFieldValid(field);
          wrapper.classList.toggle(
            isInput ? "input-error" : "dropdown-error",
            invalid && showWarnings,
          );
          control.setAttribute(
            "aria-invalid",
            String(invalid && showWarnings),
          );
          warning.hidden = !(invalid && showWarnings);
        });
        updateSetupFieldHints();
        updateVoiceCommandRequiredState(showWarnings);
      }

      function showRequirementPopup() {
        const missing = requiredDropdowns.filter(
          (field) => !isRequiredFieldValid(field),
        );
        updateRequiredDropdownWarnings(true);
        if (!missing.length) return;

        const overlay = document.getElementById("generateValidationOverlay");
        const list = document.getElementById("generateMissingList");
        const message = document.getElementById("generateValidationMessage");
        if (message) {
          message.textContent =
            `Fill the highlighted fields below, then click Generate ${getActiveFrameLabel()} Frames again.`;
        }
        list.innerHTML = missing
          .map(
            ({ label, icon }) =>
              `<li class="generate-missing-item"><i class="fas ${icon}" aria-hidden="true"></i><span>${label} is required</span></li>`,
          )
          .join("");
        overlay.dataset.firstMissing = missing[0].id;
        overlay.classList.add("open");
        overlay.setAttribute("aria-hidden", "false");
        document.getElementById("continueSetupBtn").focus();
      }

      function closeRequirementPopup(focusMissingField = false) {
        const overlay = document.getElementById("generateValidationOverlay");
        const firstMissingId = overlay.dataset.firstMissing;
        overlay.classList.remove("open");
        overlay.setAttribute("aria-hidden", "true");
        if (focusMissingField && firstMissingId) {
          const field = document.getElementById(firstMissingId);
          const target =
            field?.closest(".param-item") ||
            field?.closest(".command-frame-card") ||
            field;
          target?.scrollIntoView({ behavior: "smooth", block: "center" });
          setTimeout(() => field?.focus(), 250);
        }
      }

      function showFrameSettingsValidationPopup(frameIndex, missingFields) {
        if (!Array.isArray(missingFields) || !missingFields.length) return;

        const overlay = document.getElementById("generateValidationOverlay");
        const list = document.getElementById("generateMissingList");
        const message = document.getElementById("generateValidationMessage");
        const firstMissingId = missingFields[0].id;
        const frameLabel = `${getActiveFrameLabel()} Frame ${frameIndex + 1}`;

        if (message) {
          const missingNames = missingFields
            .map((field) => field.label)
            .join(" and ");

          message.textContent =
            `${frameLabel} is not ready to save. Select ${missingNames} before entering the frame value and continuing configuration.`;
        }
        if (list) {
          list.innerHTML = missingFields
            .map(
              ({ label, icon }) =>
                `<li class="generate-missing-item"><i class="fas ${icon}" aria-hidden="true"></i><span>${label} is required for ${frameLabel}</span></li>`,
            )
            .join("");
        }

        overlay.dataset.firstMissing = firstMissingId;
        overlay.classList.add("open");
        overlay.setAttribute("aria-hidden", "false");
        document.getElementById("continueSetupBtn")?.focus();
      }

      document
        .getElementById("continueSetupBtn")
        .addEventListener("click", () => closeRequirementPopup(true));
      document
        .getElementById("generateValidationOverlay")
        .addEventListener("click", function (event) {
          if (event.target === this) closeRequirementPopup(true);
        });
      document.addEventListener("keydown", function (event) {
        if (
          event.key === "Escape" &&
          document
            .getElementById("generateValidationOverlay")
            .classList.contains("open")
        ) {
          closeRequirementPopup(true);
        }
      });

      function renderAll() {
        renderByteRow("byteRowContainer", bytes);
        updateSelectedInfo();
        updateFrameSizeLabel();
        const count =
          parseInt(document.getElementById("cmdFrameCountInput").value) || 0;
        if (count > 0 && bytes.length > 0 && checkRequirements()) {
          generateCommandFrames(count, true);
        } else {
          updateCommandFrameCount();
        }
        updateFieldDescFrameSelect();
        renderFieldDescription();
      }

      function renderByteRow(containerId, byteArray) {
        const container = document.getElementById(containerId);
        if (!container) return;
        container.innerHTML = "";
        byteArray.forEach((b, idx) => {
          const div = document.createElement("div");
          div.className = "byte-item" + (b.active ? " active" : "");
          div.dataset.index = idx;
          div.innerHTML = `<span class="byte-label">Byte ${idx + 1}</span><span class="byte-value">${b.value}</span>`;
          div.addEventListener("click", function (e) {
            e.stopPropagation();
            toggleByte(idx);
          });
          container.appendChild(div);
        });
      }

      function toggleByte(index) {
        if (index >= 0 && index < bytes.length) {
          bytes[index].active = !bytes[index].active;
          renderAll();
          const count =
            parseInt(document.getElementById("cmdFrameCountInput").value) ||
            0;
          if (count > 0 && bytes.length > 0 && checkRequirements()) {
            generateCommandFrames(count, true);
          }
        }
      }

      function updateSelectedInfo() {
        const activeIndices = bytes
          .map((b, i) => (b.active ? i + 1 : null))
          .filter((v) => v !== null);
        const selectedCount = document.getElementById("selectedCount");
        const selectedBytesList =
          document.getElementById("selectedBytesList");
        if (selectedCount) selectedCount.textContent = activeIndices.length;
        if (selectedBytesList) {
          selectedBytesList.textContent =
            activeIndices.length > 0 ? activeIndices.join(", ") : "None";
        }
      }

      function updateFrameSizeLabel() {
        const frameSizeLabel = document.getElementById("frameSizeLabel");
        if (frameSizeLabel) frameSizeLabel.textContent = bytes.length;
      }

      function generate8Bytes() {
        initBytes(8);
        if (bytes.length >= 7) {
          bytes[0].active = true;
          bytes[2].active = true;
          bytes[6].active = true;
        }
        renderAll();
        const count =
          parseInt(document.getElementById("cmdFrameCountInput").value) || 0;
        if (count > 0 && checkRequirements()) {
          generateCommandFrames(count, true);
        }
      }

      const addByteBtn = document.getElementById("addByteBtn");
      if (addByteBtn) {
        addByteBtn.addEventListener("click", function () {
          const newId = bytes.length;
          bytes.push({
            id: newId,
            value: generateByteValue(newId),
            active: false,
          });
          renderAll();
          const count =
            parseInt(document.getElementById("cmdFrameCountInput").value) ||
            0;
          if (count > 0 && checkRequirements()) {
            generateCommandFrames(count, true);
          }
        });
      }

      const resetBytesBtn = document.getElementById("resetBytesBtn");
      if (resetBytesBtn) {
        resetBytesBtn.addEventListener("click", function () {
          generate8Bytes();
        });
      }

      function generateCommandFrames(count, preserveSelection) {
        if (isCommandGetStatusCommandLocked()) {
          count = 1;
          preserveSelection = true;
          enforceCommandGetStatusCommandState(true);
        }
        if (!preserveSelection && !checkRequirements()) {
          showRequirementPopup();
          return;
        }

        const container = document.getElementById("commandFramesContainer");
        if (count > 0 && frameGenerationRevealed) {
          document
            .getElementById("commandFramesSection")
            ?.classList.add("is-visible");
        }
        container.replaceChildren();
        container.dataset.visibleFrameType = activeFrameType;
        container.setAttribute(
          "aria-label",
          `${getActiveFrameLabel()} frames only`,
        );
        const byteSize = bytes.length;
        if (byteSize === 0) {
          document.getElementById("cmdFrameCountDisplay").textContent = 0;
          return;
        }

        if (!preserveSelection) {
          frameCodes = frameCodes.slice(0, count);
          frameValueGroups = frameValueGroups.slice(0, count);
          frameConfigurations = frameConfigurations.slice(0, count);
          const newFieldDesc = {};
          const newByteDesc = {};
          const newViewModes = {};
          for (let i = 0; i < count; i++) {
            if (fieldDescriptions[i]) newFieldDesc[i] = fieldDescriptions[i];
            if (byteDescriptions[i]) newByteDesc[i] = byteDescriptions[i];
            if (fieldViewModes[i]) newViewModes[i] = fieldViewModes[i];
          }
          fieldDescriptions = newFieldDesc;
          byteDescriptions = newByteDesc;
          fieldViewModes = newViewModes;
        }
        while (frameCodes.length < count) frameCodes.push("");
        while (frameValueGroups.length < count) frameValueGroups.push([]);
        while (framePartitionStates.length < count)
          framePartitionStates.push(null);

        // Command, Response and Error are independent. New Response/Error
        // frames stay empty until the user enters their own hexadecimal bytes.
        while (frameConfigurations.length < count) {
          frameConfigurations.push({
            dataFlowDirection: "",
            multipleUi: "",
          });
        }
        framePartitionStates = framePartitionStates.slice(0, count);
        frameConfigurations = frameConfigurations.slice(0, count);
        if (
          Number.isInteger(activePartitionFrameIndex) &&
          activePartitionFrameIndex >= count
        ) {
          activePartitionFrameIndex = null;
          selectedFrameIndex = null;
          document
            .getElementById("apiPartitionSection")
            .classList.remove("frame-partition-active");
        }
        if (Number.isInteger(activePartitionFrameIndex)) {
          applyStepOneTemplateToFrames(
            count,
            false,
            activePartitionFrameIndex,
          );
        }

        for (let i = 0; i < count; i++) {
          const card = document.createElement("div");
          card.dataset.frameType = activeFrameType;
          const fillStatus = getFrameFillStatus(i);
          card.className = "command-frame-card";
          if (fillStatus === "filled") card.classList.add("partition-complete");
          else if (fillStatus === "in-progress")
            card.classList.add("frame-in-progress");
          else card.classList.add("needs-partition");
          card.style.animationDelay = `${Math.min(i * 55, 330)}ms`;
          if (selectedFrameIndex === i) card.classList.add("selected");
          const frameName = `${getActiveFrameLabel()} Frame ${i + 1}`;
          const codeText = frameCodes[i] || "Not entered";
          const frameConfiguration = frameConfigurations[i] || {
            dataFlowDirection: "",
            multipleUi: "",
          };
          const directionText =
            frameConfiguration.dataFlowDirection === "server_to_device"
              ? "Server to Device"
              : frameConfiguration.dataFlowDirection === "device_to_server"
                ? "Device to Server"
                : "Direction not selected";
          const directionIcon =
            frameConfiguration.dataFlowDirection === "device_to_server"
              ? "fa-arrow-left"
              : frameConfiguration.dataFlowDirection === "server_to_device"
                ? "fa-arrow-right"
                : "fa-right-left";
          const statusBadge =
            fillStatus === "filled"
              ? '<span class="frame-status-badge filled"><i class="fas fa-circle-check"></i> Filled</span>'
              : fillStatus === "in-progress"
                ? '<span class="frame-status-badge in-progress"><i class="fas fa-spinner"></i> In progress</span>'
                : '<span class="frame-status-badge pending"><i class="fas fa-hourglass-half"></i> Pending</span>';
          const stateHtml =
            fillStatus === "filled"
              ? '<div class="frame-partition-state complete"><i class="fas fa-circle-check"></i> API partitioned</div>'
              : fillStatus === "in-progress"
                ? '<div class="frame-partition-state in-progress"><i class="fas fa-pen-to-square"></i> Finish partitioning</div>'
                : '<div class="frame-partition-state" hidden style="display:none"></div>';

          const configLabel =
            fillStatus === "filled"
              ? "Open Configuration"
              : fillStatus === "in-progress"
                ? "Continue Configuration"
                : "Click Here to Configure";

          card.innerHTML = `
                        <div class="frame-card-head">
                          <div class="frame-title">
                            <span class="frame-title-main">
                              <span class="frame-card-icon" aria-hidden="true"><i class="fas fa-code"></i></span>
                              <span>${frameName}</span>
                            </span>
                          </div>
                          ${statusBadge}
                          <button type="button" class="remove-btn" data-idx="${i}" title="Delete ${frameName}" aria-label="Delete ${frameName}"><i class="fas fa-trash-can"></i></button>
                        </div>
                        <div class="frame-settings" aria-label="${frameName} settings">
                          <div class="frame-setting">
                            <label for="frameDirection${i}"><i class="fas fa-right-left"></i> Data Flow Direction</label>
                            <select id="frameDirection${i}" class="frame-direction-select" data-idx="${i}" required>
                              <option value="" disabled ${frameConfiguration.dataFlowDirection ? "" : "selected"}>Select Direction</option>
                              <option value="server_to_device" ${frameConfiguration.dataFlowDirection === "server_to_device" ? "selected" : ""}>Server to Device</option>
                              <option value="device_to_server" ${frameConfiguration.dataFlowDirection === "device_to_server" ? "selected" : ""}>Device to Server</option>
                            </select>
                          </div>
                          <div class="frame-setting">
                            <label for="frameMultipleUi${i}">
                              <i class="fas fa-window-restore"></i> Multiple UI
                            </label>

                            <button
                              type="button"
                              id="frameMultipleUi${i}"
                              class="frame-multiple-ui-button ${frameConfiguration.multipleUi ? "has-value" : ""}"
                              data-idx="${i}"
                              data-value="${frameConfiguration.multipleUi || ""}"
                              aria-haspopup="dialog"
                              aria-expanded="false"
                              aria-invalid="false"
                            >
                              <span class="multiple-ui-button-main">
                                <i class="fas ${
                                  frameConfiguration.multipleUi === "true"
                                    ? "fa-layer-group"
                                    : frameConfiguration.multipleUi === "false"
                                      ? "fa-square"
                                      : "fa-window-restore"
                                }"></i>
                                <span class="multiple-ui-button-copy">
                                  <strong>${
                                    frameConfiguration.multipleUi === "true"
                                      ? "True — Multiple UI"
                                      : frameConfiguration.multipleUi === "false"
                                        ? "False — Single UI"
                                        : "Choose True or False"
                                  }</strong>
                                  <small>${
                                    frameConfiguration.multipleUi === "true"
                                      ? "This frame can represent more than one UI control."
                                      : frameConfiguration.multipleUi === "false"
                                        ? "This frame represents one UI control."
                                        : "Click to choose the UI representation."
                                  }</small>
                                </span>
                              </span>
                              <i class="fas fa-chevron-right multiple-ui-chevron" aria-hidden="true"></i>
                            </button>
                          </div>
                        </div>
                        <div class="frame-code">Code: <strong>${codeText}</strong></div>
                        ${stateHtml}
                        <button type="button" class="frame-config-btn" data-idx="${i}" title="${configLabel}" aria-label="${configLabel} for ${frameName}"><i class="fas fa-sliders"></i> ${configLabel}</button>
                    `;
          if (awaitingFrameClick && fillStatus !== "filled") {
            card.classList.add("awaiting-click");
          }

          const commandFrameFullyLocked = isCommandGetStatusCommandLocked();
          if (commandFrameFullyLocked) {
            card.classList.add("command-get-status-frame-locked");
            const multipleUiButton = card.querySelector(".frame-multiple-ui-button");
            if (multipleUiButton) {
              multipleUiButton.disabled = true;
              multipleUiButton.setAttribute("aria-disabled", "true");
              multipleUiButton.title = "Multiple UI is locked for Command Get Status";
            }
            const configButton = card.querySelector(".frame-config-btn");
            if (configButton) {
              configButton.disabled = true;
              configButton.setAttribute("aria-disabled", "true");
              configButton.innerHTML = '<i class="fas fa-lock"></i> Configuration Locked';
              configButton.title = "Only Data Flow Direction can be edited";
            }
          }

          card.addEventListener("click", function (e) {
            if (commandFrameFullyLocked) return;
            if (
              e.target.closest(".remove-btn") ||
              e.target.closest(".frame-config-btn") ||
              e.target.closest(".frame-multiple-ui-button")
            )
              return;
            document.getElementById("byteDetailPopup").style.display = "none";
            openFramePartitionEditor(i);
          });

          card
            .querySelector(".frame-config-btn")
            .addEventListener("click", function (e) {
              e.preventDefault();
              e.stopPropagation();
              if (commandFrameFullyLocked) return;
              document.getElementById("byteDetailPopup").style.display =
                "none";
              openFramePartitionEditor(i);
            });

          const deleteHandler = function (e) {
            e.preventDefault();
            e.stopPropagation();
            deleteCommandFrame(i);
          };
          const removeFrameButton = card.querySelector(".remove-btn");
          if (isCommandGetStatusCommandLocked()) {
            removeFrameButton?.remove();
          } else {
            removeFrameButton?.addEventListener("click", deleteHandler);
          }
          card.querySelectorAll(".frame-settings, .frame-settings select, .frame-multiple-ui-button")
            .forEach((element) => {
              element.addEventListener("click", (event) => {
                event.stopPropagation();
              });
            });
          card
            .querySelector(".frame-direction-select")
            .addEventListener("change", function (event) {
              event.stopPropagation();
              frameConfigurations[i].dataFlowDirection = this.value;
              const direction = card.querySelector(".frame-direction");
              const isServerToDevice = this.value === "server_to_device";
              direction.innerHTML = `<i class="fas ${isServerToDevice ? "fa-arrow-right" : "fa-arrow-left"}"></i> ${isServerToDevice ? "Server to Device" : "Device to Server"}`;
              this.classList.remove("frame-field-error");
              this.setAttribute("aria-invalid", "false");
              markConfigurationUnsaved();
            });
          card
            .querySelector(".frame-multiple-ui-button")
            .addEventListener("click", function (event) {
              event.preventDefault();
              event.stopPropagation();
              if (commandFrameFullyLocked) return;
              openMultipleUiPopup(i, this);
            });
          container.appendChild(card);
        }

        if (count < 20 && !isCommandGetStatusCommandLocked()) {
          const addCard = document.createElement("button");
          addCard.type = "button";
          addCard.className = "add-frame-card";
          addCard.id = "addCommandFrameCard";
          addCard.setAttribute(
            "aria-label",
            `Add a new ${getActiveFrameLabel().toLowerCase()} frame`,
          );
          addCard.innerHTML = `
              <span class="add-frame-card-inner">
                <i class="fas fa-plus"></i>
                <span>Add ${getActiveFrameLabel()} Frame</span>
              </span>
            `;
          addCard.addEventListener("click", addCommandFrame);
          container.appendChild(addCard);
        }

        updateCommandFrameCount();
        updateFramePartitionStates();
        updateFieldDescFrameSelect();
        renderFieldDescription();
        const banner = document.getElementById("framesNextBanner");
        if (banner) {
          banner.classList.toggle("show", awaitingFrameClick && count > 0);
        }
      }

      /*
       * Command / Response / Error byte editor
       * --------------------------------------
       * No hardcoded protocol bytes are inserted. Every frame begins with a
       * single editable byte whose default value is 00. Each byte is rendered as:
       *
       *        [ - ]  [ BYTE ]  [ + ]
       *
       * Minus removes that byte. Plus inserts a new byte with value 00 immediately
       * after it. Manually emptied/incomplete draft bytes deliberately clear the hidden
       * full API value so the existing save validation cannot accidentally
       * save an older complete value while the visible editor is incomplete.
       */
      function getHexEditorBytes() {
        if (Array.isArray(hexEditorDraftBytes) && hexEditorDraftBytes.length) {
          return [...hexEditorDraftBytes];
        }

        const savedBytes = normalizeHex(String(fullApiValue || ""))
          .match(/[0-9A-F]{2}/g) || [];
        return savedBytes.length ? savedBytes : ["00"];
      }

      function setIncompleteHexDraft(values) {
        hexEditorDraftBytes = values.length ? [...values] : [""];
        hexEditorDraftIsIncomplete = true;
        fullApiValue = "";
        const hiddenInput = document.getElementById("fullApiInput");
        if (hiddenInput) hiddenInput.value = "";

        // Keep the visible byte positions alive in the partition workspace.
        // The empty/partial byte is rendered as -- (or A- while typing), but
        // fullApiValue stays empty so the frame cannot be saved prematurely.
        restoredByteCount = hexEditorDraftBytes.length;
        partitionsConfirmed = false;
        setPartitionChanged();
      }

      function syncHexEditorToApiValue() {
        const byteInputs = document.querySelectorAll("#hexByteEditor .hex-byte");
        const values = Array.from(byteInputs).map(function (input) {
          return normalizeHex(input.value)
            .replace(/[^0-9A-F]/g, "")
            .slice(0, 2);
        });

        hexEditorDraftBytes = values.length ? values : [""];

        const allComplete =
          values.length > 0 &&
          values.every(function (value) {
            return /^[0-9A-F]{2}$/.test(value);
          });

        if (!allComplete) {
          setIncompleteHexDraft(values);
          // Update counts, timeline and validation without rebuilding the
          // focused byte inputs while the user is still typing.
          renderApiPartitionEditor(true);
          return false;
        }

        fullApiValue = values.join("");
        hexEditorDraftIsIncomplete = false;
        const hiddenInput = document.getElementById("fullApiInput");
        if (hiddenInput) hiddenInput.value = fullApiValue;

        restoredByteCount = values.length;
        setPartitionChanged();
        renderApiPartitionEditor();
        return true;
      }

      function renderHexByteEditor() {
        const editor = document.getElementById("hexByteEditor");
        if (!editor) return;

        if (isCommandGetStatusCommandLocked()) {
          enforceCommandGetStatusCommandState(true);
          editor.replaceChildren();
          COMMAND_GET_STATUS_FIXED_BYTES.forEach(function (value, index) {
            const unit = document.createElement("span");
            unit.className = "hex-byte-unit command-get-status-locked-byte";

            const input = document.createElement("input");
            input.type = "text";
            input.className = "hex-byte hex-byte-fixed";
            input.value = value;
            input.readOnly = true;
            input.tabIndex = -1;
            input.setAttribute("aria-readonly", "true");
            input.setAttribute("aria-label", "Locked byte " + (index + 1));
            input.title = "Fixed Command Get Status byte";

            ["beforeinput", "input", "paste", "cut", "drop", "keydown"].forEach(
              function (eventName) {
                input.addEventListener(eventName, function (event) {
                  event.preventDefault();
                  input.value = value;
                  enforceCommandGetStatusCommandState(true);
                });
              },
            );

            unit.appendChild(input);
            editor.appendChild(unit);
          });
          return;
        }

        if (isCommandGetStatusResponseFrame()) {
          editor.replaceChildren();
          const byteValues = getCommandGetStatusResponseDraftBytes();
          hexEditorDraftBytes = [...byteValues];

          byteValues.forEach(function (value, index) {
            const lastIndex = byteValues.length - 1;
            const fixedByte = index === 0 || index === 1 || index === lastIndex;
            const unit = document.createElement("span");
            unit.className = "hex-byte-unit" + (fixedByte ? " command-get-status-locked-byte" : "");

            const input = document.createElement("input");
            input.type = "text";
            input.className = "hex-byte" + (fixedByte ? " hex-byte-fixed" : "");
            input.maxLength = 2;
            input.inputMode = "text";
            input.autocomplete = "off";
            input.spellcheck = false;
            input.value = value;
            input.placeholder = "--";
            input.setAttribute("aria-label", fixedByte ? `Locked response byte ${index + 1}` : `Response payload byte ${index + 1}`);

            if (fixedByte) {
              input.readOnly = true;
              input.tabIndex = -1;
              input.setAttribute("aria-readonly", "true");
              input.title = index === 0
                ? "Fixed DE protocol byte"
                : index === 1
                  ? "Fixed E7 protocol byte"
                  : "Fixed 0A terminator byte";
              ["beforeinput", "input", "paste", "cut", "drop", "keydown"].forEach((eventName) => {
                input.addEventListener(eventName, function (event) {
                  event.preventDefault();
                  const current = getCommandGetStatusResponseDraftBytes();
                  current[0] = "DE";
                  current[1] = "E7";
                  current[current.length - 1] = "0A";
                  input.value = current[index];
                });
              });
            } else {
              input.addEventListener("input", function () {
                this.value = normalizeHex(this.value)
                  .replace(/[^0-9A-F]/g, "")
                  .slice(0, 2);
                const inputs = Array.from(document.querySelectorAll("#hexByteEditor .hex-byte"));
                const values = inputs.map((element) => normalizeHex(element.value).replace(/[^0-9A-F]/g, "").slice(0, 2));
                values[0] = "DE";
                values[1] = "E7";
                values[values.length - 1] = "0A";
                const synced = syncCommandGetStatusResponseValue(values, true);
                renderApiPartitionEditor(true);
                if (synced && this.value.length === 2) {
                  const currentIndex = inputs.indexOf(this);
                  const next = inputs[currentIndex + 1];
                  if (next && !next.readOnly) {
                    next.focus();
                    next.select();
                  }
                }
              });
            }

            // Payload bytes only may be removed. DE, E7 and final 0A never get a minus button.
            if (!fixedByte) {
              const minus = document.createElement("button");
              minus.type = "button";
              minus.className = "hex-byte-minus";
              minus.innerHTML = '<i class="fas fa-minus"></i>';
              minus.title = "Remove this payload byte";
              minus.setAttribute("aria-label", "Remove response payload byte " + (index + 1));
              minus.addEventListener("click", function (event) {
                event.preventDefault();
                event.stopPropagation();
                const current = getCommandGetStatusResponseDraftBytes();
                if (index < 2 || index >= current.length - 1) return;

                // Remove the deleted byte's Field Configuration and shift only
                // configurations that belong to bytes located after it.
                remapCommandGetStatusResponseStateForRemovedByte(index);

                current.splice(index, 1);
                syncCommandGetStatusResponseValue(current, true);
                enforceCommandGetStatusPartitionRules();
                renderApiPartitionEditor();
              });
              unit.appendChild(minus);
            }

            unit.appendChild(input);

            // Add is allowed ONLY after E7 or an existing payload byte, i.e. before final 0A.
            // Therefore there is no + between DE and E7 and no + after 0A.
            const allowPlus = index >= 1 && index < lastIndex;
            if (allowPlus) {
              const plus = document.createElement("button");
              plus.type = "button";
              plus.className = "hex-byte-plus";
              plus.innerHTML = '<i class="fas fa-plus"></i>';
              plus.title = "Add payload byte before final 0A";
              plus.setAttribute("aria-label", "Add response payload byte after byte " + (index + 1));
              plus.addEventListener("click", function (event) {
                event.preventDefault();
                event.stopPropagation();
                const current = getCommandGetStatusResponseDraftBytes();
                const insertAt = index + 1;

                /*
                 * IMPORTANT: move existing partition/configuration state BEFORE
                 * inserting the byte. This keeps the old 0A configuration on
                 * the shifted 0A byte while the NEW payload byte starts at 00.
                 */
                remapCommandGetStatusResponseStateForInsertedByte(insertAt);

                current.splice(insertAt, 0, "00");
                // Shift user-created payload cuts; fixed wrapper cuts are rebuilt below.
                partitionCuts = partitionCuts.map((cut) => cut >= insertAt ? cut + 1 : cut);
                syncCommandGetStatusResponseValue(current, true);
                enforceCommandGetStatusPartitionRules();

                // Re-assert that the fresh payload byte has no inherited popup
                // values after the fixed wrapper partitions are rebuilt.
                const newByteKey = `${insertAt}-${insertAt + 1}`;
                delete partitionFieldConfigurations[newByteKey];
                delete selectedBitGroups[newByteKey];
                if (!getCommandGetStatusFixedPartitionName({ start: insertAt, end: insertAt + 1 })) {
                  delete partitionLabels[newByteKey];
                  delete partitionViewModes[newByteKey];
                }

                renderApiPartitionEditor();
                requestAnimationFrame(function () {
                  const inputs = document.querySelectorAll("#hexByteEditor .hex-byte");
                  if (inputs[insertAt] && !inputs[insertAt].readOnly) {
                    inputs[insertAt].focus();
                    inputs[insertAt].select();
                  }
                });
              });
              unit.appendChild(plus);
            }

            editor.appendChild(unit);
          });
          return;
        }

        editor.replaceChildren();
        const byteValues = getHexEditorBytes();
        hexEditorDraftBytes = byteValues.length ? [...byteValues] : [""];

        byteValues.forEach(function (value, index) {
          const unit = document.createElement("span");
          unit.className = "hex-byte-unit";

          const minus = document.createElement("button");
          minus.type = "button";
          minus.className = "hex-byte-minus";
          minus.innerHTML = '<i class="fas fa-minus"></i>';
          minus.title = "Remove this byte";
          minus.setAttribute("aria-label", "Remove byte " + (index + 1));
          minus.disabled = byteValues.length === 1 && value === "";

          minus.addEventListener("click", function (event) {
            event.preventDefault();
            event.stopPropagation();

            const currentBytes = getHexEditorBytes();
            if (index < 0 || index >= currentBytes.length) return;

            currentBytes.splice(index, 1);
            if (!currentBytes.length) currentBytes.push("00");

            const newByteCount = currentBytes.length;
            partitionCuts = Array.from(
              new Set(
                partitionCuts
                  .map(function (cut) {
                    return cut > index ? cut - 1 : cut;
                  })
                  .filter(function (cut) {
                    return cut > 0 && cut < newByteCount;
                  }),
              ),
            ).sort(function (a, b) {
              return a - b;
            });

            const allComplete = currentBytes.every(function (item) {
              return /^[0-9A-F]{2}$/.test(item);
            });

            hexEditorDraftBytes = currentBytes;
            if (allComplete) {
              fullApiValue = currentBytes.join("");
              hexEditorDraftIsIncomplete = false;
              const hiddenInput = document.getElementById("fullApiInput");
              if (hiddenInput) hiddenInput.value = fullApiValue;
              restoredByteCount = currentBytes.length;
              partitionsConfirmed = false;
              setPartitionChanged();
            } else {
              setIncompleteHexDraft(currentBytes);
            }

            renderApiPartitionEditor();

            requestAnimationFrame(function () {
              const inputs = document.querySelectorAll("#hexByteEditor .hex-byte");
              const focusIndex = Math.min(index, inputs.length - 1);
              if (focusIndex >= 0 && inputs[focusIndex]) {
                inputs[focusIndex].focus();
                inputs[focusIndex].select();
              }
            });
          });

          const input = document.createElement("input");
          input.type = "text";
          input.className = "hex-byte";
          input.maxLength = 2;
          input.inputMode = "text";
          input.autocomplete = "off";
          input.spellcheck = false;
          input.value = value;
          input.placeholder = "--";
          input.setAttribute("aria-label", "Byte " + (index + 1));

          input.addEventListener("input", function () {
            this.value = normalizeHex(this.value)
              .replace(/[^0-9A-F]/g, "")
              .slice(0, 2);

            const editorInputs = Array.from(
              document.querySelectorAll("#hexByteEditor .hex-byte"),
            );
            const currentIndex = editorInputs.indexOf(this);
            const synced = syncHexEditorToApiValue();

            if (synced) {
              requestAnimationFrame(function () {
                const refreshedInputs = Array.from(
                  document.querySelectorAll("#hexByteEditor .hex-byte"),
                );
                const nextInput = refreshedInputs[currentIndex + 1];
                if (nextInput) {
                  nextInput.focus();
                  nextInput.select();
                }
              });
            }
          });

          const plus = document.createElement("button");
          plus.type = "button";
          plus.className = "hex-byte-plus";
          plus.innerHTML = '<i class="fas fa-plus"></i>';
          plus.title = "Add a new byte after this byte";
          plus.setAttribute("aria-label", "Add byte after byte " + (index + 1));

          plus.addEventListener("click", function (event) {
            event.preventDefault();
            event.stopPropagation();

            const currentBytes = getHexEditorBytes();
            const insertAt = index + 1;
            currentBytes.splice(insertAt, 0, "00");

            partitionCuts = partitionCuts.map(function (cut) {
              return cut >= insertAt ? cut + 1 : cut;
            });

            // A newly added byte starts as 00, so the Command Value remains
            // complete/valid immediately after the + button is clicked.
            hexEditorDraftBytes = [...currentBytes];
            hexEditorDraftIsIncomplete = false;
            fullApiValue = currentBytes.join("");
            const hiddenInput = document.getElementById("fullApiInput");
            if (hiddenInput) hiddenInput.value = fullApiValue;
            restoredByteCount = currentBytes.length;
            partitionsConfirmed = false;
            setPartitionChanged();
            renderApiPartitionEditor();

            requestAnimationFrame(function () {
              const inputs = document.querySelectorAll("#hexByteEditor .hex-byte");
              if (inputs[insertAt]) {
                inputs[insertAt].focus();
                inputs[insertAt].select();
              }
            });
          });

          unit.append(minus, input, plus);
          editor.appendChild(unit);
        });
      }

      function normalizeHex(value) {
        return value.replace(/\s+/g, "").replace(/^0x/i, "").toUpperCase();
      }

      function isValidHexCommand(value) {
        return (
          value.length > 0 &&
          value.length % 2 === 0 &&
          /^[0-9A-F]+$/.test(value)
        );
      }

      function hexToBinary(value) {
        return value
          .split("")
          .map((hexDigit) =>
            parseInt(hexDigit, 16).toString(2).padStart(4, "0"),
          )
          .join("");
      }

      function renderCommandCodeBoxes(command, frameIdx) {
        const grid = document.getElementById("byteDetailGrid");
        grid.innerHTML = "";
        if (!command) {
          grid.innerHTML =
            '<div class="empty-command">Enter command values above. Each value field will be shown as one box.</div>';
          return;
        }
        const savedGroups = frameValueGroups[frameIdx] || [];
        const displayGroups = savedGroups.length ? savedGroups : [command];
        const line = document.createElement("div");
        line.className = "command-code-line";
        const label = document.createElement("span");
        label.className = "command-code-label";
        label.textContent = "Command Code:";
        const row = document.createElement("div");
        row.className = "command-character-row";
        displayGroups.forEach((groupValue, groupIndex) => {
          const box = document.createElement("span");
          box.className = "command-character clickable";
          applyPartitionColor(box, groupIndex);
          const byteVal = groupValue;
          box.textContent = byteVal;
          box.dataset.byteValue = byteVal;
          box.dataset.byteIndex = groupIndex;
          box.dataset.frameIdx = frameIdx;
          box.addEventListener("click", function (e) {
            e.stopPropagation();
            const clickedFrame = parseInt(this.dataset.frameIdx);
            const byteIndex = parseInt(this.dataset.byteIndex);
            const fieldSelect = document.getElementById(
              "fieldDescFrameSelect",
            );
            if (!fieldSelect) return;
            fieldSelect.value = String(clickedFrame);
            renderFieldDescription();
            const target = document.querySelector(
              `.field-desc-card[data-byte-index="${byteIndex}"]`,
            );
            if (target) {
              target.scrollIntoView({ behavior: "smooth", block: "center" });
              target.style.boxShadow = "0 0 0 3px rgba(169,139,118,.30)";
              setTimeout(() => {
                target.style.boxShadow = "";
              }, 900);
            }
          });
          row.appendChild(box);
        });
        line.appendChild(label);
        line.appendChild(row);
        grid.appendChild(line);
      }

      // ---- Byte Field Modal ----
      let currentModalFrameIdx = null;
      let currentModalByteKey = null;
      let currentModalBitPosition = null;
      let currentModalBitPositions = null;
      let currentModalByteIndex = null;
      let currentModalPartitionKey = null;

      /*
       * Always open Field Configuration from its first field. The modal is a
       * scroll container, so without this reset it keeps the old position when
       * the user closes it, goes back, and configures a partition again.
       */
      function resetByteFieldModalPosition() {
        const overlay = document.getElementById("byteFieldModal");
        const modal = overlay?.querySelector(".byte-modal");
        if (overlay) overlay.scrollTop = 0;
        if (modal) modal.scrollTop = 0;

        requestAnimationFrame(function () {
          if (overlay) overlay.scrollTop = 0;
          if (modal) modal.scrollTop = 0;
        });
      }

      /* Always show UI Type options from None and Text when reopened. */
      function resetUiTypePickerPosition() {
        const picker = document.getElementById("uiTypePicker");
        if (picker) picker.scrollTop = 0;

        requestAnimationFrame(function () {
          if (picker) picker.scrollTop = 0;
        });
      }

      function getFieldConfigurationMultipleUiValue() {
        /*
         * Byte-wise configuration has an explicit frame index.
         * Partition configuration uses the currently selected frame.
         */
        const frameIndex =
          currentModalFrameIdx !== null &&
          currentModalFrameIdx !== undefined
            ? currentModalFrameIdx
            : selectedFrameIndex;

        if (
          frameIndex === null ||
          frameIndex === undefined ||
          frameIndex < 0
        ) {
          return "";
        }

        return String(
          frameConfigurations?.[frameIndex]?.multipleUi || "",
        ).toLowerCase();
      }

      function syncFieldNameByMultipleUi(existingConfiguration = {}) {
        const nameInput = document.getElementById("fName");
        const nameHint = document.getElementById("fieldNameHint");

        if (!nameInput) return;

        const multipleUiValue = getFieldConfigurationMultipleUiValue();
        const parameterName =
          document.getElementById("paramNameInput")?.value?.trim() || "";

        const savedName = String(
          existingConfiguration.name ??
          existingConfiguration.fieldName ??
          existingConfiguration.field_name ??
          "",
        ).trim();

        /*
         * false = Single UI
         * Name automatically follows Parameter Name.
         */
        if (multipleUiValue === "false") {
          nameInput.value = parameterName;
          nameInput.readOnly = true;
          nameInput.classList.add("field-name-auto");
          nameInput.placeholder = "Parameter Name";

          if (nameHint) {
            nameHint.innerHTML =
              '<i class="fas fa-link"></i> Single UI: Name is automatically taken from Parameter Name.';
          }
          return;
        }

        /*
         * true = Multiple UI
         * Every field/UI can have its own name, so the user must enter it.
         */
        if (multipleUiValue === "true") {
          nameInput.readOnly = false;
          nameInput.classList.remove("field-name-auto");
          nameInput.value = savedName;
          nameInput.placeholder = "Enter Name";

          if (nameHint) {
            nameHint.innerHTML =
              '<i class="fas fa-pen"></i> Multiple UI: Enter a Name for this field.';
          }
          return;
        }

        nameInput.readOnly = false;
        nameInput.classList.remove("field-name-auto");
        nameInput.value = savedName;
        nameInput.placeholder = "Enter Name";

        if (nameHint) {
          nameHint.innerHTML =
            '<i class="fas fa-circle-info"></i> Select Single or Multiple UI for the frame.';
        }
      }

      function openByteFieldModal(frameIdx, byteVal, byteIndex, bitPos) {
        if (isCommandGetStatusCommandLocked()) return;
        if (isCommandGetStatusLockedResponseByteIndex(byteIndex)) return;
        currentModalPartitionKey = null;
        currentModalFrameIdx = frameIdx;
        currentModalByteIndex = byteIndex;
        currentModalBitPosition = bitPos !== undefined ? bitPos : null;
        currentModalBitPositions = null;
        currentModalByteKey =
          currentModalBitPosition === null
            ? `byte:${byteIndex}`
            : `bit:${byteIndex}:${currentModalBitPosition}`;

        let displayLabel = `Value ${byteIndex + 1} ${byteVal}`;
        if (bitPos !== undefined) {
          const binaryValue = hexToBinary(byteVal);
          const bitValue =
            binaryValue[binaryValue.length - 1 - bitPos] || "0";
          displayLabel = `Value ${byteIndex + 1} ${byteVal} Bit ${bitPos} = ${bitValue}`;
        }
        document.getElementById("modalByteCode").textContent = displayLabel;

        const existing =
          fieldDescriptions[frameIdx]?.[currentModalByteKey] || {};
        syncFieldNameByMultipleUi(existing);
        document.getElementById("fDataType").value =
          existing.dataType || "";
        document.getElementById("fValueDef").value =
          existing.valueDef || "";
        document.getElementById("fDefaultValue").value =
          existing.defaultvalue ?? existing.defaultValue ?? existing.default_value ?? "";
        document.getElementById("fUiType").value = existing.uiType || "none";
        document.getElementById("fUiInOut").value =
          String(existing.uiType || "none").trim().toLowerCase() === "none"
            ? "none"
            : (existing.uiInOut || "");
        document.getElementById("fScalling").value = existing.scalling || "";
        document.getElementById("fDisplayMin").value =
          existing.displayValueMin ?? "";
        document.getElementById("fDisplayMax").value =
          existing.displayValueMax ?? "";
        document.getElementById("fNotes").value =
          existing.developerNotes ?? existing.notes ?? "";

        const notificationSelect =
          document.getElementById("fNotificationEnable");
        if (notificationSelect) {
          const savedNotification =
            String(existing.notificationEnable || "").trim();

          if (savedNotification === "Yes" || savedNotification === "No") {
            notificationSelect.value = savedNotification;
          } else {
            notificationSelect.value = "";
          }
        }
        document.getElementById("fAsperUi").value = existing.asperui ?? existing.asperUi ?? "";
        document.getElementById("fUiSerialNo").value = existing.sno_asperui ?? existing.uiSerialNo ?? "";
        const byteUiValuesInput = document.getElementById("fUiValues");
        if (byteUiValuesInput) {
          delete byteUiValuesInput.dataset.messageInitialRestoreDone;
          byteUiValuesInput.value = existing.asperuivalue ?? existing.uiValues ?? "";
        }
        applyUiTypeAutoValues(existing.uiType || "none", false);
        document.getElementById("fMessage").value = existing.message || "";
        document.getElementById("fSliderStep").value = existing.sliderStep ?? "";
        updateUiTypeDependentFields(existing.uiType || "none");

        clearFieldFormWarnings();
        renderUiTypePicker(existing.uiType || "none");
        syncFieldReferenceControls();
        document.getElementById("byteFieldModal").style.display = "flex";
        resetByteFieldModalPosition();
        resetUiTypePickerPosition();
      }

      function openPartitionFieldModal(
        partitionKeyValue,
        partitionCode,
        partitionIndex,
        bitPos,
        bitGroup,
      ) {
        if (isCommandGetStatusCommandLocked()) return;
        if (isCommandGetStatusLockedResponsePartitionKey(partitionKeyValue)) return;
        currentModalPartitionKey = partitionKeyValue;
        currentModalFrameIdx = null;
        currentModalByteIndex = partitionIndex;
        currentModalBitPositions = Array.isArray(bitGroup)
          ? [...bitGroup].sort((a, b) => a - b)
          : null;
        currentModalBitPosition =
          currentModalBitPositions?.length === 1
            ? currentModalBitPositions[0]
            : bitPos !== undefined
              ? bitPos
              : null;
        currentModalByteKey = currentModalBitPositions
          ? bitGroupConfigKey(currentModalBitPositions)
          : currentModalBitPosition === null
            ? "byte"
            : `bit:${currentModalBitPosition}`;

        let displayLabel = `Partition ${partitionIndex + 1} ${partitionCode}`;
        if (currentModalBitPositions) {
          displayLabel = `Partition ${partitionIndex + 1} ${partitionCode} ${bitGroupLabel(currentModalBitPositions)}`;
        } else if (bitPos !== undefined) {
          const binaryValue = hexToBinary(partitionCode);
          const bitValue =
            binaryValue[binaryValue.length - 1 - bitPos] || "0";
          displayLabel = `Partition ${partitionIndex + 1} ${partitionCode} Bit ${bitPos} = ${bitValue}`;
        }
        document.getElementById("modalByteCode").textContent = displayLabel;

        const existing =
          partitionFieldConfigurations[partitionKeyValue]?.[
          currentModalByteKey
          ] || {};
        syncFieldNameByMultipleUi(existing);
        document.getElementById("fDataType").value =
          existing.dataType || "";
        document.getElementById("fValueDef").value =
          existing.valueDef || "";
        document.getElementById("fDefaultValue").value =
          existing.defaultvalue ?? existing.defaultValue ?? existing.default_value ?? "";
        document.getElementById("fUiType").value = existing.uiType || "none";
        document.getElementById("fUiInOut").value =
          String(existing.uiType || "none").trim().toLowerCase() === "none"
            ? "none"
            : (existing.uiInOut || "");
        document.getElementById("fScalling").value = existing.scalling || "";
        document.getElementById("fDisplayMin").value =
          existing.displayValueMin ?? "";
        document.getElementById("fDisplayMax").value =
          existing.displayValueMax ?? "";
        document.getElementById("fNotes").value =
          existing.developerNotes ?? existing.notes ?? "";

        const notificationSelect =
          document.getElementById("fNotificationEnable");
        if (notificationSelect) {
          const savedNotification =
            String(existing.notificationEnable || "").trim();

          if (savedNotification === "Yes" || savedNotification === "No") {
            notificationSelect.value = savedNotification;
          } else {
            notificationSelect.value = "";
          }
        }
        document.getElementById("fAsperUi").value = existing.asperui ?? existing.asperUi ?? "";
        document.getElementById("fUiSerialNo").value = existing.sno_asperui ?? existing.uiSerialNo ?? "";
        const partitionUiValuesInput = document.getElementById("fUiValues");
        if (partitionUiValuesInput) {
          delete partitionUiValuesInput.dataset.messageInitialRestoreDone;
          partitionUiValuesInput.value = existing.asperuivalue ?? existing.uiValues ?? "";
        }
        applyUiTypeAutoValues(existing.uiType || "none", false);
        document.getElementById("fMessage").value = existing.message || "";
        document.getElementById("fSliderStep").value = existing.sliderStep ?? "";
        updateUiTypeDependentFields(existing.uiType || "none");
        clearFieldFormWarnings();
        renderUiTypePicker(existing.uiType || "none");
        syncFieldReferenceControls();
        document.getElementById("byteFieldModal").style.display = "flex";
        resetByteFieldModalPosition();
        resetUiTypePickerPosition();
      }

      function closeByteFieldModal() {
        closeUiConfigurationPopup();
        resetByteFieldModalPosition();
        resetUiTypePickerPosition();
        document.getElementById("byteFieldModal").style.display = "none";
        currentModalFrameIdx = null;
        currentModalByteKey = null;
        currentModalBitPosition = null;
        currentModalBitPositions = null;
        currentModalByteIndex = null;
        currentModalPartitionKey = null;
      }

      document
        .getElementById("closeFieldModal")
        .addEventListener("click", closeByteFieldModal);
      document
        .getElementById("cancelFieldModal")
        .addEventListener("click", closeByteFieldModal);
      document
        .getElementById("byteFieldModal")
        .addEventListener("click", function (e) {
          if (e.target === this) closeByteFieldModal();
        });

      function clearFieldFormWarnings() {
        const warning = document.getElementById("fieldFormWarning");
        if (warning) warning.classList.remove("show");
        document
          .querySelectorAll("#modalFieldForm .form-group.field-invalid, #uiConfigurationModal .form-group.field-invalid")
          .forEach((group) => {
            group.classList.remove("field-invalid");
          });
        document
          .querySelectorAll('#modalFieldForm [aria-invalid="true"], #uiConfigurationModal [aria-invalid="true"]')
          .forEach((control) => {
            control.setAttribute("aria-invalid", "false");
          });
        clearUiConfigurationWarning();
      }

      function validateFieldForm() {
        clearFieldFormWarnings();
        const nameInput = document.getElementById("fName");
        const requiredSelects = [
          document.getElementById("fDataType"),
          document.getElementById("fValueDef"),
          document.getElementById("fUiType"),
          document.getElementById("fNotificationEnable"),
          document.getElementById("fUiInOut"),
        ];
        const invalidControls = [];

        if (!nameInput?.value.trim()) {
          invalidControls.push(nameInput);
        }

        requiredSelects.forEach((control) => {
          if (!control.value) invalidControls.push(control);
        });

        const selectedUiType = document.getElementById("fUiType")?.value || "";
        const displayMinInput = document.getElementById("fDisplayMin");
        const displayMaxInput = document.getElementById("fDisplayMax");
        const asperUiInput = document.getElementById("fAsperUi");
        const uiValuesInput = document.getElementById("fUiValues");
        const sliderStepInput = document.getElementById("fSliderStep");
        let stateUiValuesInvalid = false;

        /* Toggle Switch / Button: Preset Names + exactly two Functioning Names are required.
           Push Button requires Preset Names only. */
        if (usesPresetNamesUiType(selectedUiType)) {
          if (!asperUiInput?.value.trim()) invalidControls.push(asperUiInput);
        }

        if (isToggleUiType(selectedUiType) || isStandardButtonUiType(selectedUiType)) {
          const stateValue = String(uiValuesInput?.value || "").trim();
          stateUiValuesInvalid = !/^\d+,\d+$/.test(stateValue);
          if (stateUiValuesInvalid && uiValuesInput && !invalidControls.includes(uiValuesInput)) {
            invalidControls.push(uiValuesInput);
          }
        }

        /* Dropdown popup: No. of Contents defines the count; every generated
           Content No. (1..N) must have one Content in List of Contents. */
        if (isDropdownUiType(selectedUiType)) {
          const dropdownCount = getDropdownUiCount(asperUiInput?.value || "");
          const dropdownMappings = getDropdownUiMappings();
          const dropdownUiValueEditor = document.getElementById("dropdownUiValueEditor");
          if (dropdownCount < 1) invalidControls.push(asperUiInput);
          if (
            dropdownCount < 1 ||
            dropdownMappings.length !== dropdownCount ||
            dropdownMappings.some((item) => !String(item.label || "").trim())
          ) {
            const visibleDropdownControl = dropdownUiValueEditor || uiValuesInput;
            if (visibleDropdownControl && !invalidControls.includes(visibleDropdownControl)) {
              invalidControls.push(visibleDropdownControl);
            }
          }
        }

        /*
         * Display range is required for sliders and now also for Text /
         * Enter Text.  The existing save object below writes these values as
         * displayValueMin / displayValueMax, which the backend stores in
         * api_frame_fields.display_value_min / display_value_max.
         */
        const normalizedSelectedUiType = String(selectedUiType || "").trim().toLowerCase();
        const requiresDisplayRange =
          isSliderUiType(selectedUiType) ||
          normalizedSelectedUiType === "text" ||
          normalizedSelectedUiType === "enter text";

        if (requiresDisplayRange) {
          const minValue = String(displayMinInput?.value ?? "").trim();
          const maxValue = String(displayMaxInput?.value ?? "").trim();

          if (!minValue) invalidControls.push(displayMinInput);
          if (!maxValue) invalidControls.push(displayMaxInput);

          if (
            minValue &&
            maxValue &&
            Number.isFinite(Number(minValue)) &&
            Number.isFinite(Number(maxValue)) &&
            Number(minValue) > Number(maxValue)
          ) {
            if (displayMinInput && !invalidControls.includes(displayMinInput)) {
              invalidControls.push(displayMinInput);
            }
            if (displayMaxInput && !invalidControls.includes(displayMaxInput)) {
              invalidControls.push(displayMaxInput);
            }
          }
        }

        /* Slider popup additionally requires step; Scaling remains optional. */
        if (isSliderUiType(selectedUiType)) {
          if (
            !sliderStepInput?.value.trim() ||
            Number(sliderStepInput.value) <= 0
          ) {
            invalidControls.push(sliderStepInput);
          }
        }

        const messageInput = document.getElementById("fMessage");
        const normalizedMessageUiType = String(selectedUiType || "").trim().toLowerCase();

        /*
         * Text / Enter Text no longer expose Mix, Mix Values, or Message as
         * required Field Configuration controls. Their existing preview is
         * preserved, and Display Min / Display Max are the only additional
         * required values for these two UI types.
         */
        if (
          normalizedMessageUiType !== "text" &&
          normalizedMessageUiType !== "enter text" &&
          isMessagePreviewUiType(selectedUiType)
        ) {
          const messageUiValue = String(uiValuesInput?.value || "").trim();
          if (!messageUiValue) {
            if (uiValuesInput && !invalidControls.includes(uiValuesInput)) {
              invalidControls.push(uiValuesInput);
            }
          } else if (messageInput) {
            messageInput.value = messageUiValue;
          }
        }

        if (isDisplayToastUiType(selectedUiType)) {
          const displayMessageValue = String(uiValuesInput?.value || "").trim();
          if (!displayMessageValue && uiValuesInput && !invalidControls.includes(uiValuesInput)) {
            invalidControls.push(uiValuesInput);
          }
        }

        if (!invalidControls.length) return true;

        invalidControls.forEach((control) => {
          control.setAttribute("aria-invalid", "true");
          control.closest(".form-group")?.classList.add("field-invalid");
        });
        const warning = document.getElementById("fieldFormWarning");
        if (warning) {
          warning.classList.add("show");

          const missingLabels = invalidControls
            .filter(Boolean)
            .map((control) => {
              const group = control.closest(".form-group");
              const label = group?.querySelector("label");
              return label
                ? label.textContent.trim().replace(/\s+/g, " ")
                : control.id;
            });

          const toggleMessage = stateUiValuesInvalid
            ? " Toggle Switch / Button Functioning Names must contain exactly two comma-separated numeric values (example: 01,02)."
            : "";

          warning.innerHTML = `
            <i class="fas fa-triangle-exclamation"></i>
            <span>
              Please correct the Field Configuration values:
              ${missingLabels.join(", ")}.${toggleMessage}
            </span>
          `;
        }

        const firstInvalid = invalidControls.filter(Boolean)[0];
        if (firstInvalid?.closest("#uiConfigurationModal")) {
          openUiConfigurationPopup(selectedUiType);
        }
        firstInvalid?.focus();
        return false;
      }

      document
        .querySelectorAll("#modalFieldForm input, #modalFieldForm select, #uiConfigurationModal input, #uiConfigurationModal select")
        .forEach((control) => {
          control.addEventListener("input", function () {
            this.closest(".form-group")?.classList.remove("field-invalid");
            this.setAttribute("aria-invalid", "false");
          });
          control.addEventListener("change", function () {
            this.closest(".form-group")?.classList.remove("field-invalid");
            this.setAttribute("aria-invalid", "false");
          });
        });

      // Keep these requested fields numeric-only and manual-entry only.
      // Spinner buttons are hidden by CSS, and mouse-wheel changes are blocked.
      ["fDefaultValue", "fDisplayMin", "fDisplayMax"].forEach((id) => {
        const input = document.getElementById(id);
        if (!input) return;
        input.addEventListener("keydown", function (event) {
          if (["e", "E", "+"].includes(event.key)) {
            event.preventDefault();
          }
        });
        input.addEventListener(
          "wheel",
          function (event) {
            if (document.activeElement === this) {
              event.preventDefault();
            }
          },
          { passive: false },
        );
      });

      const dropdownAsperUiInput = document.getElementById("fAsperUi");
      if (dropdownAsperUiInput) {
        dropdownAsperUiInput.addEventListener("input", function () {
          const selectedUiType = String(document.getElementById("fUiType")?.value || "")
            .trim()
            .toLowerCase();
          const isDropdown = isDropdownUiType(selectedUiType);
          const isText = selectedUiType === "text";
          if (!isDropdown && !isText) return;

          // Dropdown and Text both use fAsperUi as a single numeric count.
          const numericOnly = String(this.value || "").replace(/\D/g, "");
          if (this.value !== numericOnly) this.value = numericOnly;

          if (isDropdown) {
            configureDropdownUiControls(selectedUiType);
          } else {
            configureTextMessageControls(selectedUiType);
          }
        });

        dropdownAsperUiInput.addEventListener("keydown", function (event) {
          const selectedUiType = String(document.getElementById("fUiType")?.value || "")
            .trim()
            .toLowerCase();
          if (!isDropdownUiType(selectedUiType) && selectedUiType !== "text") return;

          const allowed = new Set([
            "Backspace", "Delete", "ArrowLeft", "ArrowRight",
            "Home", "End", "Tab",
          ]);
          if (event.ctrlKey || event.metaKey || allowed.has(event.key) || /^\d$/.test(event.key)) return;
          event.preventDefault();
        });

        dropdownAsperUiInput.addEventListener("blur", function () {
          const selectedUiType = String(document.getElementById("fUiType")?.value || "")
            .trim()
            .toLowerCase();

          if (isDropdownUiType(selectedUiType)) {
            const normalized = normalizeDropdownAsperUi(this.value);
            if (this.value !== normalized) this.value = normalized;
            configureDropdownUiControls(selectedUiType);
            return;
          }

          if (selectedUiType === "text") {
            const raw = String(this.value || "").replace(/\D/g, "");
            const count = Number.parseInt(raw, 10);
            const normalized = Number.isFinite(count) && count > 0 ? String(count) : "";
            if (this.value !== normalized) this.value = normalized;
            configureTextMessageControls(selectedUiType);
          }
        });
      }

      ["input", "change"].forEach((eventName) => {
        dropdownAsperUiInput?.addEventListener(eventName, function () {
          const selectedUiType = document.getElementById("fUiType")?.value || "";
          if (isDisplayToastUiType(selectedUiType)) {
            renderDisplayToastUiLiveDemo();
          }
        });
      });


      document.getElementById("textMessageRows")?.addEventListener("input", function (event) {
        const input = event.target.closest("[data-text-message-index]");
        if (!input) return;

        const selectedUiType = String(document.getElementById("fUiType")?.value || "")
          .trim()
          .toLowerCase();
        if (selectedUiType !== "text") return;

        const count = getTextMessageCount();
        const index = Number.parseInt(input.dataset.textMessageIndex || "-1", 10);
        if (!Number.isInteger(index) || index < 0 || index >= count) return;

        const values = ensureTextMessageSlots();
        values[index] = input.value;
        setTextMessageValues(values, false);

        input.setAttribute("aria-invalid", "false");
        input.closest(".form-group")?.classList.remove("field-invalid");
        renderMessageUiLiveDemo();
      });

      const dropdownUiValueIndex = document.getElementById("dropdownUiValueIndex");
      dropdownUiValueIndex?.addEventListener("change", function () {
        const selectedUiType = document.getElementById("fUiType")?.value || "";
        if (!isDropdownUiType(selectedUiType)) return;
        selectDropdownUiValue(this.value, true);
      });

      const dropdownUiValueEditor = document.getElementById("dropdownUiValueEditor");
      dropdownUiValueEditor?.addEventListener("input", function () {
        const selectedUiType = document.getElementById("fUiType")?.value || "";
        if (!isDropdownUiType(selectedUiType)) return;
        updateSelectedDropdownUiValue();
      });

      document.getElementById("dropdownUiValueSummary")?.addEventListener("click", function (event) {
        const button = event.target.closest("[data-dropdown-key]");
        if (!button) return;
        selectDropdownUiValue(button.getAttribute("data-dropdown-key") || "", true);
      });

      document.getElementById("dropdownPreviewSelect")?.addEventListener("change", function () {
        const selectedUiType = document.getElementById("fUiType")?.value || "";
        if (!isDropdownUiType(selectedUiType)) return;
        renderDropdownUiLiveDemo();
      });

      const standaloneMessageInput = document.getElementById("fMessage");
      if (standaloneMessageInput) {
        standaloneMessageInput.addEventListener("input", function () {
          const selectedUiType = String(document.getElementById("fUiType")?.value || "")
            .trim()
            .toLowerCase();
          if (!isMessagePreviewUiType(selectedUiType)) return;

          // Text uses the generated Message 1..N editor. Do not let the hidden
          // standalone Message field overwrite those generated values.
          if (selectedUiType === "text") {
            renderMessageUiLiveDemo();
            return;
          }

          const uiValuesInput = document.getElementById("fUiValues");
          if (uiValuesInput && uiValuesInput.value !== this.value) {
            uiValuesInput.value = this.value;
          }
          renderMessageUiLiveDemo();
        });
      }

      const toggleUiValuesInput = document.getElementById("fUiValues");
      if (toggleUiValuesInput) {
        toggleUiValuesInput.addEventListener("input", function () {
          const selectedUiType = document.getElementById("fUiType")?.value || "";

          if (isToggleUiType(selectedUiType) || isStandardButtonUiType(selectedUiType)) {
            const sanitized = sanitizeToggleUiValues(this.value);
            if (this.value !== sanitized) {
              this.value = sanitized;
            }

            if (isToggleUiType(selectedUiType)) {
              renderToggleUiLiveDemo(false);
            } else {
              renderButtonUiLiveDemo(true);
            }
            return;
          }

          if (isPushButtonUiType(selectedUiType)) {
            renderButtonUiLiveDemo(true);
            return;
          }

          if (isDropdownUiType(selectedUiType)) {
            configureDropdownUiControls(selectedUiType);
            return;
          }

          if (isMessagePreviewUiType(selectedUiType)) {
            renderMessageUiLiveDemo();
            return;
          }

          if (isDisplayToastUiType(selectedUiType)) {
            renderDisplayToastUiLiveDemo();
          }
        });

        toggleUiValuesInput.addEventListener("keydown", function (event) {
          const selectedUiType = document.getElementById("fUiType")?.value || "";
          const normalizedUiType = String(selectedUiType).trim().toLowerCase();

          // fUiValues is a textarea so Console can keep real line breaks.
          // For every other UI type it behaves like the previous one-line input.
          if (!isToggleUiType(selectedUiType) && !isStandardButtonUiType(selectedUiType)) {
            if (event.key === "Enter" && normalizedUiType !== "console") {
              event.preventDefault();
            }
            return;
          }

          const allowedControlKeys = new Set([
            "Backspace",
            "Delete",
            "ArrowLeft",
            "ArrowRight",
            "ArrowUp",
            "ArrowDown",
            "Home",
            "End",
            "Tab",
          ]);

          if (event.ctrlKey || event.metaKey || allowedControlKeys.has(event.key)) {
            return;
          }

          if (/^\d$/.test(event.key)) return;

          if (event.key === "," && !this.value.includes(",")) {
            return;
          }

          event.preventDefault();
        });
      }

      const toggleAsperUiSelect = document.getElementById("fToggleAsperUi");
      if (toggleAsperUiSelect) {
        toggleAsperUiSelect.addEventListener("change", function () {
          const selectedUiType = document.getElementById("fUiType")?.value || "";
          if (!usesPresetNamesUiType(selectedUiType)) return;

          const asperUiInput = document.getElementById("fAsperUi");
          const normalized = getTogglePresetAsperUiValue(this.value) || "false,true";

          this.value = normalized;
          setToggleAsperUiCustomMode(false, { focus: false });
          if (asperUiInput) {
            asperUiInput.value = normalized;
            asperUiInput.closest(".form-group")?.classList.remove("field-invalid");
            asperUiInput.setAttribute("aria-invalid", "false");
          }

          if (isToggleUiType(selectedUiType)) renderToggleUiLiveDemo(true);
          if (isButtonUiType(selectedUiType)) renderButtonUiLiveDemo(true);
        });
      }

      const toggleCustomAsperUiBtn = document.getElementById("fToggleCustomAsperUiBtn");
      toggleCustomAsperUiBtn?.addEventListener("click", function () {
        const selectedUiType = document.getElementById("fUiType")?.value || "";
        if (!usesPresetNamesUiType(selectedUiType)) return;

        const customInput = document.getElementById("fToggleCustomAsperUiInput");
        const enablingCustom = Boolean(customInput?.hidden);
        setToggleAsperUiCustomMode(enablingCustom, { focus: true });
        if (isToggleUiType(selectedUiType)) renderToggleUiLiveDemo(true);
        if (isButtonUiType(selectedUiType)) renderButtonUiLiveDemo(true);
      });

      const toggleCustomAsperUiInput = document.getElementById("fToggleCustomAsperUiInput");
      toggleCustomAsperUiInput?.addEventListener("input", function () {
        const selectedUiType = document.getElementById("fUiType")?.value || "";
        if (!usesPresetNamesUiType(selectedUiType)) return;

        const asperUiInput = document.getElementById("fAsperUi");
        if (asperUiInput) {
          // No character restriction here: custom As Per UI accepts any text.
          // A comma separates the two Toggle state labels.
          asperUiInput.value = this.value;
          asperUiInput.closest(".form-group")?.classList.remove("field-invalid");
          asperUiInput.setAttribute("aria-invalid", "false");
        }
        if (isToggleUiType(selectedUiType)) renderToggleUiLiveDemo(true);
        if (isButtonUiType(selectedUiType)) renderButtonUiLiveDemo(true);
      });

      toggleCustomAsperUiInput?.addEventListener("change", function () {
        const selectedUiType = document.getElementById("fUiType")?.value || "";
        if (!usesPresetNamesUiType(selectedUiType)) return;
        const asperUiInput = document.getElementById("fAsperUi");
        if (!asperUiInput) return;
        const normalized = normalizeToggleAsperUiValue(this.value);
        this.value = normalized;
        asperUiInput.value = normalized;
        if (isToggleUiType(selectedUiType)) renderToggleUiLiveDemo(true);
        if (isButtonUiType(selectedUiType)) renderButtonUiLiveDemo(true);
      });

      const toggleLiveSwitch = document.getElementById("toggleLiveSwitch");
      if (toggleLiveSwitch) {
        toggleLiveSwitch.addEventListener("click", function () {
          const selectedUiType = document.getElementById("fUiType")?.value || "";
          if (!isToggleUiType(selectedUiType)) return;

          const pair = getToggleLiveValuePair(
            document.getElementById("fUiValues")?.value || "",
          );
          if (!pair.ready) return;

          toggleLiveDemoState = !toggleLiveDemoState;
          renderToggleUiLiveDemo(false);
        });
      }

      const buttonPreviewControl = document.getElementById("buttonPreviewControl");
      if (buttonPreviewControl) {
        const setPushButtonPreviewPressed = (pressed) => {
          const uiType = String(document.getElementById("fUiType")?.value || "")
            .trim()
            .toLowerCase();
          if (!isPushButtonUiType(uiType)) return;

          const state = document.getElementById("buttonPreviewState");
          const output = document.getElementById("buttonPreviewCurrentValue");
          const asperUiValue = String(document.getElementById("fAsperUi")?.value || "").trim();
          const style = getToggleAsperUiStyle(asperUiValue || "false,true");

          buttonPreviewControl.classList.toggle("is-pressed", Boolean(pressed));
          buttonPreviewControl.classList.remove("is-on");
          buttonPreviewControl.setAttribute("aria-pressed", pressed ? "true" : "false");

          if (state) {
            state.textContent = pressed ? "PRESSED" : "READY";
          }
          if (output && pressed) {
            output.textContent = style.displayLabel;
          }
        };

        buttonPreviewControl.addEventListener("pointerdown", function () {
          setPushButtonPreviewPressed(true);
        });
        buttonPreviewControl.addEventListener("pointerup", function () {
          setPushButtonPreviewPressed(false);
        });
        buttonPreviewControl.addEventListener("pointercancel", function () {
          setPushButtonPreviewPressed(false);
        });
        buttonPreviewControl.addEventListener("pointerleave", function () {
          setPushButtonPreviewPressed(false);
        });

        buttonPreviewControl.addEventListener("click", function () {
          const uiType = document.getElementById("fUiType")?.value || "";
          if (!isButtonUiType(uiType)) return;

          if (isStandardButtonUiType(uiType)) {
            const pair = getToggleLiveValuePair(
              document.getElementById("fUiValues")?.value || ""
            );
            if (!pair.ready) return;

            // Normal Button is latching/two-state. It must not behave like
            // the momentary Push Button preview.
            buttonLiveDemoState = !buttonLiveDemoState;
            renderButtonUiLiveDemo(false);
            return;
          }

          // Push Button is momentary; pointer handlers show press/release.
          const output = document.getElementById("buttonPreviewCurrentValue");
          const asperUiValue = String(document.getElementById("fAsperUi")?.value || "").trim();
          const style = getToggleAsperUiStyle(asperUiValue || "false,true");
          if (output) output.textContent = style.displayLabel;
        });
      }

      const messageSendButton = document.getElementById("messageSendButton");
      messageSendButton?.addEventListener("click", function () {
        const selectedUiType = String(document.getElementById("fUiType")?.value || "")
          .trim()
          .toLowerCase();
        if (selectedUiType !== "enter text") return;
        this.classList.add("sent");
        window.setTimeout(() => this.classList.remove("sent"), 180);
      });

      const uiConfigurationModal = document.getElementById("uiConfigurationModal");
      document
        .getElementById("closeUiConfigurationModal")
        ?.addEventListener("click", closeUiConfigurationPopup);
      document
        .getElementById("doneUiConfigurationModal")
        ?.addEventListener("click", function () {
          if (!validateUiConfigurationPopup()) return;
          closeUiConfigurationPopup();
        });
      document
        .getElementById("editUiConfigValues")
        ?.addEventListener("click", function () {
          const uiType = document.getElementById("fUiType")?.value || "";
          const toggleCustomInput = document.getElementById("fToggleCustomAsperUiInput");
          const target = usesPresetNamesUiType(uiType)
            ? ((toggleCustomInput && !toggleCustomInput.hidden)
                ? toggleCustomInput
                : (document.getElementById("fToggleAsperUi") || document.getElementById("fUiValues")))
            : isDropdownUiType(uiType)
                ? (document.getElementById("dropdownUiValueEditor") || document.getElementById("fUiValues"))
                : isMessagePreviewUiType(uiType)
                  ? document.getElementById("fUiValues")
                : isDisplayToastUiType(uiType)
                  ? document.getElementById("fUiValues")
                : isSliderUiType(uiType)
                ? document.getElementById("fDisplayMin")
                : null;
          target?.focus();
        });

      uiConfigurationModal?.addEventListener("click", function (event) {
        if (event.target === this) closeUiConfigurationPopup();
      });

      ["fDisplayMin", "fDisplayMax", "fSliderStep", "fScalling"].forEach((id) => {
        const control = document.getElementById(id);
        if (!control) return;
        control.addEventListener("input", renderSliderUiLiveDemo);
        control.addEventListener("change", renderSliderUiLiveDemo);
      });

      const uiSliderPreview = document.getElementById("uiSliderPreview");
      uiSliderPreview?.addEventListener("input", function () {
        const valueEl = document.getElementById("uiSliderPreviewValue");
        const uiType = document.getElementById("fUiType")?.value || "";
        const theme = getSliderPreviewTheme(uiType);
        if (valueEl) valueEl.textContent = formatSliderPreviewValue(this.value, theme);
      });

      const uiAutoTimerPreview = document.getElementById("uiAutoTimerPreview");
      uiAutoTimerPreview?.addEventListener("input", function () {
        const uiType = document.getElementById("fUiType")?.value || "";
        if (!isAutoTimerUiType(uiType)) return;
        const sharedPreview = document.getElementById("uiSliderPreview");
        if (sharedPreview) sharedPreview.value = this.value;
        renderSliderUiLiveDemo();
      });


      function setHueCirclePreviewFromPointer(event) {
        const gauge = document.getElementById("uiHueCircleGauge");
        const preview = document.getElementById("uiSliderPreview");
        const uiType = document.getElementById("fUiType")?.value || "";
        if (!gauge || !preview || !isHueCircleUiType(uiType)) return;

        const rect = gauge.getBoundingClientRect();
        const centerX = rect.left + (rect.width / 2);
        const centerY = rect.top + (rect.height / 2);
        const dx = Number(event.clientX) - centerX;
        const dy = Number(event.clientY) - centerY;

        // Ignore an exact centre press because it has no meaningful angle.
        if (!Number.isFinite(dx) || !Number.isFinite(dy) || Math.hypot(dx, dy) < 3) return;

        // atan2() gives 0deg at 3 o'clock and grows clockwise on screen, which
        // is the same coordinate system used by the rotated SVG circle.
        let pointerAngle = Math.atan2(dy, dx) * (180 / Math.PI);
        if (pointerAngle < 0) pointerAngle += 360;

        const startAngle = 135;
        const sweepAngle = 281;
        let relative = (pointerAngle - startAngle + 360) % 360;

        // The remaining part is the intentional open gap. While dragging in
        // that gap, stay on the nearest endpoint instead of wrapping/jumping.
        if (relative > sweepAngle) {
          const distanceToEnd = relative - sweepAngle;
          const distanceToStart = 360 - relative;
          relative = distanceToEnd < distanceToStart ? sweepAngle : 0;
        }

        const min = Number(preview.min || 0);
        const max = Number(preview.max || 100);
        const step = Number(preview.step || 1) > 0 ? Number(preview.step || 1) : 1;
        const ratio = Math.min(1, Math.max(0, relative / sweepAngle));
        const raw = min + ((max - min) * ratio);
        const snapped = min + (Math.round((raw - min) / step) * step);
        const clamped = Math.min(max, Math.max(min, snapped));

        preview.value = String(clamped);
        renderSliderUiLiveDemo();
      }

      const uiHueCircleGauge = document.getElementById("uiHueCircleGauge");
      let hueCirclePointerActive = false;

      uiHueCircleGauge?.addEventListener("pointerdown", function (event) {
        const uiType = document.getElementById("fUiType")?.value || "";
        if (!isHueCircleUiType(uiType)) return;
        event.preventDefault();
        hueCirclePointerActive = true;
        this.classList.add("is-dragging");
        this.setPointerCapture?.(event.pointerId);
        setHueCirclePreviewFromPointer(event);
      });

      uiHueCircleGauge?.addEventListener("pointermove", function (event) {
        if (!hueCirclePointerActive) return;
        event.preventDefault();
        setHueCirclePreviewFromPointer(event);
      });

      ["pointerup", "pointercancel", "lostpointercapture"].forEach((eventName) => {
        uiHueCircleGauge?.addEventListener(eventName, function (event) {
          hueCirclePointerActive = false;
          this.classList.remove("is-dragging");
          if (eventName !== "lostpointercapture" && this.hasPointerCapture?.(event.pointerId)) {
            this.releasePointerCapture?.(event.pointerId);
          }
        });
      });

      uiHueCircleGauge?.addEventListener("keydown", function (event) {
        const uiType = document.getElementById("fUiType")?.value || "";
        const preview = document.getElementById("uiSliderPreview");
        if (!preview || !isHueCircleUiType(uiType)) return;

        const step = Number(preview.step || 1) > 0 ? Number(preview.step || 1) : 1;
        let next = Number(preview.value || preview.min || 0);
        if (event.key === "ArrowRight" || event.key === "ArrowUp") next += step;
        else if (event.key === "ArrowLeft" || event.key === "ArrowDown") next -= step;
        else if (event.key === "Home") next = Number(preview.min || 0);
        else if (event.key === "End") next = Number(preview.max || 100);
        else return;

        event.preventDefault();
        next = Math.min(Number(preview.max), Math.max(Number(preview.min), next));
        preview.value = String(next);
        renderSliderUiLiveDemo();
      });

      document.addEventListener("keydown", function (event) {
        if (event.key === "Escape" && uiConfigurationModal?.classList.contains("open")) {
          closeUiConfigurationPopup();
        }
      });

      document
        .getElementById("saveFieldModal")
        .addEventListener("click", function () {
          if (isCommandGetStatusCommandLocked()) {
            closeByteFieldModal();
            return;
          }
          if (
            currentModalPartitionKey !== null &&
            isCommandGetStatusLockedResponsePartitionKey(currentModalPartitionKey)
          ) {
            closeByteFieldModal();
            return;
          }
          if (
            currentModalPartitionKey === null &&
            currentModalByteIndex !== null &&
            isCommandGetStatusLockedResponseByteIndex(currentModalByteIndex)
          ) {
            closeByteFieldModal();
            return;
          }
          if (currentModalByteKey === null) return;
          if (
            currentModalFrameIdx === null &&
            currentModalPartitionKey === null
          )
            return;
          if (!validateFieldForm()) return;

          const fieldName = document.getElementById("fName").value.trim();

          // Default Value is no longer entered separately.
          // Whatever is saved in Name must also be stored in the existing
          // default-value keys so the backend persists it to default_value.
          const defaultValueInput = document.getElementById("fDefaultValue");
          if (defaultValueInput) defaultValueInput.value = fieldName;

          const configuration = {
            name: fieldName,
            fieldName: fieldName,
            field_name: fieldName,
            dataType: document.getElementById("fDataType").value,
            valueDef: document.getElementById("fValueDef").value,
            defaultvalue: fieldName,
            defaultValue: fieldName,
            default_value: fieldName,
            uiType: document.getElementById("fUiType").value,
            asperui: document.getElementById("fAsperUi").value.trim(),
            sno_asperui: document.getElementById("fUiSerialNo").value.trim(),
            asperuivalue: document.getElementById("fUiValues").value.trim(),
            // Compatibility aliases retained for older saved browser data.
            asperUi: document.getElementById("fAsperUi").value.trim(),
            uiSerialNo: document.getElementById("fUiSerialNo").value.trim(),
            uiValues: document.getElementById("fUiValues").value.trim(),
            message: isMessagePreviewUiType(document.getElementById("fUiType").value)
              ? document.getElementById("fUiValues").value
              : document.getElementById("fMessage").value,
            sliderStep: document.getElementById("fSliderStep").value,
            sliderStepValue: document.getElementById("fSliderStep").value,
            uiInOut: document.getElementById("fUiInOut").value,
            scalling: document.getElementById("fScalling").value,

            /*
             * These keys already exist in the current schema/save mapping.
             * Only the frontend inputs were added.
             */
            displayValueMin:
              document.getElementById("fDisplayMin").value,
            displayValueMax:
              document.getElementById("fDisplayMax").value,

            /*
             * Frontend-only automatic rule:
             * Text / Notification / Enter Text / Console => Yes
             * All remaining UI Types => No
             */
            notificationEnable:
              document.getElementById("fNotificationEnable").value,

            developerNotes:
              document.getElementById("fNotes").value.trim(),

            bitPosition: currentModalBitPosition,
            bitPositions: currentModalBitPositions
              ? [...currentModalBitPositions]
              : null,
            byteIndex: currentModalByteIndex,
          };

          if (currentModalPartitionKey !== null) {
            const partitionKeyValue = currentModalPartitionKey;
            const partitionIndex = getPartitionRanges().findIndex(
              (range) => partitionKey(range) === partitionKeyValue,
            );
            if (!partitionFieldConfigurations[partitionKeyValue]) {
              partitionFieldConfigurations[partitionKeyValue] = {};
            }
            partitionFieldConfigurations[partitionKeyValue][
              currentModalByteKey
            ] = configuration;
            setPartitionChanged();
            closeByteFieldModal();
            renderApiPartitionEditor();
            if (partitionIndex !== -1)
              openPartitionModePopup(partitionKeyValue, partitionIndex);
            persistConfiguration("Field saved");
            return;
          }

          if (!fieldDescriptions[currentModalFrameIdx]) {
            fieldDescriptions[currentModalFrameIdx] = {};
          }
          fieldDescriptions[currentModalFrameIdx][currentModalByteKey] =
            configuration;
          closeByteFieldModal();
          renderFieldDescription();
          updateFieldDescFrameSelect();
          persistConfiguration("Field saved");
        });

      // ---- Field Description Rendering ----
      function renderFieldDescription() {
        const container = document.getElementById("fieldDescContainer");
        const frameSelect = document.getElementById("fieldDescFrameSelect");
        if (!container || !frameSelect) return;
        const selectedFrame = parseInt(frameSelect.value);

        if (
          isNaN(selectedFrame) ||
          !frameCodes[selectedFrame] ||
          frameCodes[selectedFrame].length === 0
        ) {
          container.innerHTML =
            `<div class="field-empty"><i class="fas fa-code"></i><span>Enter a ${getActiveFrameLabel().toLowerCase()} frame code to configure its fields.</span></div>`;
          return;
        }

        const command = frameCodes[selectedFrame];
        const savedGroups = frameValueGroups[selectedFrame] || [];
        const commandBytes = savedGroups.length
          ? savedGroups.slice()
          : [command];

        container.innerHTML = "";
        if (!byteDescriptions[selectedFrame])
          byteDescriptions[selectedFrame] = {};
        if (!fieldViewModes[selectedFrame])
          fieldViewModes[selectedFrame] = {};

        commandBytes.forEach((byteVal, idx) => {
          const byteKey = `byte:${idx}`;
          const currentDesc = byteDescriptions[selectedFrame][idx] || "";
          const currentView =
            fieldViewModes[selectedFrame][idx] || "bytewise";
          const wrapper = document.createElement("div");
          wrapper.className = "field-desc-card";
          applyPartitionColor(wrapper, idx);
          wrapper.dataset.byteIndex = idx;

          const topRow = document.createElement("div");
          topRow.className = "field-card-top";
          const byteLabel = document.createElement("span");
          byteLabel.className = "field-byte-badge";
          byteLabel.textContent = byteVal;
          topRow.appendChild(byteLabel);

          const byteMeta = document.createElement("div");
          byteMeta.className = "field-byte-meta";
          const indexLabel = document.createElement("span");
          indexLabel.className = "field-byte-index";
          indexLabel.textContent = `Value ${idx + 1} 0x${byteVal}`;
          byteMeta.appendChild(indexLabel);

          const select = document.createElement("select");
          select.className = "byte-field-select";
          select.setAttribute(
            "aria-label",
            `Description for value ${idx + 1} ${byteVal}`,
          );
          const emptyOpt = document.createElement("option");
          emptyOpt.value = "";
          emptyOpt.textContent = "Select field description";
          select.appendChild(emptyOpt);
          FIELD_DESC_OPTIONS.forEach((opt) => {
            const option = document.createElement("option");
            option.value = opt;
            option.textContent = opt.charAt(0).toUpperCase() + opt.slice(1);
            if (opt === currentDesc) option.selected = true;
            select.appendChild(option);
          });
          select.addEventListener("change", function (e) {
            e.stopPropagation();
            byteDescriptions[selectedFrame][idx] = this.value;
            if (this.value !== "data")
              delete fieldViewModes[selectedFrame][idx];
            else if (!fieldViewModes[selectedFrame][idx])
              fieldViewModes[selectedFrame][idx] = "bytewise";
            renderFieldDescription();
          });
          byteMeta.appendChild(select);
          topRow.appendChild(byteMeta);
          wrapper.appendChild(topRow);

          if (currentDesc) {
            const cardBody = document.createElement("div");
            cardBody.className = "field-card-body";

            if (currentDesc === "data") {
              const toggleDiv = document.createElement("div");
              toggleDiv.className = "view-toggle-buttons";
              const btnByte = document.createElement("button");
              btnByte.type = "button";
              btnByte.className =
                "view-toggle-btn" +
                (currentView === "bytewise" ? " active" : "");
              btnByte.innerHTML = '<i class="fas fa-cube"></i> Byte Wise';
              const btnBit = document.createElement("button");
              btnBit.type = "button";
              btnBit.className =
                "view-toggle-btn" +
                (currentView === "bitwise" ? " active" : "");
              btnBit.innerHTML = '<i class="fas fa-grip"></i> Bit Wise';
              btnByte.addEventListener("click", function () {
                fieldViewModes[selectedFrame][idx] = "bytewise";
                renderFieldDescription();
              });
              btnBit.addEventListener("click", function () {
                fieldViewModes[selectedFrame][idx] = "bitwise";
                renderFieldDescription();
              });
              toggleDiv.append(btnByte, btnBit);
              cardBody.appendChild(toggleDiv);
            } else {
              const byteOnlyLabel = document.createElement("div");
              byteOnlyLabel.className = "view-toggle-buttons single-view";
              const byteOnlyButton = document.createElement("button");
              byteOnlyButton.type = "button";
              byteOnlyButton.className = "view-toggle-btn active";
              byteOnlyButton.innerHTML =
                '<i class="fas fa-cube"></i> Byte Wise';
              byteOnlyButton.title = "Open complete byte configuration";
              byteOnlyButton.addEventListener("click", function () {
                openByteFieldModal(selectedFrame, byteVal, idx);
              });
              byteOnlyLabel.appendChild(byteOnlyButton);
              cardBody.appendChild(byteOnlyLabel);
            }

            if (currentDesc !== "data" || currentView === "bytewise") {
              const field = fieldDescriptions[selectedFrame]?.[byteKey] || {};
              const action = document.createElement("button");
              action.type = "button";
              action.className = "byte-wise-action";
              action.innerHTML = `<span><strong>Configure Complete Byte</strong><small>${field.dataType || "Unsigned integer"} ${field.uiType || "No UI selected"}</small></span><i class="fas fa-chevron-right"></i>`;
              action.addEventListener("click", function () {
                openByteFieldModal(selectedFrame, byteVal, idx);
              });
              cardBody.appendChild(action);
            } else {
              const labels = document.createElement("div");
              labels.className = "binary-labels";
              const binary = hexToBinary(byteVal);
              const bitCount = binary.length;
              labels.style.gridTemplateColumns = `repeat(${bitCount}, minmax(22px, 1fr))`;
              for (let b = bitCount - 1; b >= 0; b--) {
                const label = document.createElement("span");
                label.textContent = `b${b}`;
                labels.appendChild(label);
              }
              cardBody.appendChild(labels);

              const bitContainer = document.createElement("div");
              bitContainer.className = "bitwise-bits";
              bitContainer.style.gridTemplateColumns = `repeat(${bitCount}, minmax(22px, 1fr))`;
              for (let b = bitCount - 1; b >= 0; b--) {
                const bitVal = binary[bitCount - 1 - b];
                const bitEl = document.createElement("button");
                bitEl.type = "button";
                bitEl.className = `bit bit-${bitVal}`;
                bitEl.textContent = bitVal;
                bitEl.title = `Configure Bit ${b} (value ${bitVal})`;
                bitEl.setAttribute(
                  "aria-label",
                  `Configure bit ${b}, value ${bitVal}`,
                );
                bitEl.addEventListener("click", function () {
                  openByteFieldModal(selectedFrame, byteVal, idx, b);
                });
                bitContainer.appendChild(bitEl);
              }
              cardBody.appendChild(bitContainer);
              const binaryValue = document.createElement("div");
              binaryValue.className = "binary-value";
              binaryValue.textContent = `${byteVal} = ${binary}`;
              cardBody.appendChild(binaryValue);
            }
            wrapper.appendChild(cardBody);
          }

          container.appendChild(wrapper);
        });
      }

      function updateFieldDescFrameSelect() {
        const select = document.getElementById("fieldDescFrameSelect");
        if (!select) return;
        const currentVal = select.value;
        select.innerHTML = '<option value="">Select Frame</option>';
        const count = document.querySelectorAll(
          "#commandFramesContainer .command-frame-card",
        ).length;
        for (let i = 0; i < count; i++) {
          const opt = document.createElement("option");
          opt.value = i;
          opt.textContent = `${getActiveFrameLabel()} Frame ${i + 1}`;
          if (frameCodes[i] && frameCodes[i].length > 0) {
            opt.textContent += ` (${frameCodes[i]})`;
          }
          select.appendChild(opt);
        }
        if (
          currentVal &&
          select.querySelector(`option[value="${currentVal}"]`)
        ) {
          select.value = currentVal;
        } else if (select.options.length > 1) {
          select.value = select.options[1].value;
        }
      }

      function showCommandEntryPopup(frameName, frameIdx) {
        const popup = document.getElementById("byteDetailPopup");
        document.getElementById("popupFrameName").textContent = frameName;
        let entry = popup.querySelector(".command-entry");
        if (!entry) {
          entry = document.createElement("div");
          entry.className = "command-entry";
          popup
            .querySelector(".popup-head")
            .insertAdjacentElement("afterend", entry);
        }
        const lockCommandFrame = isCommandGetStatusCommandLocked();
        if (lockCommandFrame) {
          enforceCommandGetStatusCommandState(true);
        }
        const existingCode = lockCommandFrame
          ? COMMAND_GET_STATUS_FIXED_VALUE
          : (frameCodes[frameIdx] || "");
        const savedGroups = frameValueGroups[frameIdx] || [];
        let entryBytes = lockCommandFrame
          ? COMMAND_GET_STATUS_FIXED_BYTES.slice()
          : savedGroups.length
            ? savedGroups.slice()
            : existingCode
              ? [existingCode]
              : [""];

        entry.innerHTML = `
                    <label class="control-label"><i class="fas fa-keyboard"></i> Enter ${getActiveFrameLabel().toLowerCase()} frame code byte by byte</label>
                    <div class="byte-editor-hint"><i class="fas fa-circle-info"></i> Each box accepts any number of hexadecimal characters. Example: A12C0B or 1234567890.</div>
                    <div id="commandByteCount" class="command-byte-count"><i class="fas fa-cubes"></i> Value fields: 1</div>
                    <div id="commandByteEditor" class="command-byte-editor"></div>
                    <div class="apply-command-row">
                        <button type="button" id="applyCommandCodeBtn"><i class="fas fa-eye"></i> Show Code</button>
                    </div>
                    <div class="command-error" id="commandCodeError"></div>
                `;

        const editor = entry.querySelector("#commandByteEditor");
        const errorBox = entry.querySelector("#commandCodeError");
        const byteCount = entry.querySelector("#commandByteCount");

        function cleanHexValue(value) {
          return value.toUpperCase().replace(/[^0-9A-F]/g, "");
        }

        function resizeHexInput(input) {
          const width = Math.min(
            360,
            Math.max(80, input.value.length * 11 + 30),
          );
          input.style.width = `${width}px`;
        }

        function renderByteInputs(focusIndex) {
          editor.innerHTML = "";
          byteCount.innerHTML = `<i class="fas fa-cubes"></i> Value fields: ${entryBytes.length}`;
          entryBytes.forEach((byteValue, byteIndex) => {
            const unit = document.createElement("div");
            unit.className = "command-byte-unit";

            const byteLabel = document.createElement("label");
            byteLabel.innerHTML = `<i class="fas fa-code"></i> Hex value ${byteIndex + 1}`;

            const byteInput = document.createElement("input");
            byteInput.type = "text";
            byteInput.className = "command-byte-input";
            byteInput.value = cleanHexValue(byteValue);
            byteInput.placeholder = "A12C0B";
            byteInput.inputMode = "text";
            byteInput.autocomplete = "off";
            byteInput.spellcheck = false;
            byteInput.setAttribute(
              "aria-label",
              `${getActiveFrameLabel()} frame hexadecimal value ${byteIndex + 1}`,
            );
            resizeHexInput(byteInput);

            if (lockCommandFrame) {
              byteInput.readOnly = true;
              byteInput.tabIndex = -1;
              byteInput.classList.add("hex-byte-fixed");
              byteInput.setAttribute("aria-readonly", "true");
              byteInput.title = "Fixed Command Get Status byte";
              ["beforeinput", "input", "paste", "cut", "drop", "keydown"].forEach(
                function (eventName) {
                  byteInput.addEventListener(eventName, function (event) {
                    event.preventDefault();
                    byteInput.value = COMMAND_GET_STATUS_FIXED_BYTES[byteIndex];
                    enforceCommandGetStatusCommandState(true);
                  });
                },
              );
            } else byteInput.addEventListener("input", function () {
              const cleaned = cleanHexValue(this.value);
              this.value = cleaned;
              entryBytes[byteIndex] = cleaned;
              resizeHexInput(this);
              this.classList.remove("invalid");
              errorBox.textContent = "";
            });
            if (!lockCommandFrame) byteInput.addEventListener("keydown", function (event) {
              if (event.key === "Enter") applyCommand(event);
            });

            if (!lockCommandFrame) byteInput.addEventListener("paste", function (event) {
              const pasted = event.clipboardData
                .getData("text")
                .replace(/\s+/g, "")
                .replace(/^0x/i, "")
                .toUpperCase()
                .replace(/[^0-9A-F]/g, "");
              if (pasted) {
                event.preventDefault();
                entryBytes[byteIndex] = pasted;
                renderByteInputs(byteIndex);
              }
            });

            unit.append(byteLabel, byteInput);

            if (!lockCommandFrame && entryBytes.length > 1) {
              const removeButton = document.createElement("button");
              removeButton.type = "button";
              removeButton.className = "remove-command-byte";
              removeButton.innerHTML = '<i class="fas fa-xmark"></i>';
              removeButton.title = `Remove Hex Value ${byteIndex + 1}`;
              removeButton.setAttribute(
                "aria-label",
                `Remove ${getActiveFrameLabel().toLowerCase()} frame hexadecimal value ${byteIndex + 1}`,
              );
              removeButton.addEventListener("click", function (event) {
                event.preventDefault();
                event.stopPropagation();
                entryBytes.splice(byteIndex, 1);
                renderByteInputs(Math.max(0, byteIndex - 1));
              });
              unit.appendChild(removeButton);
            }
            editor.appendChild(unit);
          });

          if (!lockCommandFrame) {
            const addButton = document.createElement("button");
            addButton.type = "button";
            addButton.className = "add-command-byte";
            addButton.innerHTML = '<i class="fas fa-plus"></i>';
            addButton.title = "Add another hexadecimal value";
            addButton.setAttribute(
              "aria-label",
              `Add another ${getActiveFrameLabel().toLowerCase()} frame hexadecimal value`,
            );
            addButton.addEventListener("click", function (event) {
              event.preventDefault();
              event.stopPropagation();
              entryBytes.push("");
              renderByteInputs(entryBytes.length - 1);
            });
            editor.appendChild(addButton);
          }

          if (!lockCommandFrame && Number.isInteger(focusIndex)) {
            const inputs = editor.querySelectorAll(".command-byte-input");
            if (inputs[focusIndex]) {
              const targetInput = inputs[focusIndex];
              targetInput.classList.add("new-byte");
              targetInput.focus();
              targetInput.select();
              setTimeout(() => {
                targetInput.scrollIntoView?.({
                  behavior: "smooth",
                  block: "nearest",
                  inline: "nearest",
                });
                targetInput.classList.remove("new-byte");
              }, 0);
            }
          }
        }

        const applyCommand = function (event) {
          if (event) {
            event.preventDefault();
            event.stopPropagation();
          }
          if (lockCommandFrame) {
            enforceCommandGetStatusCommandState(true);
            entryBytes = COMMAND_GET_STATUS_FIXED_BYTES.slice();
            frameValueGroups[frameIdx] = entryBytes.slice();
            frameCodes[frameIdx] = COMMAND_GET_STATUS_FIXED_VALUE;
            renderCommandCodeBoxes(COMMAND_GET_STATUS_FIXED_VALUE, frameIdx);
            renderByteInputs();
            return;
          }
          const inputs = Array.from(
            editor.querySelectorAll(".command-byte-input"),
          );
          let firstInvalid = null;
          inputs.forEach((byteInput, index) => {
            const byteValue = cleanHexValue(byteInput.value);
            entryBytes[index] = byteValue;
            const invalid = byteValue.length === 0;
            byteInput.classList.toggle("invalid", invalid);
            if (invalid && !firstInvalid) firstInvalid = byteInput;
          });

          if (firstInvalid) {
            errorBox.textContent =
              "Enter at least one hexadecimal character in every value field.";
            firstInvalid.focus();
            return;
          }
          const command = entryBytes.join("");
          errorBox.textContent = "";
          frameValueGroups[frameIdx] = entryBytes.slice();
          frameCodes[frameIdx] = command;
          renderCommandCodeBoxes(command, frameIdx);

          const cards = document.querySelectorAll(".command-frame-card");
          const currentCard = cards[frameIdx];
          if (currentCard) {
            const codeText = currentCard.querySelector(".frame-code strong");
            if (codeText) codeText.textContent = command;
            currentCard.classList.add("selected");
          }
          updateFieldDescFrameSelect();
          renderFieldDescription();
          markConfigurationUnsaved();
        };
        entry
          .querySelector("#applyCommandCodeBtn")
          .addEventListener("click", applyCommand);

        renderByteInputs();
        renderCommandCodeBoxes(frameCodes[frameIdx] || "", frameIdx);
        popup.style.display = "block";
        if (!lockCommandFrame) {
          setTimeout(() => {
            const firstEmpty = Array.from(
              editor.querySelectorAll(".command-byte-input"),
            ).find((input) => !input.value);
            (
              firstEmpty || editor.querySelector(".command-byte-input")
            )?.focus();
          }, 0);
        }
      }

      document
        .getElementById("closePopupBtn")
        .addEventListener("click", function () {
          document.getElementById("byteDetailPopup").style.display = "none";
          selectedFrameIndex = null;
          document
            .querySelectorAll(".command-frame-card")
            .forEach((c) => c.classList.remove("selected"));
        });

      // Keep the command editor open during all internal interactions.
      // This is required because + and remove rebuild their clicked controls.
      document
        .getElementById("byteDetailPopup")
        .addEventListener("click", function (event) {
          event.stopPropagation();
        });

      function updateCommandFrameCount() {
        if (isCommandGetStatusCommandLocked()) {
          enforceCommandGetStatusCommandState(true);
          document.getElementById("cmdFrameCountDisplay").textContent = "1";
          document.getElementById("cmdFrameCountInput").value = "1";
          frameTypeStores.command.count = 1;
          return;
        }
        const count = document.querySelectorAll(
          "#commandFramesContainer .command-frame-card",
        ).length;
        document.getElementById("cmdFrameCountDisplay").textContent = count;
        document.getElementById("cmdFrameCountInput").value = count;
        frameTypeStores[activeFrameType].count = count;
        saveActiveFrameTypeStore();
        updateFrameTypeUi();
        if (count === 0) {
          document.getElementById("byteDetailPopup").style.display = "none";
          selectedFrameIndex = null;
          activePartitionFrameIndex = null;
          document
            .getElementById("apiPartitionSection")
            .classList.remove("frame-partition-active");
        }
      }

      document
        .getElementById("generateFramesBtn")
        .addEventListener("click", function () {
          const requestedCount =
            parseInt(document.getElementById("cmdFrameCountInput").value) ||
            0;
          if (!checkRequirements() || requestedCount < 1) {
            showRequirementPopup();
            return;
          }
          showSetupWarnings = false;
          updateRequiredDropdownWarnings(false);
          if (bytes.length === 0) {
            generate8Bytes();
          }
          const count =
            parseInt(document.getElementById("cmdFrameCountInput").value) ||
            0;
          if (count > 0 && bytes.length > 0) {
            frameGenerationRevealed = true;
            awaitingFrameClick = true;
            generateCommandFrames(count, false);
            document
              .getElementById("commandFramesSection")
              ?.classList.add("is-visible");
            document
              .getElementById("commandFramesSection")
              ?.scrollIntoView({ behavior: "smooth", block: "start" });
          } else if (count === 0) {
            awaitingFrameClick = false;
            document.getElementById("commandFramesContainer").innerHTML = "";
            updateCommandFrameCount();
            document.getElementById("byteDetailPopup").style.display = "none";
            selectedFrameIndex = null;
            frameCodes = [];
            frameValueGroups = [];
            framePartitionStates = [];
            frameConfigurations = [];
            activePartitionFrameIndex = null;
            document
              .getElementById("apiPartitionSection")
              .classList.remove("frame-partition-active");
            fieldDescriptions = {};
            byteDescriptions = {};
            fieldViewModes = {};
            updateFieldDescFrameSelect();
            renderFieldDescription();
            document
              .getElementById("framesNextBanner")
              ?.classList.remove("show");
          }
        });

      document
        .getElementById("cmdFrameCountInput")
        .addEventListener("input", function () {
          let val = parseInt(this.value) || 0;
          if (val < 0) val = 0;
          if (val > 20) val = 20;
          this.value = val;
          const invalid = val < 1;
          this.closest(".input-with-icon")?.classList.toggle(
            "input-error",
            showSetupWarnings && invalid,
          );
          this.setAttribute(
            "aria-invalid",
            String(showSetupWarnings && invalid),
          );
          updateSetupFieldHints();
        });

      // Initialize Step 1 voice controls for the active frame type.
      renderVoiceCommandUiFromStore(frameTypeStores[activeFrameType]);

      document
        .getElementById("voiceCommandEnableSelect")
        ?.addEventListener("change", function () {
          syncVoiceCommandVisibility();
          updateRequiredDropdownWarnings(showSetupWarnings);
          const store = frameTypeStores[activeFrameType];
          if (store) {
            const voiceState = collectVoiceCommandsFromUi();
            store.voiceCommandEnabled = voiceState.enabled;
            store.voiceCommands = voiceState.commands;
          }
          if (typeof markConfigurationUnsaved === "function") {
            markConfigurationUnsaved();
          }
        });

      document
        .getElementById("addVoiceCommandBtn")
        ?.addEventListener("click", function () {
          addVoiceCommandInput("", true);
          updateRequiredDropdownWarnings(showSetupWarnings);
          const store = frameTypeStores[activeFrameType];
          if (store) {
            const voiceState = collectVoiceCommandsFromUi();
            store.voiceCommandEnabled = voiceState.enabled;
            store.voiceCommands = voiceState.commands;
          }
        });

      document
        .getElementById("triggerUiSelect")
        ?.addEventListener("change", function () {
          updateRequiredDropdownWarnings(showSetupWarnings);
          const count = document.querySelectorAll(
            "#commandFramesContainer .command-frame-card",
          ).length;
          if (count > 0 && checkRequirements()) {
            generateCommandFrames(count, true);
          } else if (count > 0 && !checkRequirements()) {
            document.getElementById("commandFramesContainer").innerHTML = "";
            updateCommandFrameCount();
            document.getElementById("byteDetailPopup").style.display = "none";
            selectedFrameIndex = null;
            frameCodes = [];
            frameValueGroups = [];
            framePartitionStates = [];
            frameConfigurations = [];
            activePartitionFrameIndex = null;
            document
              .getElementById("apiPartitionSection")
              .classList.remove("frame-partition-active");
            fieldDescriptions = {};
            byteDescriptions = {};
            fieldViewModes = {};
            updateFieldDescFrameSelect();
            renderFieldDescription();
          }
        });

      ["paramNameInput", "cmdFrameCountInput"].forEach((id) => {
        document.getElementById(id)?.addEventListener("input", function () {
          if (COMMAND_GET_STATUS_EDIT_LOCKED) {
            enforceCommandGetStatusCommandState(true);
            syncCommandGetStatusLockUi();
          }
          updateRequiredDropdownWarnings(showSetupWarnings);
        });
      });

      const addCommandFrameBottom = document.getElementById(
        "addCommandFrameBottom",
      );
      if (addCommandFrameBottom) {
        addCommandFrameBottom.addEventListener("click", addCommandFrame);
      }
      document
        .getElementById("addCommandFrameBtn")
        ?.addEventListener("click", addCommandFrame);

      const apiTimelineScroll =
        document.getElementById("apiTimelineScroll");
      document
        .getElementById("previousPartitionBtn")
        ?.addEventListener("click", function () {
          scrollToAdjacentPartition(-1);
        });
      document
        .getElementById("nextPartitionBtn")
        ?.addEventListener("click", function () {
          scrollToAdjacentPartition(1);
        });
      apiTimelineScroll?.addEventListener(
        "scroll",
        updatePartitionNavigation,
        { passive: true },
      );
      window.addEventListener("resize", updatePartitionNavigation);

      document.querySelectorAll(".frame-type-btn").forEach((button) => {
        button.addEventListener("click", function () {
          switchFrameType(this.dataset.frameType, true);
        });
      });

      /*
       * Choose Frames to Include listeners
       */
      document
        .querySelectorAll(".frame-include-checkbox")
        .forEach((checkbox) => {
          checkbox.addEventListener("change", function () {
            setFrameTypeIncluded(
              this.dataset.frameType,
              this.checked,
            );
          });
        });

      document
        .getElementById("selectAllFrameTypesBtn")
        ?.addEventListener("click", function () {
          Object.keys(FRAME_TYPE_LABELS).forEach((frameType) => {
            const checkbox = getFrameIncludeCheckbox(frameType);
            if (checkbox && !checkbox.checked) {
              setFrameTypeIncluded(frameType, true);
            }
          });

          syncFrameInclusionUi();
        });

      document
        .getElementById("selectedFrameTypeChips")
        ?.addEventListener("click", function (event) {
          const removeButton = event.target.closest(
            "[data-remove-frame-type]",
          );

          if (!removeButton) return;

          setFrameTypeIncluded(
            removeButton.dataset.removeFrameType,
            false,
          );
        });

      /*
       * For a new Add form no saved restore runs, so initialize the row
       * immediately with Command selected.
       */
      if (!serverApp.id) {
        initializeFrameInclusionFromStores();
      }


      document.querySelectorAll(".flow-stage[data-flow-frame-type]").forEach((button) => {
        button.addEventListener("click", function () {
          if (!isFrameTypeIncluded(this.dataset.flowFrameType)) {
            return;
          }

          // Command / Response / Error navigation should land on the generated
          // frame cards first. The partition editor opens only after a frame
          // card (or Configure button) is selected.
          switchFrameType(this.dataset.flowFrameType, false);
          const framesSection = document.getElementById("commandFramesSection");
          framesSection?.classList.add("section-highlight");
          framesSection?.scrollIntoView({ behavior: "smooth", block: "start" });
          window.setTimeout(
            () => framesSection?.classList.remove("section-highlight"),
            1200,
          );
        });
      });

      document
        .getElementById("deleteConfigurationBtn")
        ?.addEventListener("click", async function () {
          if (!serverApp.deleteUrl) return;
          if (!window.confirm("Delete this API configuration permanently?")) {
            return;
          }
          this.disabled = true;
          try {
            const response = await fetch(serverApp.deleteUrl, {
              method: "POST",
              headers: csrfRequestHeaders(),
              credentials: "same-origin",
            });
            const result = await response.json().catch(() => null);
            if (!response.ok || !result?.success) {
              throw new Error(result?.message || "Delete failed.");
            }
            window.location.assign(
              result.redirect_url || serverApp.createUrl,
            );
          } catch (error) {
            this.disabled = false;
            alert(error.message || "The configuration could not be deleted.");
          }
        });

      const fieldDescFrameSelect = document.getElementById(
        "fieldDescFrameSelect",
      );
      if (fieldDescFrameSelect) {
        fieldDescFrameSelect.addEventListener(
          "change",
          renderFieldDescription,


        );
      }
      // const stepOneDemoOverlay =
      //   document.getElementById("stepOneDemoOverlay");
      // document
      //   .getElementById("openStepOneDemo")
      //   .addEventListener("click", function () {
      //     stepOneDemoOverlay.style.display = "flex";
      //   });
      // document
      //   .getElementById("closeStepOneDemo")
      //   .addEventListener("click", function () {
      //     stepOneDemoOverlay.style.display = "none";
      //   });
      // document
      //   .getElementById("dismissStepOneDemo")
      //   .addEventListener("click", function () {
      //     stepOneDemoOverlay.style.display = "none";
      //   });
      // stepOneDemoOverlay.addEventListener("click", function (event) {
      //   if (event.target === stepOneDemoOverlay)
      //     stepOneDemoOverlay.style.display = "none";
      // });

      // New configurations start with one default byte: 00. Edit mode still
      // restores the value supplied by the backend for existing saved frames.
      if (!serverApp.id && !serverApp.initialConfiguration) {
        const defaultInput = document.getElementById("fullApiInput");
        if (defaultInput) defaultInput.value = "00";
        fullApiValue = "00";
        hexEditorDraftBytes = ["00"];
        hexEditorDraftIsIncomplete = false;
        restoredByteCount = 1;
      }

      const embeddedConfigurationRestored = restoreSavedConfiguration(
        serverApp.initialConfiguration,
      );
      if (!embeddedConfigurationRestored) {
        updateFrameTypeUi();
        renderApiPartitionEditor();
        renderAll();
        document.getElementById("commandFramesContainer").innerHTML = "";
        updateCommandFrameCount();
        document.getElementById("cmdFrameCountInput").value = 0;
        updateFieldDescFrameSelect();
        renderFieldDescription();
      }
      if (serverApp.id && !embeddedConfigurationRestored) {
        loadEditConfiguration();
      }
      enforceCommandGetStatusCommandState(true);
      syncCommandGetStatusLockUi();
      initializeParameterNameChooser();
      updateRequiredDropdownWarnings(false);
      initializeFieldReferenceControls();
      renderUiTypePicker("none");

      document
        .querySelectorAll(
          "#paramNameInput,#parameterNameSourceSelect,#existingParameterNameSelect,#customParameterNameInput,#cmdFrameCountInput,#triggerUiSelect,#fullApiInput",
        )
        .forEach((control) => {
          control.addEventListener(
            control.tagName === "SELECT" ? "change" : "input",
            markConfigurationUnsaved,
          );
        });

      document.addEventListener("click", function (e) {
        const popup = document.getElementById("byteDetailPopup");
        if (popup.style.display === "block") {
          if (
            !popup.contains(e.target) &&
            !e.target.closest(".command-frame-card")
          ) {
            popup.style.display = "none";
            selectedFrameIndex = null;
            document
              .querySelectorAll(".command-frame-card")
              .forEach((c) => c.classList.remove("selected"));
          }
        }
      });
    })();
  </script>
  

<script id="radioCardCompatibilityBridge">
  (function () {
    const bindings = [
      { selectId: "parameterNameSourceSelect", radioName: "parameterNameSourceRadio" },
      { selectId: "voiceCommandEnableSelect", radioName: "voiceCommandEnableRadio" },
    ];

    function radioInputs(binding) {
      return Array.from(document.querySelectorAll(`input[name="${binding.radioName}"]`));
    }

    function syncRadiosFromSelect(binding) {
      const select = document.getElementById(binding.selectId);
      if (!select) return;
      radioInputs(binding).forEach((radio) => {
        radio.checked = String(radio.value) === String(select.value || "");
      });
    }

    function bridgeSelectValue(binding) {
      const select = document.getElementById(binding.selectId);
      if (!select || select.dataset.radioBridgeReady === "1") return;
      select.dataset.radioBridgeReady = "1";

      const descriptor = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, "value");
      if (descriptor?.get && descriptor?.set) {
        Object.defineProperty(select, "value", {
          configurable: true,
          enumerable: true,
          get() {
            return descriptor.get.call(this);
          },
          set(nextValue) {
            descriptor.set.call(this, nextValue);
            syncRadiosFromSelect(binding);
          },
        });
      }

      radioInputs(binding).forEach((radio) => {
        radio.addEventListener("change", function () {
          if (!this.checked || this.disabled) return;
          select.value = this.value;
          select.dispatchEvent(new Event("change", { bubbles: true }));
        });
      });

      select.addEventListener("change", () => syncRadiosFromSelect(binding));
      syncRadiosFromSelect(binding);
    }

    function initializeRadioBridges() {
      bindings.forEach(bridgeSelectValue);
    }

    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", initializeRadioBridges, { once: true });
    } else {
      initializeRadioBridges();
    }
  })();
</script>



<script id="globalCustomSelectEnhancer">
  (function () {
    const SKIP_SELECTOR = [
      'select[multiple]',
      'select.radio-select-proxy',
      '#parameterNameSourceSelect',
      '#voiceCommandEnableSelect',
      '#fUiType',
      '#fNotificationEnable',
      '#fUiInOut'
    ].join(',');

    const state = {
      activeSelect: null,
      activeWrapper: null,
      activeTrigger: null,
      portal: null,
      lastSignature: new WeakMap(),
    };

    function iconClassForOption(text) {
      const value = String(text || '').toLowerCase();
      if (/server|cloud/.test(value)) return 'fa-cloud';
      if (/device|hardware/.test(value)) return 'fa-microchip';
      if (/yes|true|enable|enabled|active|on/.test(value)) return 'fa-check';
      if (/no|false|disable|disabled|off|none/.test(value)) return 'fa-ban';
      if (/read.*write|write.*read|both/.test(value)) return 'fa-right-left';
      if (/read/.test(value)) return 'fa-eye';
      if (/write/.test(value)) return 'fa-pen';
      if (/command/.test(value)) return 'fa-terminal';
      if (/response|reply/.test(value)) return 'fa-reply';
      if (/error|fail|invalid/.test(value)) return 'fa-triangle-exclamation';
      if (/data|database/.test(value)) return 'fa-database';
      if (/dropdown|list/.test(value)) return 'fa-list';
      if (/slider|range/.test(value)) return 'fa-sliders';
      if (/button/.test(value)) return 'fa-square';
      if (/timer|time/.test(value)) return 'fa-clock';
      if (/status/.test(value)) return 'fa-circle-info';
      if (/custom/.test(value)) return 'fa-pen-to-square';
      if (/existing/.test(value)) return 'fa-database';
      return 'fa-circle-dot';
    }

    function optionSignature(select) {
      return Array.from(select.children).map(function (child) {
        if (child.tagName === 'OPTGROUP') {
          return 'G:' + child.label + ':' + Array.from(child.children).map(function (option) {
            return [option.value, option.textContent, option.disabled].join('~');
          }).join('|');
        }
        if (child.tagName === 'OPTION') {
          return 'O:' + [child.value, child.textContent, child.disabled].join('~');
        }
        return '';
      }).join('||');
    }

    function ensurePortal() {
      if (state.portal && state.portal.isConnected) return state.portal;
      const portal = document.createElement('div');
      portal.className = 'ef-dropdown-portal';
      portal.setAttribute('role', 'listbox');
      portal.setAttribute('aria-hidden', 'true');
      document.body.appendChild(portal);
      state.portal = portal;
      return portal;
    }

    function updateTrigger(select) {
      const wrapper = select._efCustomWrapper ||
        (select.nextElementSibling?.classList?.contains('ef-custom-select') ? select.nextElementSibling : null);
      if (!wrapper) return;
      const trigger = wrapper.querySelector('.ef-custom-select-trigger');
      const text = wrapper.querySelector('.ef-custom-select-trigger-text');
      const selectedOption = select.options[select.selectedIndex] || null;
      if (text) {
        text.textContent = selectedOption
          ? String(selectedOption.textContent || '').trim()
          : 'Select an option';
      }
      if (trigger) {
        trigger.disabled = Boolean(select.disabled);
        trigger.setAttribute('aria-disabled', String(Boolean(select.disabled)));
        trigger.setAttribute('aria-expanded', String(state.activeSelect === select));
        trigger.title = selectedOption ? String(selectedOption.textContent || '').trim() : '';
      }
      wrapper.classList.toggle('is-disabled', Boolean(select.disabled));
      wrapper.classList.toggle(
        'has-error',
        select.classList.contains('dropdown-error') ||
          select.getAttribute('aria-invalid') === 'true' ||
          Boolean(select.closest('.dropdown-error'))
      );
      wrapper.style.display = select.hidden ? 'none' : '';
    }

    function rebuildPortal(select) {
      const portal = ensurePortal();
      portal.replaceChildren();
      let optionCount = 0;

      Array.from(select.children).forEach(function (child) {
        if (child.tagName === 'OPTGROUP') {
          const group = document.createElement('div');
          group.className = 'ef-dropdown-group-label';
          group.textContent = child.label || 'Options';
          portal.appendChild(group);
          Array.from(child.children).forEach(function (option) {
            appendOption(select, option, portal);
            optionCount += 1;
          });
          return;
        }
        if (child.tagName === 'OPTION') {
          appendOption(select, child, portal);
          optionCount += 1;
        }
      });

      if (!optionCount) {
        const empty = document.createElement('div');
        empty.className = 'ef-dropdown-empty';
        empty.textContent = 'No options available';
        portal.appendChild(empty);
      }
    }

    function appendOption(select, option, portal) {
      const row = document.createElement('button');
      row.type = 'button';
      row.className = 'ef-dropdown-option';
      row.setAttribute('role', 'option');
      row.dataset.value = option.value;
      row.disabled = Boolean(option.disabled);
      row.classList.toggle('is-disabled', Boolean(option.disabled));
      row.classList.toggle('is-selected', option.selected);
      row.setAttribute('aria-selected', String(option.selected));

      const icon = document.createElement('span');
      icon.className = 'ef-dropdown-option-icon';
      icon.innerHTML = '<i class="fas ' + iconClassForOption(option.textContent) + '"></i>';

      const label = document.createElement('span');
      label.textContent = String(option.textContent || '').trim();

      row.append(icon, label);
      row.addEventListener('click', function (event) {
        event.preventDefault();
        event.stopPropagation();
        if (row.disabled) return;
        select.value = option.value;
        select.dispatchEvent(new Event('change', { bubbles: true }));
        select.dispatchEvent(new Event('input', { bubbles: true }));
        updateTrigger(select);
        closeDropdown(true);
      });
      portal.appendChild(row);
    }

    function positionPortal() {
      if (!state.activeTrigger || !state.portal?.classList.contains('is-open')) return;
      const rect = state.activeTrigger.getBoundingClientRect();
      const viewportGap = 10;
      const minWidth = Math.max(190, rect.width);
      const maxWidth = Math.min(420, window.innerWidth - viewportGap * 2);
      const width = Math.min(Math.max(minWidth, rect.width), maxWidth);

      state.portal.style.width = width + 'px';
      state.portal.style.left = Math.min(
        Math.max(viewportGap, rect.left),
        Math.max(viewportGap, window.innerWidth - width - viewportGap)
      ) + 'px';

      state.portal.style.top = '0px';
      state.portal.style.visibility = 'hidden';
      state.portal.classList.add('is-open');
      const menuHeight = state.portal.getBoundingClientRect().height;
      const spaceBelow = window.innerHeight - rect.bottom - viewportGap;
      const spaceAbove = rect.top - viewportGap;
      const openAbove = menuHeight > spaceBelow && spaceAbove > spaceBelow;
      const top = openAbove
        ? Math.max(viewportGap, rect.top - Math.min(menuHeight, spaceAbove) - 6)
        : Math.min(window.innerHeight - viewportGap, rect.bottom + 6);
      state.portal.style.top = top + 'px';
      state.portal.style.visibility = 'visible';
    }

    function openDropdown(select, wrapper, trigger) {
      if (select.disabled) return;
      if (state.activeSelect === select) {
        closeDropdown(true);
        return;
      }
      closeDropdown(false);
      state.activeSelect = select;
      state.activeWrapper = wrapper;
      state.activeTrigger = trigger;
      wrapper.classList.add('is-open');
      trigger.setAttribute('aria-expanded', 'true');
      rebuildPortal(select);
      const portal = ensurePortal();
      portal.setAttribute('aria-hidden', 'false');
      portal.classList.add('is-open');
      positionPortal();

      requestAnimationFrame(function () {
        const selected = portal.querySelector('.ef-dropdown-option.is-selected:not(:disabled)');
        if (selected) selected.scrollIntoView({ block: 'nearest' });
      });
    }

    function closeDropdown(returnFocus) {
      if (state.activeWrapper) state.activeWrapper.classList.remove('is-open');
      if (state.activeTrigger) state.activeTrigger.setAttribute('aria-expanded', 'false');
      if (state.portal) {
        state.portal.classList.remove('is-open');
        state.portal.setAttribute('aria-hidden', 'true');
        state.portal.style.visibility = '';
      }
      const trigger = state.activeTrigger;
      state.activeSelect = null;
      state.activeWrapper = null;
      state.activeTrigger = null;
      if (returnFocus && trigger?.isConnected) trigger.focus({ preventScroll: true });
    }

    function enhanceSelect(select) {
      if (!(select instanceof HTMLSelectElement)) return;
      if (select.matches(SKIP_SELECTOR)) return;
      if (Number(select.size || 0) > 1) return;
      if (select.dataset.efCustomSelectReady === '1') {
        updateTrigger(select);
        return;
      }

      select.dataset.efCustomSelectReady = '1';
      const wrapper = document.createElement('span');
      wrapper.className = 'ef-custom-select';
      select.insertAdjacentElement('afterend', wrapper);
      select._efCustomWrapper = wrapper;
      select.classList.add('ef-native-select-hidden');

      const trigger = document.createElement('button');
      trigger.type = 'button';
      trigger.className = 'ef-custom-select-trigger';
      trigger.setAttribute('aria-haspopup', 'listbox');
      trigger.setAttribute('aria-expanded', 'false');
      const label = document.createElement('span');
      label.className = 'ef-custom-select-trigger-text';
      trigger.appendChild(label);
      wrapper.appendChild(trigger);

      trigger.addEventListener('click', function (event) {
        event.preventDefault();
        event.stopPropagation();
        openDropdown(select, wrapper, trigger);
      });

      trigger.addEventListener('keydown', function (event) {
        if (event.key === 'ArrowDown' || event.key === 'Enter' || event.key === ' ') {
          event.preventDefault();
          openDropdown(select, wrapper, trigger);
          requestAnimationFrame(function () {
            const target = state.portal?.querySelector('.ef-dropdown-option.is-selected:not(:disabled)') ||
              state.portal?.querySelector('.ef-dropdown-option:not(:disabled)');
            target?.focus();
          });
        }
      });

      select.addEventListener('change', function () {
        updateTrigger(select);
        if (state.activeSelect === select) rebuildPortal(select);
      });

      select.addEventListener('focus', function () {
        if (!select.disabled) trigger.focus({ preventScroll: true });
      });

      const observer = new MutationObserver(function () {
        state.lastSignature.delete(select);
        updateTrigger(select);
        if (state.activeSelect === select) {
          rebuildPortal(select);
          positionPortal();
        }
      });
      observer.observe(select, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ['disabled', 'hidden', 'aria-invalid', 'class'],
      });

      updateTrigger(select);
      state.lastSignature.set(select, optionSignature(select));
    }

    function scan(root) {
      if (!root) return;
      if (root instanceof HTMLSelectElement) enhanceSelect(root);
      if (root.querySelectorAll) {
        root.querySelectorAll('select').forEach(enhanceSelect);
      }
    }

    function periodicSync() {
      document.querySelectorAll('select[data-ef-custom-select-ready="1"]').forEach(function (select) {
        if (!select.isConnected) return;
        const signature = optionSignature(select);
        if (state.lastSignature.get(select) !== signature) {
          state.lastSignature.set(select, signature);
          if (state.activeSelect === select) rebuildPortal(select);
        }
        updateTrigger(select);
      });
      if (state.activeSelect) positionPortal();
    }

    function init() {
      ensurePortal();
      scan(document);

      const documentObserver = new MutationObserver(function (records) {
        records.forEach(function (record) {
          record.addedNodes.forEach(function (node) {
            if (node.nodeType === 1) scan(node);
          });
        });
      });
      documentObserver.observe(document.body, { childList: true, subtree: true });

      document.addEventListener('click', function (event) {
        if (event.target.closest('.ef-custom-select-trigger') || event.target.closest('.ef-dropdown-portal')) return;
        closeDropdown(false);
      });

      document.addEventListener('keydown', function (event) {
        if (event.key === 'Escape' && state.activeSelect) {
          event.preventDefault();
          closeDropdown(true);
        }
      });

      window.addEventListener('resize', function () {
        if (state.activeSelect) positionPortal();
      });
      window.addEventListener('scroll', function () {
        if (state.activeSelect) positionPortal();
      }, true);

      setInterval(periodicSync, 350);
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', init, { once: true });
    } else {
      init();
    }
  })();
</script>
</body>

</html>
